window.BASAIR_QUESTIONS=(window.BASAIR_QUESTIONS||[]).concat([{"id":"s2-535","number":535,"surah":2,"verses":[133],"references":[{"surah":2,"verses":[133]}],"verseLabel":"البقرة: 133","question":"كيف عُدَّ إسماعيل من ﴿آبَائِكَ﴾ ليعقوب وهو عمه؟","answer":"لأن العرب تسمي العم أبًا؛ فإطلاق الآباء هنا يشمل إسماعيل، وهو عم يعقوب. وهذا استعمال عربي في اتساع معنى الأبوة، لا تغيير للنسب.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص322، تحت «شرح المفردات: «آبائك»»","url":""}]},{"id":"s2-536","number":536,"surah":2,"verses":[133],"references":[{"surah":2,"verses":[133]}],"verseLabel":"البقرة: 133","question":"ما سرّ إعادة لفظ ﴿إله﴾ ثم وصفه بالوحدة في قولهم: ﴿إِلَهَكَ وَإِلَهَ آبَائِكَ... إِلَهًا وَاحِدًا﴾؟","answer":"أعيد لفظ ﴿إلهًا﴾ ليُبنى عليه الوصف ﴿واحدًا﴾، فصرحوا بوحدة المعبود بعد ذكر إله يعقوب وآبائه، ولم تكن الإعادة لمجرد التوكيد اللفظي.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص326، تحت «بلاغة إعادة لفظ «إله» ووصفه «واحدًا»»","url":""}]},{"id":"s2-537","number":537,"surah":2,"verses":[133],"references":[{"surah":2,"verses":[133]}],"verseLabel":"البقرة: 133","question":"ما دلالة الجملة الاسمية وتقديم ﴿له﴾ في قولهم: ﴿وَنَحْنُ لَهُ مُسْلِمُونَ﴾؟","answer":"الجملة الاسمية تدل على الثبات والاستمرار، وتقديم ﴿له﴾ يفيد القصر؛ أي نحن مسلمون له وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص327، تحت «تقديم المتعلق على الخبر يفيد القصر»","url":""}]},{"id":"s2-538","number":538,"surah":2,"verses":[134],"references":[{"surah":2,"verses":[134]}],"verseLabel":"البقرة: 134","question":"ما سرّ تكرار قوله تعالى: ﴿تِلْكَ أُمَّةٌ قَدْ خَلَتْ لَهَا مَا كَسَبَتْ...﴾ في الآيتين 134 و141؟","answer":"كرر النص بعد عرض دعوى اليهود والنصارى ليقطع التعلق بالأنساب من الجهتين: فعمل الآباء لهم، وعمل المخاطبين لهم، ولا يغني أحد عن أحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص380–381، تحت «فائدة تكرار آية: «تلك أمة قد خلت لها ما كسبت»»","url":""}]},{"id":"s2-539","number":539,"surah":2,"verses":[134],"references":[{"surah":2,"verses":[134]}],"verseLabel":"البقرة: 134","question":"ما سرّ التعبير في قوله تعالى: ﴿تِلْكَ أُمَّةٌ قَدْ خَلَتْ﴾ باسم الإشارة للبعيد؟","answer":"البعد يلحظ انقضاء زمنهم وعلو منزلة الصالحين منهم معًا، ويوقظ المخاطب من الاتكال على تاريخ لم يعشه. مهما عظم السابقون فقد عبروا إلى حسابهم، وبقي على الحاضرين أن يصنعوا عملهم هم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص330، تحت «دلالة التعبير بلفظ الإشارة «تلك» الدال على البعد»","url":""}]},{"id":"s2-540","number":540,"surah":2,"verses":[134],"references":[{"surah":2,"verses":[134]}],"verseLabel":"البقرة: 134","question":"ما دلالة تقديم ﴿لها﴾ و﴿لكم﴾ في قوله تعالى: ﴿لَهَا مَا كَسَبَتْ وَلَكُمْ مَا كَسَبْتُمْ﴾؟","answer":"التقديم يقصر كسب كل جماعة عليها: حسنات الآباء لا تعبر آليًا إلى الأبناء، وذنوبهم لا تحمل على غير فاعلها. وفي المقابلة قطع لأطماع من جعل النسب رصيدًا يغنيه عن الإيمان والعمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص331، تحت «فائدة تقديم المسند على المسند إليه»","url":""}]},{"id":"s2-541","number":541,"surah":2,"verses":[134],"references":[{"surah":2,"verses":[134]}],"verseLabel":"البقرة: 134","question":"ما فائدة قوله تعالى: ﴿وَلَا تُسْأَلُونَ عَمَّا كَانُوا يَعْمَلُونَ﴾ بعد قوله: ﴿لَهَا مَا كَسَبَتْ وَلَكُمْ مَا كَسَبْتُمْ﴾؟","answer":"أكدت الجملة استقلال المسؤولية من جهة الحساب بعد أن قررته من جهة الملك: لا تملكون كسبهم ولا تسألون عن عملهم. والزيادة تغلق الوهمين معًا؛ لا ينفعكم فضلهم بلا اقتداء، ولا يصح أن تتخذوا أخطاءهم عذرًا لتقصيركم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص331، تحت «فائدة نفي السؤال عن عملهم التوكيد»","url":""}]},{"id":"s2-542","number":542,"surah":2,"verses":[135],"references":[{"surah":2,"verses":[135]}],"verseLabel":"البقرة: 135","question":"ما سرّ جمع قول الفريقين في قوله تعالى: ﴿وَقَالُوا كُونُوا هُودًا أَوْ نَصَارَى تَهْتَدُوا﴾؟","answer":"القول موزع على الفريقين: اليهود قالوا كونوا هودًا، والنصارى قالوا كونوا نصارى. و﴿أو﴾ فصلت الدعوتين، وفي العبارة احتباك؛ حُذف ﴿تهتدوا﴾ من الأولى و﴿كونوا﴾ من الثانية لدلالة المذكور عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص343، تحت «بلاغة الاحتباك»","url":""}]},{"id":"s2-543","number":543,"surah":2,"verses":[135],"references":[{"surah":2,"verses":[135]}],"verseLabel":"البقرة: 135","question":"ما سرّ مجيء الرد بقوله تعالى: ﴿بَلْ مِلَّةَ إِبْرَاهِيمَ﴾ من غير ذكر فعل؟","answer":"جاءت ﴿بل﴾ لإبطال دعوى الفريقين والانتقال إلى الملة الحق، وحذف الفعل اعتمادًا على السياق؛ والتقدير: بل نتبع ملة إبراهيم، أو: بل اتبعوا ملة إبراهيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص344، تحت «أثر حرف الإضراب في تقرير المعاني»","url":""}]},{"id":"s2-544","number":544,"surah":2,"verses":[135],"references":[{"surah":2,"verses":[135]}],"verseLabel":"البقرة: 135","question":"ما دلالة وصف إبراهيم بأنه ﴿حَنِيفًا﴾؟","answer":"الحنيف هو المائل عن الأديان الباطلة والشرك إلى الدين المستقيم والتوحيد الخالص؛ فالوصف ينفي عن إبراهيم ما نسبه إليه الفريقان.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص335، تحت «شرح المفردات: «حنيفًا»»","url":""}]},{"id":"s2-545","number":545,"surah":2,"verses":[135],"references":[{"surah":2,"verses":[135]}],"verseLabel":"البقرة: 135","question":"ما فائدة قوله تعالى: ﴿وَمَا كَانَ مِنَ الْمُشْرِكِينَ﴾ بعد وصف إبراهيم بأنه ﴿حَنِيفًا﴾؟","answer":"وصف ﴿حنيفًا﴾ يثبت ميل إبراهيم إلى التوحيد، ثم جاء ﴿وما كان من المشركين﴾ احتراسًا يقطع كل احتمال لإدخاله في شيء من الشرك، ويرد دعوى من نسبه إلى ملل حدثت بعده.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص345، تحت «بلاغة الفاصلة القرآنية في تقرير المعاني السياقية»","url":""}]},{"id":"s2-546","number":546,"surah":2,"verses":[136],"references":[{"surah":2,"verses":[136]}],"verseLabel":"البقرة: 136","question":"ما سرّ التعبير في قوله تعالى في البقرة ﴿قولوا آمنا﴾، وفي آل عمران ﴿قل آمنا﴾؟","answer":"جاءت ﴿قولوا﴾ في البقرة لأن الخطاب عام لجميع المؤمنين المقصودين بالأمر، وجاءت ﴿قل﴾ في آل عمران لأن الأمر موجه ابتداء إلى النبي ﷺ، وإن كان مضمون الإيمان يشمل من اتبعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص352، تحت «توجيه المتشابه اللفظي»","url":""}]},{"id":"s2-547","number":547,"surah":2,"verses":[136],"references":[{"surah":2,"verses":[136]}],"verseLabel":"البقرة: 136","question":"ما سرّ التعبير هنا في قوله تعالى ﴿وما أنزل إلينا﴾، وفي آل عمران ﴿وما أنزل علينا﴾؟","answer":"في البقرة خوطب المؤمنون جميعًا، فناسب ﴿إلينا﴾ لأن الوحي ينتهي إليهم بواسطة النبي ﷺ. وفي آل عمران صدر الخطاب بـ﴿قل﴾ للنبي ﷺ، فناسب ﴿علينا﴾ باعتبار نزول الوحي عليه من فوق؛ والاختلاف اختلاف اعتبار وتفنن في العبارة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص352، تحت «توجيه المتشابه اللفظي»","url":""}]},{"id":"s2-548","number":548,"surah":2,"verses":[136],"references":[{"surah":2,"verses":[136]},{"surah":3,"verses":[84]}],"verseLabel":"البقرة: 136، آل عمران: 84","question":"ما سرّ تكرار ﴿وَمَا أُوتِيَ﴾ قبل ﴿النَّبِيُّونَ﴾ في البقرة، وحذفها في نظيرها من آل عمران؟","answer":"البقرة خطاب للمؤمنين، ومقامها تسجيل إيمانهم المفصل بجميع ما أوتي الأنبياء من غير تفريق، فناسب توكيد فعل الإيتاء مرة أخرى. أما آل عمران فالخطاب فيه صادر من النبي ﷺ، وهو منزه أصلًا عن التفريق بين الرسل؛ فلم يحتج المقام إلى التوكيد نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص407–408، تحت عنوان «توجيه التشابه اللفظي بين قوله: ﴿وما أنزل علينا وما أنزل على إبراهيم﴾ وقوله: ﴿قولوا آمنا بالله وما أنزل إلينا وما أنزل إلى إبراهيم﴾»","url":""}]},{"id":"s2-549","number":549,"surah":2,"verses":[136],"references":[{"surah":2,"verses":[136]}],"verseLabel":"البقرة: 136","question":"ما سرّ تقديم الإيمان بما أنزل إلى المسلمين على ذكر ما أنزل إلى الأنبياء السابقين؟","answer":"قُدّم ما أنزل إلى المسلمين لأنه الكتاب الذي خوطبوا به ويلزمهم اتباعه، ومن طريقه عرفوا صدق ما أنزل إلى الأنبياء السابقين؛ ثم عطف عليه سائر الوحي بيانًا لوحدته.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص350، تحت «دلالة تقديم القرآن على سائر الكتب السماوية»","url":""}]},{"id":"s2-550","number":550,"surah":2,"verses":[136],"references":[{"surah":2,"verses":[136]}],"verseLabel":"البقرة: 136","question":"ما سرّ اختلاف التعبير بين ﴿مَا أُنْزِلَ إِلَيْنَا﴾ و﴿مَا أُوتِيَ مُوسَى وَعِيسَى﴾؟","answer":"عبر بالإنزال مع الوحي المنزل، وبالإيتاء مع موسى وعيسى لأنه أعم وأوسع؛ فيشمل ما أوتياه من الكتابين والمعجزات الحسية، وقد اشتهرا بكليهما، فناسبهما لفظ الإيتاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص349، تحت عنوان «سر التعبير بـ﴿أنزل﴾ و﴿أوتي﴾»","url":""}]},{"id":"s2-551","number":551,"surah":2,"verses":[136],"references":[{"surah":2,"verses":[136]}],"verseLabel":"البقرة: 136","question":"ما سرّ ترتيب إبراهيم وإسماعيل وإسحاق ويعقوب والأسباط قبل موسى وعيسى؟","answer":"رتبهم بحسب الأصل والنسب والتاريخ: إبراهيم أبو الملة، ثم ابناه إسماعيل وإسحاق، ثم يعقوب وذريته، ثم الرسالات الكبرى في بني إسرائيل. وهذا التدرج يبين أن الوحي سلسلة واحدة لا ملكية حصرية لفريق متأخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص348، تحت «ترتيب الأنبياء زمانيًا ودلاليًا على طريقة التدلي»","url":""}]},{"id":"s2-552","number":552,"surah":2,"verses":[136],"references":[{"surah":2,"verses":[136]}],"verseLabel":"البقرة: 136","question":"ما سرّ التعبير في قوله تعالى: ﴿لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِنْهُمْ﴾، مع أن للأنبياء درجات مختلفة؟","answer":"المنفي هو التفريق في أصل الإيمان والقبول، لا تفاوت الفضل والخصائص؛ فلا يؤمن المسلم ببعض ويكفر ببعض كما فعلت جماعات من أهل الكتاب. كلمة ﴿أحد﴾ في سياق النفي تستغرق كل فرد، فتغلق أي استثناء من التصديق.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص351، تحت «بلاغة جملة: «لا نفرق بين أحد منهم»»","url":""}]},{"id":"s2-553","number":553,"surah":2,"verses":[136],"references":[{"surah":2,"verses":[136]}],"verseLabel":"البقرة: 136","question":"ما مناسبة ختم آية الإيمان بالكتب والرسل بقوله: ﴿وَنَحْنُ لَهُ مُسْلِمُونَ﴾؟","answer":"لأن التصديق لا يكتمل بلا انقياد؛ فبعد بيان ما تؤمن به الأمة قرر حالها العملي تجاه مصدر الوحي. وتقديم ﴿له﴾ يقصر الإسلام على الله، والجملة الاسمية تثبت هذا الخضوع صفةً دائمة لا موقفًا مؤقتًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص351، تحت «تشابه الأطراف في الفاصلة «ونحن له مسلمون»»","url":""}]},{"id":"s2-554","number":554,"surah":2,"verses":[137],"references":[{"surah":2,"verses":[137]}],"verseLabel":"البقرة: 137","question":"ما سرّ التعبير في قوله تعالى: ﴿فسيكفيكهم الله﴾ بالسين لا بسوف؟","answer":"السين أقرب زمنًا وأوجز، فحملت وعدًا سريعًا مطمئنًا بكفاية عداوتهم، وناسبت مقام المواجهة المباشرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص355، تحت «بلاغة الفاء في قوله: «فسيكفيكهم الله»، ودلالتها البيانية»","url":""}]},{"id":"s2-555","number":555,"surah":2,"verses":[137],"references":[{"surah":2,"verses":[137]}],"verseLabel":"البقرة: 137","question":"ما وجه التعبير في قوله تعالى: ﴿فَإِنْ آمَنُوا بِمِثْلِ مَا آمَنْتُمْ بِهِ﴾؛ وهل للإيمان الحق «مثل» آخر؟","answer":"ليس المراد إثبات مثل آخر للإيمان الحق؛ فالحق واحد. وإنما سيق الشرط على طريق التبكيت وإرخاء العنان في المجادلة: فإن آمنوا بما آمنتم به من الإيمان الجامع بالله ووحيه ورسله فقد اهتدوا، وإلا قامت عليهم الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص353–354، تحت «دلالة اقتران الشرط بالفاء، في قوله: «فإن آمنوا بمثل ما آمنتم به»»","url":""}]},{"id":"s2-556","number":556,"surah":2,"verses":[137],"references":[{"surah":2,"verses":[137]}],"verseLabel":"البقرة: 137","question":"لماذا قال: ﴿فإن آمنوا بمثل ما آمنتم به﴾ بأداة ﴿إن﴾، ولم يقل: «فإذا آمنوا»؟","answer":"لأن إيمانهم في هذا المقام غير متحقق الوقوع؛ فجاءت «إن» بما يلائم عدم الجزم بحصوله، وأشارت إلى أن منهم من يؤمن ومنهم من يتولى.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص354، تحت «سر التعبير بأداة (إن) دون (إذا)»","url":""}]},{"id":"s2-557","number":557,"surah":2,"verses":[137],"references":[{"surah":2,"verses":[137]}],"verseLabel":"البقرة: 137","question":"ما الذي يصوّره قوله: ﴿فإنما هم في شقاق﴾، بجمع ﴿إنما﴾ و﴿في﴾؟","answer":"يقصر موقفهم بعد التولي على الشقاق والعداوة للحق، ويصوّرهم حرف «في» كأن الشقاق محيط بهم ومستولٍ عليهم؛ فتتأكد شدة المخالفة ورسوخها.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص355، تحت «سر القصر بإنما في قوله: «فإنما هم في شقاق»»","url":""}]},{"id":"s2-558","number":558,"surah":2,"verses":[137],"references":[{"surah":2,"verses":[137]}],"verseLabel":"البقرة: 137","question":"ما سرّ التعبير بالكفاية في قوله تعالى: ﴿فَسَيَكْفِيكَهُمُ اللَّهُ﴾، دون التصريح بالنصر عليهم؟","answer":"وعده الله بالكفاية ليطمئنه إلى أنه يتولى دفع شرهم الحاصل من شقاقهم، وفي ذلك تسلية وتثبيت وضمان للتأييد؛ فالله وحده الكافي والحافظ وعليه يكون التوكل.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص355–356، تحت «بلاغة الفاء في قوله: «فسيكفيكهم الله» ودلالاتها البيانية»","url":""}]},{"id":"s2-559","number":559,"surah":2,"verses":[137],"references":[{"surah":2,"verses":[137]}],"verseLabel":"البقرة: 137","question":"ما مناسبة ختم الوعد بقوله تعالى: ﴿وَهُوَ السَّمِيعُ الْعَلِيمُ﴾؟","answer":"يسمع أقوالهم ومجادلاتهم ويعلم كيدهم الخفي وحال الرسول، فلا يفوته ما يحتاج إلى كفاية. والتعريف وضمير الفصل يفيدان كمال الصفتين واختصاصه بالسمع والعلم المحيطين اللذين يقوم عليهما الوعد.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص356، تحت «بلاغة الفاصلة القرآنية: «وهو السميع العليم»»","url":""}]},{"id":"s2-560","number":560,"surah":2,"verses":[138],"references":[{"surah":2,"verses":[138]}],"verseLabel":"البقرة: 138","question":"ما سرّ التعبير عن الدين بقوله تعالى: ﴿صِبْغَةَ اللَّهِ﴾؟","answer":"سُمِّي دين الله صبغةً على سبيل المشاكلة لزعم النصارى أن ماء المعمودية يكسبهم صفة النصرانية؛ فرد القرآن بأن الصبغة الحقيقية دين الله وفطرته، فهي التي تميز المؤمن لا الطقس الشكلي.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص359، تحت «الاستعارة التصريحية في قوله تعالى: «صبغة الله»»","url":""}]},{"id":"s2-561","number":561,"surah":2,"verses":[138],"references":[{"surah":2,"verses":[138]}],"verseLabel":"البقرة: 138","question":"ما سرّ التعبير في قوله تعالى: ﴿وَمَنْ أَحْسَنُ مِنَ اللَّهِ صِبْغَةً﴾ بصيغة المفاضلة، وهل توجد صبغة حسنة تقاربها؟","answer":"جاءت صيغة التفضيل في استفهام إنكاري توبيخي ينفي أن تكون صبغة أحسن من صبغة الله؛ بل صبغته بالغة الحسن، ولا تقاربها صبغة سواها، ولو توهم أصحابها فيها خيرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص359، تحت «غرض الاستفهام في قوله: «ومن أحسن من الله صبغة»»","url":""}]},{"id":"s2-562","number":562,"surah":2,"verses":[138],"references":[{"surah":2,"verses":[138]}],"verseLabel":"البقرة: 138","question":"ما مناسبة قوله: ﴿وَنَحْنُ لَهُ عَابِدُونَ﴾ بعد قوله قبل آيتين: ﴿وَنَحْنُ لَهُ مُسْلِمُونَ﴾؟","answer":"كل فاصلة تلائم ما قبلها: «ونحن له مسلمون» تناسب الإيمان بالله وما أنزل، بما يقتضيه من الانقياد لأمره؛ و«ونحن له عابدون» تلائم «صبغة الله» التي هي دينه، فتقرر أثر هذا الدين في عبادة الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص374، تحت «جمال الاتساق في فواصل الآيات»","url":""}]},{"id":"s2-563","number":563,"surah":2,"verses":[139],"references":[{"surah":2,"verses":[139]}],"verseLabel":"البقرة: 139","question":"ما دلالة قوله تعالى: ﴿أَتُحَاجُّونَنَا فِي اللَّهِ﴾؟","answer":"حذف المضاف في ﴿في الله﴾، والتقدير: في دين الله أو شريعته أو شأنه؛ وفي هذا الإيجاز توسيع لمحل المحاجة ومبالغة في تصوير جهلهم وشناعة جدالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص370، تحت «نكتة الإيجاز بالحذف في قوله: «أتحاجوننا في الله»»","url":""}]},{"id":"s2-564","number":564,"surah":2,"verses":[139],"references":[{"surah":2,"verses":[139]}],"verseLabel":"البقرة: 139","question":"ما سرّ التعبير في قوله تعالى: ﴿وَهُوَ رَبُّنَا وَرَبُّكُمْ﴾؟","answer":"قرر أن الله رب الفريقين جميعًا، فلا وجه لادعاء أهل الكتاب اختصاصهم بالقرب منه؛ وإنما مناط الترجيح إخلاص العبادة والعمل الصالح.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص371، تحت «ترشيح الإنكار بالأسلوب الخبري: «وهو ربنا وربكم ولنا أعمالنا»»","url":""}]},{"id":"s2-565","number":565,"surah":2,"verses":[139],"references":[{"surah":2,"verses":[139]}],"verseLabel":"البقرة: 139","question":"ما دلالة تقديم ﴿لنا﴾ و﴿لكم﴾ في قوله تعالى: ﴿وَلَنَا أَعْمَالُنَا وَلَكُمْ أَعْمَالُكُمْ﴾؟","answer":"التقديم يقصر عمل كل فريق عليه ويفصل المسؤولية: لا يغني انتساب أحد إلى نبي عن عمله، ولا يحمل المؤمن تبعة تحريف غيره. وفي المقابلة هدوء حاسم؛ بدل النزاع في الأنساب يعاد كل إنسان إلى رصيده الحقيقي.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص372، تحت «التقديم للقصر في قوله: «ولنا أعمالنا ولكم أعمالكم»»","url":""}]},{"id":"s2-566","number":566,"surah":2,"verses":[139],"references":[{"surah":2,"verses":[139]}],"verseLabel":"البقرة: 139","question":"ما سرّ التعبير في قوله تعالى: ﴿وَنَحْنُ لَهُ مُخْلِصُونَ﴾، دون أن يقال: «ونحن مؤمنون به»؟","answer":"اختير الإخلاص لأنه يثبت إفراد الله بالإيمان والطاعة والعبادة، وينفي الشرك، ويشمل إخلاص النية في العبادات والمعاملات؛ وتقديم ﴿له﴾ والجملة الاسمية يفيدان القصر والثبات.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص373، تحت «بلاغة الفاصلة: «ونحن له مخلصون»»","url":""}]},{"id":"s2-567","number":567,"surah":2,"verses":[140],"references":[{"surah":2,"verses":[140]}],"verseLabel":"البقرة: 140","question":"كيف يزعمون أن إبراهيم وإسماعيل وإسحاق ويعقوب كانوا يهودًا أو نصارى، وقد عاشوا قبل ظهور اليهودية والنصرانية؟","answer":"صاغ القرآن الدعوى في سؤال يكشف تناقضها الزمني بذاته؛ فهؤلاء الآباء سبقوا التوراة والإنجيل والانقسامات اللاحقة. لذلك كان انتسابهم إلى الإسلام الحنيف أصدق، أما جرّهم إلى أسماء حدثت بعدهم فإسقاط للتاريخ على الهوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص378–379، تحت «براعة الاستفهام التقريري في قوله: «أأنتم أعلم أم الله»»","url":""}]},{"id":"s2-568","number":568,"surah":2,"verses":[140],"references":[{"surah":2,"verses":[140]}],"verseLabel":"البقرة: 140","question":"ما سرّ التعبير في قوله تعالى: ﴿أَأَنْتُمْ أَعْلَمُ أَمِ اللَّهُ﴾، دون أن يقال: «والله أعلم منكم»؟","answer":"الاستفهام يجبرهم على مواجهة أحد خيارين لا ثالث لهما: علمهم المحدود أم علم الله الذي أوحى بحقيقة الأنبياء. وهو أبلغ من الخبر؛ لأن الخصم نفسه لا يستطيع أن يختار أنه أعلم من الله، فتسقط دعواه بإقراره.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص378، تحت «براعة الاستفهام التقريري في قوله: «قل أأنتم أعلم أم الله»»","url":""}]},{"id":"s2-569","number":569,"surah":2,"verses":[140],"references":[{"surah":2,"verses":[140]}],"verseLabel":"البقرة: 140","question":"ما سرّ التعبير في قوله تعالى: ﴿وَمَنْ أَظْلَمُ مِمَّنْ كَتَمَ شَهَادَةً عِنْدَهُ مِنَ اللَّهِ﴾؟","answer":"عظّم جرمهم لأنهم كتموا شهادة ثابتة عندهم مصدرها الله؛ فاجتمع علمهم بها، وشرف مصدرها، وتعمد حبسها أو تحريف أدائها، فكان ذلك من أشد الظلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص379، تحت «غرض الاستفهام في قوله: «ومن أظلم ممن كتم شهادة عنده من الله»»","url":""}]},{"id":"s2-570","number":570,"surah":2,"verses":[140],"references":[{"surah":2,"verses":[140]}],"verseLabel":"البقرة: 140","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿وَمَا اللَّهُ بِغَافِلٍ عَمَّا تَعْمَلُونَ﴾ دون التصريح بالعقوبة؟","answer":"نفي الغفلة وعيد أوسع؛ فهو يحيط بالكتمان وبالدوافع والآثار وسائر الأعمال، ويترك نوع الجزاء لهول ما يستحقون. والباء تقوي النفي: لا يغيب عنه شيء حتى لو أخفوه عن الناس أو داخل الكتب.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص380، تحت «دلالة فاصلة الآية الكريمة: «وما الله بغافل عما تعملون»»","url":""}]},{"id":"s2-571","number":571,"surah":2,"verses":[142],"references":[{"surah":2,"verses":[142]}],"verseLabel":"البقرة: 142","question":"ما دلالة الاستفهام بـ﴿ما﴾ في قولهم: ﴿مَا وَلَّاهُمْ عَنْ قِبْلَتِهِمُ﴾، دون ﴿من﴾؟","answer":"﴿ما﴾ هنا للسؤال عن سبب التحويل: أي أيُّ شيء ولّاهم وصرفهم عن قبلتهم؟ أما ﴿من﴾ فتسأل عن الفاعل، والفاعل معلوم؛ فموضع اعتراضهم هو علة التحويل.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص394، تحت «إيثار الاستفهام بـ«ما» دون «من» في «ما ولاهم»»","url":""}]},{"id":"s2-572","number":572,"surah":2,"verses":[142],"references":[{"surah":2,"verses":[142]}],"verseLabel":"البقرة: 142","question":"ما سرّ التعبير في قوله تعالى: ﴿سَيَقُولُ السُّفَهَاءُ﴾ قبل أن يقولوا اعتراضهم فعلًا؟","answer":"أخبر بالاعتراض مستقبلًا ليهيئ النبي والمؤمنين له، فلا يفاجئهم ولا يزعزعهم، وليكون وقوعه كما أخبر آية على صدق الوحي. كما يدل المضارع على أن مقالتهم ليست لحظة عابرة بل عادة يجددونها.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص391، تحت «دلالة التعبير بالمستقبل في «سيقول»»","url":""}]},{"id":"s2-573","number":573,"surah":2,"verses":[142],"references":[{"surah":2,"verses":[142]}],"verseLabel":"البقرة: 142","question":"ما سرّ وصف المعترضين بأنهم ﴿السُّفَهَاءُ مِنَ النَّاسِ﴾ قبل الرد على اعتراضهم؟","answer":"السفه خفة العقل واضطراب الرأي، وقد كشف اعتراضهم هذا الوصف؛ إذ اعترضوا على حكم المالك الذي له المشرق والمغرب. وقيد ﴿من الناس﴾ يبين أنهم طائفة من الناس لا جميعهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص391، تحت «فائدة اختيار لفظ «السفهاء»»","url":""}]},{"id":"s2-574","number":574,"surah":2,"verses":[142],"references":[{"surah":2,"verses":[142]}],"verseLabel":"البقرة: 142","question":"ما سرّ حكاية اعتراضهم بضمير الغائب: ﴿مَا وَلَّاهُمْ عَنْ قِبْلَتِهِمُ﴾؟","answer":"صوّرهم يتناجون عن المؤمنين من وراء ظهورهم لا يطلبون جوابًا صادقًا منهم؛ فالغيبة تلائم السخرية والإرجاف. وهي تكشف أنهم يتخذون التحول مادة حديث، لا مسألة علم يسألون أصحابها مباشرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص395، تحت «فائدة التعبير بضمير الغيبة «ما ولاهم عن قبلتهم»»","url":""}]},{"id":"s2-575","number":575,"surah":2,"verses":[142],"references":[{"surah":2,"verses":[142]}],"verseLabel":"البقرة: 142","question":"ما دلالة إضافة القبلة إلى المسلمين في قوله: ﴿عَنْ قِبْلَتِهِمُ الَّتِي كَانُوا عَلَيْهَا﴾ مع انتقالهم عنها؟","answer":"أضيفت القبلة إليهم لأنهم استقبلوها زمنًا طويلًا واختصوا بها، فصحت نسبتها إليهم؛ وتركهم التوجه إليها بعد التحويل لا يسلبها كونها قبلتهم السابقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص396، تحت «دلالة إضافة القبلة إلى الضمير «قبلتهم»»","url":""}]},{"id":"s2-576","number":576,"surah":2,"verses":[142],"references":[{"surah":2,"verses":[142]}],"verseLabel":"البقرة: 142","question":"ما مناسبة الجواب بقوله تعالى: ﴿قُلْ لِلَّهِ الْمَشْرِقُ وَالْمَغْرِبُ﴾ دون ذكر سبب التحويل تفصيلًا؟","answer":"أعادهم إلى الأصل الذي يبطل الاعتراض كله: الجهات ملك لله، وهو الذي يحدد وجهة العبادة في الوقت الذي يشاء. فإذا ثبت سلطان المالك لم يعد تبديل الجهة تناقضًا، بل انتقالًا بين أمرين صحيحين من مشرع واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص398، تحت «سر العدول عن ذكر القبلة إلى ذكر المشرق والمغرب في قوله: «لله المشرق والمغرب»»","url":""}]},{"id":"s2-577","number":577,"surah":2,"verses":[142],"references":[{"surah":2,"verses":[142]}],"verseLabel":"البقرة: 142","question":"ما دلالة اختيار الاسم الموصول ﴿من﴾ في قوله ﴿يهدي من يشاء﴾؟","answer":"تفيد ﴿من﴾ العموم من غير تخصيص بأشخاص معينين، وتشمل الذكور والإناث دون حاجة إلى التغليب؛ بخلاف الذي أو الذين إذا أريد بهما أشخاص محددون.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص399، تحت عنوان «دلالة التعبير بالاسم الموصول ﴿من﴾»","url":""}]},{"id":"s2-578","number":578,"surah":2,"verses":[142],"references":[{"surah":2,"verses":[142]}],"verseLabel":"البقرة: 142","question":"ما دلالة وصف الصراط بأنه ﴿مُسْتَقِيمٍ﴾ في سياق تحويل القبلة؟","answer":"الصراط الطريق الواضح، و﴿مستقيم﴾ يدل على اعتداله وعدم انحرافه. وفي سياق القبلة يقرر أن الهداية ليست إلى جهة مجردة، بل إلى طريق الطاعة الموصل إلى الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص401، تحت «مستقيم وقيم»","url":""}]},{"id":"s2-579","number":579,"surah":2,"verses":[143],"references":[{"surah":2,"verses":[143]}],"verseLabel":"البقرة: 143","question":"ما سرّ التعبير في قوله تعالى: ﴿وما كان الله ليضيع إيمانكم﴾ بنفي الكون، لا: لن يضيع؟","answer":"صيغة ﴿ما كان الله ليضيع﴾ تنفي وقوع الإضاعة نفيًا مؤكدًا، وتفيد أن ذلك لا يليق بحكمته ورحمته؛ فهي أبلغ من نفي وقوعه في المستقبل وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص420، تحت «نكتة نفي الكينونة دون نفي الفعل في قوله: «وما كان الله ليضيع إيمانكم»»","url":""}]},{"id":"s2-580","number":580,"surah":2,"verses":[143],"references":[{"surah":2,"verses":[143]},{"surah":22,"verses":[78]}],"verseLabel":"البقرة: 143، الحج: 78","question":"ما سرّ التعبير في قوله تعالى في البقرة: ﴿لِتَكُونُوا شُهَدَاءَ عَلَى النَّاسِ وَيَكُونَ الرَّسُولُ عَلَيْكُمْ شَهِيدًا﴾ فقدم شهادة الأمة، بينما قال في الحج: ﴿لِيَكُونَ الرَّسُولُ شَهِيدًا عَلَيْكُمْ وَتَكُونُوا شُهَدَاءَ عَلَى النَّاسِ﴾ فقدم شهادة الرسول؟","answer":"قدمت شهادة الأمة على الناس تشريفًا لها وإثباتًا لمنزلتها بين الأمم، ثم خصت بأن رسولها وحده هو الشهيد عليها؛ فجمعت الآية تكريم الأمة وبيان اختصاص شهادة الرسول بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص387، تحت «توجيه المتشابه اللفظي»","url":""}]},{"id":"s2-581","number":581,"surah":2,"verses":[143],"references":[{"surah":2,"verses":[143]}],"verseLabel":"البقرة: 143","question":"إلى ماذا يشير قوله تعالى: ﴿وَكَذَلِكَ جَعَلْنَاكُمْ أُمَّةً وَسَطًا﴾؟","answer":"تشير ﴿كذلك﴾ إلى الهداية المذكورة قبلها؛ فكما هدى الله هذه الأمة إلى صراط مستقيم جعلها أمة عدل وخيرية مؤهلة للشهادة على الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص409، تحت «دلالة اسم الإشارة في قوله «وكذلك»»","url":""}]},{"id":"s2-582","number":582,"surah":2,"verses":[143],"references":[{"surah":2,"verses":[143]}],"verseLabel":"البقرة: 143","question":"لماذا وصف الأمة بأنها ﴿وَسَطًا﴾، ولم يقل: «خيارًا» أو «عادلة»؟","answer":"لأن ﴿وسطًا﴾ تجمع الخيرية والعدل والاعتدال معًا؛ فالخصال المحمودة أوساط بين طرفين مذمومين، وبذلك تؤهل الوسطية الأمة للشهادة، فهي أوسع من وصف واحد كـ«خيارًا» أو «عادلة».","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص410، تحت «إيثار الوصف بالمصدر المذكر «أمة وسطًا»»","url":""}]},{"id":"s2-583","number":583,"surah":2,"verses":[143],"references":[{"surah":2,"verses":[143]}],"verseLabel":"البقرة: 143","question":"ما علاقة شهادة الأمة بشهادة الرسول في قوله: ﴿لِتَكُونُوا شُهَدَاءَ عَلَى النَّاسِ وَيَكُونَ الرَّسُولُ عَلَيْكُمْ شَهِيدًا﴾؟","answer":"جعل الله الأمة الوسط عدولًا تشهد على الأمم بأن رسلها بلغتها، ويشهد الرسول على هذه الأمة بأنه بلغها؛ فشهادتها على الناس متفرعة عن تلقيها الوحي، وشهادة الرسول تزكي قيامها بهذه الأمانة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص413، تحت «جمال المقابلة بين الجمل»","url":""}]},{"id":"s2-584","number":584,"surah":2,"verses":[143],"references":[{"surah":2,"verses":[143]}],"verseLabel":"البقرة: 143","question":"ما سرّ التعبير في قوله تعالى عن بيت المقدس: ﴿الْقِبْلَةَ الَّتِي كُنْتَ عَلَيْهَا﴾، ولم يسمه؟","answer":"عدل عن تسمية بيت المقدس إلى ﴿القبلة التي كنت عليها﴾ ليشاكل عبارة المعترضين قبلها: ﴿قبلتهم التي كانوا عليها﴾؛ فيأتي الرد مماثلًا للفظهم، ويربط أجزاء الخطاب ويقوي تماسكه.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص414، تحت «حذف المضاف في قوله: «وما جعلنا القبلة التي كنت عليها»»","url":""}]},{"id":"s2-585","number":585,"surah":2,"verses":[143],"references":[{"surah":2,"verses":[143]}],"verseLabel":"البقرة: 143","question":"ما المراد بقوله تعالى: ﴿إِلَّا لِنَعْلَمَ مَنْ يَتَّبِعُ الرَّسُولَ﴾ مع إحاطة علم الله بالأشياء قبل وقوعها؟","answer":"ليس المراد حدوث علم لم يكن؛ فعلم الله سابق محيط، وإنما المراد ظهور المعلوم في الواقع وتميز المتبع من المنقلب، حتى يتعلق الجزاء بالفعل الواقع المشاهد.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص415، تحت «القصر في قوله: «وما جعلنا القبلة التي كنت عليها إلا لنعلم»»","url":""}]},{"id":"s2-586","number":586,"surah":2,"verses":[143],"references":[{"surah":2,"verses":[143]}],"verseLabel":"البقرة: 143","question":"ما سرّ التعبير في قوله تعالى: ﴿مَنْ يَتَّبِعُ الرَّسُولَ﴾، دون أن يقال: «من يطيع الله»؟","answer":"لأن موضع الامتحان أمر وصلهم بواسطة الرسول وقد خالف ما ألفوه؛ فظهر صدق الإيمان في اتباعه عند التحويل. ووصفه بالرسالة يقرر أن اتباعه ليس طاعة بشر من ذاته، بل طاعة المرسل الذي بلّغه الأمر.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص412، تحت «إيثار التعبير بالرسول»","url":""}]},{"id":"s2-587","number":587,"surah":2,"verses":[143],"references":[{"surah":2,"verses":[143]}],"verseLabel":"البقرة: 143","question":"ما سرّ التعبير في قوله تعالى عن المرتد: ﴿يَنْقَلِبُ عَلَى عَقِبَيْهِ﴾، دون أن يقال: «يرتد»؟","answer":"الصورة تجعله شخصًا استدار فجأة على مؤخر قدميه فعاد من حيث جاء، بعد أن كان وجهه إلى الهدى؛ وفيها خطر السقوط والانتكاس. فهي لا تخبر عن الرجوع فقط، بل تجعل القارئ يراه حركةً مهينة إلى الخلف.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص418، تحت «نكتة المجاز في «على عقبيه»»","url":""}]},{"id":"s2-588","number":588,"surah":2,"verses":[143],"references":[{"surah":2,"verses":[143]}],"verseLabel":"البقرة: 143","question":"ما سرّ التعبير في قوله تعالى: ﴿وَإِنْ كَانَتْ لَكَبِيرَةً﴾، وما الشيء الذي كان كبيرًا؟","answer":"يعود الضمير إلى القبلة أو التولية والتحويل؛ أي كانت شاقة ثقيلة على النفوس التي ألفت جهةً أو تعلقت بعادة وقومية. ووصفت بالكبر لتكشف حقيقة الامتحان: الطاعة تظهر حين يثقل الأمر، لا حين يوافق المألوف.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص419، تحت «مرجع الضمير في قوله: «وإن كانت لكبيرة»»","url":""}]},{"id":"s2-590","number":590,"surah":2,"verses":[143],"references":[{"surah":2,"verses":[143]}],"verseLabel":"البقرة: 143","question":"ما سرّ التعبير في قوله تعالى عن صلواتهم السابقة إلى بيت المقدس: ﴿وَمَا كَانَ اللَّهُ لِيُضِيعَ إِيمَانَكُمْ﴾، فسمّى الصلاة إيمانًا؟","answer":"لأن الصلاة أبرز عمل يصدر عن الإيمان ويصدقه، فأطلق اسم الأصل على ثمرته تشريفًا لها وإثباتًا أن العمل داخل في حقيقة الإيمان. كما طمأنهم أن الطاعة الصحيحة في زمن الأمر لا تبطل حين يتغير الحكم؛ فالله يثيب الامتثال في المرحلتين.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص422، تحت «هداية التعبير عن الصلاة بلفظ الإيمان في «ليضيع إيمانكم»»","url":""}]},{"id":"s2-591","number":591,"surah":2,"verses":[143],"references":[{"surah":2,"verses":[143]}],"verseLabel":"البقرة: 143","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿إِنَّ اللَّهَ بِالنَّاسِ لَرَءُوفٌ رَحِيمٌ﴾؟","answer":"جاءت الخاتمة بعد ذكر مشقة التحويل والخوف على الصلوات السابقة؛ فالرأفة تدفع عنهم ضياع العمل والمشقة، والرحمة توصل إليهم الثواب والخير. والتوكيد يطمئنهم إلى حفظ أعمالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص426، تحت «الرحمة والرأفة»","url":""}]},{"id":"s2-592","number":592,"surah":2,"verses":[144],"references":[{"surah":2,"verses":[144]}],"verseLabel":"البقرة: 144","question":"ما سرّ التعبير في قوله تعالى: ﴿قد نرى تقلب وجهك في السماء﴾ ولم يذكر أن النبي طلب تغيير القبلة؟","answer":"في الآية إظهار لأدب النبي ﷺ؛ إذ كان يقلب وجهه مترقبًا الوحي من غير تصريح بطلب، فعلم الله رغبته وأجابه، وفي ذلك بيان عنايته به.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص432، تحت «دلالة الكناية في قوله: «قد نرى تقلب وجهك»»","url":""}]},{"id":"s2-593","number":593,"surah":2,"verses":[144],"references":[{"surah":2,"verses":[144]}],"verseLabel":"البقرة: 144","question":"ما سرّ التعبير في قوله تعالى: ﴿في السماء﴾ لا: إلى السماء؟","answer":"تفيد ﴿في﴾ أن وجهه كان يتردد في نواحي السماء مرة بعد مرة ترقبًا للوحي، أما ﴿إلى﴾ فقد تدل على مجرد جهة النظر.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص433، تحت «فائدة استعمال حرف الظرفية «في السماء»»","url":""}]},{"id":"s2-594","number":594,"surah":2,"verses":[144],"references":[{"surah":2,"verses":[144]}],"verseLabel":"البقرة: 144","question":"ما سرّ التعبير في قوله تعالى: ﴿شطر المسجد الحرام﴾ لا: شطر الكعبة؟","answer":"المسجد الحرام يشتمل على الكعبة، وهو جهة ظاهرة يمكن أن يتوجه إليها البعيد؛ فناسب الحكم العام للناس في الآفاق، مع كون الكعبة عين القبلة للقريب.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص437، تحت «فائدة ذكر «المسجد الحرام» دون الكعبة»","url":""}]},{"id":"s2-595","number":595,"surah":2,"verses":[144],"references":[{"surah":2,"verses":[144]}],"verseLabel":"البقرة: 144","question":"ما سرّ التعبير في قوله تعالى: ﴿تَقَلُّبَ وَجْهِكَ﴾، دون أن يقال: «رفع وجهك»؟","answer":"لأن التقلب يصور تردد النظر والتطلع إلى الوحي، وذكر الوجه أعم وأشرف وأبلغ من ذكر العين وحدها؛ فدل على دوام التطلع في جهات السماء لا على مجرد رفع عابر.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص432، تحت «دلالة الكناية في قوله: «قد نرى تقلب وجهك»»","url":""}]},{"id":"s2-596","number":596,"surah":2,"verses":[144],"references":[{"surah":2,"verses":[144]}],"verseLabel":"البقرة: 144","question":"ما سرّ التعبير في قوله تعالى: ﴿فَلَنُوَلِّيَنَّكَ قِبْلَةً﴾ بالنون واللام المؤكدتين؟","answer":"جاءت اللام دالة على قسم مضمر، وجاءت نون التوكيد للمبالغة في تحقق الوعد ووقوعه؛ والفاء تربط هذا الوعد بسبب ما قبله من تقلب وجه النبي ﷺ في السماء.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص434، تحت «دلالة الفاء واللام في «فلنولينك قبلة ترضاها»»","url":""}]},{"id":"s2-597","number":597,"surah":2,"verses":[144],"references":[{"surah":2,"verses":[144]}],"verseLabel":"البقرة: 144","question":"ما سرّ التعبير في قوله تعالى: ﴿قِبْلَةً تَرْضَاهَا﴾، دون أن يقال: «تحبها»؟","answer":"الرضا أخص من مجرد الميل والمحبة؛ فهو قبول وطمأنينة إلى ما يوافق الحق والحكمة. فالتعبير ينزه رغبة النبي ﷺ عن العصبية، ويبين موافقة القبلة لما يرضاه شرعًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص435، تحت «إيثار التعبير بفعل الرضا في قوله: «ترضاها»»","url":""}]},{"id":"s2-598","number":598,"surah":2,"verses":[144],"references":[{"surah":2,"verses":[144]}],"verseLabel":"البقرة: 144","question":"ما سرّ تقديم الوعد: ﴿فَلَنُوَلِّيَنَّكَ قِبْلَةً تَرْضَاهَا﴾ على الأمر: ﴿فَوَلِّ وَجْهَكَ﴾؟","answer":"قُدم الوعد تأنيسًا للنبي ﷺ وبشارة له بما كان يترقبه، ثم جاء الأمر تنفيذًا لذلك الوعد؛ فظهر أن التحويل اختيار إلهي لا اجتهادًا شخصيًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص436، تحت «نكتة تقديم الوعد على الأمر»","url":""}]},{"id":"s2-599","number":599,"surah":2,"verses":[144],"references":[{"surah":2,"verses":[144]}],"verseLabel":"البقرة: 144","question":"ما سرّ الانتقال من خطاب النبي ﷺ مفردًا إلى خطاب الأمة: ﴿وَحَيْثُ مَا كُنْتُمْ فَوَلُّوا وُجُوهَكُمْ شَطْرَهُ﴾؟","answer":"بدأ بالنبي ﷺ لأنه متلقي الوحي وإمام الأمة، ثم عمم الخطاب ليدل على أن الحكم شامل لجميع المؤمنين في كل مكان، لا خاص بصلاة النبي أو بموضع معين.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص438، تحت «سبب إفراد النبي وأمره قبل أمر الأمة»","url":""}]},{"id":"s2-600","number":600,"surah":2,"verses":[144],"references":[{"surah":2,"verses":[144]}],"verseLabel":"البقرة: 144","question":"ما دلالة قوله تعالى عن أهل الكتاب: ﴿يَعْلَمُونَ أَنَّهُ الْحَقُّ مِنْ رَبِّهِمْ﴾؟","answer":"التعريف في ﴿الحق﴾ يقرر ثبوت الحكم، وقوله ﴿من ربهم﴾ يبين أن مصدره الله الذي يقرون بكتابه؛ فاعتراضهم مع العلم كتمان وعناد لا اشتباه.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص440، تحت «القصر بالتعريف في «أنه الحق»؛ ودلالة الجار والمجرور «من ربهم»»","url":""}]},{"id":"s2-601","number":601,"surah":2,"verses":[144],"references":[{"surah":2,"verses":[144]}],"verseLabel":"البقرة: 144","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿وَمَا اللَّهُ بِغَافِلٍ عَمَّا يَعْمَلُونَ﴾؟","answer":"ختم بنفي الغفلة عن أعمالهم لتحريكهم إلى العمل بالحق الذي علموه؛ ففيه وعد للمؤمنين بثوابهم ووعيد للمعترضين بأن الله لا يهمل أعمال العباد.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص441، تحت «فائدة نفي الغفلة عن الفعل لا عن الذوات في «بغافل عما تعملون»»","url":""}]},{"id":"s2-602","number":602,"surah":2,"verses":[144,149,150],"references":[{"surah":2,"verses":[144,149,150]}],"verseLabel":"البقرة: 144 و149 و150","question":"ما سرّ تكرار أمر استقبال المسجد الحرام ثلاث مرات في الآيات 144 و149 و150؟","answer":"تكرر الأمر لتقرير نسخ الجهة الأولى وتأكيد الاتجاه الجديد؛ لأن أمر القبلة مظنة فتنة وشبهة، فاقتضى مزيد اهتمام وتوكيد. وأعيد النص ليبنى عليه بيان علة التحويل وقطع حجج المعترضين.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص500، تحت «تكرار الأمر بتولية الوجه إلى القبلة»","url":""}]},{"id":"s2-603","number":603,"surah":2,"verses":[145],"references":[{"surah":2,"verses":[145]}],"verseLabel":"البقرة: 145","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلَئِنْ أَتَيْتَ الَّذِينَ أُوتُوا الْكِتَابَ بِكُلِّ آيَةٍ مَا تَبِعُوا قِبْلَتَكَ﴾؟","answer":"أسلوب الشرط مع ﴿كل آية﴾ للمبالغة في بيان رسوخ عنادهم: فمهما جاءتهم الأدلة لم يتبعوا القبلة؛ لأن المانع ليس خفاء الحجة بل اتباع الهوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص448، تحت «اجتماع القسم والشرط في قوله: «ولئن أتيت الذين أوتوا الكتاب»»","url":""}]},{"id":"s2-604","number":604,"surah":2,"verses":[145],"references":[{"surah":2,"verses":[145]}],"verseLabel":"البقرة: 145","question":"ما سرّ التعبير في قوله تعالى: ﴿مَا تَبِعُوا قِبْلَتَكَ﴾ بالإفراد مع أن أهل الكتاب جماعات؟","answer":"لأن الكعبة قبلة واحدة يجتمع المسلمون عليها، فالمفرد يبرز وحدتها في مقابل اضطراب قبَل المعترضين. كما أن الفعل يصور المطلوب اتباع حكم واحد واضح لا الدخول في تفاصيل مذهب كامل.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص451، تحت «سر إفراد القبلة في قوله: «قبلتهم»»","url":""}]},{"id":"s2-605","number":605,"surah":2,"verses":[145],"references":[{"surah":2,"verses":[145]}],"verseLabel":"البقرة: 145","question":"ما سرّ التعبير في قوله تعالى: ﴿وَمَا أَنْتَ بِتَابِعٍ قِبْلَتَهُمْ﴾ اسمًا، دون أن يقال: «ولا تتبع قبلتهم»؟","answer":"اسم الفاعل المنفي مع الباء في ﴿وما أنت بتابع﴾ يفيد ثبات نفي الاتباع واستمراره؛ فلا رجوع إلى قبلتهم ولا مداهنة فيها بعد ورود الحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص451، تحت «المقارنة بين النفي بالجملة الاسمية والفعلية»","url":""}]},{"id":"s2-606","number":606,"surah":2,"verses":[145],"references":[{"surah":2,"verses":[145]}],"verseLabel":"البقرة: 145","question":"ما سرّ التعبير في قوله تعالى: ﴿وَمَا بَعْضُهُمْ بِتَابِعٍ قِبْلَةَ بَعْضٍ﴾؟","answer":"يكشف تناقضهم: يطالبون المسلمين باتباعهم، وهم أنفسهم لا يجتمعون على قبلة واحدة ولا يتبع اليهود قبلة النصارى أو العكس. فإذا كانت مخالفة القبلة دليل بطلان عندهم، لزم أن يبطل بعضهم بعضًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص452، تحت «مرجع الضمير ودلالته في «وما بعضهم بتابع قبلة بعض»»","url":""}]},{"id":"s2-607","number":607,"surah":2,"verses":[145],"references":[{"surah":2,"verses":[145]}],"verseLabel":"البقرة: 145","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلَئِنِ اتَّبَعْتَ أَهْوَاءَهُمْ﴾ بالجمع؟","answer":"لأن مطالبهم متفرقة متناقضة؛ لكل فريق غرض وقبلة وما يريده من النبي، فلا يجمعها حق واحد بل أهواء متعددة. وجاء الشرط المفروض مع استحالته ليقرر للأمة أن العلم لا يسمح بمجاملة الباطل مهما اشتد الضغط.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص453، تحت «إيثار الجمع على الإفراد في «ولئن اتبعت أهواءهم»»","url":""}]},{"id":"s2-608","number":608,"surah":2,"verses":[145],"references":[{"surah":2,"verses":[145]}],"verseLabel":"البقرة: 145","question":"ما سرّ التعبير في قوله تعالى: ﴿إِنَّكَ إِذًا لَمِنَ الظَّالِمِينَ﴾، دون أن يقال: «فإنك ظالم»؟","answer":"اجتمع التوكيد بإن واللام في الخبر، وجُعل على سبيل الفرض من زمرة الظالمين بدل الاكتفاء بوصفه بظالم؛ فالاندراج في جماعتهم أبلغ في إثبات الوصف. وفي هذا تشديد للتحذير من اتباع الهوى بعد العلم، وحث على اقتفاء الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص455، تحت عنوان «كثرة المؤكدات في الآية»","url":""}]},{"id":"s2-609","number":609,"surah":2,"verses":[146],"references":[{"surah":2,"verses":[146]}],"verseLabel":"البقرة: 146","question":"ما سرّ التعبير في قوله تعالى: ﴿يَعْرِفُونَهُ كَمَا يَعْرِفُونَ أَبْنَاءَهُمْ﴾، دون أن يقال: «يعلمون صدقه علمًا يقينيًا»؟","answer":"عدل عن الخبر المباشر إلى التشبيه لأنه أبلغ في وصف المعرفة وأوقع في اليقين؛ فمعرفتهم الرسول ﷺ بصفاته كمعرفتهم أبناءهم معرفة حسية لا يداخلها اشتباه، ولذلك كان كتمانهم بعد هذه المعرفة أشد ذمًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص465، تحت «إيثار التشبيه على أسلوب الإخبار في التعبير»","url":""}]},{"id":"s2-610","number":610,"surah":2,"verses":[146],"references":[{"surah":2,"verses":[146]}],"verseLabel":"البقرة: 146","question":"ما سرّ تخصيص الأبناء في قوله تعالى: ﴿يَعْرِفُونَهُ كَمَا يَعْرِفُونَ أَبْنَاءَهُمْ﴾؟","answer":"الأبناء الذكور كانوا أشهر ملازمةً للآباء وظهورًا في مجتمعهم وأدق اتصالًا بالنسب الذي يحفظونه، فكانت معرفتهم بهم مضربًا في اليقين. واختيار الصورة التي لا يجادلون فيها يجعل الحجة من واقعهم هم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص466، تحت «توجيه الخصوص بالذكر»","url":""}]},{"id":"s2-611","number":611,"surah":2,"verses":[146],"references":[{"surah":2,"verses":[146]}],"verseLabel":"البقرة: 146","question":"ما سرّ التعبير في قوله تعالى: ﴿وَإِنَّ فَرِيقًا مِنْهُمْ لَيَكْتُمُونَ الْحَقَّ﴾، ولم ينسب الكتمان إلى أهل الكتاب جميعًا؟","answer":"قيد الكتمان بـ﴿فريقًا منهم﴾ إنصافًا؛ فلم ينسبه إلى أهل الكتاب جميعًا، بل إلى الذين عرفوا الحق ثم تعمدوا ستره.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص467، تحت «فائدة تقييد الكاتمين وعدم إطلاق الحكم»","url":""}]},{"id":"s2-613","number":613,"surah":2,"verses":[147],"references":[{"surah":2,"verses":[147]},{"surah":3,"verses":[60]}],"verseLabel":"البقرة: 147، آل عمران: 60","question":"ما سرّ اختلاف التعبير بين قوله تعالى في البقرة: ﴿فَلَا تَكُونَنَّ مِنَ الْمُمْتَرِينَ﴾ بنون التوكيد الثقيلة، وقوله تعالى في آل عمران: ﴿فَلَا تَكُنْ مِنَ الْمُمْتَرِينَ﴾ من غيرها؟","answer":"أكد النهي في البقرة بنون التوكيد لأن سياقها مبني على التوكيد، وسبق فيه ﴿فلنولينك﴾، فناسب تآلف الصيغ أن يقال ﴿فلا تكونن﴾؛ أما موضع آل عمران فجاء على الأصل ﴿فلا تكن﴾ لعدم سبق ما يوجب هذا التوكيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص477، تحت «دلالة تكرار التركيب في سياقات مختلفة»","url":""}]},{"id":"s2-614","number":614,"surah":2,"verses":[147],"references":[{"surah":2,"verses":[147]}],"verseLabel":"البقرة: 147","question":"ما سرّ استقلال جملة ﴿الْحَقُّ مِنْ رَبِّكَ﴾، دون أن يقال: «وهو الحق من ربك»؟","answer":"جاءت جملة اسمية مستأنفة لتقرر حقيقة مستقلة ثابتة: الحق الجدير بالاتباع هو المنزل من ربك، وغيره باطل؛ وتعريف ﴿الحق﴾ يفيد القصر ويقوي الحسم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص473، تحت «دلالة الاستئناف والتذييل في الآية»","url":""}]},{"id":"s2-615","number":615,"surah":2,"verses":[147],"references":[{"surah":2,"verses":[147]},{"surah":3,"verses":[60]}],"verseLabel":"البقرة: 147؛ آل عمران: 60","question":"ما دلالة التعبير بالرب في ﴿الحق من ربك﴾ في البقرة؟","answer":"يستحضر لفظ الرب الرعاية والاهتمام، وإضافته إلى ضمير النبي ﷺ تذكره بقرب ربه منه وأن الحق منحة منه؛ فيهوّن عليه ما يلقاه من جدال أهل الكتاب حول تحويل القبلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص474–475، تحت عنوان «دلالة استعمال لفظ الرب، عوضًا عن اسم الجلالة»","url":""}]},{"id":"s2-1517","number":1517,"surah":2,"verses":[147],"references":[{"surah":2,"verses":[147]},{"surah":3,"verses":[60]}],"verseLabel":"البقرة: 147؛ آل عمران: 60","question":"ما فائدة إضافة الرب إلى ضمير النبي ﷺ في ﴿الحق من ربك﴾ في آل عمران؟","answer":"في التعبير بالربوبية مع إضافتها إلى الرسول ﷺ زيادة في تشريفه ورفع مكانته وإحاطته بعالي المنزلة ورفيع المقام.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص175، تحت عنوان «سر التعبير بلفظ الربوبية، وإضافته»","url":""}]},{"id":"s2-616","number":616,"surah":2,"verses":[147],"references":[{"surah":2,"verses":[147]}],"verseLabel":"البقرة: 147","question":"ما سرّ توجيه النهي إلى النبي ﷺ في قوله: ﴿فَلَا تَكُونَنَّ مِنَ الْمُمْتَرِينَ﴾ مع ثبوت يقينه؟","answer":"ليس النهي لإثبات شك عند النبي ﷺ؛ فالشك غير متوقع منه، وإنما ورد الخطاب له لتقرير اليقين وتوجيه الأمة من ورائه، حتى لا يكون أحد من الممترين بعد وضوح أن الحق من الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص475، تحت «غرض النهي عن الامتراء»","url":""}]},{"id":"s2-617","number":617,"surah":2,"verses":[148],"references":[{"surah":2,"verses":[148]}],"verseLabel":"البقرة: 148","question":"ما سرّ التعبير في قوله تعالى: ﴿ولكل وجهة هو موليها﴾ فأبهم صاحب التولية؟","answer":"يحتمل أن يعود ﴿هو﴾ إلى كل صاحب وجهة، أي هو مستقبلها ومولٍّ وجهه إليها، ويحتمل أن يعود إلى الله، أي يولي كل ملة قبلتها؛ غير أن المصدر يرجح الأول لموافقته ظاهر اللفظ والسياق.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص486، تحت «إيجاز بحذف المفعول به في قوله: «موليها»»","url":""}]},{"id":"s2-619","number":619,"surah":2,"verses":[148],"references":[{"surah":2,"verses":[148]}],"verseLabel":"البقرة: 148","question":"ما سرّ التعبير في قوله تعالى: ﴿فَاسْتَبِقُوا الْخَيْرَاتِ﴾ بعد الحديث عن القبلة، دون أن يقال: «فاستقبلوا جهتكم»؟","answer":"لما كان لكل أهل دين وجهة يتمسكون بها، صرف الله المسلمين عن الجدل مع المكابرين إلى المبادرة بالأعمال الصالحة؛ فالمطلوب بعد بيان القبلة الامتثال والعمل لا استهلاك الوقت في الخصومة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص486، تحت «دلالة لفظ «الخيرات» بين الخصوص السياقي والعموم اللفظي»","url":""}]},{"id":"s2-620","number":620,"surah":2,"verses":[148],"references":[{"surah":2,"verses":[148]}],"verseLabel":"البقرة: 148","question":"ما سرّ التعبير في قوله تعالى: ﴿الْخَيْرَاتِ﴾ بالجمع؟","answer":"جاءت ﴿الخيرات﴾ جمعًا لتعم كل عمل صالح حسن في الشرع، مع دخول امتثال القبلة فيها دخولًا أوليًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص486–487، تحت «دلالة لفظ «الخيرات» بين الخصوص السياقي والعموم اللفظي»","url":""}]},{"id":"s2-621","number":621,"surah":2,"verses":[148],"references":[{"surah":2,"verses":[148]}],"verseLabel":"البقرة: 148","question":"ما سرّ التعبير في قوله تعالى: ﴿أَيْنَ مَا تَكُونُوا يَأْتِ بِكُمُ اللَّهُ جَمِيعًا﴾ بعد اختلاف الوجهات؟","answer":"بعد تفرق الناس في الجهات والأمكنة، ذكّرهم بوحدة المصير: أينما يكونوا يجمعهم الله للحساب. فاختلاف المكان لا يمنع الاجتماع ولا يغير مسؤولية العمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص487، تحت «علة الفصل في قوله: «أين ما تكونوا يأت بكم الله جميعا»»","url":""}]},{"id":"s2-622","number":622,"surah":2,"verses":[148],"references":[{"surah":2,"verses":[148]}],"verseLabel":"البقرة: 148","question":"ما سرّ التعبير في قوله تعالى: ﴿يَأْتِ بِكُمُ اللَّهُ﴾، دون أن يقال: «يبعثكم الله»؟","answer":"عُبِّر عن البعث بالإتيان، وهو جلب الشيء وإحضاره؛ وفيه تذكير بأن الناس، أينما كانوا، سيُجمعون للحساب والجزاء، فلا مهرب لهم منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص488، تحت «دلالة المجاز في قوله تعالى: «يأت بكم الله»»","url":""}]},{"id":"s2-623","number":623,"surah":2,"verses":[148],"references":[{"surah":2,"verses":[148]}],"verseLabel":"البقرة: 148","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿إِنَّ اللَّهَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ﴾؟","answer":"لما كان جمع الخلق من كل مكان قد يستبعد، ختم بكمال القدرة ردًا على الاستبعاد، وتأكيدًا أن الله قادر على جمعهم ومجازاتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص488، تحت «بلاغة الفاصلة في قوله: «إن الله على كل شيء قدير»»","url":""}]},{"id":"s2-624","number":624,"surah":2,"verses":[149],"references":[{"surah":2,"verses":[149]}],"verseLabel":"البقرة: 149","question":"ما سرّ التعبير هنا في قوله تعالى: ﴿وَإِنَّهُ لَلْحَقُّ مِنْ رَبِّكَ﴾ بزيادة اللام، بعدما قال في الآية 144: ﴿أَنَّهُ الْحَقُّ مِنْ رَبِّهِمْ﴾؟","answer":"زيدت اللام مع ﴿إن﴾ لتأكيد ثبات حكم استقبال القبلة ودفع توهم نسخه، ولا سيما مع تكرار الأمر بها؛ وجاء ﴿من ربك﴾ للإيماء إلى أن هذا الحق مقتضى تربية الله لنبيه وحكمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص494، تحت «فائدة التأكيد بمؤكدات عدة»","url":""}]},{"id":"s2-625","number":625,"surah":2,"verses":[149],"references":[{"surah":2,"verses":[149]}],"verseLabel":"البقرة: 149","question":"ما مناسبة تكرار قوله تعالى: ﴿وَمَا اللَّهُ بِغَافِلٍ عَمَّا تَعْمَلُونَ﴾؟","answer":"ختم بنفي الغفلة المؤكد لإثبات كمال علم الله بأعمال الأمة؛ وهذه الصيغة أنسب بمقام التنبيه والوعيد والزجر، حتى لا يظن عامل أن فعله يخفى عن الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص495، تحت «فائدة النفي في قوله: «وما الله بغافل»»","url":""}]},{"id":"s2-626","number":626,"surah":2,"verses":[150],"references":[{"surah":2,"verses":[150]},{"surah":5,"verses":[3,44]}],"verseLabel":"البقرة: 150، المائدة: 3 و44","question":"ما سرّ اختلاف التعبير بين إثبات الياء في ﴿وَاخْشَوْنِي﴾ بالبقرة وحذفها في ﴿وَاخْشَوْنِ﴾ بالمائدة؟","answer":"أثبتت الياء في البقرة لأن تحويل القبلة كان موضع جدال شديد، فناسب زيادة المبنى زيادة التوكيد في خشية الله دون الناس. وحذفت في المائدة بعد ظهور الإسلام ويأس الكافرين، فناسب التخفيف.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص213، تحت «سر إثبات الياء في «واخشوني» في آية البقرة، وحذفها في موضعي المائدة «واخشون»»","url":""}]},{"id":"s2-627","number":627,"surah":2,"verses":[150],"references":[{"surah":2,"verses":[150]},{"surah":5,"verses":[3]}],"verseLabel":"البقرة: 150، المائدة: 3","question":"ما سرّ اختلاف التعبير بين ﴿وَلِأُتِمَّ نِعْمَتِي عَلَيْكُمْ﴾ في البقرة و﴿وَأَتْمَمْتُ عَلَيْكُمْ نِعْمَتِي﴾ في المائدة؟","answer":"جاء المضارع في البقرة لأن تمام النعمة كان مستقبلًا ينتظر اكتماله بفتح مكة وانتشار الإسلام، وجاء الماضي في المائدة ـ وهي من أواخر ما نزل ـ لإعلان تحقق تمام النعمة واستقرارها.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص557، تحت «سر وصف النعمة بالإتمام في قوله تعالى: «وأتممت عليكم نعمتي»»","url":""}]},{"id":"s2-628","number":628,"surah":2,"verses":[150],"references":[{"surah":2,"verses":[150]},{"surah":5,"verses":[3]}],"verseLabel":"البقرة: 150، المائدة: 3","question":"ما سرّ تقديم ﴿نِعْمَتِي﴾ في البقرة، وتقديم ﴿عَلَيْكُمْ﴾ في المائدة؟","answer":"قدمت البقرة ﴿نعمتي﴾ لأن المقام بشارة بنعمة ينتظر تمامها فكانت موضع العناية، وقدمت المائدة ﴿عليكم﴾ لأن المقام تقرير إحاطة النعمة بالمؤمنين بعد تحققها.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص558، تحت «دلالة تأخير المعمول في قوله: «وأتممت عليكم نعمتي» دون تقديمه، كما في موضع البقرة»","url":""}]},{"id":"s2-629","number":629,"surah":2,"verses":[150],"references":[{"surah":2,"verses":[150]}],"verseLabel":"البقرة: 150","question":"ما وجه الاستثناء في قوله تعالى: ﴿لِئَلَّا يَكُونَ لِلنَّاسِ عَلَيْكُمْ حُجَّةٌ إِلَّا الَّذِينَ ظَلَمُوا مِنْهُمْ﴾؛ وهل للظالمين حجة صحيحة؟","answer":"تنقطع الحجج الصحيحة، ويبقى جدال الذين ظلموا بما يظنونه حجة وليس بحجة في التحقيق؛ وعلى الاتصال سمي متعلقهم حجة مجازًا بحسب زعمهم، ويجوز حمل الاستثناء على الانقطاع: لا حجة لأحد، لكن يبقى ظلم المعاندين.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص503، تحت «تردد الاستثناء بين الاتصال والانقطاع»","url":""}]},{"id":"s2-630","number":630,"surah":2,"verses":[150],"references":[{"surah":2,"verses":[150]}],"verseLabel":"البقرة: 150","question":"ما سرّ التعبير في قوله تعالى: ﴿فَلَا تَخْشَوْهُمْ وَاخْشَوْنِي﴾، فجمع بين النهي والأمر؟","answer":"نهاهم عن خشية المعترضين على تحويل القبلة، وأمرهم أن يخصوا الله بالخشية؛ تثبيتًا لهم على امتثال الحكم في هذا الاختبار، فهو وحده النافع الضار المستحق للخشية.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص504، تحت «بلاغة التوشيح بين المعاني»","url":""}]},{"id":"s2-631","number":631,"surah":2,"verses":[150],"references":[{"surah":2,"verses":[150]}],"verseLabel":"البقرة: 150","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلِأُتِمَّ نِعْمَتِي عَلَيْكُمْ وَلَعَلَّكُمْ تَهْتَدُونَ﴾؛ ما علاقة القبلة بإتمام النعمة؟","answer":"كان تحويل القبلة إلى الكعبة إتمامًا للنعمة؛ لما فيه من استقلال المسلمين عن أهل الكتاب، وتشريف البيت الحرام، وإجابة دعوة إبراهيم، ورجاء اهتدائهم إلى الحق بالامتثال.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص504، تحت «بلاغة قوله تعالى: «ولأتم نعمتي»»","url":""}]},{"id":"s2-632","number":632,"surah":2,"verses":[151],"references":[{"surah":2,"verses":[151]}],"verseLabel":"البقرة: 151","question":"ما سرّ التعبير في قوله تعالى: ﴿فيكم رسولًا منكم﴾، دون أن يقال: إليكم رسولًا؟","answer":"﴿فيكم﴾ تدل على وجود الرسول بينهم وإقامته ومخالطته لهم، وهي أبلغ في الامتنان من مجرد الإرسال إليهم؛ لأنهم يشاهدون سيرته ويتلقون عنه ويقتدون به.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص512، تحت «إيثار التنكير في التعبير عن صاحب الرسالة في قوله: «رسولًا»»","url":""}]},{"id":"s2-633","number":633,"surah":2,"verses":[151],"references":[{"surah":2,"verses":[151]}],"verseLabel":"البقرة: 151","question":"ما مناسبة تشبيه إتمام نعمة القبلة بإرسال الرسول في قوله تعالى: ﴿كَمَا أَرْسَلْنَا فِيكُمْ رَسُولًا مِنْكُمْ﴾؟","answer":"شبّه نعمة تحويل القبلة بنعمة إرسال الرسول؛ فكلتاهما من تمام الامتنان والهداية، وجاءت النعمة الجديدة في سياق النعمة السابقة الظاهرة ليُعرف قدرها ووجوب شكرها.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص510، تحت «بلاغة التشبيه في قوله: «كما أرسلنا»»","url":""}]},{"id":"s2-634","number":634,"surah":2,"verses":[151],"references":[{"surah":2,"verses":[151]}],"verseLabel":"البقرة: 151","question":"ما سرّ التعبير في قوله تعالى: ﴿رَسُولًا مِنْكُمْ﴾؟","answer":"لأنه من قومهم، يعرفون نسبه ولسانه وحاله ويأنسون به، فيكون تلقيهم عنه وفهمهم لبلاغه أيسر، وتتم عليهم نعمة الرسالة من غير حاجز غربة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص511، تحت «إيثار التعبير بلفظ «فيكم» دون لفظ «إليكم»»","url":""}]},{"id":"s2-635","number":635,"surah":2,"verses":[151],"references":[{"surah":2,"verses":[151]}],"verseLabel":"البقرة: 151","question":"ما دلالة أفعال المضارع في قوله تعالى: ﴿يَتْلُو عَلَيْكُمْ آيَاتِنَا وَيُزَكِّيكُمْ وَيُعَلِّمُكُمُ الْكِتَابَ وَالْحِكْمَةَ﴾؟","answer":"تفيد الاستمرار والتجدد؛ فتلاوة الوحي متوالية، وتزكية النفوس تحتاج إلى المداومة والمعالجة، وتعليم الكتاب يستمر مع نزوله.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص512–513، تحت «التعبير بأفعال المضارع ودلالة كل منها»","url":""}]},{"id":"s2-636","number":636,"surah":2,"verses":[151],"references":[{"surah":2,"verses":[151]}],"verseLabel":"البقرة: 151","question":"ما فائدة قوله تعالى: ﴿وَيُعَلِّمُكُمْ مَا لَمْ تَكُونُوا تَعْلَمُونَ﴾ بعد تعليم الكتاب والحكمة؟","answer":"عطف التعليم العام على تعليم الكتاب والحكمة ليشمل ما وراءهما من أخبار الغيب وقصص الأمم والتشريعات وسائر ما لم يكونوا يعلمونه، وفيه إظهار لسعة نعمة التعليم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص514، تحت «بلاغة ذكر العام بعد الخاص»","url":""}]},{"id":"s2-637","number":637,"surah":2,"verses":[152],"references":[{"surah":2,"verses":[152]}],"verseLabel":"البقرة: 152","question":"ما سرّ التعبير في قوله تعالى: ﴿فاذكروني أذكركم﴾ فجعل ذكر الله للعبد جوابًا لذكر العبد؟","answer":"جاء الوعد على المقابلة: من ذكر الله بالطاعة والثناء ذكره الله بالرحمة والثواب والعناية. وذكر الله لعبده أعظم من ذكر العبد لربه.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص521، تحت «دلالة معنى الشرط في قوله: «فاذكروني أذكركم»»","url":""}]},{"id":"s2-639","number":639,"surah":2,"verses":[152],"references":[{"surah":2,"verses":[152]}],"verseLabel":"البقرة: 152","question":"ما سرّ التعبير في قوله تعالى: ﴿وَاشْكُرُوا لِي﴾ باللام، دون أن يقال: «واشكروني»؟","answer":"تعدية الشكر باللام تراعي إحسان المشكور وأفعاله؛ فالعبد يشكر الله باعتبار ما يدرك من نعمه، مع قصوره عن الإحاطة بها. وتذكر الموسوعة أن تعديته باللام هي الوجه الأفصح في اللغة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص522، تحت «الفرق الدلالي بين قوله: (شكره) و(شكر له)»","url":""}]},{"id":"s2-640","number":640,"surah":2,"verses":[152],"references":[{"surah":2,"verses":[152]}],"verseLabel":"البقرة: 152","question":"ما سرّ مقابلة الشكر بقوله تعالى: ﴿وَلَا تَكْفُرُونِ﴾؟","answer":"لأن الكفر في أصله الستر، وكفر النعمة سترها وجحودها، فهو الضد المقابل للشكر؛ لذلك جمع الأمر بالشكر والنهي عن نقيضه لتأكيد المعنى.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص522، تحت «بلاغة أسلوب الاحتراس في قوله تعالى: «ولا تكفرون»»","url":""}]},{"id":"s2-641","number":641,"surah":2,"verses":[153],"references":[{"surah":2,"verses":[153]}],"verseLabel":"البقرة: 153","question":"ما سرّ التعبير في قوله تعالى: ﴿استعينوا بالصبر والصلاة﴾، دون أن يقال: اصبروا وصلوا؟","answer":"جعل الصبر والصلاة وسيلتين يطلب بهما عون الله على سائر التكاليف والمحن، لا فعلين منفصلين ينتهيان عند أدائهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص528، تحت «لماذا كان الأمر بالاستعانة دون فعل (اصبروا)؟»","url":""}]},{"id":"s2-642","number":642,"surah":2,"verses":[153],"references":[{"surah":2,"verses":[153]}],"verseLabel":"البقرة: 153","question":"ما سرّ اختلاف ختام هذه الآية: ﴿إِنَّ اللَّهَ مَعَ الصَّابِرِينَ﴾ عن ختام نظيرتها السابقة في البقرة: 45؟","answer":"في الآية السابقة كان المقام بيان ثقل الصلاة واستثناء الخاشعين، فناسب ذكر الخشوع. وهنا السياق تمهيد للابتلاء والجهاد، فناسب وعد الصابرين بمعية الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص530، تحت «توجيه المتشابه اللفظي»","url":""}]},{"id":"s2-643","number":643,"surah":2,"verses":[153],"references":[{"surah":2,"verses":[153]}],"verseLabel":"البقرة: 153","question":"ما سرّ تجديد النداء بقوله تعالى: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا﴾ بعد قوله: ﴿فاذكروني﴾؟","answer":"لأن السياق ينتقل من شكر النعمة إلى الاستعداد للابتلاء، فاحتاج الأمر الجديد إلى تنبيه مستقل يستثير صفة الإيمان التي تدفع إلى الامتثال. وكأن النداء يقول: مقتضى إيمانكم أن تلجؤوا إلى الصبر والصلاة عند الشدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص527، تحت «دلالة أسلوب النداء في قوله: «يا أيها الذين آمنوا»»","url":""}]},{"id":"s2-645","number":645,"surah":2,"verses":[153],"references":[{"surah":2,"verses":[153]}],"verseLabel":"البقرة: 153","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿إِنَّ اللَّهَ مَعَ الصَّابِرِينَ﴾ دون «المصلين»؟","answer":"خص الصابرين بالمعية لأن المقام مقام تكاليف ومشاق تحتاج إلى الصبر والثبات، فناسب أن يبشر الممتثلين بمعية الله وعونه.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص529، تحت «بلاغة الفاصلة القرآنية»","url":""}]},{"id":"s2-646","number":646,"surah":2,"verses":[154],"references":[{"surah":2,"verses":[154]}],"verseLabel":"البقرة: 154","question":"ما وجه النهي عن تسمية من يقتل في سبيل الله أمواتًا مع وقوع الموت الحسي؟","answer":"النهي لا ينفي مفارقة أجسادهم للحياة الدنيا، وإنما ينفي أن تكون حقيقتهم عدمًا؛ فهم أحياء حياة برزخية لا تدركها الحواس المعتادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص535، تحت «تعيين مراد النهي مبني على مقصد السياق في قوله: «ولا تقولوا»»","url":""}]},{"id":"s2-648","number":648,"surah":2,"verses":[154],"references":[{"surah":2,"verses":[154]}],"verseLabel":"البقرة: 154","question":"ما دلالة تقييد القتل بقوله تعالى: ﴿فِي سَبِيلِ اللَّهِ﴾؟","answer":"لأن فضل الشهادة لا يثبت لمجرد وقوع القتل، بل لمن قتل مخلصًا في سبيل الله وإعلاء كلمته؛ فالقيد يخرج غير ذلك.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص535، تحت «فائدة قيد: «في سبيل الله»»","url":""}]},{"id":"s2-649","number":649,"surah":2,"verses":[154],"references":[{"surah":2,"verses":[154]}],"verseLabel":"البقرة: 154","question":"ما أثر الطباق في قوله تعالى: ﴿أَمْوَاتٌ بَلْ أَحْيَاءٌ﴾؟","answer":"قابلت الآية الموت بالحياة، فانتقل الكلام من نفي اعتقاد موت الشهداء إلى إثبات الحياة لهم. وهذه المقابلة بين المعنيين تزيد المعنى وضوحًا واستجلاءً.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص535–536، تحت «فن الطباق في قوله: ﴿أموات بل أحياء﴾»","url":""}]},{"id":"s2-650","number":650,"surah":2,"verses":[154],"references":[{"surah":2,"verses":[154]}],"verseLabel":"البقرة: 154","question":"ما دلالة قوله تعالى بعد إثبات حياتهم: ﴿وَلَكِنْ لَا تَشْعُرُونَ﴾؟","answer":"حياتهم البرزخية ثابتة، لكن أدوات الحس لا تدرك كيفيتها. لذلك نفى الشعور لا العلم؛ لأن العلم بها حاصل بخبر الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص536، تحت «دلالة حذف المفعول في قوله: «ولكن لا تشعرون»»","url":""}]},{"id":"s2-651","number":651,"surah":2,"verses":[155],"references":[{"surah":2,"verses":[155]}],"verseLabel":"البقرة: 155","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلَنَبْلُوَنَّكُمْ﴾ مؤكدًا، والله يعلم أحوالهم قبل الابتلاء؟","answer":"ليس الابتلاء لتحصيل علم يخفى على الله، وإنما لوقوع الاختبار في العمل؛ وجاءت اللام والنون لتأكيد حتمية الابتلاء وتهيئة المؤمنين له قبل نزوله.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص541، تحت «دلالة المضارع ونون الجمع والجملة الخبرية في قوله: «ولنبلونكم»»","url":""}]},{"id":"s2-652","number":652,"surah":2,"verses":[155],"references":[{"surah":2,"verses":[155]}],"verseLabel":"البقرة: 155","question":"ما سرّ التعبير في قوله تعالى: ﴿بِشَيْءٍ مِنَ الْخَوْفِ وَالْجُوعِ﴾، دون أن يقال: «بالخوف والجوع»؟","answer":"تفيد ﴿شيء﴾ تقليل مقدار الابتلاء وتخفيف وقعه؛ فهو بعض من الخوف والجوع، وفي ذلك رحمة وتسلية مع تحقق الاختبار.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص542، تحت «نكتة إيثار إفراد شيء على الجمع»","url":""}]},{"id":"s2-653","number":653,"surah":2,"verses":[155],"references":[{"surah":2,"verses":[155]}],"verseLabel":"البقرة: 155","question":"ما سرّ ترتيب أنواع الابتلاء: الخوف، ثم الجوع، ثم نقص الأموال والأنفس والثمرات؟","answer":"رتبها بحسب شدة وقعها وتعلق الناس بها: الخوف المهدد للأمن، ثم الجوع، ثم نقص الأموال، فالأنفس، فالثمرات؛ فبدأ بالأشد والأعم أثرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص544، تحت «السر في ترتيب المذكورات فيما يبتلى فيه العباد»","url":""}]},{"id":"s2-654","number":654,"surah":2,"verses":[155],"references":[{"surah":2,"verses":[155]}],"verseLabel":"البقرة: 155","question":"ما سرّ التعبير في قوله تعالى: ﴿وَبَشِّرِ الصَّابِرِينَ﴾ ولم يذكر بماذا يبشرهم؟","answer":"حذف المبشَّر به ليعظم ويتنوع: نصر ومغفرة وصلوات ورحمة وهداية وجنة، ثم تكشف الآية التالية بعضه. لو ذُكر جزاء واحد لضاق الرجاء، أما الحذف فيفتح كل خير يليق بصبرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص544، تحت «دلالة اسم الإشارة على المحذوف في قوله: «وبشر الصابرين»»","url":""}]},{"id":"s2-655","number":655,"surah":2,"verses":[156],"references":[{"surah":2,"verses":[156]}],"verseLabel":"البقرة: 156","question":"ما سرّ التعبير عما يصيب الإنسان بلفظ ﴿مصيبة﴾؟","answer":"سميت مصيبة من الإصابة؛ لأنها نازلة تصيب الإنسان وتقع به فعلًا، فيصدق اللفظ على ما نزل به من مكروه.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص548، تحت «سر التعبير بلفظ «مصيبة» دون لفظ (ابتلاء)»","url":""}]},{"id":"s2-656","number":656,"surah":2,"verses":[156],"references":[{"surah":2,"verses":[156]}],"verseLabel":"البقرة: 156","question":"ما دلالة قول الصابرين عند المصيبة: ﴿إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ﴾؟","answer":"قولهم ﴿إنا لله﴾ إقرار بأنهم وما يملكون ملك لله، وقولهم ﴿وإنا إليه راجعون﴾ تذكير بأن المصير إليه؛ فيخف وقع الفقد حين يرد الملك والمآل إلى صاحبهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص549، تحت «فائدة العطف والتقديم في قوله: ﴿قالوا إنا لله وإنا إليه راجعون﴾»","url":""}]},{"id":"s2-657","number":657,"surah":2,"verses":[156],"references":[{"surah":2,"verses":[156]}],"verseLabel":"البقرة: 156","question":"ما سرّ التعبير في قوله تعالى: ﴿الَّذِينَ إِذَا أَصَابَتْهُمْ مُصِيبَةٌ﴾ بـ﴿إذا﴾ لا بـ«إن»؟","answer":"﴿إذا﴾ تستعمل للمتحقق المتوقع، والمصائب سنة لا يسلم منها إنسان؛ فربى المؤمن على الاستعداد لها لا توهم ندرتها. أما ﴿إن﴾ فقد توحي بأن الوقوع مشكوك فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص548، تحت «فائدة الشرط بـ«إذا» دون «إن»»","url":""}]},{"id":"s2-658","number":658,"surah":2,"verses":[156],"references":[{"surah":2,"verses":[156]}],"verseLabel":"البقرة: 156","question":"ما دلالة تنكير ﴿مصيبة﴾ في قوله تعالى: ﴿إِذَا أَصَابَتْهُمْ مُصِيبَةٌ﴾؟","answer":"نكرت ﴿مصيبة﴾ لتعم كل ما يصيب الإنسان من البلاء، فلا يختص الاسترجاع بنوع معين كالموت.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص549، تحت «دلالة التنكير في لفظ: «مصيبة»»","url":""}]},{"id":"s2-659","number":659,"surah":2,"verses":[157],"references":[{"surah":2,"verses":[157]}],"verseLabel":"البقرة: 157","question":"ما سرّ التعبير في قوله تعالى: ﴿عَلَيْهِمْ صَلَوَاتٌ مِنْ رَبِّهِمْ وَرَحْمَةٌ﴾، فجمع الصلوات وأفرد الرحمة؟","answer":"جمعت الصلوات لتنوع ما يشمله العطاء من الرحمة والتزكية والمغفرة، وأفردت الرحمة وهي اسم واسع يشمل وجوه الخير والفضل.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص553، تحت «دلالة المقابلة بين جمع «صلوات» وإفراد «رحمة»»","url":""}]},{"id":"s2-660","number":660,"surah":2,"verses":[157],"references":[{"surah":2,"verses":[157]}],"verseLabel":"البقرة: 157","question":"ما دلالة تكرار اسم الإشارة في قوله تعالى: ﴿وَأُولَئِكَ هُمُ الْمُهْتَدُونَ﴾ بعد ﴿أُولَئِكَ عَلَيْهِمْ صَلَوَاتٌ﴾؟","answer":"ليجعل لكل جزاء استقلاله: لهم عطاء الرب، وهم فوق ذلك أصحاب الهداية الراسخة التي أوصلتهم إلى الصبر. والتكرار يرفع منزلتهم، وضمير الفصل والتعريف يقصران الهداية الكاملة في هذا المقام عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص555، تحت «فائدة تكرار اسم الإشارة «أولئك»»","url":""}]},{"id":"s2-661","number":661,"surah":2,"verses":[158],"references":[{"surah":2,"verses":[158]}],"verseLabel":"البقرة: 158","question":"ما دلالة وصف الصفا والمروة بأنهما ﴿مِنْ شَعَائِرِ اللَّهِ﴾؟","answer":"لأن المسلمين تحرجوا من السعي لما ارتبط بهما في الجاهلية من أصنام، فجاء الوحي يفصل الشعيرة الإبراهيمية عن تشويه المشركين. كما يرتبطان بابتلاء هاجر وسعيها، فصارا شاهدين على الثقة بالله وتحول الشدة إلى زمزم وعمران.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص562، تحت «توجيه المخصوص بالذكر»","url":""}]},{"id":"s2-662","number":662,"surah":2,"verses":[158],"references":[{"surah":2,"verses":[158]}],"verseLabel":"البقرة: 158","question":"ما سرّ التعبير في قوله تعالى: ﴿فَلَا جُنَاحَ عَلَيْهِ أَنْ يَطَّوَّفَ بِهِمَا﴾، مع أن السعي عبادة وليس مجرد أمر مباح؟","answer":"نفي الجناح جاء لإزالة الحرج الذي وجدوه بسبب ما علق بالصفا والمروة في الجاهلية، لا لبيان أن السعي مجرد مباح؛ فالمقام رفع توهم المنع.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص565، تحت «تعيين غرض النفي يعلم بالسياق»","url":""}]},{"id":"s2-663","number":663,"surah":2,"verses":[158],"references":[{"surah":2,"verses":[158]}],"verseLabel":"البقرة: 158","question":"ما سرّ التعبير في قوله تعالى: ﴿أَنْ يَطَّوَّفَ بِهِمَا﴾ بصيغة التفعّل، دون أن يقال: «أن يطوف»؟","answer":"صيغة ﴿يطوّف﴾ تدل على التكلف والتكرر في الذهاب والعودة بين الصفا والمروة، فناسبت عمل السعي المتكرر.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص565، تحت «تثقيل اللفظ لبيان ثقل العمل لا ثقل المعتقد»","url":""}]},{"id":"s2-664","number":664,"surah":2,"verses":[158],"references":[{"surah":2,"verses":[158]}],"verseLabel":"البقرة: 158","question":"ما سرّ التعبير في قوله تعالى: ﴿وَمَنْ تَطَوَّعَ خَيْرًا﴾ ولم يحدد نوع الخير؟","answer":"أطلق الخير ليشمل الزيادة في الطاعة وكل عمل يختاره العبد فوق الواجب، ولا يحصره في السعي وحده. فالقاعدة تتسع: ما يبذله العبد طوعًا لا يضيع عند الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص568، تحت «دلالة التنكير في قوله: «خيرا» العموم»","url":""}]},{"id":"s2-665","number":665,"surah":2,"verses":[158],"references":[{"surah":2,"verses":[158]}],"verseLabel":"البقرة: 158","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿فَإِنَّ اللَّهَ شَاكِرٌ عَلِيمٌ﴾، وما معنى شكر الله لعبده؟","answer":"شكر الله لعبده قبوله عمله وإثابته عليه ومضاعفة جزائه. وقدم ﴿شاكر﴾ لاتصاله بالتطوع، ثم ﴿عليم﴾ لأنه يعلم العمل والنية.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص569، تحت «بلاغة إيراد الأسماء الحسنى اختيارًا وترتيبًا»","url":""}]},{"id":"s2-666","number":666,"surah":2,"verses":[159],"references":[{"surah":2,"verses":[159]}],"verseLabel":"البقرة: 159","question":"ما سرّ التعبير في قوله تعالى: ﴿إِنَّ الَّذِينَ يَكْتُمُونَ مَا أَنْزَلْنَا﴾ بنون العظمة؟","answer":"لبيان شرف المنزل وعظم الجريمة في الوقت نفسه: الذي يكتمونه ليس رأيًا بشريًا، بل وحي أنزله الله العظيم. فكلما عظم مصدر البيان اشتد قبح من حبسه عن الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص573، تحت «الجمع بين دلالة تعظيم المنزل وتقبيح الكاتم في قوله: «أنزلنا»»","url":""}]},{"id":"s2-667","number":667,"surah":2,"verses":[159],"references":[{"surah":2,"verses":[159]}],"verseLabel":"البقرة: 159","question":"ما سرّ الجمع بين ﴿الْبَيِّنَاتِ وَالْهُدَى﴾؟","answer":"جمع بين الأدلة الواضحة التي تكشف الحق والهدى الذي يرشد إليه، ليشمل الوعيد كتمان وجوه البيان والإرشاد جميعًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص574، تحت «سر إفراد الهدى وتأخيره عن البينات في قوله: «من البينات والهدى»»","url":""}]},{"id":"s2-668","number":668,"surah":2,"verses":[159],"references":[{"surah":2,"verses":[159]}],"verseLabel":"البقرة: 159","question":"ما سرّ التعبير في قوله تعالى: ﴿مِنْ بَعْدِ مَا بَيَّنَّاهُ لِلنَّاسِ فِي الْكِتَابِ﴾؟","answer":"لأن الكتمان بعد البيان أغلظ؛ لم تكن المعلومة غامضة ولا ملكًا خاصًا للعالم، بل جعلها الله للناس وأودعها كتابًا محفوظًا. فالقيود تنزع كل عذر: عرفوها، وكانت عامة، ومثبتة في مصدر يمكن الرجوع إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص574، تحت «مدلول (من) الابتدائية في قوله: «من بعد ما بيناه»»","url":""}]},{"id":"s2-669","number":669,"surah":2,"verses":[159],"references":[{"surah":2,"verses":[159]}],"verseLabel":"البقرة: 159","question":"ما سرّ التعبير في قوله تعالى: ﴿أُولَئِكَ يَلْعَنُهُمُ اللَّهُ وَيَلْعَنُهُمُ اللَّاعِنُونَ﴾ وكرر اللعن؟","answer":"كرر الفعل لإبراز لعنة الله ولعنة اللاعنين حكمين مستقلين وتأكيد شدة الوعيد على الكاتمين.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص577، تحت «دلالة تكرار الفعل «يلعنهم»»","url":""}]},{"id":"s2-670","number":670,"surah":2,"verses":[160],"references":[{"surah":2,"verses":[160]},{"surah":24,"verses":[5]}],"verseLabel":"البقرة: 160، النور: 5","question":"ما سرّ زيادة ﴿وَبَيَّنُوا﴾ في توبة كاتمي الهدى بالبقرة، وعدم ذكرها في النور: 5؟","answer":"زيد ﴿وبينوا﴾ لأن ذنبهم كتمان البينات والهدى، فلا تتم توبتهم حتى يظهروا ما كتموه. أما آية النور ففي ذنب القذف، فليس فيها علم مكتوم يحتاج إلى بيان.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص427، تحت «توجيه التشابه اللفظي بين هذه الآية وسورة البقرة»","url":""}]},{"id":"s2-671","number":671,"surah":2,"verses":[160],"references":[{"surah":2,"verses":[160]},{"surah":3,"verses":[89]}],"verseLabel":"البقرة: 160، آل عمران: 89","question":"ما سرّ اختلاف خاتمة توبة كاتمي الهدى: ﴿وَأَنَا التَّوَّابُ الرَّحِيمُ﴾، عن خاتمة آل عمران: ﴿فَإِنَّ اللَّهَ غَفُورٌ رَحِيمٌ﴾؟","answer":"ناسب ﴿التواب﴾ في البقرة التصريح بالتوبة بعد كتمان الهدى، فهو أخص بقبول الرجوع. وفي آل عمران جاء ﴿غفور﴾ في سياق الكفر بعد الإيمان؛ فناسب الاسم الدال على ستر الذنب ومغفرته.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص433، تحت «والاختلاف بين الآيتين في ثلاثة مواضع»","url":""}]},{"id":"s2-672","number":672,"surah":2,"verses":[160],"references":[{"surah":2,"verses":[160]},{"surah":3,"verses":[89]}],"verseLabel":"البقرة: 160، آل عمران: 89","question":"ما سرّ زيادة ﴿مِنْ بَعْدِ ذَلِكَ﴾ في آل عمران: 89، وعدم ذكرها في نظيرتها من البقرة؟","answer":"ذكرت آل عمران ﴿من بعد ذلك﴾ لأن السياق وصف انتقالًا زمنيًا خطيرًا: الكفر بعد الإيمان ثم ازدياد الكفر. أما البقرة فالكلام عن كتمان البينات، فلم يحتج إلى القيد نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص433، تحت «والاختلاف بين الآيتين في ثلاثة مواضع»","url":""}]},{"id":"s2-673","number":673,"surah":2,"verses":[160],"references":[{"surah":2,"verses":[160]}],"verseLabel":"البقرة: 160","question":"ما سرّ الجمع بين التوبة والإصلاح والبيان في قوله تعالى: ﴿تَابُوا وَأَصْلَحُوا وَبَيَّنُوا﴾؟","answer":"قابلت الآية الوعيد السابق بما يرفع سببه: فالتوبة والإصلاح رجوع إلى الله الذي يعلم السر والخفي، والبيان يظهر للناس ما كتموه ويعرّفهم بتوبتهم؛ فالناس لا يعلمون تغير حال الكاتمين حتى يبينوه.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص581، تحت عنوان «براعة اللف والنشر المرتب»","url":""}]},{"id":"s2-674","number":674,"surah":2,"verses":[160],"references":[{"surah":2,"verses":[160]}],"verseLabel":"البقرة: 160","question":"ما سرّ التعبير في قوله تعالى: ﴿فَأُولَئِكَ أَتُوبُ عَلَيْهِمْ﴾ مع أن التائب هو العبد؟","answer":"توبة العبد رجوعه إلى الله، وتوبة الله عليه رجوعه بالقبول والمغفرة والرضا؛ فالفعلان متقابلان لا متماثلان. والفاء تربط القبول بتحقق شروط الإصلاح والبيان، فلا تبقى التوبة دعوى بلا أثر.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص577، تحت «دلالة تكرار الفعل «يتوب عليهم»»","url":""}]},{"id":"s2-675","number":675,"surah":2,"verses":[160],"references":[{"surah":2,"verses":[160]}],"verseLabel":"البقرة: 160","question":"ما سرّ الالتفات إلى المتكلم في ﴿فأولئك أتوب عليهم﴾ بعد ﴿يلعنهم الله﴾؟","answer":"انتقل الأسلوب من الغيبة إلى صيغة المتكلم لبيان حالهم بعد قبول توبتهم وتشريف منزلتهم؛ فصدور الوعد منه سبحانه مباشرة يزيد إكرامهم وتقريبهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص583، تحت عنوان «الالتفات في قوله: ﴿أنزلنا﴾، ﴿بيناه﴾، ﴿يلعنهم الله﴾، ﴿أتوب﴾»","url":""}]},{"id":"s2-1518","number":1518,"surah":2,"verses":[160],"references":[{"surah":2,"verses":[160]}],"verseLabel":"البقرة: 160","question":"ما دلالة خاتمة ﴿وأنا التواب الرحيم﴾ في وعد التائبين من كتمان الحق؟","answer":"الخاتمة تقرر قبول توبة التائبين وتجمع لهم المغفرة والرحمة، وفي صيغة التواب دلالة على كثرة القبول. وهي تذييل يؤكد الوعد السابق ويأتي بمنزلة الدليل عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص583، تحت عنوان «بلاغة الفاصلة في قوله: ﴿وأنا التواب الرحيم﴾»","url":""}]},{"id":"s2-676","number":676,"surah":2,"verses":[161],"references":[{"surah":2,"verses":[161]}],"verseLabel":"البقرة: 161","question":"ما سرّ التعبير في قوله تعالى: ﴿إِنَّ الَّذِينَ كَفَرُوا وَمَاتُوا وَهُمْ كُفَّارٌ﴾؛ أليس موتهم بعد الكفر مفهومًا؟","answer":"قد يكفر الإنسان ثم يتوب قبل الموت، فلا يستحق الحكم المذكور؛ لذلك قيد العاقبة بالموت على الكفر. والجملة الحالية ﴿وهم كفار﴾ تثبت أن الصفة لازمتهم حتى أُغلق باب العمل، لا أنها مرحلة عابرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص588، تحت «تغاير الصيغ في التعبير عن اللعن»","url":""}]},{"id":"s2-677","number":677,"surah":2,"verses":[161],"references":[{"surah":2,"verses":[161]}],"verseLabel":"البقرة: 161","question":"كيف يُفهم قوله تعالى: ﴿وَالنَّاسِ أَجْمَعِينَ﴾ في لعنة من مات على الكفر، مع أن أهل دينه قد لا يلعنونه؟","answer":"تذكر الموسوعة عدة توجيهات: أن المراد المؤمنون ممن يعتد بلعنهم، أو عموم استحقاق اللعن، أو وقوعه من الجميع في الآخرة؛ إذ يتلاعن أهل الضلال هناك.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص588–589، تحت «ذكر العام واحتمال إرادته أو إرادة الخاص»","url":""}]},{"id":"s2-678","number":678,"surah":2,"verses":[162],"references":[{"surah":2,"verses":[162]}],"verseLabel":"البقرة: 162","question":"ما سرّ التعبير في قوله تعالى: ﴿خَالِدِينَ فِيهَا﴾، وإلى ماذا يعود الضمير مع أن المذكور «اللعنة»؟","answer":"يعود الضمير إلى اللعنة المذكورة، أي خالدين في أثرها وعذابها، ويجوز عوده إلى النار المفهومة من المقام.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص592، تحت «تنوع الاحتمال في مرجع الضمير»","url":""}]},{"id":"s2-679","number":679,"surah":2,"verses":[162],"references":[{"surah":2,"verses":[162]}],"verseLabel":"البقرة: 162","question":"ما سرّ الجمع بين قوله تعالى: ﴿لَا يُخَفَّفُ عَنْهُمُ الْعَذَابُ وَلَا هُمْ يُنْظَرُونَ﴾؟","answer":"نفت الآية أمرين يتمناهما المعذب: تخفيف شدة العذاب، أو تأخيره وإمهاله. فتقرر دوام العذاب من غير تخفيف ولا مهلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص593، تحت «ترابط جمل التذييل في بيان مقصود المعنى»","url":""}]},{"id":"s2-680","number":680,"surah":2,"verses":[163],"references":[{"surah":2,"verses":[163]}],"verseLabel":"البقرة: 163","question":"ما سرّ التعبير في قوله تعالى: ﴿وَإِلَهُكُمْ إِلَهٌ وَاحِدٌ﴾ فكرر لفظ ﴿إله﴾؟","answer":"الأول مبتدأ يقرر المعبود المنسوب إليهم، والثاني خبر موصوف بالوحدة، فاجتمع تقرير الألوهية وتوكيد وحدانيتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص596، تحت «نكتة توسط لفظ إله بين المبتدأ والخبر في قوله: «وإلهكم إله واحد»»","url":""}]},{"id":"s2-681","number":681,"surah":2,"verses":[163],"references":[{"surah":2,"verses":[163]}],"verseLabel":"البقرة: 163","question":"ما فائدة قوله تعالى: ﴿لَا إِلَهَ إِلَّا هُوَ﴾ بعد قوله: ﴿إِلَهٌ وَاحِدٌ﴾؟","answer":"الجملة الأولى تثبت أن إلههم واحد، ثم جاء النفي والاستثناء لقصر الألوهية عليه ونفيها عن كل ما سواه؛ فاجتمع الإثبات الصريح والنفي العام.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص598، تحت «الفرق في الإخبار عن التوحيد بين قوله: «وإلهكم إله واحد» وقوله: «لا إله إلا هو»»","url":""}]},{"id":"s2-682","number":682,"surah":2,"verses":[163],"references":[{"surah":2,"verses":[163]}],"verseLabel":"البقرة: 163","question":"ما مناسبة ختم آية التوحيد باسمَي ﴿الرَّحْمَنُ الرَّحِيمُ﴾؟","answer":"ختم باسمَي الرحمة ليبين أن الإله الواحد المتفرد بالألوهية واسع الرحمة، وليفتح باب الرجاء بعد سياق اللعن والعذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص599، تحت «قصر صفة الرحمة على الله في قوله: «الرحمن الرحيم»»","url":""}]},{"id":"s2-683","number":683,"surah":2,"verses":[164],"references":[{"surah":2,"verses":[164]}],"verseLabel":"البقرة: 164","question":"ما سرّ جمع هذه الآيات الكونية المتنوعة في آية واحدة؟","answer":"جمعت الآية دلائل من الخلق والحركة والرزق والحياة؛ لتبين أن انتظام هذه الظواهر المختلفة وتعاونها تحت تدبير واحد دليل على وحدانية المدبر.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص612، تحت «فائدة الفصل بين الجمل من أول الآية إلى آخرها»","url":""}]},{"id":"s2-684","number":684,"surah":2,"verses":[164],"references":[{"surah":2,"verses":[164]},{"surah":29,"verses":[63]}],"verseLabel":"البقرة: 164، العنكبوت: 63","question":"ما سرّ اختلاف التعبير بين قوله تعالى في البقرة: ﴿فَأَحْيَا بِهِ الْأَرْضَ بَعْدَ مَوْتِهَا﴾، وقوله تعالى في العنكبوت: ﴿فَأَحْيَا بِهِ الْأَرْضَ مِنْ بَعْدِ مَوْتِهَا﴾ بزيادة ﴿مِنْ﴾؟","answer":"زيدت ﴿مِنْ﴾ في العنكبوت لأنها لابتداء الغاية، فتشير إلى إحياء الأرض عقب شروع موتها، وناسب ذلك ما سبق من عموم رزق الله خلقه؛ أما البقرة والجاثية ففي تعداد القدرة، فناسب الإحياء بعد تراخي الموت مدة لما فيه من زيادة الدلالة على القدرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص646، تحت «نوع «من» ودلالتها»","url":""}]},{"id":"s2-686","number":686,"surah":2,"verses":[164],"references":[{"surah":2,"verses":[164]}],"verseLabel":"البقرة: 164","question":"ما سرّ التعبير في قوله تعالى: ﴿وَاخْتِلَافِ اللَّيْلِ وَالنَّهَارِ﴾، دون أن يقال: «وتعاقبهما»؟","answer":"الاختلاف يجمع التعاقب وتفاوت الطول والقصر والحر والبرد والضياء والظلمة، واختلاف ما يصلح فيهما من أعمال؛ فهو أوسع من مجرد مجيء أحدهما بعد الآخر. وكل هذا التنوع يجري بنظام لا يضطرب.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص608، تحت «فائدة إضافة الاختلاف لليل والنهار في الآية»","url":""}]},{"id":"s2-687","number":687,"surah":2,"verses":[164],"references":[{"surah":2,"verses":[164]}],"verseLabel":"البقرة: 164","question":"ما دلالة تقييد الفلك بقوله تعالى: ﴿بِمَا يَنْفَعُ النَّاسَ﴾؟","answer":"قيدها بالنفع لأن موضع الدلالة ليس مجرد جريان السفن، بل تسخيرها لحمل أقوات الناس وتجارتهم ومسافريهم، فاجتمعت القدرة والنعمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص609، تحت «دلالة (ما) في قوله: «بما ينفع الناس»»","url":""}]},{"id":"s2-688","number":688,"surah":2,"verses":[164],"references":[{"surah":2,"verses":[164]}],"verseLabel":"البقرة: 164","question":"ما سرّ التعبير في قوله تعالى: ﴿فَأَحْيَا بِهِ الْأَرْضَ بَعْدَ مَوْتِهَا﴾، مع أن الأرض لا تموت كالحيوان؟","answer":"شبه جفاف الأرض وخلوها من النبات بالموت، وإنباتها واخضرارها بالحياة؛ وفي هذا التحول المشاهد دليل على إمكان الإحياء والبعث.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص610، تحت «بلاغة قوله: «فأحيا به الأرض»»","url":""}]},{"id":"s2-689","number":689,"surah":2,"verses":[164],"references":[{"surah":2,"verses":[164]}],"verseLabel":"البقرة: 164","question":"ما سرّ التعبير في قوله تعالى: ﴿وَبَثَّ فِيهَا مِنْ كُلِّ دَابَّةٍ﴾، دون أن يقال: «وخلق الدواب»؟","answer":"اختير البث لأنه يصور إيجاد الدواب ونشرها وتفريقها في الأرض، و﴿من كل﴾ تعم أنواعها المتنوعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص603–604، تحت «شرح المفردات: ﴿وبث﴾ و﴿دابة﴾»","url":""}]},{"id":"s2-690","number":690,"surah":2,"verses":[164],"references":[{"surah":2,"verses":[164]}],"verseLabel":"البقرة: 164","question":"ما سرّ التعبير في قوله تعالى: ﴿وَتَصْرِيفِ الرِّيَاحِ﴾، دون أن يقال: «وهبوب الرياح»؟","answer":"التصريف يشمل تغيير اتجاهها وقوتها وحرارتها ومنافعها، وسوقها مرة بالبشرى ومرة بالتلقيح أو تحريك السحاب؛ فهي لا تهب على نمط واحد. هذا التدبير المتنوع هو موضع الدلالة، لا وجود الهواء المتحرك فقط.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص612، تحت «أوجه الإيجاز بالحذف في قوله: «وتصريف الرياح»»","url":""}]},{"id":"s2-691","number":691,"surah":2,"verses":[164],"references":[{"surah":2,"verses":[164]}],"verseLabel":"البقرة: 164","question":"ما دلالة وصف السحاب بأنه ﴿الْمُسَخَّرِ بَيْنَ السَّمَاءِ وَالْأَرْضِ﴾؟","answer":"التسخير هو التذليل والسوق إلى الغرض المخصوص بأمر الله وإرادته؛ فالسحاب مهيأ لما يساق إليه، يجري وفق تدبير الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص604–605، تحت «شرح المفردات: ﴿والسحاب المسخر﴾»","url":""}]},{"id":"s2-692","number":692,"surah":2,"verses":[164],"references":[{"surah":2,"verses":[164]}],"verseLabel":"البقرة: 164","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿لَآيَاتٍ لِقَوْمٍ يَعْقِلُونَ﴾ مع أن هذه الظواهر يراها الجميع؟","answer":"لأن مجرد رؤية الظواهر لا تكفي؛ وإنما تصير آيات نافعة لمن يتدبر نظامها ويعبر منها بعقله إلى معرفة الخالق ووحدانيته.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص613، تحت «وجه تخصيص الآيات بقوله: «لقوم يعقلون»، ودلالة اللام فيها»","url":""}]},{"id":"s2-693","number":693,"surah":2,"verses":[165],"references":[{"surah":2,"verses":[165]}],"verseLabel":"البقرة: 165","question":"ما سرّ التعبير في قوله تعالى: ﴿وَمِنَ النَّاسِ مَنْ يَتَّخِذُ مِنْ دُونِ اللَّهِ أَنْدَادًا﴾ بعد كل آيات التوحيد السابقة؟","answer":"جاء ذكر الأنداد بعد دلائل التوحيد لإظهار تناقض الشرك مع الآيات الظاهرة، و﴿من الناس﴾ للتبعيض لأن هذا الفعل صادر من فريق منهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص618، تحت «الاستئناف لبيان حال المشركين»","url":""}]},{"id":"s2-694","number":694,"surah":2,"verses":[165],"references":[{"surah":2,"verses":[165]}],"verseLabel":"البقرة: 165","question":"لماذا سمّى المعبودات ﴿أَنْدَادًا﴾؟","answer":"الند هو المثل والنظير المخالف. والمراد هنا الأصنام أو من يطيعونهم من الرجال من دون الله؛ وتسميتها أندادًا لا تثبت وجود مماثل حقيقي لله.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص615–616، تحت «شرح المفردات: ﴿أندادًا﴾»","url":""}]},{"id":"s2-695","number":695,"surah":2,"verses":[165],"references":[{"surah":2,"verses":[165]}],"verseLabel":"البقرة: 165","question":"ما سرّ التعبير في قوله تعالى: ﴿يُحِبُّونَهُمْ كَحُبِّ اللَّهِ﴾، دون أن يقال: «يعبدونهم مع الله»؟","answer":"عبر بالحب ليبين أنهم سووا أندادهم بالله في المحبة والتعظيم، فكشف مقدار تعلقهم الباطل بها، لا مجرد صورة فعل ظاهر.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص621، تحت «معنى التشبيه في قوله: «كحب الله»»","url":""}]},{"id":"s2-696","number":696,"surah":2,"verses":[165],"references":[{"surah":2,"verses":[165]}],"verseLabel":"البقرة: 165","question":"ما سرّ التعبير في قوله تعالى: ﴿وَالَّذِينَ آمَنُوا أَشَدُّ حُبًّا لِلَّهِ﴾، دون أن يقال: «يحبون الله أكثر»؟","answer":"المؤمنون أشد حبًا لله لإخلاص حبهم له وثباته، أما المشركون فيوزعون حبهم بين الله وأندادهم؛ فحب المؤمن أوحد وأرسخ.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص622، تحت «دلالة التعبير عن الحب بـ«أشد» دون «أحب» في الآية»","url":""}]},{"id":"s2-697","number":697,"surah":2,"verses":[165],"references":[{"surah":2,"verses":[165]}],"verseLabel":"البقرة: 165","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلَوْ يَرَى الَّذِينَ ظَلَمُوا إِذْ يَرَوْنَ الْعَذَابَ﴾ وأظهر ﴿الذين ظلموا﴾ بدل «ولو يروا»؟","answer":"الإظهار يثبت علة ما يرونه: ظلمهم هو الذي ساقهم إلى المشهد، ويعيد وصفهم عند جواب التمني حتى لا يضيع سبب العقوبة في الضمائر. كما يجعل السامع يقف على الاسم المذموم قبل هول العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص624، تحت «نكتة إظهار ما حقه الإضمار»","url":""}]},{"id":"s2-698","number":698,"surah":2,"verses":[165],"references":[{"surah":2,"verses":[165]}],"verseLabel":"البقرة: 165","question":"ما سرّ الجمع بين قوله تعالى: ﴿أَنَّ الْقُوَّةَ لِلَّهِ جَمِيعًا وَأَنَّ اللَّهَ شَدِيدُ الْعَذَابِ﴾؟","answer":"الجملة الأولى تنفي القوة عن الأنداد وتثبتها كلها لله، والثانية تبين أثر هذه القوة في عقاب المشركين؛ فجمع بين زوال النصير وشدة العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص627، تحت «فائدة الوصل في قوله: «أن القوة لله جميعًا وأن الله شديد العذاب»»","url":""}]},{"id":"s2-699","number":699,"surah":2,"verses":[166],"references":[{"surah":2,"verses":[166]}],"verseLabel":"البقرة: 166","question":"لماذا عُبّر بالماضي في قوله تعالى: ﴿إِذْ تَبَرَّأَ الَّذِينَ اتُّبِعُوا مِنَ الَّذِينَ اتَّبَعُوا﴾ مع أن التبرؤ يقع في الآخرة؟","answer":"للدلالة على تحقق وقوعه؛ فصُوّر الأمر المستقبل بصورة ما وقع وانقضى، تأكيدًا لوقوعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص631، تحت «إيثار التعبير بالفعل الماضي في قوله: ﴿إذ تبرأ﴾»","url":""}]},{"id":"s2-700","number":700,"surah":2,"verses":[166],"references":[{"surah":2,"verses":[166]}],"verseLabel":"البقرة: 166","question":"ما سرّ التعبير في قوله تعالى: ﴿وَتَقَطَّعَتْ بِهِمُ الْأَسْبَابُ﴾، وما الأسباب التي تتقطع؟","answer":"الأسباب هي الوصلات التي جمعتهم في الدنيا، كالقرابة والاتباع والدين والمودة؛ وصوّر انقطاعها بانقطاع الحبال، فلا ينتفعون بها عند معاينة العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص635، تحت «الاستعارة التمثيلية في تقطع الأسباب»","url":""}]},{"id":"s2-701","number":701,"surah":2,"verses":[167],"references":[{"surah":2,"verses":[167]}],"verseLabel":"البقرة: 167","question":"ما دلالة تمني الأتباع: ﴿لَوْ أَنَّ لَنَا كَرَّةً فَنَتَبَرَّأَ مِنْهُمْ كَمَا تَبَرَّءُوا مِنَّا﴾؟","answer":"تمنوا الرجوع ليقابلوا تبرؤ المتبوعين منهم بالتبرؤ منهم، فتكشف الأمنية حسرتهم على اتباعهم وانقلاب الصلة التي كانت بينهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص637، تحت «دلالة التمني بـ«لو» في قوله: «لو أن لنا كرة فنتبرأ منهم»»","url":""}]},{"id":"s2-702","number":702,"surah":2,"verses":[167],"references":[{"surah":2,"verses":[167]}],"verseLabel":"البقرة: 167","question":"ما سرّ التعبير في قوله تعالى: ﴿كَذَلِكَ يُرِيهِمُ اللَّهُ أَعْمَالَهُمْ حَسَرَاتٍ عَلَيْهِمْ﴾؛ كيف تصير الأعمال حسرات؟","answer":"يريهم الله سوء عاقبة أعمالهم وما ترتب عليها من فوات النجاة، فتغدو أسبابًا للندم، وجمعت الحسرات لتعددها وتتابعها.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص639، تحت «معنى الرؤية في قوله: «يريهم الله أعمالهم حسرات عليهم»»","url":""}]},{"id":"s2-703","number":703,"surah":2,"verses":[167],"references":[{"surah":2,"verses":[167]}],"verseLabel":"البقرة: 167","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿وَمَا هُمْ بِخَارِجِينَ مِنَ النَّارِ﴾؟","answer":"ختم بنفي خروجهم من النار نفيًا مؤكدًا بالباء، ليقطع كل رجاء في الانفكاك منها ويقرر دوام العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص640، تحت «الاعتراض والتذييل في الآية»","url":""}]},{"id":"s2-704","number":704,"surah":2,"verses":[168],"references":[{"surah":2,"verses":[168]}],"verseLabel":"البقرة: 168","question":"ما سرّ التعبير في قوله تعالى: ﴿ولا تتبعوا خطوات الشيطان﴾ لا: لا تتبعوا الشيطان؟","answer":"صور الإغواء خطوات صغيرة متتابعة؛ فالشيطان لا ينقل غالبًا إلى النهاية دفعة واحدة، بل يستدرج بتنازل يعقبه آخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص648، تحت «دلالة النهي عن اتباع الخطوات في قوله: «ولا تتبعوا خطوات الشيطان»»","url":""}]},{"id":"s2-705","number":705,"surah":2,"verses":[168],"references":[{"surah":2,"verses":[168]}],"verseLabel":"البقرة: 168","question":"ما سرّ خطاب الناس جميعًا بقوله تعالى: ﴿يَا أَيُّهَا النَّاسُ كُلُوا مِمَّا فِي الْأَرْضِ﴾، دون تخصيص المؤمنين؟","answer":"عم الخطاب الناس لأن الانتفاع بما في الأرض عام، ولأن السياق يرد تحريم المشركين أشياء من الحرث والأنعام بغير حجة من الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص645، تحت «فائدة الاستئناف في قوله: «يا أيها الناس»»","url":""}]},{"id":"s2-706","number":706,"surah":2,"verses":[168],"references":[{"surah":2,"verses":[168]}],"verseLabel":"البقرة: 168","question":"ما سرّ الجمع بين الوصفين: ﴿حَلَالًا طَيِّبًا﴾؟","answer":"جمع بين الحلال في حكم الشرع والطيب في صفة المأكول واستطابة النفس له، فلا يغني أحد الوصفين عن الآخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص647، تحت «دلالة الجمع بين الصفتين: الحلال والطيب»","url":""}]},{"id":"s2-707","number":707,"surah":2,"verses":[168],"references":[{"surah":2,"verses":[168]}],"verseLabel":"البقرة: 168","question":"ما سرّ التعبير في قوله تعالى: ﴿إِنَّهُ لَكُمْ عَدُوٌّ مُبِينٌ﴾ فقدم ﴿لكم﴾؟","answer":"التقديم يقرب الخطر ويخصص عداوته بالمخاطبين: ليس حديثًا عن عدو بعيد، بل عدوكم أنتم. و﴿مبين﴾ تحتمل ظاهر العداوة ومُظهرها بأثره؛ فلا عذر لمن يسلك خطوات خصم أعلن قصده منذ البداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص650، تحت «نكتة التقديم والتأخير في قوله: «إنه لكم عدو مبين»»","url":""}]},{"id":"s2-708","number":708,"surah":2,"verses":[169],"references":[{"surah":2,"verses":[169]}],"verseLabel":"البقرة: 169","question":"ما سرّ ترتيب أوامر الشيطان: ﴿بِالسُّوءِ وَالْفَحْشَاءِ وَأَنْ تَقُولُوا عَلَى اللَّهِ مَا لَا تَعْلَمُونَ﴾؟","answer":"رتبها تصاعديًا: السوء يعم المعاصي، والفحشاء ما اشتد قبحه منها، والقول على الله بلا علم من أقبح ذلك لما فيه من الافتراء وإضلال الغير.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص654، تحت «التفصيل والتبيين في الآية لما أجمل سابقا»","url":""}]},{"id":"s2-709","number":709,"surah":2,"verses":[169],"references":[{"surah":2,"verses":[169]}],"verseLabel":"البقرة: 169","question":"ما سرّ التعبير في قوله تعالى: ﴿مَا لَا تَعْلَمُونَ﴾ ولم يذكر ما الذي لا يعلمونه؟","answer":"حذف المفعول ليعم كل قول على الله بلا علم: في ذاته وأحكامه وحلاله وحرامه ووعده ووعيده. فلا ينجو المتكلم بأن موضوعه صغير؛ العبرة بجرأة النسبة إلى الله من غير برهان.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص656، تحت «فائدة حذف المفعول به في قوله: «ما لا تعلمون»»","url":""}]},{"id":"s2-710","number":710,"surah":2,"verses":[170],"references":[{"surah":2,"verses":[170]}],"verseLabel":"البقرة: 170","question":"ما دلالة عدم ذكر متعلق الهداية في قوله تعالى: ﴿وَلَا يَهْتَدُونَ﴾؟","answer":"حذف متعلق الهداية ليعم؛ أي لا يهتدون إلى حق ولا طريق رشد في هذا المقام، فلا يقيد ضلالهم بوجه واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص670، تحت «فائدة الحذف في قوله تعالى: «ولا يهتدون»»","url":""}]},{"id":"s2-711","number":711,"surah":2,"verses":[170],"references":[{"surah":2,"verses":[170]},{"surah":5,"verses":[104]}],"verseLabel":"البقرة: 170؛ المائدة: 104","question":"ما سرّ اختلاف التعبير بين قولهم في البقرة: ﴿بَلْ نَتَّبِعُ مَا أَلْفَيْنَا عَلَيْهِ آبَاءَنَا﴾، وقولهم في المائدة: ﴿حَسْبُنَا مَا وَجَدْنَا عَلَيْهِ آبَاءَنَا﴾؟","answer":"في البقرة حكى قولهم مجرد اتباع ما كانوا قد ألفوا عليه آباءهم. أما في المائدة فزاد قولهم ﴿حسبنا﴾، أي يكفينا ما وجدنا عليه الآباء؛ فدل على أنهم حسموا الأمر واكتفوا بالموروث، فكان قولهم أبلغ في الجزم والاكتفاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص763–764، تحت عنوان «الفرق المعجمي بين قوله: ﴿يعقلون﴾ وقوله: ﴿يعلمون﴾»","url":""}]},{"id":"s2-712","number":712,"surah":2,"verses":[170],"references":[{"surah":2,"verses":[170]}],"verseLabel":"البقرة: 170","question":"ما دلالة قولهم: ﴿مَا أَلْفَيْنَا عَلَيْهِ آبَاءَنَا﴾، دون الاستناد إلى علم أو حجة؟","answer":"لفظ ﴿ألفينا﴾ يدل على أنهم صادفوا آباءهم على حال فألفوها واتبعوها؛ فهو اعتراف بأن مستندهم الموروث لا العلم بصحته.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص671، تحت «(وجد) و(ألفى)»","url":""}]},{"id":"s2-714","number":714,"surah":2,"verses":[170],"references":[{"surah":2,"verses":[170]}],"verseLabel":"البقرة: 170","question":"ما سرّ التعبير في قوله تعالى: ﴿أَوَلَوْ كَانَ آبَاؤُهُمْ لَا يَعْقِلُونَ شَيْئًا وَلَا يَهْتَدُونَ﴾؟","answer":"لا يذم اتباع الآباء لمجرد أنهم آباء، بل إذا فقدوا المصدرين اللذين يصححان الطريق: العقل الذي ينظر، والهداية التي تأتي من الوحي. فالسؤال يختبر التقليد: أيبقى واجبًا حتى لو اجتمع الجهل والضلال؟","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص670، تحت «سر تقديم نفي العقل على نفي الهداية»","url":""}]},{"id":"s2-715","number":715,"surah":2,"verses":[170],"references":[{"surah":2,"verses":[170]}],"verseLabel":"البقرة: 170","question":"ما سرّ التعبير في قوله تعالى: ﴿لَا يَعْقِلُونَ شَيْئًا﴾، ولم يكتفِ بـ«لا يعقلون»؟","answer":"﴿شيئًا﴾ في سياق النفي تستغرق أدنى قدر معتبر في موضع الاتباع؛ أي ليس عندهم من الحجة ما يسوغ جعلهم معيارًا للدين. والمقصود نفي العقل النافع في هذا الباب، لا نفي القدرة الذهنية عنهم مطلقًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص668، تحت «إعراب «شيئا» مبني على معنى العموم»","url":""}]},{"id":"s2-716","number":716,"surah":2,"verses":[170],"references":[{"surah":2,"verses":[170]},{"surah":5,"verses":[104]}],"verseLabel":"البقرة: 170 والمائدة: 104","question":"ما سرّ اختلاف التعبير بين ﴿لَا يَعْقِلُونَ شَيْئًا﴾ في البقرة و﴿لَا يَعْلَمُونَ شَيْئًا﴾ في المائدة؟","answer":"نفي العلم في المائدة أبلغ ومناسب لدعوى ﴿حسبنا ما وجدنا﴾، أما البقرة فقولهم مجرد اتباع ما ألفوا فناسب نفي التعقل، واتفق الموضعان في نفي الهداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص669، تحت «توجيه المتشابه اللفظي»","url":""}]},{"id":"s2-717","number":717,"surah":2,"verses":[171],"references":[{"surah":2,"verses":[171]}],"verseLabel":"البقرة: 171","question":"ما وجه التمثيل في قوله تعالى: ﴿وَمَثَلُ الَّذِينَ كَفَرُوا كَمَثَلِ الَّذِي يَنْعِقُ بِمَا لَا يَسْمَعُ﴾؟","answer":"حذف من طرفي التشبيه ما دل عليه المذكور؛ فالتقدير مثل الداعي والكفار كمثل الناعق والمنعوق به الذي لا يدرك إلا الصوت، فالكفار هم المشبهون بالمنعوق به.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص678، تحت «دلالة التشبيه في قوله: «ومثل الذين كفروا كمثل الذي ينعق»»","url":""}]},{"id":"s2-718","number":718,"surah":2,"verses":[171],"references":[{"surah":2,"verses":[171]}],"verseLabel":"البقرة: 171","question":"ما سرّ التعبير في قوله تعالى: ﴿بِمَا لَا يَسْمَعُ إِلَّا دُعَاءً وَنِدَاءً﴾، دون أن يقال: «بمن لا يفهم»؟","answer":"لأن الصورة لا تنفي وصول الصوت إلى الأذن، بل تنفي تجاوزه إلى الفهم والاستجابة؛ فهم يسمعون ألفاظ الوحي كما تسمع البهيمة صوت الراعي، ولا يعون مقصوده. وهذا أشد في الذم من مجرد فقد السماع.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص689، تحت «الدعاء والنداء»","url":""}]},{"id":"s2-719","number":719,"surah":2,"verses":[171],"references":[{"surah":2,"verses":[171]}],"verseLabel":"البقرة: 171","question":"ما سرّ الجمع بين ﴿دُعَاءً﴾ و﴿نِدَاءً﴾ مع تقارب معناهما؟","answer":"جمع اللفظين لاستيعاب صور الصوت الموجه إليهم؛ فالنداء قد يقع بأداته دون التصريح باسم المنادى، أما الدعاء فلا يكاد يكون إلا مع ذكر المدعو، وهم لا يدركون من ذلك إلا مجرد الصوت.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص689، تحت «الدعاء والنداء»","url":""}]},{"id":"s2-720","number":720,"surah":2,"verses":[171],"references":[{"surah":2,"verses":[171]}],"verseLabel":"البقرة: 171","question":"ما وجه وصفهم بقوله تعالى: ﴿صُمٌّ بُكْمٌ عُمْيٌ﴾ مع سلامة حواسهم الظاهرة؟","answer":"هذه أوصاف مجازية لتعطيل وظائف الحواس في تلقي الحق؛ فهم يسمعون الأصوات ولا يقبلون الهدى، ولا ينطقون به، ولا يعتبرون بما يرون، فكأن حواسهم مفقودة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص687، تحت «الاستعارة التصريحية والتشبيه البليغ في قوله: «صم بكم عمي»»","url":""}]},{"id":"s2-722","number":722,"surah":2,"verses":[171],"references":[{"surah":2,"verses":[171]}],"verseLabel":"البقرة: 171","question":"ما مناسبة ختم المثل بقوله تعالى: ﴿فَهُمْ لَا يَعْقِلُونَ﴾؟","answer":"الفاء ترتب عدم التعقل النافع على تعطيل السمع والنطق والبصر عن الحق. والمضارع يدل على استمرار تركهم استعمال العقل، لا على انعدام أصل القوة العقلية.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص689، تحت «دلالة نفي العقل في قوله: «فهم لا يعقلون»»","url":""}]},{"id":"s2-723","number":723,"surah":2,"verses":[168,172],"references":[{"surah":2,"verses":[168,172]}],"verseLabel":"البقرة: 172 والبقرة: 168","question":"ما سرّ التعبير هنا في قوله تعالى: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا كُلُوا﴾، وقال قبلها: ﴿يَا أَيُّهَا النَّاسُ كُلُوا﴾؟","answer":"كان خطاب الآية 168 للناس جميعًا لإبطال التحريمات المبتدعة، أما هنا فخص المؤمنين لأن المقام مقام شكر المنعم وإخلاص العبادة له بعد الانتفاع بالطيبات.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص697، تحت «توجيه المتشابه اللفظي»","url":""}]},{"id":"s2-724","number":724,"surah":2,"verses":[172],"references":[{"surah":2,"verses":[172]}],"verseLabel":"البقرة: 172","question":"ما سرّ تكرار الأمر بالأكل في الآية 172 بعد وروده في الآية 168؟","answer":"الأمر الأول إباحة عامة للناس ورد على تحريم المشركين، والثاني خطاب للمؤمنين يربط أكل الطيبات بالشكر والعبادة؛ فاختلف المخاطب والغرض.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص697، تحت «توجيه المتشابه اللفظي»","url":""}]},{"id":"s2-726","number":726,"surah":2,"verses":[172],"references":[{"surah":2,"verses":[172]}],"verseLabel":"البقرة: 172","question":"ما مناسبة إتباع الأمر بالأكل بقوله تعالى: ﴿وَاشْكُرُوا لِلَّهِ﴾؟","answer":"أردف الأمر بالأكل بالشكر لأن إباحة الطيبات والتمكين منها نعمة تستوجب شكر الله بالطاعة والثناء عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص699، تحت «دلالة إرداف الأمر بالشكر بعد الأمر بالأكل»","url":""}]},{"id":"s2-727","number":727,"surah":2,"verses":[172],"references":[{"surah":2,"verses":[172]}],"verseLabel":"البقرة: 172","question":"ما سرّ التعبير في قوله تعالى: ﴿وَاشْكُرُوا لِلَّهِ﴾، دون أن يقال: «واشكروني»؟","answer":"تعدية الشكر باللام تبرز الإحسان الذي صدر من الله وتكلّف العباد بما يطيقون من الاعتراف بأفعاله وآلائه، بدل الإحاطة بحقيقة ذاته ونعمه التي لا تحصى. وفيها لطف وتخفيف مع تعظيم الاستحقاق.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص698، تحت «دلالة الأمر في قوله تعالى: «واشكروا لله»»","url":""}]},{"id":"s2-728","number":728,"surah":2,"verses":[172],"references":[{"surah":2,"verses":[172]}],"verseLabel":"البقرة: 172","question":"ما سرّ تعليق الشكر بقوله تعالى: ﴿إِنْ كُنْتُمْ إِيَّاهُ تَعْبُدُونَ﴾ مع وجوبه؟","answer":"الشرط للحث وإظهار التلازم، لا للشك: إن كنتم تخصونه بالعبادة حقًا فخصوه بالشكر؛ فالشكر شاهد صدق العبودية.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص700، تحت «دلالة الشرط في قوله: «إن كنتم إياه تعبدون»»","url":""}]},{"id":"s2-729","number":729,"surah":2,"verses":[172],"references":[{"surah":2,"verses":[172]},{"surah":16,"verses":[114]}],"verseLabel":"البقرة: 172؛ النحل: 114","question":"ما سرّ تقديم ﴿إِيَّاهُ﴾ في ﴿إِنْ كُنْتُمْ إِيَّاهُ تَعْبُدُونَ﴾؟","answer":"يفيد تقديم إياه الاختصاص؛ أي إن كنتم تخصونه وحده بالعبادة دون غيره فاشكروا له. فتقديم المفعول يقرر إخلاص العبادة له، ويربط هذا الإخلاص بالشكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص700–701، تحت عنوان «دلالة تقديم ﴿إياه﴾، وتأخير الفعل»","url":""}]},{"id":"s2-730","number":730,"surah":2,"verses":[173],"references":[{"surah":2,"verses":[173]}],"verseLabel":"البقرة: 173","question":"ما سرّ التعبير في قوله تعالى: ﴿إنما حرم عليكم﴾ بأداة الحصر؟","answer":"جاء الحصر ردًا على من حرم ما لم يحرمه الله، أو قصرًا للمذكورات على حال الاختيار دون الاضطرار، لا حصرًا مطلقًا لكل محرمات الشريعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص706، تحت «توجيه القصر في قوله تعالى: «إنما حرم عليكم الميتة»»","url":""}]},{"id":"s2-731","number":731,"surah":2,"verses":[173],"references":[{"surah":2,"verses":[173]}],"verseLabel":"البقرة: 173","question":"ما سرّ التعبير في قوله تعالى: ﴿لحم الخنزير﴾، دون أن يقال: الخنزير؟","answer":"لأن المقام في المأكولات فخص اللحم، وهو المقصود الأعظم من الحيوان، مع دلالة النصوص على تحريم سائر أجزائه المأكولة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص707، تحت «وجه ذكر لفظ اللحم مع الخنزير دون الميتة»","url":""}]},{"id":"s2-732","number":732,"surah":2,"verses":[173],"references":[{"surah":2,"verses":[173]}],"verseLabel":"البقرة: 173","question":"ما سرّ زيادة ﴿فَلَا إِثْمَ عَلَيْهِ﴾ بعد الاضطرار في البقرة، وعدم ذكرها في آية المائدة؟","answer":"صرحت البقرة برفع الحرج لتقرير أصل رخصة الضرورة، وفي المائدة دل ختام ﴿فإن الله غفور رحيم﴾ على سقوط الإثم ضمنًا مع سياق تفصيل أوسع.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص536، تحت «نكتة ذكر قوله: «فلا إثم عليه» في البقرة، ولم يذكر ذلك في آية المائدة»","url":""}]},{"id":"s2-733","number":733,"surah":2,"verses":[173],"references":[{"surah":2,"verses":[173]},{"surah":5,"verses":[3]}],"verseLabel":"البقرة: 173، المائدة: 3","question":"ما سرّ اختلاف التعبير بين قوله تعالى في البقرة: ﴿إِنَّمَا حَرَّمَ عَلَيْكُمُ الْمَيْتَةَ﴾ بأداة الحصر، وقوله تعالى في المائدة: ﴿حُرِّمَتْ عَلَيْكُمُ الْمَيْتَةُ﴾ بلا ﴿إنما﴾؟","answer":"سبقت البقرة إباحة عامة للطيبات، فجاءت ﴿إنما﴾ لحصر المستثنيات المحرمة ومنع تحريم ما أحل الله. أما المائدة فمقام استكمال الأحكام وتفصيل المحرمات، فجاء التقرير من غير إعادة الحصر.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص535، تحت «سر التعبير بأسلوب القصر «إنما» في موضع البقرة دون موضع المائدة»","url":""}]},{"id":"s2-734","number":734,"surah":2,"verses":[173],"references":[{"surah":2,"verses":[173]},{"surah":5,"verses":[3]}],"verseLabel":"البقرة: 173، المائدة: 3","question":"ما سرّ التصريح بفاعل التحريم في البقرة: ﴿حَرَّمَ عَلَيْكُمُ﴾، وبناء الفعل للمجهول في المائدة: ﴿حُرِّمَتْ عَلَيْكُمُ﴾؟","answer":"صرحت البقرة بالفاعل لتقرر أن التحريم لله وحده في مواجهة من يشرّع من عنده. أما خطاب المؤمنين في المائدة فمعلوم فيه المحرِّم، فبني الفعل للمجهول وتوجه الاهتمام إلى المحرمات.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص535، تحت «سر التعبير بالبناء للفاعل في موضع البقرة في قوله: «إنما حرم»، وبالبناء للمفعول في موضع المائدة»","url":""}]},{"id":"s2-735","number":735,"surah":2,"verses":[173],"references":[{"surah":2,"verses":[173]},{"surah":5,"verses":[3]}],"verseLabel":"البقرة: 173، المائدة: 3","question":"ما سرّ التعبير في قوله تعالى في البقرة: ﴿وَمَا أُهِلَّ بِهِ لِغَيْرِ اللَّهِ﴾، وفي المائدة: ﴿وَمَا أُهِلَّ لِغَيْرِ اللَّهِ بِهِ﴾ بتغيير ترتيب الجارّين؟","answer":"سياق البقرة بدأ بالرزق والطعام، فقدم ﴿به﴾ العائد على المذبوح لأنه موضع الحديث. أما المائدة فسياقها يبرز جهة التحليل والتحريم وإبطال ما يُصرف لغير الله، فقدم ﴿لغير الله﴾ ليجعل بطلان الجهة المشركة في واجهة العبارة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص536، تحت «السر في تقديم الجار والمجرور «به» على «لغير الله» في قوله: «وما أهل به لغير الله»»","url":""}]},{"id":"s2-736","number":736,"surah":2,"verses":[173],"references":[{"surah":2,"verses":[173]},{"surah":5,"verses":[3]}],"verseLabel":"البقرة: 173، المائدة: 3","question":"ما سرّ اقتصار آية البقرة على أربعة محرمات، وزيادة صور أخرى في آية المائدة؟","answer":"ذكرت البقرة أصول المحرمات، ثم جاءت المائدة ـ وهي من أواخر ما نزل ـ في مقام استكمال التشريع وتفصيل الصور الداخلة في تلك الأصول.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص536، تحت «السر في زيادة المحرمات في سورة المائدة عن المحرمات في سورة البقرة»","url":""}]},{"id":"s2-737","number":737,"surah":2,"verses":[173],"references":[{"surah":2,"verses":[173]},{"surah":6,"verses":[145]},{"surah":16,"verses":[115]}],"verseLabel":"البقرة: 173، الأنعام: 145، النحل: 115","question":"ما سرّ اختلاف الخاتمة بين ﴿فَإِنَّ اللَّهَ غَفُورٌ رَحِيمٌ﴾ في البقرة والنحل، و﴿فَإِنَّ رَبَّكَ غَفُورٌ رَحِيمٌ﴾ في الأنعام؟","answer":"ناسب اسم الجلالة في البقرة والنحل سياق النعمة والعبادة والتشريع: فالمنعم المعبود هو الغفور الرحيم. وفي الأنعام تكرر وصف الرب مع آثار التربية والإنشاء، فناسب قوله ﴿ربك﴾ رخصة الضرورة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص715، تحت «لماذا قال في موضع: «فإن ربك»، وفي الآخر: «فإن الله»؟»","url":""}]},{"id":"s2-738","number":738,"surah":2,"verses":[173],"references":[{"surah":2,"verses":[173]}],"verseLabel":"البقرة: 173","question":"ما سرّ التعبير في قوله تعالى: ﴿إِنَّمَا حَرَّمَ عَلَيْكُمُ﴾ بعد الأمر بالأكل من الطيبات؟","answer":"جاء بعد إباحة الطيبات ردًا على التحريم المبتدع، وقصر المذكورات بالنسبة لما استحله الكفار أو على حال الاختيار، ثم استثنى الاضطرار.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص705، تحت «فائدة الحصر بـ«إنما» دون غيرها في قوله: «إنما حرم عليكم الميتة»»","url":""}]},{"id":"s2-739","number":739,"surah":2,"verses":[173],"references":[{"surah":2,"verses":[173]}],"verseLabel":"البقرة: 173","question":"ما سرّ التعبير في قوله تعالى: ﴿حَرَّمَ عَلَيْكُمُ الْمَيْتَةَ﴾، والتحريم في الحقيقة متعلق بأكلها لا بذاتها؟","answer":"حذف متعلق التحريم إيجازًا لدلالة مقام الأكل عليه، فالتقدير: حرم عليكم أكل الميتة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص707، تحت «نكتة الإيجاز بحذف المضاف في: «حرم عليكم الميتة»»","url":""}]},{"id":"s2-740","number":740,"surah":2,"verses":[173],"references":[{"surah":2,"verses":[173]}],"verseLabel":"البقرة: 173","question":"ما سرّ التعبير في قوله تعالى: ﴿وَمَا أُهِلَّ بِهِ لِغَيْرِ اللَّهِ﴾، دون أن يقال: «وما ذبح للأصنام»؟","answer":"عبر بالإهلال ليشمل ما رفع عند ذبحه اسم غير الله وقصد به التقرب إليه، أيًا كان ذلك الغير.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص708، تحت «بيان المفعول الذي لم يسم فاعله، في قوله: «وما أهل به»»","url":""}]},{"id":"s2-741","number":741,"surah":2,"verses":[173],"references":[{"surah":2,"verses":[173]}],"verseLabel":"البقرة: 173","question":"ما سرّ التعبير في قوله تعالى في المضطر: ﴿غَيْرَ بَاغٍ وَلَا عَادٍ﴾، فغاير بين ﴿غير﴾ و﴿لا﴾؟","answer":"جاءت ﴿غير﴾ حالًا جامعةً لقيد الاضطرار، ثم عطف عليها ﴿ولا عاد﴾ لنفي الوصف الثاني وتوكيد استقلاله؛ فلا يكون طالبًا للمحرم من غير ضرورة، ولا متجاوزًا قدر ما يدفع الهلاك.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص712، تحت «دلالة مجيء «غير» دون «لا» في الآية»","url":""}]},{"id":"s2-742","number":742,"surah":2,"verses":[173],"references":[{"surah":2,"verses":[173]}],"verseLabel":"البقرة: 173","question":"ما المحذوف المقدر في قوله تعالى: ﴿فَمَنِ اضْطُرَّ غَيْرَ بَاغٍ وَلَا عَادٍ فَلَا إِثْمَ عَلَيْهِ﴾؟","answer":"التقدير: فمن اضطر فأكل فلا إثم عليه؛ فرفع الإثم متعلق بالأكل عند الاضطرار، لا بمجرد الاضطرار. وحُذف الأكل لدلالة السياق عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص711، تحت «الإيجاز بالحذف لمقدر: ﴿فمن اضطر غير باغ ولا عاد﴾»","url":""}]},{"id":"s2-743","number":743,"surah":2,"verses":[173],"references":[{"surah":2,"verses":[173]}],"verseLabel":"البقرة: 173","question":"ما مناسبة ختم رخصة المضطر باسمَي ﴿غَفُورٌ رَحِيمٌ﴾؟","answer":"ختم بالمغفرة لرفع تبعة تناول المحرم عند الضرورة، وبالرحمة لأن تشريع الرخصة رحمة بالمضطر وحفظ لنفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص713، تحت «دلالة التذييل في قوله: «فإن الله غفور رحيم»»","url":""}]},{"id":"s2-744","number":744,"surah":2,"verses":[174],"references":[{"surah":2,"verses":[174]}],"verseLabel":"البقرة: 174","question":"ما سرّ الوصل بالواو بين كتمان الكتاب وأخذ الثمن، دون الفاء؟","answer":"عطف الاشتراء بالواو لجمع الجريمتين في الحكم والوعيد من غير إفادة ترتيب زمني لازم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص720، تحت «سر الوصل بين الجملتين بالواو دون الفاء»","url":""}]},{"id":"s2-745","number":745,"surah":2,"verses":[174],"references":[{"surah":2,"verses":[174]},{"surah":3,"verses":[77]}],"verseLabel":"البقرة: 174، آل عمران: 77","question":"ما سرّ زيادة قوله تعالى: ﴿مَا يَأْكُلُونَ فِي بُطُونِهِمْ إِلَّا النَّارَ﴾ في البقرة، وابتداء الوعيد في آل عمران بقوله: ﴿أُولَئِكَ لَا خَلَاقَ لَهُمْ فِي الْآخِرَةِ﴾؟","answer":"فصلت البقرة جرم الكتمان وأخذ الثمن، فناسبه تفصيل الوعيد وتصوير المأكول نارًا. أما آل عمران فبدأت بنفي نصيبهم في الآخرة، مع اشتراك الموضعين في بقية أصول الوعيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص729، تحت «توجيه المتشابه اللفظي»","url":""}]},{"id":"s2-746","number":746,"surah":2,"verses":[174],"references":[{"surah":2,"verses":[174]},{"surah":3,"verses":[77]}],"verseLabel":"البقرة: 174، آل عمران: 77","question":"ما سرّ زيادة قوله تعالى: ﴿وَلَا يَنْظُرُ إِلَيْهِمْ﴾ في آل عمران، وعدم ذكره في آية البقرة النظيرة؟","answer":"جريمة آل عمران تضمنت بيع عهد الله والأيمان، فزيد في عقوبتهم حرمان نظر الرضا والرعاية. وناسب ذكر النظر سياق العهد الذي يقتضي عادة نظر التعاهد والتكريم، بينما ناسب نفي الكلام في البقرة كتمانهم كلام الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص315، تحت «تعدد الكنايات في قوله تعالى: «ولا ينظر إليهم يوم القيامة»»","url":""}]},{"id":"s2-747","number":747,"surah":2,"verses":[174],"references":[{"surah":2,"verses":[174]}],"verseLabel":"البقرة: 174","question":"ما سرّ التعبير في قوله تعالى: ﴿يَكْتُمُونَ مَا أَنْزَلَ اللَّهُ مِنَ الْكِتَابِ﴾، ولم يحدد ما كتموه؟","answer":"أبهم المكتوم ليعم كل ما أخفوه من الحق، ومنه صفة النبي والبشارة به والأحكام التي خالفت أهواءهم. فالتعميم يمنع حصر الجريمة في معلومة واحدة ويجعل الوعيد لكل كتمان متعمد للوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص720، تحت «فائدة التعبير بـ(من) البيانية، وموقعها الإعرابي»","url":""}]},{"id":"s2-748","number":748,"surah":2,"verses":[174],"references":[{"surah":2,"verses":[174]}],"verseLabel":"البقرة: 174","question":"ما دلالة وصف الثمن بأنه ﴿قَلِيلًا﴾ ولو كان في نظر أصحابه كثيرًا؟","answer":"وصف بالقليل لأنه قليل في ذاته أو بالنسبة إلى عظيم ما ترتب عليه من الضرر، ولأن مدته منقطعة مهما كثر.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص721، تحت «وجه وصف الثمن بالقليل في قوله: «ثمنًا قليلًا»»","url":""}]},{"id":"s2-749","number":749,"surah":2,"verses":[174],"references":[{"surah":2,"verses":[174]}],"verseLabel":"البقرة: 174","question":"ما سرّ التعبير في قوله تعالى: ﴿أُولَئِكَ﴾، دون أن يقال: «هم لا يأكلون»؟","answer":"اسم الإشارة يستحضر صورتهم البشعة بالأوصاف السابقة، ويبين أن كتمانهم وبيعهم الحق هما سبب الحكم الآتي. وفي الإشارة إلى البعيد إبعاد لهم في منزلة الذم والاحتقار.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص722، تحت «نكتة الإخبار باسم الإشارة «أولئك ما يأكلون في بطونهم إلا النار»»","url":""}]},{"id":"s2-750","number":750,"surah":2,"verses":[174],"references":[{"surah":2,"verses":[174]}],"verseLabel":"البقرة: 174","question":"ما سرّ التعبير في قوله تعالى: ﴿مَا يَأْكُلُونَ فِي بُطُونِهِمْ إِلَّا النَّارَ﴾، مع أنهم يأكلون مالًا؟","answer":"سمى ما يأكلونه نارًا باعتبار مآله وسببيته للعذاب، فالثمن المحرم سبب النار.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص724، تحت «نكتة ذكر النار في قوله: «ما يأكلون في بطونهم إلا النار»»","url":""}]},{"id":"s2-751","number":751,"surah":2,"verses":[174],"references":[{"surah":2,"verses":[174]}],"verseLabel":"البقرة: 174","question":"ما فائدة قوله: ﴿فِي بُطُونِهِمْ﴾، والأكل لا يكون عادة إلا فيها؟","answer":"ذكر البطون توكيدًا للأكل وبيانًا لمقره، وفيه تشنيع عليهم وتنبيه إلى أنهم باعوا آخرتهم بطاعة بطونهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص723، تحت «فائدة ذكر قوله: «في بطونهم» بعد ذكر الأكل»","url":""}]},{"id":"s2-752","number":752,"surah":2,"verses":[174],"references":[{"surah":2,"verses":[174]}],"verseLabel":"البقرة: 174","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلَا يُكَلِّمُهُمُ اللَّهُ يَوْمَ الْقِيَامَةِ﴾، مع أن القرآن يذكر خطاب الله للكافرين؟","answer":"المنفي كلام الرضا والتكريم، لا كل خطاب؛ فقد يخاطبون بالتوبيخ والحساب. وعوقب من كتم كلام الله بحرمان كلام الرحمة والتشريف.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص726، تحت «المقصود بنفي تكليم الكاتمين يوم القيامة في قوله: «ولا يكلمهم الله يوم القيامة»»","url":""}]},{"id":"s2-753","number":753,"surah":2,"verses":[174],"references":[{"surah":2,"verses":[174]}],"verseLabel":"البقرة: 174","question":"ما سرّ تقديم ﴿لَا يُكَلِّمُهُمُ اللَّهُ﴾ على ﴿وَلَا يُزَكِّيهِمْ﴾؟","answer":"قدم حرمانهم من كلام التكريم لأنه أظهر وجوه الإعراض والغضب، ثم نفى تزكيتهم وتطهيرهم، وأعقب ذلك بالعذاب الأليم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص728، تحت «السر في ترتيب هذه الأخبار الأربعة»","url":""}]},{"id":"s2-754","number":754,"surah":2,"verses":[174],"references":[{"surah":2,"verses":[174]}],"verseLabel":"البقرة: 174","question":"ما مناسبة قوله تعالى: ﴿وَلَهُمْ عَذَابٌ أَلِيمٌ﴾ بعد تصوير ما يأكلونه بالنار؟","answer":"تختم الجملة الوعيد بالتصريح بما أُعد لهم من العذاب الأليم، بعد مقابلة شراء الثمن القليل بأكل النار، وكتمان الدين بالحرمان من تكليم الله، وتحريف الحق بنفي التزكية.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص728–729، تحت «السر في ترتيب هذه الأخبار الأربعة»","url":""}]},{"id":"s2-755","number":755,"surah":2,"verses":[175],"references":[{"surah":2,"verses":[175]}],"verseLabel":"البقرة: 175","question":"ما دلالة تكرار اسم الإشارة في قوله تعالى: ﴿أُولَئِكَ الَّذِينَ اشْتَرَوُا الضَّلَالَةَ بِالْهُدَى﴾ بعد قوله: ﴿أُولَئِكَ مَا يَأْكُلُونَ...﴾؟","answer":"لأن كل حكم من الحكمين عظيم يستحق أن يستقل بإشارة تلفت إليه؛ الأولى تصور العقوبة، والثانية تكشف الصفقة التي أوقعتهم فيها. والتكرار يعيد استحضارهم بوصفهم جديرين بأحكام متتابعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص733، تحت «نكتة تكرار اسم الإشارة في قوله: «أولئك... أولئك الذين اشتروا»»","url":""}]},{"id":"s2-756","number":756,"surah":2,"verses":[175],"references":[{"surah":2,"verses":[175]}],"verseLabel":"البقرة: 175","question":"ما سرّ المقابلة بين ﴿الضَّلَالَةَ بِالْهُدَى﴾ و﴿الْعَذَابَ بِالْمَغْفِرَةِ﴾؟","answer":"المقابلة تعرض الخسارتين معًا: اختاروا في الدنيا الضلال بدل الهدى، فآل اختيارهم في الآخرة إلى العذاب بدل المغفرة. وهكذا يرى القارئ أن الجزاء ليس منفصلًا عن الصفقة، بل هو تمامها.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص735، تحت «دلالة المقابلة في قوله: «الضلالة بالهدى والعذاب بالمغفرة»»","url":""}]},{"id":"s2-757","number":757,"surah":2,"verses":[175],"references":[{"surah":2,"verses":[175]}],"verseLabel":"البقرة: 175","question":"ما سرّ تصوير كتمان الحق بالشراء في قوله تعالى: ﴿اشْتَرَوُا الضَّلَالَةَ بِالْهُدَى﴾؟","answer":"لأنهم تركوا ما كان في أيديهم من علم وهداية وأخذوا مكانه الضلال والثمن، فشبه الاختيار المتعمد بمبادلة تجارية. والباء تدخل على المتروك المبذول، فكأن الهدى رأس مال أضاعوه.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص734، تحت «براعة الاستعارة التصريحية في قوله: «اشتروا الضلالة بالهدى»»","url":""}]},{"id":"s2-758","number":758,"surah":2,"verses":[175],"references":[{"surah":2,"verses":[175]}],"verseLabel":"البقرة: 175","question":"ما معنى التعجب في قوله: ﴿فَمَا أَصْبَرَهُمْ عَلَى النَّارِ﴾؟","answer":"يوجه الأسلوب المخاطبين إلى التعجب من جرأتهم على الأعمال التي تؤدي إلى النار؛ فقد أقدموا على أسباب العذاب كأنهم موطنون أنفسهم على احتماله. فهو تقريع لهم على إيثار الضلالة، لا مدح لصبر محمود.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص737، تحت عنوان «معنى التعجب»","url":""}]},{"id":"s2-759","number":759,"surah":2,"verses":[176],"references":[{"surah":2,"verses":[176]}],"verseLabel":"البقرة: 176","question":"إلى ماذا يشير قوله: ﴿ذَلِكَ بِأَنَّ اللَّهَ نَزَّلَ الْكِتَابَ بِالْحَقِّ﴾؟","answer":"يشير إلى الوعيد والجزاء السابق كله؛ استحقوه لأن الله أنزل كتابًا ملابسًا للحق، فقابلوا البيان بالكتمان والاختلاف. فاسم الإشارة يجمع صور العقاب ثم يكشف علتها الجامعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص739، تحت «فائدة التعبير باسم الإشارة في قوله: «ذلك بأن الله نزل الكتاب بالحق»»","url":""}]},{"id":"s2-760","number":760,"surah":2,"verses":[176],"references":[{"surah":2,"verses":[176]}],"verseLabel":"البقرة: 176","question":"ما المراد بقوله تعالى: ﴿نَزَّلَ الْكِتَابَ بِالْحَقِّ﴾، وهل تنزيله بالحق هو سبب العذاب؟","answer":"الحق هنا الصدق وبيان الحق. وسبب العذاب ليس تنزيل الكتاب نفسه، بل مخالفتهم له وكتمانهم؛ ولذلك يقدَّر في السياق: فاختلفوا فيه، فآمنوا ببعضه وكفروا ببعضه بالكتمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص741، تحت «دلالة لفظ الحق في تقدير محذوف في: ﴿ذلك بأن الله نزل الكتاب بالحق﴾»","url":""}]},{"id":"s2-761","number":761,"surah":2,"verses":[176],"references":[{"surah":2,"verses":[176]}],"verseLabel":"البقرة: 176","question":"ما سرّ التعبير في قوله تعالى: ﴿اخْتَلَفُوا فِي الْكِتَابِ﴾، دون أن يقال: «اختلفوا على الكتاب»؟","answer":"عدي الاختلاف بـ﴿في﴾ لأنه واقع في شأن الكتاب ومعانيه، لا مجرد خصومة خارجية عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص742، تحت «فائدة الإخبار عن اختلافهم: «اختلفوا في الكتاب»»","url":""}]},{"id":"s2-762","number":762,"surah":2,"verses":[176],"references":[{"surah":2,"verses":[176]}],"verseLabel":"البقرة: 176","question":"ما دلالة وصف الشقاق بأنه ﴿بَعِيدٍ﴾؟","answer":"صوّر الشقاق كأنه مكان بعيد انغمسوا فيه؛ أي بلغ خلافهم غاية أبعدتهم عن الحق وعن سبيل الاجتماع عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص743، تحت «فائدة الوصف بالبعد في قوله: «لفي شقاق بعيد»»","url":""}]},{"id":"s2-763","number":763,"surah":2,"verses":[177],"references":[{"surah":2,"verses":[177]},{"surah":4,"verses":[136]}],"verseLabel":"البقرة: 177، النساء: 136","question":"ما سرّ تقديم اليوم الآخر في أركان الإيمان بآية البر، وتأخيره في النساء: 136؟","answer":"تتحدث البقرة عن المؤمن الصادق الذي يعمل للقاء الله؛ فأقرب ما يحرّك سعيه بعد الإيمان بالله هو رجاء الآخرة وخوفها، لذلك قُدّمت. أما النساء فتحذر من الكافر بهذه الأصول، والآخرة أبعد الحقائق عن اعتناء الكافر وتصديقه، فأُخرت في ذكر ما ينكره. فترتيب البقرة يصور دوافع المؤمن، وترتيب النساء يصور تدرج المنكر في البعد.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص757، تحت «تقديم الإيمان بالله واليوم الآخر على الملائكة والكتب والرسل»","url":""}]},{"id":"s2-764","number":764,"surah":2,"verses":[177],"references":[{"surah":2,"verses":[177]}],"verseLabel":"البقرة: 177","question":"ما سرّ افتتاح آية البر بنفي أن يكون البر تولية الوجوه قبل المشرق والمغرب؟","answer":"نفت الآية أن يكون تمام البر مجرد تولية الوجه جهة المشرق أو المغرب، ثم بينت أن البر يشمل الإيمان وأعمال الطاعة والوفاء والصبر.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص752–753، تحت «نفي المقصور بالتعريف بلام الجنس»","url":""}]},{"id":"s2-766","number":766,"surah":2,"verses":[177],"references":[{"surah":2,"verses":[177]}],"verseLabel":"البقرة: 177","question":"ما سرّ تخصيص المشرق والمغرب بالذكر دون سائر الجهات؟","answer":"لأنهما الجهتان اللتان دار حولهما نزاع القبلة: بيت المقدس في جهة، والكعبة في الأخرى؛ فذكرهما يستوعب طرفي الجدل.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص755، تحت «بيان الدلالة الإيحائية في ذكر الجهتين»","url":""}]},{"id":"s2-767","number":767,"surah":2,"verses":[177],"references":[{"surah":2,"verses":[177]}],"verseLabel":"البقرة: 177","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلَكِنَّ الْبِرَّ مَنْ آمَنَ﴾، فجعل البر شخصًا لا عملًا؟","answer":"إما أن في الكلام مضافًا محذوفًا تقديره «ولكن بر من آمن»، وإما أنه من المبالغة حتى جعل الموصوف بالبر نفس البر لكمال اتصافه به.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص755، تحت «توجيه الإخبار عن المصدر باسم الذات»","url":""}]},{"id":"s2-768","number":768,"surah":2,"verses":[177],"references":[{"surah":2,"verses":[177]}],"verseLabel":"البقرة: 177","question":"ما سرّ البدء في خصال البر بالإيمان بالله واليوم الآخر؟","answer":"لأن الإيمان بالله أصل الأعمال ومصدر الإخلاص، والإيمان بالآخرة دافع المحاسبة والجزاء؛ فإذا استقاما نشأت بقية الخصال على أساسها. فقدم الباطن الذي يمنح السلوك معناه قبل تفصيل البذل والوفاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص756، تحت «بلاغة تقديم الإيمان على اليوم الآخر وإيتاء المال، وأفعال الجوارح»","url":""}]},{"id":"s2-769","number":769,"surah":2,"verses":[177],"references":[{"surah":2,"verses":[177]}],"verseLabel":"البقرة: 177","question":"ما سرّ إفراد ﴿الْكِتَابِ﴾ وجمع ﴿الْمَلَائِكَةِ﴾ و﴿النَّبِيِّينَ﴾؟","answer":"أفرد ﴿الكتاب﴾ لأنه اسم جنس يشمل الكتب المنزلة، وجمع الملائكة والنبيين لأن أفراد كل منهما متعددون.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص758، تحت «وجه إفراد لفظ الكتاب»","url":""}]},{"id":"s2-770","number":770,"surah":2,"verses":[177],"references":[{"surah":2,"verses":[177]}],"verseLabel":"البقرة: 177","question":"إلى مَن يعود الضمير في قوله: ﴿وَآتَى الْمَالَ عَلَى حُبِّهِ﴾؟","answer":"يحتمل عود الضمير إلى المال، أي يعطيه مع حبه، أو إلى الله فيعطي ابتغاء مرضاته، أو إلى الإيتاء نفسه فيعطي محبًا للبذل.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص760، تحت «بيان مرجع الضمير ودلالته في قوله تعالى: «على حبه»»","url":""}]},{"id":"s2-771","number":771,"surah":2,"verses":[177],"references":[{"surah":2,"verses":[177]}],"verseLabel":"البقرة: 177","question":"ما سرّ تقديم ﴿ذَوِي الْقُرْبَى﴾ في مصارف المال؟","answer":"قدم ذوي القربى لأن حقهم يجمع القرابة والحاجة، والصدقة عليهم صدقة وصلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص761، تحت «سر ترتيب ورود من يستحق المال»","url":""}]},{"id":"s2-772","number":772,"surah":2,"verses":[177],"references":[{"surah":2,"verses":[177]}],"verseLabel":"البقرة: 177","question":"ما سرّ التعبير في قوله تعالى: ﴿ابْنَ السَّبِيلِ﴾، فأضاف المسافر إلى الطريق؟","answer":"صوّره كأنه ابن للطريق لشدة ملازمته له وانقطاعه عن أهله وماله؛ فالإضافة تستحضر غربته وحاجته ولو كان غنيًا في بلده. إنها صورة تختصر حال المسافر المنقطع.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص762، تحت «وجه إضافة «ابن» إلى «السبيل»»","url":""}]},{"id":"s2-773","number":773,"surah":2,"verses":[177],"references":[{"surah":2,"verses":[177]}],"verseLabel":"البقرة: 177","question":"ما سرّ التعبير في قوله تعالى: ﴿وَفِي الرِّقَابِ﴾، دون أن يقال: «والرقاب» مثل بقية الأصناف؟","answer":"جاءت ﴿في﴾ لأن المال يجعل في سبب فك الرقاب وتحريرها، لا يدفع إلى الرقبة نفسها.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص763، تحت «وجه استعمال «في» مع الرقاب دون الباقين»","url":""}]},{"id":"s2-774","number":774,"surah":2,"verses":[177],"references":[{"surah":2,"verses":[177]}],"verseLabel":"البقرة: 177","question":"ما سرّ التعبير في قوله تعالى: ﴿أَقَامَ الصَّلَاةَ وَآتَى الزَّكَاةَ﴾ بعد قوله: ﴿وَآتَى الْمَالَ عَلَى حُبِّهِ﴾؟","answer":"إيتاء المال الأول تطوع واسع في وجوه البر، أما الزكاة فحق مفروض مضبوط؛ فذكرهما ليجمع البر بين البذل الاختياري وأداء الواجب المالي.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص765، تحت «السر في ذكر إيتاء الزكاة بعد ذكر إيتاء المال»","url":""}]},{"id":"s2-775","number":775,"surah":2,"verses":[177],"references":[{"surah":2,"verses":[177]}],"verseLabel":"البقرة: 177","question":"ما دلالة إفراد ﴿عَهْدِهِمْ﴾ مع تعدد العهود؟","answer":"أفرد ﴿عهدهم﴾ لأن المفرد المضاف يعم جنس العهد، فيشمل ما عقدوه مع الله والناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص767، تحت «سر إيثار إفراد العهد على الجمع»","url":""}]},{"id":"s2-776","number":776,"surah":2,"verses":[177],"references":[{"surah":2,"verses":[177]}],"verseLabel":"البقرة: 177","question":"ما سرّ رفع ﴿وَالْمُوفُونَ﴾ ثم نصب ﴿وَالصَّابِرِينَ﴾ وسط الصفات؟","answer":"رفع ﴿الموفون﴾ عطفًا على ما قبله، ونصب ﴿الصابرين﴾ على الاختصاص للمدح تنبيهًا إلى رفعة الصبر وشدة الحاجة إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص767، تحت «سر العدول إلى نصب «والصابرين»»","url":""}]},{"id":"s2-777","number":777,"surah":2,"verses":[177],"references":[{"surah":2,"verses":[177]}],"verseLabel":"البقرة: 177","question":"ما سرّ ترتيب الصبر في ﴿الْبَأْسَاءِ وَالضَّرَّاءِ وَحِينَ الْبَأْسِ﴾؟","answer":"البأساء شدة الفقر، والضراء ما يصيب البدن، وحين البأس وقت القتال؛ فرتب الصبر في المال والبدن ثم في أشد المواقف وأخطرها.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص768، تحت «الترقي في الصبر من الأدنى إلى الأعلى»","url":""}]},{"id":"s2-778","number":778,"surah":2,"verses":[177],"references":[{"surah":2,"verses":[177]}],"verseLabel":"البقرة: 177","question":"ما دلالة تكرار ﴿أُولَئِكَ﴾ في قوله تعالى: ﴿أُولَئِكَ الَّذِينَ صَدَقُوا وَأُولَئِكَ هُمُ الْمُتَّقُونَ﴾؟","answer":"كرر اسم الإشارة ليستقل كل حكم: صدقهم نتيجة اجتماع خصال البر، ثم ثبتت لهم منزلة التقوى. وضمير الفصل والتعريف يقويان اختصاصهم بكمال التقوى في المقام.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص770، تحت «فائدة تكرار اسم الإشارة»","url":""}]},{"id":"s2-779","number":779,"surah":2,"verses":[178],"references":[{"surah":2,"verses":[178]}],"verseLabel":"البقرة: 178","question":"ما سرّ التعبير في قوله تعالى: ﴿كتب عليكم القصاص﴾ مع أن القصاص حق لأولياء القتيل؟","answer":"كتب على الجماعة إقامة نظامه ومنع الثأر المتجاوز، وعلى أولياء الدم التزام حدوده؛ فالحكم يحمي المجتمع ولا يخص صاحب الحق وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص777، تحت «وجه إفادة «كتب عليكم» الوجوب»","url":""}]},{"id":"s2-780","number":780,"surah":2,"verses":[178],"references":[{"surah":2,"verses":[178]}],"verseLabel":"البقرة: 178","question":"ما سرّ التعبير في قوله تعالى: ﴿القتلى﴾ بالجمع، ثم فصّل: الحر بالحر والعبد بالعبد والأنثى بالأنثى؟","answer":"أجمل جنس الوقائع أولًا ثم أبطل صور الجاهلية التي تقتل غير الجاني أو تضاعف الثأر بحسب الطبقة، فرد القصاص إلى المماثلة والعدل.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص779، تحت «قصدية التعبير بلفظ «القتلى»»","url":""}]},{"id":"s2-781","number":781,"surah":2,"verses":[178],"references":[{"surah":2,"verses":[178]}],"verseLabel":"البقرة: 178","question":"ما مناسبة افتتاح حكم القصاص بقوله تعالى: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا﴾؟","answer":"استثير وصف الإيمان ليهيئ النفوس لقبول حكم يمس الدماء والرغبة في الانتقام؛ فمقتضى الإيمان التسليم لعدل الله وضبط القصاص.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص777، تحت «بيان وجه مناداة المؤمنين في الآية»","url":""}]},{"id":"s2-782","number":782,"surah":2,"verses":[178],"references":[{"surah":2,"verses":[178]}],"verseLabel":"البقرة: 178","question":"ما سرّ التعبير في قوله تعالى: ﴿كُتِبَ عَلَيْكُمُ الْقِصَاصُ﴾، دون أن يقال: «أُمرتم بالقصاص»؟","answer":"عبر بـ﴿كتب﴾ لإفادة الفرض والإثبات، وبني للمجهول للتركيز على نفس الحكم مع العلم بأن فارضه الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص777، تحت «وجه إفادة «كتب عليكم» الوجوب»","url":""}]},{"id":"s2-783","number":783,"surah":2,"verses":[178],"references":[{"surah":2,"verses":[178]}],"verseLabel":"البقرة: 178","question":"ما سرّ التعبير في قوله تعالى: ﴿الْقِصَاصُ فِي الْقَتْلَى﴾، دون أن يقال: «أن تقتلوا القاتل»؟","answer":"عبر بالقصاص لبيان المماثلة، و﴿في القتلى﴾ تحدد مجال الحكم، وجمع القتلى ليعم جنس وقائع القتل.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص779، تحت «قصدية التعبير بلفظ «القتلى»»","url":""}]},{"id":"s2-784","number":784,"surah":2,"verses":[178],"references":[{"surah":2,"verses":[178]}],"verseLabel":"البقرة: 178","question":"ما سرّ التفصيل في قوله تعالى: ﴿الْحُرُّ بِالْحُرِّ وَالْعَبْدُ بِالْعَبْدِ وَالْأُنْثَى بِالْأُنْثَى﴾؟","answer":"جاء التفصيل لإبطال تجاوزات الجاهلية التي كانت تقتل الحر بالعبد والرجل بالمرأة طلبًا للمفاخرة، فأثبت المماثلة ومنع العدوان في القصاص.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص779، تحت «فائدة القيد بوصف الحرية والعبدية»","url":""}]},{"id":"s2-785","number":785,"surah":2,"verses":[178],"references":[{"surah":2,"verses":[178]}],"verseLabel":"البقرة: 178","question":"ما سرّ إفراد الأنثى بالذكر مع دخولها في عموم القتلى؟","answer":"ذكرت الأنثى ردًا على من كان لا يقتص للمرأة أو يطلب بها رجلًا، وللتصريح بأن دمها مصون وأن المماثلة تشملها.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص780، تحت «وجه إفراد الأنثى بالذكر»","url":""}]},{"id":"s2-786","number":786,"surah":2,"verses":[178],"references":[{"surah":2,"verses":[178]}],"verseLabel":"البقرة: 178","question":"ما سرّ التعبير في قوله تعالى: ﴿فَمَنْ عُفِيَ لَهُ﴾ بالفاء؟","answer":"الفاء تصل خبر العفو بحكم القصاص في ترتيب البيان، لا أنها تفيد وقوع العفو حتمًا أو فورًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص781، تحت «دلالة الفاء في «فمن عفي له»»","url":""}]},{"id":"s2-787","number":787,"surah":2,"verses":[178],"references":[{"surah":2,"verses":[178]}],"verseLabel":"البقرة: 178","question":"ما سرّ وصف القاتل بالأخوة في قوله تعالى: ﴿مِنْ أَخِيهِ﴾ بعد جريمة القتل؟","answer":"سماه أخًا لبقاء أخوة الإيمان أو الإنسانية رغم الجناية، وفي ذلك ترقيق لقلب ولي الدم وحث على العفو.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص782، تحت «وجه استعمال الأخوة ودلالتها»","url":""}]},{"id":"s2-788","number":788,"surah":2,"verses":[178],"references":[{"surah":2,"verses":[178]}],"verseLabel":"البقرة: 178","question":"ما سرّ التعبير في قوله تعالى: ﴿شَيْءٌ﴾ في قوله: ﴿فَمَنْ عُفِيَ لَهُ مِنْ أَخِيهِ شَيْءٌ﴾؟","answer":"نكر ﴿شيء﴾ ليشمل أي قدر من العفو، ولو عن بعض الحق أو من بعض الأولياء؛ فإذا حصل شيء منه انتقل الحكم إلى اتباع المعروف وأداء الدية.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص782، تحت «بيان وجه تنكير «شيء»»","url":""}]},{"id":"s2-789","number":789,"surah":2,"verses":[178],"references":[{"surah":2,"verses":[178]}],"verseLabel":"البقرة: 178","question":"ما سرّ التعبير في قوله تعالى: ﴿فَاتِّبَاعٌ بِالْمَعْرُوفِ وَأَدَاءٌ إِلَيْهِ بِإِحْسَانٍ﴾، ولم يذكر الفاعلين؟","answer":"حذف الفاعلان وجيء بالمصدرين ليعم الحكم: فعلى ولي الدم اتباع المطالبة بالمعروف، وعلى القاتل أداء الدية إليه بإحسان من غير مماطلة ولا أذى.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص783، تحت «بيان الحذف في الجملة في قوله: «فاتباع بالمعروف وأداء إليه بإحسان»»","url":""}]},{"id":"s2-790","number":790,"surah":2,"verses":[178],"references":[{"surah":2,"verses":[178]}],"verseLabel":"البقرة: 178","question":"ما سرّ الجمع بين ﴿بِالْمَعْرُوفِ﴾ و﴿بِإِحْسَانٍ﴾؟","answer":"قُيِّد اتباع ولي الدم بالمعروف حتى يطلب حقه على الوجه المشروع، وقُيِّد أداء القاتل بالإحسان حتى يدفعه كاملًا من غير مطل ولا أذى.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص784، تحت «توجيه عود الضمير على العافي»","url":""}]},{"id":"s2-791","number":791,"surah":2,"verses":[178],"references":[{"surah":2,"verses":[178]}],"verseLabel":"البقرة: 178","question":"ما سرّ التعبير في قوله تعالى: ﴿ذَلِكَ تَخْفِيفٌ مِنْ رَبِّكُمْ وَرَحْمَةٌ﴾ بعد تشريع القصاص؟","answer":"الإشارة إلى تشريع العفو وقبول الدية بدل الاقتصار على القصاص؛ فهو تخفيف ورحمة من الرب الذي يرعى عباده ويشرع ما يصلحهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص785، تحت «وجه الجمع بين القصاص والرحمة»","url":""}]},{"id":"s2-792","number":792,"surah":2,"verses":[178],"references":[{"surah":2,"verses":[178]}],"verseLabel":"البقرة: 178","question":"ما مناسبة الوعيد بقوله تعالى: ﴿فَمَنِ اعْتَدَى بَعْدَ ذَلِكَ فَلَهُ عَذَابٌ أَلِيمٌ﴾ بعد التخفيف والرحمة؟","answer":"يحذر الوعيد من الاعتداء بعد العفو وأخذ الدية، حمايةً للصلح من أن يفسده ثأر جديد؛ فلا يحمل الغضب أولياء الدم على نقض العفو وتجديد الفتنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص785، تحت عنوان «قصدية التعبير باسم الإشارة في قوله: ﴿بعد ذلك﴾»","url":""}]},{"id":"s2-793","number":793,"surah":2,"verses":[179],"references":[{"surah":2,"verses":[179]}],"verseLabel":"البقرة: 179","question":"ما وجه وصف القصاص بالحياة في قوله تعالى: ﴿وَلَكُمْ فِي الْقِصَاصِ حَيَاةٌ﴾ مع أنه قتل؟","answer":"في القصاص حياة لأنه يردع من يهم بالقتل، ويحفظ حياة الجاني من تعدي أولياء الدم إلى غيره، ويمنع امتداد الثأر؛ فيفوت بقتل واحد قتل كثير.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص791، تحت «بلاغة التعبير «ولكم في القصاص حياة» دون غيرها من عبارات العرب»","url":""}]},{"id":"s2-794","number":794,"surah":2,"verses":[179],"references":[{"surah":2,"verses":[179]}],"verseLabel":"البقرة: 179","question":"ما سرّ تعريف ﴿القصاص﴾ وتنكير ﴿حياة﴾؟","answer":"عُرّف القصاص لأنه الحكم المعهود المحدد، ونُكرت ﴿حياة﴾ للتعظيم والتكثير؛ أي لكم فيه نوع عظيم واسع من الحياة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص790، تحت «فائدة تعريف لفظ «القصاص»، وتنكير لفظ «حياة»»","url":""}]},{"id":"s2-796","number":796,"surah":2,"verses":[179],"references":[{"surah":2,"verses":[179]}],"verseLabel":"البقرة: 179","question":"ما سرّ التعبير في قوله تعالى: ﴿فِي الْقِصَاصِ حَيَاةٌ﴾ باستعمال ﴿في﴾؟","answer":"جعل الحياة كأنها مودعة داخل القصاص مع أن ظاهره قتل؛ وهذه المفارقة البيانية تدعو إلى استخراج الحكمة الكامنة: الردع يزيل سبب الموت، وإزالة سبب الموت إبقاء للحياة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص790، تحت «بلاغة المجاز المرسل في جملة القصاص»","url":""}]},{"id":"s2-797","number":797,"surah":2,"verses":[179],"references":[{"surah":2,"verses":[179]}],"verseLabel":"البقرة: 179","question":"ما مناسبة النداء بقوله: ﴿يَا أُولِي الْأَلْبَابِ﴾ والختم بقوله: ﴿لَعَلَّكُمْ تَتَّقُونَ﴾؟","answer":"خص أولي الألباب لأنهم الذين يدركون الحياة الكامنة وراء ظاهر القصاص. وختم بالتقوى لأن استشعار القصاص يردع عن القتل ويحمل على اتقاء العدوان.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص792، تحت «نكتة تعليل الحكم في جملة التذييل»","url":""}]},{"id":"s2-798","number":798,"surah":2,"verses":[180],"references":[{"surah":2,"verses":[180]}],"verseLabel":"البقرة: 180","question":"لماذا ذُكّر الفعل في قوله تعالى: ﴿كُتِبَ عَلَيْكُمْ﴾ مع أن نائب الفاعل هو ﴿الْوَصِيَّةُ﴾؟","answer":"حُمِلت الوصية على معنى الإيصاء، وهو مصدر مذكر، ويجوز أن يكون التذكير بسبب طول الفاصل بين الفعل والوصية؛ فالفصل سوّغ ترك علامة التأنيث.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص797، تحت «دلالة وجه تذكير الفعل المسند للوصية المؤنثة»","url":""}]},{"id":"s2-799","number":799,"surah":2,"verses":[180],"references":[{"surah":2,"verses":[180]}],"verseLabel":"البقرة: 180","question":"ما سرّ التعبير في قوله تعالى: ﴿إِذَا حَضَرَ أَحَدَكُمُ الْمَوْتُ﴾ بـ﴿إذا﴾، دون أن يقال: «إن حضر»؟","answer":"لأن الموت متحقق الوقوع لا مشكوك فيه، و﴿إذا﴾ تستعمل للمتوقع المتيقن؛ والمراد حضور أسبابه وعلاماته لا حضور الموت التام الذي ينقطع معه العمل. فالصيغة تجمع اليقين والتنبيه إلى وقت المبادرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص797، تحت «دلالة «إذا» بين الشرطية والظرفية»","url":""}]},{"id":"s2-800","number":800,"surah":2,"verses":[180],"references":[{"surah":2,"verses":[180]}],"verseLabel":"البقرة: 180","question":"ما سرّ التعبير في قوله تعالى: ﴿إِنْ تَرَكَ خَيْرًا﴾، دون أن يقال: «إن ترك مالًا»؟","answer":"سُمِّي المال خيرًا، والمراد مال ذو قدر أو مال كثير تصح الوصية فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص798، تحت «وجه تسمية المال «خيرًا»»","url":""}]},{"id":"s2-801","number":801,"surah":2,"verses":[180],"references":[{"surah":2,"verses":[180]}],"verseLabel":"البقرة: 180","question":"ما سرّ عطف ﴿الْأَقْرَبِينَ﴾ على ﴿الْوَالِدَيْنِ﴾ مع دخولهما في الأقربين؟","answer":"عطف الأقربين للتعميم بعد التخصيص؛ فالوالدان أحق الناس بالوصية، ثم يليهما سائر الأقربين، فاجتمع التنويه بالأصل واستيعاب بقية القرابة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص799، تحت «دلالة عطف العام على الخاص»","url":""}]},{"id":"s2-802","number":802,"surah":2,"verses":[180],"references":[{"surah":2,"verses":[180]}],"verseLabel":"البقرة: 180","question":"ما دلالة تقييد الوصية بقوله تعالى: ﴿بِالْمَعْرُوفِ﴾؟","answer":"قُيِّدت بالمعروف لتكون في قدرها وجهتها على ما أقره الشرع والعدل، من غير إضرار بالورثة ولا جور في التفضيل.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص799، تحت «قصدية التعبير بلفظ «المعروف»»","url":""}]},{"id":"s2-803","number":803,"surah":2,"verses":[180],"references":[{"surah":2,"verses":[180]}],"verseLabel":"البقرة: 180","question":"ما سرّ التعبير في قوله تعالى: ﴿حَقًّا﴾ بعد أن قال: ﴿كُتِبَ عَلَيْكُمْ﴾؟","answer":"﴿حقًا﴾ مصدر مؤكد لمضمون الكتابة، يزيد تقرير الوجوب ويقطع توهم أن الوصية مجرد استحباب مهمل في مقامها. فاجتمع لفظ الفرض ومصدر التوكيد لتشديد حفظ الحقوق.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص799، تحت «نكتة التأكيد بالمصدر «حقًا»»","url":""}]},{"id":"s2-804","number":804,"surah":2,"verses":[180],"references":[{"surah":2,"verses":[180]}],"verseLabel":"البقرة: 180","question":"ما سرّ التعبير في قوله تعالى: ﴿حَقًّا عَلَى الْمُتَّقِينَ﴾، مع أن الحكم لا يختص بالمتقين؟","answer":"خصهم بالذكر تشريفًا وإغراءً بالاقتداء؛ لأنهم أسرع إلى تنفيذ أمر الله حين تضيق النفس بالمال أو يحضر الموت. فليس القيد لإخراج غيرهم، بل للإيحاء بأن الوفاء بهذا الحق علامة تقوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص800، تحت «دلالة تخصيص الواجب بالمتقين»","url":""}]},{"id":"s2-805","number":805,"surah":2,"verses":[181],"references":[{"surah":2,"verses":[181]}],"verseLabel":"البقرة: 181","question":"ما سرّ التعبير في قوله تعالى عن الوصية: ﴿فَمَنْ بَدَّلَهُ﴾ بضمير مذكر، دون أن يقال: «بدّلها»؟","answer":"ذُكِّر الضمير لأن المراد الإيصاء أو قول الموصي، وكلاهما مذكر، وفي التذكير إشارة إلى قوة لزوم تنفيذ الوصية من غير تغيير إلا لإزالة ظلم أو ميل.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص12، تحت «وجه تذكير الضمير في قوله تعالى: «فمن بدله»»","url":""}]},{"id":"s2-806","number":806,"surah":2,"verses":[181],"references":[{"surah":2,"verses":[181]}],"verseLabel":"البقرة: 181","question":"ما دلالة تقييد التبديل بقوله تعالى: ﴿بَعْدَ مَا سَمِعَهُ﴾؟","answer":"قُيِّد التبديل بالسماع لأن إثم تغيير الوصية يثبت بعد العلم بها؛ فمن لم يعلمها لا يكون تغييره تبديلًا متعمدًا لما سمع.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص11، تحت «وجه تقييد السمع في حق الموصي»","url":""}]},{"id":"s2-807","number":807,"surah":2,"verses":[181],"references":[{"surah":2,"verses":[181]}],"verseLabel":"البقرة: 181","question":"ما سرّ البدء بالمفرد في ﴿فَمَنْ بَدَّلَهُ﴾ ثم مراعاة المعنى بالجمع في ﴿عَلَى الَّذِينَ يُبَدِّلُونَهُ﴾؟","answer":"أفرد أولًا لأن الشرط يتناول كل فرد يقع منه التبديل، ثم جمع ليشمل الإثم كل من باشر تغيير الوصية أو رضي به ووافق عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص13، تحت «سر العدول عن المفرد إلى الجمع، في: «يبدلونه»»","url":""}]},{"id":"s2-808","number":808,"surah":2,"verses":[181],"references":[{"surah":2,"verses":[181]}],"verseLabel":"البقرة: 181","question":"ما سرّ التعبير في قوله تعالى: ﴿عَلَى الَّذِينَ يُبَدِّلُونَهُ﴾، دون أن يقال: «فعليهم إثمه»؟","answer":"أعاد الموصول ليعلق الحكم بالصفة نفسها: التبديل هو سبب الإثم. وبدل أن يخفيهم الضمير، سماهم مرة أخرى بفعلهم ليشهّر بالجناية ويقرر أن من اتصف بها دخل في الوعيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص13، تحت «نكتة وضع الاسم الموصول موضع الضمير»","url":""}]},{"id":"s2-809","number":809,"surah":2,"verses":[181],"references":[{"surah":2,"verses":[181]}],"verseLabel":"البقرة: 181","question":"ما مناسبة ختم التحذير من تبديل الوصية بقوله تعالى: ﴿إِنَّ اللَّهَ سَمِيعٌ عَلِيمٌ﴾؟","answer":"﴿سميع﴾ للوصية التي نطق بها الموصي، و﴿عليم﴾ بصفتها وبكل تغيير يقع فيها، فلا يخفى عليه تبديل المبدلين.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص13، تحت «بلاغة التذييل بقول الله تعالى: «إن الله سميع عليم»»","url":""}]},{"id":"s2-810","number":810,"surah":2,"verses":[182],"references":[{"surah":2,"verses":[182]}],"verseLabel":"البقرة: 182","question":"ما سرّ التعبير في قوله تعالى في إصلاح الوصية ﴿فلا إثم عليه﴾، دون أن يقال: فله أجر؟","answer":"لأن المصلح قد يغير ألفاظ وصية فيخشى أن يدخل في وعيد التبديل، فالمقصود أولًا رفع هذا الحرج، والأجر مفهوم من الإصلاح.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص21، تحت «دلالة العدول عن إثبات الأجر للمصلح إلى نفي الإثم عنه»","url":""}]},{"id":"s2-811","number":811,"surah":2,"verses":[182],"references":[{"surah":2,"verses":[182]}],"verseLabel":"البقرة: 182","question":"ما سرّ التعبير في قوله تعالى: ﴿فَمَنْ خَافَ مِنْ مُوصٍ جَنَفًا أَوْ إِثْمًا﴾، مع أن الخوف يكون من أمر مستقبل؟","answer":"الخوف هنا مستعمل مجازًا في العلم، أو في الظن والتوقع؛ مع الإشارة إلى أن المتوقع أمر مكروه. وفي التعبير حث على المبادرة إلى الإصلاح عند ظهور بوادر الفساد في الوصية قبل استحكامه.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص18، تحت «معنى الفاء في قوله: ﴿فمن خاف من موص﴾، ودلالة المجاز المرسل»","url":""}]},{"id":"s2-812","number":812,"surah":2,"verses":[182],"references":[{"surah":2,"verses":[182]}],"verseLabel":"البقرة: 182","question":"ما سرّ الجمع بين ﴿جَنَفًا﴾ و﴿إِثْمًا﴾؟","answer":"الجنف ميل عن العدل قد يقع خطأ أو جهلًا، والإثم ميل متعمد مع العلم؛ فجمعهما ليشمل الخلل غير المقصود والمقصود في الوصية.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص19، تحت «علة الجمع بين الجنف والإثم دون الاكتفاء بأحدهما»","url":""}]},{"id":"s2-813","number":813,"surah":2,"verses":[182],"references":[{"surah":2,"verses":[182]}],"verseLabel":"البقرة: 182","question":"ما سرّ التعبير في قوله تعالى: ﴿فَأَصْلَحَ بَيْنَهُمْ﴾، ولم يذكر بين مَن ومَن؟","answer":"دل سياق الوصية على الأطراف، فحذفوا ليعم الإصلاح الموصي والموصى لهم والورثة وكل من تعلق حقه بالوصية.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص19، تحت «بيان مرجع الضمير في قوله تعالى: «فأصلح بينهم»»","url":""}]},{"id":"s2-814","number":814,"surah":2,"verses":[182],"references":[{"surah":2,"verses":[182]}],"verseLabel":"البقرة: 182","question":"ما وجه نفي الإثم عن المصلح في قوله تعالى: ﴿فَلَا إِثْمَ عَلَيْهِ﴾ مع أنه يصلح الوصية؟","answer":"لأن تغيير الوصية بعد سماعها مظنة الإثم، فنفى الحرج عمن يتدخل لتصحيح جنف أو إثم؛ حتى لا يدخل الإصلاح المشروع في وعيد التبديل المحرم.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص21، تحت «دلالة العدول عن إثبات الأجر للمصلح إلى نفي الإثم عنه»","url":""}]},{"id":"s2-815","number":815,"surah":2,"verses":[182],"references":[{"surah":2,"verses":[182]}],"verseLabel":"البقرة: 182","question":"ما مناسبة ختم إصلاح الوصية بقوله تعالى: ﴿إِنَّ اللَّهَ غَفُورٌ رَحِيمٌ﴾؟","answer":"جاءت المغفرة والرحمة تعليلًا لرفع الإثم؛ فالله يغفر ما قد يقع من المصلح في اجتهاده إذا كان قصده الإصلاح، ويرحم الموصي إذا رجع عن جنفه وإثمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص24، تحت «سر ختم الآية الكريمة باسم الله الغفور»","url":""}]},{"id":"s2-816","number":816,"surah":2,"verses":[183],"references":[{"surah":2,"verses":[183]}],"verseLabel":"البقرة: 183","question":"ما سرّ التعبير في قوله تعالى: ﴿كتب عليكم الصيام﴾ كما قال في القصاص والقتال؟","answer":"عبر بـ﴿كتب﴾ لإفادة الفرض والإلزام؛ وهو تعبير يناسب التكاليف التي تشق على النفس كالقصاص والقتال والصيام.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص25، تحت «العلاقة بين وجوب القصاص والوصية، وبين وجوب الصيام»","url":""}]},{"id":"s2-817","number":817,"surah":2,"verses":[183],"references":[{"surah":2,"verses":[183]}],"verseLabel":"البقرة: 183","question":"ما مناسبة نداء المؤمنين قبل فرض الصيام بقوله تعالى: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا﴾؟","answer":"ناداهم بوصف الإيمان لإظهار مزيد العناية بالحكم الجديد، وتنبيههم إلى ما سيلقى عليهم من فريضة الصيام وأحكامها.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص27، تحت «دلالة أسلوب النداء في قوله: «يا أيها الذين آمنوا»»","url":""}]},{"id":"s2-818","number":818,"surah":2,"verses":[183],"references":[{"surah":2,"verses":[183]}],"verseLabel":"البقرة: 183","question":"ما سرّ التعبير في قوله تعالى: ﴿كُتِبَ عَلَيْكُمُ الصِّيَامُ﴾، دون أن يقال: «صوموا»؟","answer":"﴿كتب﴾ تفيد الفرض الثابت المسجل، و﴿عليكم﴾ تستحضر تبعة التكليف قبل تفصيله؛ فالصيام ليس نصيحة عارضة. وبناء الفعل للمجهول يركز على عظمة المكتوب مع وضوح أن فارضه الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص28، تحت «نكتة العدول عن (صوموا) إلى قوله: «كتب عليكم الصيام»»","url":""}]},{"id":"s2-819","number":819,"surah":2,"verses":[183],"references":[{"surah":2,"verses":[183]}],"verseLabel":"البقرة: 183","question":"ما سرّ التعبير في قوله تعالى: ﴿كَمَا كُتِبَ عَلَى الَّذِينَ مِنْ قَبْلِكُمْ﴾؟","answer":"ليؤنس المكلفين بأنهم ليسوا أول من حمل هذه العبادة، وليدل على قدم الصيام وشرفه وملاءمته لتربية البشر في الشرائع. فاشتراك الأمم فيه يخفف استثقاله ويعظم منزلته.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص30، تحت «نكات التشبيه في قوله: «كما كتب على الذين من قبلكم»»","url":""}]},{"id":"s2-820","number":820,"surah":2,"verses":[183],"references":[{"surah":2,"verses":[183]}],"verseLabel":"البقرة: 183","question":"هل تعني ﴿كَمَا كُتِبَ﴾ أن صيامنا مماثل تمامًا لصيام الأمم السابقة؟","answer":"التشبيه في أصل فرض الصيام، لا في تطابق الأيام والكيفية وسائر الأحكام؛ أي كتب عليكم الصيام كما كتب على من قبلكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص32، تحت «تعيين وجه الشبه في قوله: «كما كتب على الذين من قبلكم»»","url":""}]},{"id":"s2-821","number":821,"surah":2,"verses":[183],"references":[{"surah":2,"verses":[183]}],"verseLabel":"البقرة: 183","question":"ما سرّ اختيار لفظ ﴿الصِّيَامُ﴾ هنا، واستعمال «الصوم» في موضع آخر؟","answer":"الصيام والصوم يشتركان في أصل الإمساك، وغلب ﴿الصيام﴾ على العبادة الشرعية عن المفطرات، أما الصوم فأصل الإمساك وقد يستعمل في الإمساك عن الكلام.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص36، تحت «الصيام والصوم»","url":""}]},{"id":"s2-822","number":822,"surah":2,"verses":[183],"references":[{"surah":2,"verses":[183]}],"verseLabel":"البقرة: 183","question":"ما مناسبة ختم فرض الصيام بقوله تعالى: ﴿لَعَلَّكُمْ تَتَّقُونَ﴾؟","answer":"لأن الصيام يدرب النفس على ترك المباح امتثالًا، فتقوى على ترك الحرام، ويوقظ مراقبة الله؛ وحذف متعلق التقوى ليعم ما يتقى.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص34، تحت «سبب فصل جملة «لعلكم تتقون» عما قبلها»","url":""}]},{"id":"s2-823","number":823,"surah":2,"verses":[184],"references":[{"surah":2,"verses":[184]}],"verseLabel":"البقرة: 184","question":"ما سرّ التعبير في قوله تعالى: ﴿فعدة من أيام أخر﴾ بالجمع ﴿أخر﴾ لا بالإفراد؟","answer":"جُمعت ﴿أُخر﴾ لأنها صفة لـ﴿أيام﴾ المجموعة، ولئلا يوهم إفرادها أنها وصف لـ﴿عدة﴾ فيخفى المراد.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص42، تحت «توجيه المتشابه اللفظي بين قوله: «أياما معدودات» وقوله: «أياما معدودة»»","url":""}]},{"id":"s2-824","number":824,"surah":2,"verses":[184],"references":[{"surah":2,"verses":[184]}],"verseLabel":"البقرة: 184","question":"ما دلالة إفراد ﴿مسكين﴾ في قوله تعالى: ﴿طَعَامُ مِسْكِينٍ﴾؟","answer":"كانت الفدية طعامًا، وإفراد ﴿مسكين﴾ يبين أن الواجب عن كل يوم إطعام مسكين واحد، مع إمكان جمع فدية الأيام والمساكين.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص46، تحت «توجيه اختلاف القراء «فدية طعام مسكين» بين التنوين والإضافة، وبين الجمع والإفراد»","url":""}]},{"id":"s2-825","number":825,"surah":2,"verses":[184],"references":[{"surah":2,"verses":[184]}],"verseLabel":"البقرة: 184","question":"ما سرّ التعبير في قوله تعالى عن رمضان: ﴿أَيَّامًا مَعْدُودَاتٍ﴾ مع أنه شهر كامل؟","answer":"وصفها بالمعدودات تهوينًا وتيسيرًا؛ فما كان محدودًا قابلًا للعد والانقضاء يهون احتماله، ولا يستغرق العام.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص41، تحت «نكتة وصف الأيام في قوله تعالى: «أيامًا معدودات»»","url":""}]},{"id":"s2-826","number":826,"surah":2,"verses":[184],"references":[{"surah":2,"verses":[184]}],"verseLabel":"البقرة: 184","question":"ما سرّ التعبير في قوله تعالى: ﴿أَوْ عَلَى سَفَرٍ﴾، دون أن يقال: «أو مسافرًا»؟","answer":"صوّره متمكنًا من السفر وملابسًا له، كأنه مستعلٍ على مركوبه أو على طريقه؛ فليس مجرد نية سفر عابرة. والعبارة تثبت الحالة التي ترتبط بها الرخصة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص43، تحت «حذف متعلق المرض والسفر في قوله: «فمن كان منكم مريضًا أو على سفر»»","url":""}]},{"id":"s2-827","number":827,"surah":2,"verses":[184],"references":[{"surah":2,"verses":[184]}],"verseLabel":"البقرة: 184","question":"ما الإيجاز بالحذف في قوله ﴿فعدة من أيام أخر﴾؟","answer":"التقدير على القول المذكور في المصدر: فإن أفطر فعليه صوم عدة ما أفطر من أيام أخرى. فحُذف ما دل عليه السياق من الشرط والخبر والمضاف، وأغنى المذكور عن التصريح به.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص43، تحت عنوان «حذف متعلق المرض والسفر في قوله: ﴿فمن كان منكم مريضًا أو على سفر﴾»","url":""}]},{"id":"s2-1519","number":1519,"surah":2,"verses":[184],"references":[{"surah":2,"verses":[184]}],"verseLabel":"البقرة: 184","question":"لماذا نُكّرت ﴿عدة﴾ في ﴿فعدة من أيام أخر﴾ ولم يقل عدتها؟","answer":"لأن السياق يدل على أن المطلوب عدد الأيام التي أفطرها، فلا يجب غيرها؛ فأغنى هذا المعنى عن تعريف العدة بالإضافة. وجاء التنكير مع بقاء المقدار معلومًا من الكلام.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص44، تحت عنوان «دلالة تنكير عدة من قوله تعالى: ﴿فعدة من أيام أخر﴾»","url":""}]},{"id":"s2-828","number":828,"surah":2,"verses":[184],"references":[{"surah":2,"verses":[184]}],"verseLabel":"البقرة: 184","question":"ما سرّ التعبير في قوله تعالى: ﴿وَعَلَى الَّذِينَ يُطِيقُونَهُ فِدْيَةٌ﴾، مع أن المطيق قادر على الصوم؟","answer":"قيل: الآية في مرحلة كان القادر فيها مخيرًا بين الصيام والفدية ثم نسخ التخيير، وقيل: المراد من لا يطيقه إلا بمشقة بالغة كالكبير والمريض المزمن؛ فالطاقة هنا بلوغ غاية الوسع.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص45، تحت «الإيجاز بالحذف في قول الله تعالى: «وعلى الذين يطيقونه فدية»»","url":""}]},{"id":"s2-829","number":829,"surah":2,"verses":[184],"references":[{"surah":2,"verses":[184]}],"verseLabel":"البقرة: 184","question":"ما وجه إضافة الفدية إلى الطعام في قراءة ﴿فدية طعام مساكين﴾ مع أن الفدية هنا طعام؟","answer":"الفدية اسم للقدر الواجب، أما الطعام فاسم أعم يشمل الفدية وغيرها؛ فالإضافة بيانية على معنى من، والتقدير فدية من طعام، كإضافة الخاتم إلى الحديد في خاتم حديد.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص47، تحت عنوان «وجه إضافة الفدية إلى الطعام، وهي طعام»","url":""}]},{"id":"s2-830","number":830,"surah":2,"verses":[184],"references":[{"surah":2,"verses":[184]}],"verseLabel":"البقرة: 184","question":"ما سرّ التعبير في قوله تعالى: ﴿فَمَنْ تَطَوَّعَ خَيْرًا فَهُوَ خَيْرٌ لَهُ﴾، ولم يحدد نوع الخير؟","answer":"أطلقه ليشمل الزيادة في مقدار الفدية أو عدد المساكين وسائر الإحسان المرتبط بها؛ فلا يحصر التطوع في صورة واحدة. وحذف التفصيل يحفز النفس أن تبحث عن مزيد الخير بحسب قدرتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص49، تحت «بيان مرجع الضمير «هو»، ودلالة تنكير «خير» من قول الله تعالى: «فمن تطوع خيرًا فهو خير له»»","url":""}]},{"id":"s2-831","number":831,"surah":2,"verses":[184],"references":[{"surah":2,"verses":[184]}],"verseLabel":"البقرة: 184","question":"ما سرّ التعبير في قوله تعالى: ﴿وَأَنْ تَصُومُوا خَيْرٌ لَكُمْ﴾ بعد ذكر الفدية؟","answer":"بين أن الصيام خير من الفطر والفدية لمن قدر عليه، ثم التفت إلى الخطاب المباشر لحث المكلفين وتنشيطهم على اختيار الأكمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص51، تحت «نكتة الالتفات في قوله: «فمن تطوع خيرًا فهو خير له وأن تصوموا خير لكم»»","url":""}]},{"id":"s2-832","number":832,"surah":2,"verses":[184],"references":[{"surah":2,"verses":[184]}],"verseLabel":"البقرة: 184","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿إِنْ كُنْتُمْ تَعْلَمُونَ﴾؟","answer":"ختم بالشرط حثًا على العلم بفضل الصوم وعظيم ثوابه ومنفعته؛ فلو علم المكلف ذلك حق العلم لاختار الصيام.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص52، تحت «بلاغة التذييل في قول الله تعالى: «إن كنتم تعلمون»»","url":""}]},{"id":"s2-833","number":833,"surah":2,"verses":[185],"references":[{"surah":2,"verses":[185]}],"verseLabel":"البقرة: 185","question":"ما سرّ تقديم فضيلة رمضان بإنزال القرآن فيه قبل بيان حكم صيامه؟","answer":"لبيان مناسبة تخصيص رمضان بالصيام؛ فقد اختص بنزول القرآن وبدء الوحي، وفي ذكر ذلك تذكير بهذه النعمة العظيمة وفضل الشهر.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص59–60، تحت «نكتة الوصف بالاسم الموصول وصلته»","url":""}]},{"id":"s2-834","number":834,"surah":2,"verses":[185],"references":[{"surah":2,"verses":[185]}],"verseLabel":"البقرة: 185","question":"ما سرّ الجمع بين ﴿هُدًى لِلنَّاسِ﴾ و﴿بَيِّنَاتٍ مِنَ الْهُدَى وَالْفُرْقَانِ﴾؟","answer":"وصف القرآن أولًا بالهدى العام، ثم خص البينات التي تدل على ما خفي من الهدى، وذكر الفرقان الذي يميز الحق من الباطل.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص62، تحت «نكتة الإطناب بعطف الخاص على العام»","url":""}]},{"id":"s2-835","number":835,"surah":2,"verses":[185],"references":[{"surah":2,"verses":[185]}],"verseLabel":"البقرة: 185","question":"ما سرّ تكرار حكم المريض والمسافر بعد ذكره في الآية السابقة؟","answer":"أعيد الحكم بعد تعيين رمضان حتى لا يظن أن رخصة المرض والسفر كانت في الحكم الأول ثم نسخت؛ فثبت بقاؤها في فرض رمضان النهائي.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص65، تحت «سر تكرير قوله: «ومن كان مريضًا أو على سفر»»","url":""}]},{"id":"s2-836","number":836,"surah":2,"verses":[185],"references":[{"surah":2,"verses":[185]}],"verseLabel":"البقرة: 185","question":"ما سرّ العدول من ﴿أَيَّامًا مَعْدُودَاتٍ﴾ إلى التصريح بقوله: ﴿شَهْرُ رَمَضَانَ﴾؟","answer":"أجمل الأيام أولًا لتخفيف وقع التكليف، ثم عينها منعًا لالتباس زمن العبادة ولإيجاب استيعاب الشهر. والتصريح باسم رمضان يزيده تشريفًا بذكر الحدث الذي ميزه: نزول القرآن.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص59، تحت «نكتة العدول في التعبير بـ«رمضان» إلى التعبير «بشهر رمضان»»","url":""}]},{"id":"s2-837","number":837,"surah":2,"verses":[185],"references":[{"surah":2,"verses":[185]}],"verseLabel":"البقرة: 185","question":"ما وجه قوله تعالى: ﴿أُنْزِلَ فِيهِ الْقُرْآنُ﴾ مع نزول القرآن منجمًا في سنوات؟","answer":"المراد ابتداء نزول القرآن في رمضان، أو إنزاله فيه جملة إلى السماء الدنيا ثم نزوله منجمًا بحسب الوقائع.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص60، تحت «نكتة المجاز المرسل في قول الله تعالى: «شهر رمضان الذي أنزل فيه القرآن»»","url":""}]},{"id":"s2-838","number":838,"surah":2,"verses":[185],"references":[{"surah":2,"verses":[185]}],"verseLabel":"البقرة: 185","question":"ما سرّ التعبير في قوله تعالى: ﴿فَمَنْ شَهِدَ مِنْكُمُ الشَّهْرَ فَلْيَصُمْهُ﴾، وهل يُشاهَد الشهر؟","answer":"الشهود بمعنى الحضور والإقامة عند دخول الشهر، أو مشاهدة هلاله؛ والضمير يعود إلى الشهر بمعنى أيامه. فالحكم يتعلق بمن أدرك رمضان حاضرًا قادرًا، لا بمجرد رؤية جسم الشهر.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص65، تحت «تعيين مفعول (شهد) من قوله: «فمن شهد منكم الشهر»»","url":""}]},{"id":"s2-839","number":839,"surah":2,"verses":[185],"references":[{"surah":2,"verses":[185]}],"verseLabel":"البقرة: 185","question":"ما سرّ الجمع بين إثبات اليسر ونفي العسر في قوله تعالى: ﴿يُرِيدُ اللَّهُ بِكُمُ الْيُسْرَ وَلَا يُرِيدُ بِكُمُ الْعُسْرَ﴾؟","answer":"إثبات إرادة اليسر لا يقطع وحده توهم إرادة بعض العسر، فنفى العسر صراحة لتأكيد مقصد التيسير الذي ظهر في رخصتي المرض والسفر.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص67، تحت «دلالة المقابلة في قوله: «يريد الله بكم اليسر ولا يريد بكم العسر»»","url":""}]},{"id":"s2-840","number":840,"surah":2,"verses":[185],"references":[{"surah":2,"verses":[185]}],"verseLabel":"البقرة: 185","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلِتُكْمِلُوا الْعِدَّةَ﴾ بعد رخصة الإفطار؟","answer":"حتى يفهم أن التيسير لا يعني إسقاط العبادة، بل نقل الأيام الفائتة إلى وقت يقدر عليه المكلف؛ فتجتمع الرحمة مع تمام الواجب. والعطف على معنى الرخصة يكشف مقصدها لا ظاهر لفظها فقط.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص68، تحت «العطف على المعنى لا على ظاهر اللفظ في قوله: «ولتكملوا العدة»»","url":""}]},{"id":"s2-841","number":841,"surah":2,"verses":[185],"references":[{"surah":2,"verses":[185]}],"verseLabel":"البقرة: 185","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلِتُكَبِّرُوا اللَّهَ عَلَى مَا هَدَاكُمْ﴾ بعد الصيام؟","answer":"جاء التكبير تعليلًا لما عُلّم المسلمون من أحكام القضاء والخروج من عهدة الفطر؛ ليعظموا الله على هدايته لهم. والتكبير يتضمن الشكر، فيناسب إتمام العبادة والاعتراف بفضل الهادي.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص69–70، تحت عنوان «دلالة التعليلات في ﴿ولتكملوا العدة﴾، ﴿ولتكبروا الله﴾، ﴿ولعلكم تشكرون﴾»","url":""}]},{"id":"s2-842","number":842,"surah":2,"verses":[185],"references":[{"surah":2,"verses":[185]}],"verseLabel":"البقرة: 185","question":"ما مناسبة ختم آية رمضان بقوله تعالى: ﴿وَلَعَلَّكُمْ تَشْكُرُونَ﴾؟","answer":"جُعل الشكر آخر التعليلات لأنه أعم من التكبير؛ فالتكبير تعظيم يتضمن الشكر، أما الشكر فيكون بالأقوال وبفعل القربات، كالصدقات في أيام الصيام والفطر. وهو يناسب ما شرع من الترخيص والتيسير.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص70، تحت عنوان «دلالة التعليلات في ﴿ولتكملوا العدة﴾، ﴿ولتكبروا الله﴾، ﴿ولعلكم تشكرون﴾»","url":""}]},{"id":"s2-843","number":843,"surah":2,"verses":[186],"references":[{"surah":2,"verses":[186]}],"verseLabel":"البقرة: 186","question":"ما مناسبة مجيء آية الدعاء في أثناء آيات الصيام؟","answer":"جاءت بعد الصيام والتكبير والشكر لتبين أن الله قريب ممن يذكره ويشكره، مجيب لمن دعاه، ثم عاد السياق إلى بقية أحكام الصيام.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص72، تحت «مناسبة الآية لما قبلها»","url":""}]},{"id":"s2-844","number":844,"surah":2,"verses":[186],"references":[{"surah":2,"verses":[186]}],"verseLabel":"البقرة: 186","question":"ما سرّ التعبير في قوله تعالى: ﴿فليستجيبوا لي﴾، دون أن يقال: فليجيبوني؟","answer":"الاستجابة تحمل معنى الطاعة والانقياد بعد الدعوة، فليست مجرد جواب لفظي بل مقابلة قرب الله بامتثال أمره.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص80–81، تحت «دلالة صيغة (استفعل) في قوله «فليستجيبوا لي»؛ ونكتة العدول عن الفعل (فليجيبوا) إلى قوله «فليستجيبوا لي»»","url":""}]},{"id":"s2-845","number":845,"surah":2,"verses":[186],"references":[{"surah":2,"verses":[186]}],"verseLabel":"البقرة: 186","question":"ما سرّ التعبير في قوله تعالى: ﴿وَإِذَا سَأَلَكَ عِبَادِي عَنِّي﴾ وأضافهم إلى نفسه؟","answer":"أضاف العباد إلى نفسه تشريفًا وتكريمًا لهم، وهيأهم بذلك لسماع خبر قربه وإجابته لدعائهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص76، تحت «نكتة الإضافة والحذف في قوله: «وإذا سألك عبادي عني»»","url":""}]},{"id":"s2-846","number":846,"surah":2,"verses":[186],"references":[{"surah":2,"verses":[186]}],"verseLabel":"البقرة: 186","question":"ما سرّ مجيء جواب سؤال العباد مباشرة: ﴿فَإِنِّي قَرِيبٌ﴾ من غير واسطة ﴿قل﴾؟","answer":"حُذفت ﴿قل﴾ للدلالة على أنه لا واسطة بين الله وعباده في مقام الدعاء، وأنه تولى جواب سؤالهم بنفسه، وفي ذلك تكريم لهم وإيذان بشدة قربه منهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص79، تحت عنوان «وفي حذف قل في هذه الآية نكات»","url":""}]},{"id":"s2-847","number":847,"surah":2,"verses":[186],"references":[{"surah":2,"verses":[186]}],"verseLabel":"البقرة: 186","question":"ما معنى قرب الله في قوله تعالى: ﴿فَإِنِّي قَرِيبٌ﴾ مع علوه سبحانه؟","answer":"قربه سبحانه قرب علم وإحاطة وإجابة؛ فهو كامل العلم بأفعال عباده وأقوالهم وأحوالهم، يسمع دعاءهم ويجيبهم، وليس المراد تشبيه قربه بقرب المخلوقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص78، تحت «بلاغة التمثيل في قوله تعالى: «فإني قريب»»","url":""}]},{"id":"s2-848","number":848,"surah":2,"verses":[186],"references":[{"surah":2,"verses":[186]}],"verseLabel":"البقرة: 186","question":"ما وجه مجيء قوله تعالى: ﴿أُجِيبُ دَعْوَةَ الدَّاعِ إِذَا دَعَانِ﴾ دون واو بعد ﴿فَإِنِّي قَرِيبٌ﴾؟","answer":"يجوز أن تكون الجملة حالًا، أي: قريب مجيبًا، أو استئنافًا بيانيًا يجيب عن سؤال يثيره ذكر القرب: ما أثر هذا القرب؟ فيأتي الجواب بإجابة دعاء الداعين.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص80، تحت «سبب فصل قوله: ﴿أجيب دعوة الداع إذا دعان﴾ عما قبله»","url":""}]},{"id":"s2-849","number":849,"surah":2,"verses":[186],"references":[{"surah":2,"verses":[186]}],"verseLabel":"البقرة: 186","question":"ما سرّ التعبير في قوله تعالى: ﴿دَعْوَةَ الدَّاعِ﴾، دون أن يقال: «دعاء العبد»؟","answer":"عرّف ﴿الداع﴾ لإفادة الجنس والشمول، وأفرده للاهتمام بدعاء كل واحد من الداعين على سبيل الانفراد والاستقلال؛ فكل داع داخل في الوعد بالإجابة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص79–80، تحت «دلالة اللام في (الداع) من: ﴿أجيب دعوة الداع إذا دعان﴾»","url":""}]},{"id":"s2-850","number":850,"surah":2,"verses":[186],"references":[{"surah":2,"verses":[186]}],"verseLabel":"البقرة: 186","question":"ما سرّ التعبير في قوله تعالى: ﴿فَلْيَسْتَجِيبُوا لِي وَلْيُؤْمِنُوا بِي﴾، مع أن الإيمان سابق للاستجابة؟","answer":"المطلوب أن يقابلوا إجابة الله لهم بإجابة أوامره، ثم يجددوا إيمانهم وثقتهم بوعده؛ وخص الإيمان بعد عموم الاستجابة لعظم منزلته. فالدعاء علاقة ذات طرفين: سؤال من العبد وطاعة وثقة منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص81، تحت «سر عطف الخاص على العام في قوله تعالى: «فليستجيبوا لي وليؤمنوا بي»»","url":""}]},{"id":"s2-851","number":851,"surah":2,"verses":[186],"references":[{"surah":2,"verses":[186]}],"verseLabel":"البقرة: 186","question":"ما مناسبة ختم آية الدعاء بقوله تعالى: ﴿لَعَلَّهُمْ يَرْشُدُونَ﴾؟","answer":"حتى لا يظن أن ثمرة الدعاء مقصورة على نيل المطلوب العاجل؛ الغاية الأبعد إصابة الحق وحسن التصرف والهداية إلى ما ينفع. فالاستجابة والإيمان بالله يعيدان توجيه حياة العبد كلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص82، تحت «حسن الختام في قوله: «لعلهم يرشدون»»","url":""}]},{"id":"s2-852","number":852,"surah":2,"verses":[187],"references":[{"surah":2,"verses":[187]}],"verseLabel":"البقرة: 187","question":"ما سرّ تشبيه الزوجين باللباس في قوله تعالى: ﴿هُنَّ لِبَاسٌ لَكُمْ وَأَنْتُمْ لِبَاسٌ لَهُنَّ﴾؟","answer":"لأن اللباس شديد الملابسة بصاحبه ويستره ويسكن إليه؛ فالتشبيه يجمع قرب الزوجين وتداخل كل واحد منهما بالآخر والستر المتبادل بينهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص89، تحت «نكات التشبيه البليغ في قوله: «هن لباس لكم وأنتم لباس لهن»»","url":""}]},{"id":"s2-853","number":853,"surah":2,"verses":[187],"references":[{"surah":2,"verses":[187]}],"verseLabel":"البقرة: 187","question":"ما سرّ إفراد ﴿لباس﴾ مع ضمير الجمع؟","answer":"لأنه اسم جنس أو مصدر يصدق على كل زوج وزوجة، والإفراد يبرز وحدة الوظيفة المتبادلة لا عدد الأشخاص.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص90، تحت «علة إفراد اللباس مع ضمير الجمع في: «هن لباس لكم»»","url":""}]},{"id":"s2-854","number":854,"surah":2,"verses":[187],"references":[{"surah":2,"verses":[187]}],"verseLabel":"البقرة: 187","question":"ما سرّ التعبير في قوله تعالى: ﴿تختانون أنفسكم﴾ لا: تخونون؟","answer":"عُبر بالاختيان لأنه أبلغ وأشد في استهجان الفعل من الخيانة، ولأنه اختيان ذاتي يضر صاحبه نفسه؛ فالمخالف في الحقيقة يخون نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص92، تحت عنوان «نكتة التعبير بـ﴿تختانون﴾ دون تخونون»","url":""}]},{"id":"s2-855","number":855,"surah":2,"verses":[187],"references":[{"surah":2,"verses":[187]}],"verseLabel":"البقرة: 187","question":"لماذا اختير لفظ ﴿الرَّفَثُ﴾ في الكناية عن الجماع في آية الصيام؟","answer":"تختار الآية الكناية عن الجماع دون التصريح به، وتذكر الموسوعة أن اختيار الرفث، وهو أصرح من بعض الكنايات الأخرى، فيه استهجان لما وقع قبل الإباحة، وأن الجماع لا يكاد يخلو من رفث.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص88، تحت «علة إيثار لفظ ﴿الرفث﴾ في الكناية عن الجماع»","url":""}]},{"id":"s2-856","number":856,"surah":2,"verses":[187,229],"references":[{"surah":2,"verses":[187,229]}],"verseLabel":"البقرة: 187 و229","question":"ما سرّ اختلاف التعبير بين قوله تعالى في أحكام الصيام: ﴿تِلْكَ حُدُودُ اللَّهِ فَلَا تَقْرَبُوهَا﴾، وقوله تعالى في أحكام الطلاق: ﴿تِلْكَ حُدُودُ اللَّهِ فَلَا تَعْتَدُوهَا﴾؟","answer":"في الصيام نهى عن قربان المحظورات ومقدماتها، فقال ﴿فلا تقربوها﴾ مبالغة في الاحتياط. وفي الطلاق حدود ومقادير مرسومة فناسب النهي عن تجاوزها: ﴿فلا تعتدوها﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص101، تحت عنوان «الفرق في التعبير بين قوله: ﴿فلا تقربوها﴾ و﴿فلا تعتدوها﴾»","url":""}]},{"id":"s2-857","number":857,"surah":2,"verses":[187],"references":[{"surah":2,"verses":[187]}],"verseLabel":"البقرة: 187","question":"لماذا بُني ﴿أحل﴾ للمفعول في ﴿أحل لكم ليلة الصيام الرفث﴾؟","answer":"حُذف الفاعل للعلم به؛ فالمؤمنون يعلمون أن الذي يحل ويحرم هو الله تعالى، فدل المعنى على الفاعل دون حاجة إلى ذكره.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص87، تحت عنوان «توجيه القراءة الشاذة»","url":""}]},{"id":"s2-1520","number":1520,"surah":2,"verses":[187],"references":[{"surah":2,"verses":[187]}],"verseLabel":"البقرة: 187","question":"لماذا اختير لفظ ﴿أحل﴾ في إباحة الرفث ليلة الصيام؟","answer":"للامتنان على المخاطبين بتذكيرهم بما كان محرمًا قبل نزول الآية ثم أُبيح؛ فلفظ التحليل يستحضر المنع السابق، ولذلك كان هنا أبلغ من مجرد التعبير بالجواز أو الإذن.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص86–87، تحت عنوان «سر إيثار لفظ ﴿أحل﴾ على غيره من الألفاظ»","url":""}]},{"id":"s2-858","number":858,"surah":2,"verses":[187],"references":[{"surah":2,"verses":[187]}],"verseLabel":"البقرة: 187","question":"ما سرّ التعبير في قوله تعالى: ﴿الرَّفَثُ إِلَى نِسَائِكُمْ﴾ بـ﴿إلى﴾، دون أن يقال: «مع نسائكم»؟","answer":"ضمّن الرفث معنى الإفضاء والانتهاء إلى الزوجة، وجاء التعبير كناية مهذبة تبعد التصوير المكشوف لحال الجماع. فحرف الغاية يؤدي المعنى ويحفظ حياء العبارة القرآنية.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص88، تحت «وجه تعدية الرفث بـ«إلى»، في قوله تعالى: «الرفث إلى نسائكم»»","url":""}]},{"id":"s2-859","number":859,"surah":2,"verses":[187],"references":[{"surah":2,"verses":[187]}],"verseLabel":"البقرة: 187","question":"ما سرّ تقديم قوله تعالى: ﴿هُنَّ لِبَاسٌ لَكُمْ﴾ على ﴿وَأَنْتُمْ لِبَاسٌ لَهُنَّ﴾؟","answer":"قدم ذكر النساء لأن السياق سياق امتنان على الرجال بإباحة الرفث إليهن، ولأن حاجة الرجل إلى المرأة هي الأظهر في هذا المقام؛ ثم أتبعه بالمقابلة لإثبات الملابسة المتبادلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص90، تحت «علة تقديم النساء على الرجال»","url":""}]},{"id":"s2-860","number":860,"surah":2,"verses":[187],"references":[{"surah":2,"verses":[187]}],"verseLabel":"البقرة: 187","question":"ما سرّ التعبير في قوله تعالى: ﴿فَتَابَ عَلَيْكُمْ وَعَفَا عَنْكُمْ﴾ قبل إباحة المباشرة؟","answer":"قدم التوبة والعفو لمحو أثر المخالفة وطمأنة المخاطبين، ثم جاء الإذن بالمباشرة رفعًا للمنع؛ فجمع السياق العفو عما مضى والتخفيف في الحكم الآتي.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص93، تحت «معنى الفاء في قوله تعالى: «فتاب عليكم»»","url":""}]},{"id":"s2-861","number":861,"surah":2,"verses":[187],"references":[{"surah":2,"verses":[187]}],"verseLabel":"البقرة: 187","question":"ما سرّ التعبير في قوله تعالى: ﴿فَالْآنَ بَاشِرُوهُنَّ﴾؟","answer":"جيء بـ﴿الآن﴾ لبيان أن وقت الإذن بالمباشرة قد حضر بعد رفع المنع، وفيه إشعار بالتوسعة وإدخال السرور؛ و﴿باشروهن﴾ كناية مهذبة عن الجماع مأخوذة من التقاء البشرتين.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص94، تحت «توجيه مجيء «فالآن» ظرفا لفعل الأمر: «باشروهن»»","url":""}]},{"id":"s2-862","number":862,"surah":2,"verses":[187],"references":[{"surah":2,"verses":[187]}],"verseLabel":"البقرة: 187","question":"ما مناسبة قوله تعالى: ﴿وَابْتَغُوا مَا كَتَبَ اللَّهُ لَكُمْ﴾ بعد إباحة المباشرة؟","answer":"عقب إباحة المباشرة بالأمر بابتغاء ما كتب الله ليقصد المؤمن بجماعه ما أحله الله من الولد الصالح والتحصن عن الحرام، فلا يقف قصده عند مجرد قضاء الشهوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص95، تحت «فائدة تعقيب الأمر بالمباشرة بقوله تعالى: «وابتغوا ما كتب الله لكم»»","url":""}]},{"id":"s2-863","number":863,"surah":2,"verses":[187],"references":[{"surah":2,"verses":[187]}],"verseLabel":"البقرة: 187","question":"ما سرّ التعبير في قوله تعالى: ﴿حَتَّى يَتَبَيَّنَ لَكُمُ الْخَيْطُ الْأَبْيَضُ مِنَ الْخَيْطِ الْأَسْوَدِ﴾؟","answer":"شبّه ضوء الصبح الممتد بخيط أبيض يشق سواد الليل الذي يبدو كخيط أسود، فجعل انتقال الزمن مشهدًا بصريًا يمكن ضبطه. المقصود ظهور الفجر الصادق لا خيطان حسيان.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص96، تحت «بلاغة التشبيه البليغ في: «الخيط الأبيض من الخيط الأسود من الفجر»»","url":""}]},{"id":"s2-864","number":864,"surah":2,"verses":[187],"references":[{"surah":2,"verses":[187]}],"verseLabel":"البقرة: 187","question":"ما فائدة قوله تعالى: ﴿مِنَ الْفَجْرِ﴾ بعد ذكر الخيط الأبيض والأسود؟","answer":"جاء ﴿من الفجر﴾ بيانًا بعد الاستعارة؛ حتى لا يحمل الخيطان على الحقيقة، فالمراد بياض الصبح وسواد الليل.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص96، تحت «فائدة التقييد بقوله تعالى: «من الفجر»»","url":""}]},{"id":"s2-865","number":865,"surah":2,"verses":[187],"references":[{"surah":2,"verses":[187]}],"verseLabel":"البقرة: 187","question":"ما سرّ التعبير في قوله تعالى: ﴿ثُمَّ أَتِمُّوا الصِّيَامَ إِلَى اللَّيْلِ﴾، دون أن يقال: «حتى الليل»؟","answer":"﴿إلى﴾ تحدد غاية الإمساك بوضوح، و﴿ثم﴾ تعطف إتمام الصوم على مرحلة الإباحة الليلية مع بُعد ما بين طرفي الزمن. والتعبير يدل على انتهاء الصوم بدخول الليل وينفي وصال الصيام بعده.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص97، تحت «معنى انتهاء الغاية في قوله: «ثم أتموا الصيام إلى الليل»»","url":""}]},{"id":"s2-866","number":866,"surah":2,"verses":[187],"references":[{"surah":2,"verses":[187]}],"verseLabel":"البقرة: 187","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلَا تُبَاشِرُوهُنَّ وَأَنْتُمْ عَاكِفُونَ فِي الْمَسَاجِدِ﴾ بعد إباحتها ليلًا؟","answer":"لما أبيحت المباشرة ليلًا استثنيت حال الاعتكاف، لأن المعتكف منقطع لعبادة الله فلا تشمل الرخصة مباشرته النساء، وذكر المساجد لبيان الحال التي يقع فيها الاعتكاف غالبًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص99، تحت «فائدة مجيء الجملة الحالية «وأنتم عاكفون في المساجد» بعد قوله «ولا تباشروهن»»","url":""}]},{"id":"s2-867","number":867,"surah":2,"verses":[187],"references":[{"surah":2,"verses":[187]}],"verseLabel":"البقرة: 187","question":"ما سرّ التعبير في قوله تعالى عن حدود الله: ﴿فَلَا تَقْرَبُوهَا﴾، دون أن يقال: «فلا تتجاوزوها»؟","answer":"نهى عن قرب الحدود ليكون بين المكلف والمحظور حاجز يمنعه من الوقوع فيه؛ وهو أبلغ في الاحتياط والورع من الاقتصار على النهي عن التجاوز.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص100، تحت عنوان «دلالة النهي في قوله تعالى: ﴿فلا تقربوها﴾»","url":""}]},{"id":"s2-868","number":868,"surah":2,"verses":[188],"references":[{"surah":2,"verses":[188]}],"verseLabel":"البقرة: 188","question":"ما سرّ التعبير في قوله تعالى: ﴿وتدلوا بها إلى الحكام﴾ فصوّر المال كأنه دلو؟","answer":"شبه تقديم الحجة الباطلة أو الرشوة إلى الحاكم بإرسال الدلو في البئر للوصول به إلى المطلوب؛ فكما يكون الدلو وسيلة لاستخراج الماء تكون الحجة أو الرشوة وسيلة إلى أخذ مال الغير بالباطل.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص110، تحت «وجه تشبيه الرشوة بالإدلاء، في قوله تعالى: «وتدلوا بها»»","url":""}]},{"id":"s2-869","number":869,"surah":2,"verses":[188],"references":[{"surah":2,"verses":[188]}],"verseLabel":"البقرة: 188","question":"ما سرّ التعبير عن أخذ المال بالباطل بقوله تعالى: ﴿لَا تَأْكُلُوا﴾؟","answer":"عبر بالأكل لأنه أهم وجوه الانتفاع بالمال وأكثرها شيوعًا، فاستعير لكل أخذ لمال الغير بالباطل مع قصد عدم إرجاعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص105، تحت «بلاغة الاستعارة في التعبير بالأكل عن أخذ المال»","url":""}]},{"id":"s2-870","number":870,"surah":2,"verses":[188],"references":[{"surah":2,"verses":[188]}],"verseLabel":"البقرة: 188","question":"ما سرّ التعبير في قوله تعالى: ﴿أَمْوَالَكُمْ﴾، مع أن المراد أموال غيركم؟","answer":"لأن أموال الجماعة بمنزلة مال واحد يتكافل الناس على حمايته، ولأن من أكل مال أخيه أباح للآخرين أن يفعلوا مثله بماله. فالضمير يبني حاجزًا أخلاقيًا: اعتداؤك على غيرك اعتداء على مجتمعك ونفسك.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص105، تحت «نكتة إضافة الأموال إلى المخاطبين في قوله تعالى: «ولا تأكلوا أموالكم»»","url":""}]},{"id":"s2-871","number":871,"surah":2,"verses":[188],"references":[{"surah":2,"verses":[188]}],"verseLabel":"البقرة: 188","question":"ما فائدة قوله: ﴿بَيْنَكُمْ﴾؟","answer":"دل ﴿بينكم﴾ على توسط الأموال وانتقالها بين الأطراف، بحيث يكون كل واحد آكلًا من جهة ومأكولًا ماله من جهة أخرى، فعم النهي صور التعدي المتبادل.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص106، تحت «دلالة مقابلة الجمع بالجمع في قوله تعالى: ﴿ولا تأكلوا أموالكم﴾»","url":""}]},{"id":"s2-872","number":872,"surah":2,"verses":[188],"references":[{"surah":2,"verses":[188]}],"verseLabel":"البقرة: 188","question":"ما سرّ التعبير في قوله تعالى: ﴿بِهَا﴾ في ﴿وَتُدْلُوا بِهَا إِلَى الْحُكَّامِ﴾؟","answer":"تحتمل الباء الإلصاق، أي لا ترشوا الحكام بالأموال، وتحتمل السببية، أي لا تجعلوا الخصومة أو الحجة سببًا للوصول إلى الحكم الباطل؛ والضمير يعود إلى الأموال أو الحجة بحسب الوجه.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص109، تحت «دلالة الباء في قوله تعالى: «وتدلوا بها»»","url":""}]},{"id":"s2-873","number":873,"surah":2,"verses":[188],"references":[{"surah":2,"verses":[188]}],"verseLabel":"البقرة: 188","question":"ما سرّ التعبير في قوله تعالى: ﴿لِتَأْكُلُوا فَرِيقًا مِنْ أَمْوَالِ النَّاسِ﴾؟","answer":"فريقًا تعني بعض المال أو طائفة منه، واللام تبين الغاية من الاحتجاج بالباطل عند الحكام: الوصول إلى أموال الناس بغير حق، بشهادة زور أو يمين كاذبة ونحو ذلك.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص111، تحت «دلالة التعليل في قوله: ﴿لتأكلوا فريقًا من أموال الناس بالإثم﴾»","url":""}]},{"id":"s2-874","number":874,"surah":2,"verses":[188],"references":[{"surah":2,"verses":[188]}],"verseLabel":"البقرة: 188","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿وَأَنْتُمْ تَعْلَمُونَ﴾؟","answer":"لأن من يستعين بالحاكم ليغطي الباطل قد يملك حكمًا ظاهريًا، لكنه يعلم في باطنه أن المال ليس حقه؛ فعلمه يجعل جرأته وإثمه أشد. وحكم القاضي لا يغير حقيقة يعرفها الخصم.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص112، تحت «فائدة تقييد النهي بالعلم: «وأنتم تعلمون»»","url":""}]},{"id":"s2-875","number":875,"surah":2,"verses":[189],"references":[{"surah":2,"verses":[189]}],"verseLabel":"البقرة: 189","question":"ما سرّ التعبير عن الهلال بالجمع في سؤالهم عن ﴿الْأَهِلَّةِ﴾؟","answer":"لأن الهلال يتجدد كل شهر وتختلف منازله وأحوال ظهوره، فجمع باعتبار تعدد الأهلة في الشهور.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص117، تحت «السر في جمع الهلال وهو واحد: «يسألونك عن الأهلة»»","url":""}]},{"id":"s2-876","number":876,"surah":2,"verses":[189],"references":[{"surah":2,"verses":[189]}],"verseLabel":"البقرة: 189","question":"ما سرّ تخصيص الحج بالذكر بعد قوله تعالى: ﴿مَوَاقِيتُ لِلنَّاسِ﴾؟","answer":"لأنه من أعظم العبادات ارتباطًا بالشهور القمرية، فخص بعد العموم لعنايته ولأن الخطأ في وقته يخل بأدائه.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص119، تحت «السر في إفراد الحج بالذكر: «قل هي مواقيت للناس والحج»»","url":""}]},{"id":"s2-877","number":877,"surah":2,"verses":[189],"references":[{"surah":2,"verses":[189]}],"verseLabel":"البقرة: 189","question":"ما سرّ جعل الأهلة مواقيت دون الشمس؟","answer":"تغير الهلال ظاهر يسهل أن يراه عامة الناس في كل مكان ويحدد أول الشهر، فلا يحتاج إلى حساب دقيق أو أداة خاصة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص120، تحت «السر في تخصيص المواقيت والشعائر بالهلال دون الشمس»","url":""}]},{"id":"s2-878","number":878,"surah":2,"verses":[189],"references":[{"surah":2,"verses":[189]}],"verseLabel":"البقرة: 189","question":"ما سرّ توجيه الجواب إلى وظيفة الأهلة: ﴿هِيَ مَوَاقِيتُ لِلنَّاسِ وَالْحَجِّ﴾ دون بيان كيفية تكوّنها؟","answer":"عدل الجواب إلى ما يحتاجه الناس وينفعهم: ضبط مواقيت عباداتهم ومعاملاتهم وحجهم، ولم يدخل بهم في وصف فلكي لا يتعلق بمقصود التكليف.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص120، تحت «أسلوب الحكيم في قوله: «قل هي مواقيت للناس والحج»»","url":""}]},{"id":"s2-879","number":879,"surah":2,"verses":[189],"references":[{"surah":2,"verses":[189]}],"verseLabel":"البقرة: 189","question":"ما سرّ التعبير في قوله تعالى: ﴿قُلْ هِيَ مَوَاقِيتُ﴾، دون أن يقال: «فقل» كما يجيء كثيرًا بعد السؤال؟","answer":"جاء الجواب بـ﴿قل﴾ بلا فاء لأن السؤال عن أمر دنيوي ثابت واقع، وعادة القرآن في أمثال هذه الأسئلة أن يأتي الجواب مستأنفًا بلا فاء؛ أما السؤال عن أمر مقدر الوقوع في المستقبل فيحسن فيه ﴿فقل﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص117، تحت «سر العدول عن «فقل» إلى «قل» في قوله: «يسألونك عن الأهلة قل هي مواقيت»»","url":""}]},{"id":"s2-880","number":880,"surah":2,"verses":[189],"references":[{"surah":2,"verses":[189]}],"verseLabel":"البقرة: 189","question":"ما سرّ وصف الأهلة بأنها ﴿مَوَاقِيتَ﴾ بصيغة الجمع؟","answer":"لأن الأهلة تضبط أوقاتًا كثيرة للعبادات والمعاملات والعدد والحج؛ فكل وقت مضبوط بها ميقات.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص118، تحت عنوان «السر في الإعراض عن ذكر الأعمال المؤقتة»","url":""}]},{"id":"s2-881","number":881,"surah":2,"verses":[189],"references":[{"surah":2,"verses":[189]}],"verseLabel":"البقرة: 189","question":"ما علاقة قوله: ﴿وَلَيْسَ الْبِرُّ بِأَنْ تَأْتُوا الْبُيُوتَ مِنْ ظُهُورِهَا﴾ بسؤال الأهلة؟","answer":"الجامع تصحيح السؤال والعمل: كما وجّههم إلى النافع من سؤال الأهلة، أبطل عادة كانوا يعدونها برًا وهي دخول المحرم من ظهر البيت؛ فالبر امتثال الشرع لا التكلف والعادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص122، تحت عنوان «المناسبة والاتصال بين: ﴿يسألونك عن الأهلة﴾ و﴿وليس البر بأن تأتوا البيوت﴾»","url":""}]},{"id":"s2-882","number":882,"surah":2,"verses":[189],"references":[{"surah":2,"verses":[189]}],"verseLabel":"البقرة: 189","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلَكِنَّ الْبِرَّ مَنِ اتَّقَى﴾، فجعل البر شخصًا؟","answer":"بالغ حتى جعل المتقي نفس البر، أو المعنى: بر من اتقى؛ فليست القيمة في حركة غريبة يؤديها الجسد، بل في إنسان لازمته التقوى وصارت له سجية. والصياغة تقابل التكلف الظاهر بالخلق الباطن.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص124، تحت «الإخبار عن المعنى بالذات في قوله: «ولكن البر من اتقى»»","url":""}]},{"id":"s2-883","number":883,"surah":2,"verses":[189],"references":[{"surah":2,"verses":[189]}],"verseLabel":"البقرة: 189","question":"ما مناسبة الأمر بقوله تعالى: ﴿وَأْتُوا الْبُيُوتَ مِنْ أَبْوَابِهَا﴾ بعد نفي البر؟","answer":"لما نفى أن يكون الدخول من الظهور برًا أمر بضده، وهو دخول البيوت من أبوابها، فجمع بين إبطال العادة وبيان الفعل المشروع؛ وتمثيلًا: تؤتى الأمور من وجوهها وطرقها الصحيحة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص124، تحت «عطف الإنشاء على الخبر في قوله تعالى: «وأتوا البيوت من أبوابها»»","url":""}]},{"id":"s2-884","number":884,"surah":2,"verses":[189],"references":[{"surah":2,"verses":[189]}],"verseLabel":"البقرة: 189","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿وَاتَّقُوا اللَّهَ لَعَلَّكُمْ تُفْلِحُونَ﴾؟","answer":"رد ميزان البر إلى تقوى الله، فهي جماع امتثال الأوامر واجتناب النواهي، وعلق بها رجاء الفلاح ترغيبًا في لزومها.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص127، تحت «دلالة تعلق الفلاح بالتقوى في قوله: «واتقوا الله لعلكم تفلحون»»","url":""}]},{"id":"s2-885","number":885,"surah":2,"verses":[190],"references":[{"surah":2,"verses":[190]}],"verseLabel":"البقرة: 190","question":"ما دلالة تقديم ﴿فِي سَبِيلِ اللَّهِ﴾ في قوله تعالى: ﴿وَقَاتِلُوا فِي سَبِيلِ اللَّهِ الَّذِينَ يُقَاتِلُونَكُمْ﴾؟","answer":"قدم ﴿في سبيل الله﴾ لأنه موضع العناية والأهم، ولبيان أن القتال إنما يكون في نصرة دين الله وطاعته.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص134، تحت «نكتة تقديم شبه الجملة على المفعول الصريح»","url":""}]},{"id":"s2-886","number":886,"surah":2,"verses":[190],"references":[{"surah":2,"verses":[190]}],"verseLabel":"البقرة: 190","question":"ما مناسبة الانتقال من الأهلة والحج إلى الأمر بقوله تعالى: ﴿وَقَاتِلُوا فِي سَبِيلِ اللَّهِ﴾؟","answer":"لما أمر بالتقوى، وهي فعل الواجبات وترك المحظورات، أتبعها بأشد ما يشق على النفس من ذلك: قتال أعداء الله ردًا لعدوانهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص131، تحت «المناسبة بين الأمر بالتقوى، والأمر برد العدوان عن الحرمات»","url":""}]},{"id":"s2-887","number":887,"surah":2,"verses":[190],"references":[{"surah":2,"verses":[190]}],"verseLabel":"البقرة: 190","question":"ما سرّ التعبير في قوله تعالى: ﴿الَّذِينَ يُقَاتِلُونَكُمْ﴾، دون أن يقال: «قاتلوا الكافرين»؟","answer":"قدم الغاية لأنها الأهم؛ فالقتال المشروع مقيد بأن يكون في سبيل الله، ثم بين من يوجه إليهم وهم الذين يقاتلون المؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص133، تحت «دلالة الاسم الموصول في قوله: «الذين يقاتلونكم»»","url":""}]},{"id":"s2-888","number":888,"surah":2,"verses":[190],"references":[{"surah":2,"verses":[190]}],"verseLabel":"البقرة: 190","question":"ما دلالة صيغة المفاعلة في قوله تعالى: ﴿يُقَاتِلُونَكُمْ﴾؟","answer":"المفاعلة تدل على وقوع القتال بين جانبين؛ فقيد الأمر بمن يباشر قتال المسلمين، ولم يجعله عدوانًا على من لا يقاتل.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص134، تحت «دلالة المفاعلة في قوله: «الذين يقاتلونكم»»","url":""}]},{"id":"s2-889","number":889,"surah":2,"verses":[190],"references":[{"surah":2,"verses":[190]}],"verseLabel":"البقرة: 190","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلَا تَعْتَدُوا﴾، ولم يذكر ما الذي لا يعتدون فيه؟","answer":"حذف المتعلق ليعم كل عدوان: البدء بغير المقاتل، وتجاوز الضرورة، والتمثيل والغدر وإفساد ما لا صلة له بالقتال. فالإطلاق يحاصر التجاوز في الأشخاص والوسائل والغايات معًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص135، تحت «حذف المتعلق وإطلاق النهي عن الاعتداء: «ولا تعتدوا»»","url":""}]},{"id":"s2-890","number":890,"surah":2,"verses":[190],"references":[{"surah":2,"verses":[190]}],"verseLabel":"البقرة: 190","question":"ما سرّ التعبير في قوله تعالى: ﴿إِنَّ اللَّهَ لَا يُحِبُّ الْمُعْتَدِينَ﴾، دون أن يقال: «يعاقب المعتدين»؟","answer":"نفي المحبة يدل على بغض الاعتداء وتحريمه، وجاءت الجملة مؤكدة تعليلًا للنهي وتحذيرًا من تجاوز حدود الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص136، تحت «دلالة نفي المحبة في قوله: «إن الله لا يحب المعتدين»»","url":""}]},{"id":"s2-891","number":891,"surah":2,"verses":[191],"references":[{"surah":2,"verses":[191]}],"verseLabel":"البقرة: 191","question":"ما سرّ التعبير في قوله تعالى: ﴿والفتنة أشد من القتل﴾؟ وأي فتنة أشد من القتل؟","answer":"المراد فتنتهم المؤمنين عن دينهم بالكفر والصد والاضطهاد، وهي أشد لما فيها من ضرر دائم متكرر، بخلاف ألم القتل المنقطع.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص144، تحت «سر التعبير بالفتنة عن الكفر»","url":""}]},{"id":"s2-892","number":892,"surah":2,"verses":[191],"references":[{"surah":2,"verses":[191]},{"surah":4,"verses":[89,91]},{"surah":9,"verses":[5]}],"verseLabel":"البقرة: 191، النساء: 89 و91، التوبة: 5","question":"ماذا يفيد فعل ﴿ثَقِفْتُمُوهُمْ﴾ في سياق قتال المعتدين؟","answer":"يفيد الظفر بهم والتمكن منهم بعد الطلب، لا مجرد مصادفة وجودهم؛ وجاء الأمر في سياق مقابلة من أخرجوا المؤمنين وقاتلوهم، مع بقاء النهي السابق عن الاعتداء.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص356، تحت «ثقفتموهم، ووجدتموهم، وصادفتموهم»","url":""}]},{"id":"s2-893","number":893,"surah":2,"verses":[191],"references":[{"surah":2,"verses":[191]}],"verseLabel":"البقرة: 191","question":"ما سرّ التعبير في قوله تعالى: ﴿وَاقْتُلُوهُمْ﴾ بعد أن قال في الآية السابقة: ﴿وَقَاتِلُوا﴾؟","answer":"القتال مفاعلة بين فريقين في المواجهة، أما القتل فإيقاع الفعل بالمحارب بعد الظفر به؛ فانتقل اللفظ بحسب اختلاف الحال.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص139، تحت «دلالة عطف «واقتلوهم» على «وقاتلوا»»","url":""}]},{"id":"s2-894","number":894,"surah":2,"verses":[191],"references":[{"surah":2,"verses":[191]}],"verseLabel":"البقرة: 191","question":"ما سرّ التعبير في قوله تعالى: ﴿وَأَخْرِجُوهُمْ مِنْ حَيْثُ أَخْرَجُوكُمْ﴾؟","answer":"جاء الجزاء من جنس فعلهم؛ أخرجوا المؤمنين من مكة فأمروا بإخراجهم من الموضع الذي أخرجوهم منه، وكرر الفعل والظرف لتحقيق المقابلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص143، تحت «المراد بـ«حيث» في قوله تعالى: «وأخرجوهم من حيث أخرجوكم»»","url":""}]},{"id":"s2-895","number":895,"surah":2,"verses":[191],"references":[{"surah":2,"verses":[191]}],"verseLabel":"البقرة: 191","question":"ما سرّ تقديم قوله تعالى: ﴿وَأَخْرِجُوهُمْ مِنْ حَيْثُ أَخْرَجُوكُمْ﴾ على قوله: ﴿وَالْفِتْنَةُ أَشَدُّ مِنَ الْقَتْلِ﴾؟","answer":"ذكر إخراجهم مقابلةً بالمثل قبل بيان علته؛ ثم قرر أن فتنتهم للمؤمنين عن دينهم وإخراجهم من الحرم أشد من القتل الذي استنكروه.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص143، تحت «بلاغة التذييل في قوله تعالى: «والفتنة أشد من القتل»»","url":""}]},{"id":"s2-896","number":896,"surah":2,"verses":[191],"references":[{"surah":2,"verses":[191]}],"verseLabel":"البقرة: 191","question":"ما سرّ النهي عن القتال عند المسجد الحرام بعد الأمر العام بالقتال؟","answer":"لحرمة المسجد الحرام؛ فالأصل منع القتال عنده، ولا يباح إلا إذا ابتدؤوا المسلمين بالقتال فيه، فيكون الرد جزاءً لاعتدائهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص146، تحت «استثناء القتال في المسجد الحرام: «ولا تقاتلوهم عند المسجد الحرام»»","url":""}]},{"id":"s2-897","number":897,"surah":2,"verses":[191],"references":[{"surah":2,"verses":[191]}],"verseLabel":"البقرة: 191","question":"ما سرّ التعبير في قوله تعالى: ﴿حَتَّى يُقَاتِلُوكُمْ فِيهِ﴾ ثم ﴿فَإِنْ قَاتَلُوكُمْ فَاقْتُلُوهُمْ﴾؟","answer":"جعل ابتداء القتال في الحرم منهم شرطًا، فإن باشروا القتال زالت حرمتهم العملية وجاز قتل المعتدين؛ ففرّق بين بدء العدوان ودفعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص148، تحت «الإيجاز بالحذف في قوله تعالى: ﴿فإن قاتلوكم فاقتلوهم﴾»","url":""}]},{"id":"s2-898","number":898,"surah":2,"verses":[191],"references":[{"surah":2,"verses":[191]}],"verseLabel":"البقرة: 191","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿كَذَلِكَ جَزَاءُ الْكَافِرِينَ﴾؟","answer":"اسم الإشارة يلخص الجزاء السابق ويقرره قاعدة فيمن جمع الكفر والصد عن المسجد والقتال فيه؛ فالجزاء من جنس فعلهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص149، تحت «بلاغة الفاصلة القرآنية: «كذلك جزاء الكافرين»»","url":""}]},{"id":"s2-899","number":899,"surah":2,"verses":[192],"references":[{"surah":2,"verses":[192]}],"verseLabel":"البقرة: 192","question":"ما سرّ التعبير في قوله تعالى: ﴿فإن انتهوا﴾ بـ﴿إن﴾ لا ﴿إذا﴾؟","answer":"استعمل ﴿إن﴾ لأن انتهاءهم مع عنادهم غير محقق الوقوع، بخلاف ما يكثر أو يتوقع تحققه فيستعمل له ﴿إذا﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص152، تحت «سر التعبير بأداة الشرط (إن) دون (إذا) في قوله: «فإن انتهوا»»","url":""}]},{"id":"s2-900","number":900,"surah":2,"verses":[192],"references":[{"surah":2,"verses":[192]}],"verseLabel":"البقرة: 192","question":"ما سرّ التعبير في قوله تعالى: ﴿فَإِنِ انْتَهَوْا﴾، ولم يذكر عمّا ينتهون؟","answer":"حذف المتعلق ليعم: فإن انتهوا عن الكفر والفتنة والقتال والصد بحسب ما يقتضيه السياق؛ فلا يقصر الانتهاء على فعل واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص152، تحت «تقدير متعلق المنهي عنه: «فإن انتهوا»»","url":""}]},{"id":"s2-901","number":901,"surah":2,"verses":[192],"references":[{"surah":2,"verses":[192]}],"verseLabel":"البقرة: 192","question":"ما سرّ العدول عن جواب مباشر مثل «فاتركوهم» إلى قوله تعالى: ﴿فَإِنَّ اللَّهَ غَفُورٌ رَحِيمٌ﴾؟","answer":"حذف جواب الشرط لدلالة السياق عليه: فإن انتهوا عن موجب القتال كُفَّ عنهم، وختم بالمغفرة والرحمة ترغيبًا في الانتهاء وقبولًا لمن رجع.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص153، تحت «التعقيب بمغفرة الله لهم: «فإن انتهوا فإن الله غفور رحيم»»","url":""}]},{"id":"s2-902","number":902,"surah":2,"verses":[192],"references":[{"surah":2,"verses":[192]}],"verseLabel":"البقرة: 192","question":"ما مناسبة اسمَي ﴿غَفُورٌ رَحِيمٌ﴾ بعد الحديث عن القتال؟","answer":"حذف متعلق الانتهاء فاحتمل الانتهاء عن القتال أو عن الكفر، والأرجح في المصدر الانتهاء عن الكفر لأن المغفرة والرحمة علقتا به، وهما لا تجتمعان مع بقائه.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص153، تحت «التعقيب بمغفرة الله لهم: «فإن انتهوا فإن الله غفور رحيم»»","url":""}]},{"id":"s2-903","number":903,"surah":2,"verses":[193],"references":[{"surah":2,"verses":[193]},{"surah":8,"verses":[39,40]}],"verseLabel":"البقرة: 193؛ الأنفال: 39–40","question":"ما سرّ التعبير في قوله تعالى: ﴿حتى لا تكون فتنة ويكون الدين كله لله﴾؟","answer":"يبيّن المصدر أن العطف يستكمل بيان الغاية: دفع الفتن عن عباد الله، ومنها إكراههم على عبادة معتقدات الفاتنين، وأن يكون الدين لله وحده من غير إكراه لأحد فيما يدين به. فجمع التعبير إزالة الفتنة وإخلاص الدين لله.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص153، تحت عنوان «دلالة العطف في جملة ﴿ويكون﴾»","url":""}]},{"id":"s2-904","number":904,"surah":2,"verses":[193],"references":[{"surah":2,"verses":[193]},{"surah":8,"verses":[39]}],"verseLabel":"البقرة: 193، الأنفال: 39","question":"ما سرّ اختلاف التعبير بين قوله تعالى في الأنفال: ﴿وَيَكُونَ الدِّينُ كُلُّهُ لِلَّهِ﴾ بزيادة ﴿كله﴾، وقوله تعالى في البقرة: ﴿وَيَكُونَ الدِّينُ لِلَّهِ﴾ دونها؟","answer":"زاد ﴿كله﴾ في الأنفال لأن سياقها أوسع في استئصال الفتنة وظهور الدين على الشرك كله، أما البقرة فالمقام في قتال من يقاتل عند الحرم حتى تزول فتنتهم؛ فناسب الإيجاز.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص154، تحت «بلاغة التشابه اللفظي بين آية الأنفال:39 وآية البقرة:193»","url":""}]},{"id":"s2-905","number":905,"surah":2,"verses":[193],"references":[{"surah":2,"verses":[193]}],"verseLabel":"البقرة: 193","question":"ما سرّ تكرار الأمر بقوله تعالى: ﴿وَقَاتِلُوهُمْ﴾ بعد أحكام القتال السابقة؟","answer":"كرر الأمر بالقتال ليستأنف بيان غايته وحدّه: يستمر ما دامت الفتنة قائمة، وينتهي عند زوالها وإخلاص الدين لله.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص158، تحت «نكتة تكرار الأمر بالقتال، في قوله تعالى: «وقاتلوهم حتى لا تكون فتنة»»","url":""}]},{"id":"s2-906","number":906,"surah":2,"verses":[193],"references":[{"surah":2,"verses":[193]}],"verseLabel":"البقرة: 193","question":"ما سرّ التعبير في قوله تعالى: ﴿حَتَّى لَا تَكُونَ فِتْنَةٌ﴾، دون أن يقال: «حتى تهلكوهم»؟","answer":"عبر بالغاية الشرعية نفسها: زوال الفتنة، أي الكفر والشرك الصادّين عن دين الله، لا بمجرد إهلاك أشخاص الخصوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص159، تحت «دلالة وقوع «فتنة» نكرة في سياق النفي: «حتى لا تكون فتنة»»","url":""}]},{"id":"s2-907","number":907,"surah":2,"verses":[193],"references":[{"surah":2,"verses":[193]}],"verseLabel":"البقرة: 193","question":"ما سرّ عطف المثبت: ﴿وَيَكُونَ الدِّينُ لِلَّهِ﴾ على المنفي: ﴿لَا تَكُونَ فِتْنَةٌ﴾؟","answer":"جمع بين نفي المانع وإثبات المقصود؛ فتزول الفتنة والكفر، ويخلص الدين والعبادة لله وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص160، تحت «بلاغة عطف المثبت على النفي في قوله: «حتى لا تكون فتنة ويكون الدين لله»»","url":""}]},{"id":"s2-908","number":908,"surah":2,"verses":[193],"references":[{"surah":2,"verses":[193]}],"verseLabel":"البقرة: 193","question":"ما سرّ التعبير في قوله تعالى: ﴿وَيَكُونَ الدِّينُ لِلَّهِ﴾، دون أن يقال: «ويؤمنوا كلهم»؟","answer":"لأن المقصود أن يكون الدين، أي الإسلام والعبادة، خالصًا لله وحده؛ فاللام للاختصاص.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص160–161، تحت «دلالة لام التعريف ولام الجر، في قوله تعالى: ﴿الدين لله﴾»","url":""}]},{"id":"s2-909","number":909,"surah":2,"verses":[193],"references":[{"surah":2,"verses":[193]}],"verseLabel":"البقرة: 193","question":"ما سرّ التعبير في قوله تعالى: ﴿فَلَا عُدْوَانَ إِلَّا عَلَى الظَّالِمِينَ﴾، وسمّى العقوبة عدوانًا؟","answer":"سمّى جزاء الظالمين عدوانًا من باب المشاكلة ومقابلة اللفظ باللفظ؛ فهو في الحقيقة عقوبة عادلة لا ظلم فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص163، تحت «سر التعبير عن الجزاء بالعدوان، في قوله: «فلا عدوان إلا على الظالمين»»","url":""}]},{"id":"s2-910","number":910,"surah":2,"verses":[194],"references":[{"surah":2,"verses":[194]}],"verseLabel":"البقرة: 194","question":"ما دلالة تقييد الرد بقوله تعالى: ﴿بِمِثْلِ مَا اعْتَدَى عَلَيْكُمْ﴾؟","answer":"قيد الرد بالمثل لمنع تجاوز الحق تحت حرارة الانتقام؛ فالمأذون فيه دفع العدوان بقدره لا ابتداء ظلم جديد.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص173، تحت «معنى المماثلة في قوله تعالى: «بمثل ما اعتدى عليكم»»","url":""}]},{"id":"s2-911","number":911,"surah":2,"verses":[194],"references":[{"surah":2,"verses":[194]}],"verseLabel":"البقرة: 194","question":"ما سرّ التعبير في قوله تعالى: ﴿الشَّهْرُ الْحَرَامُ بِالشَّهْرِ الْحَرَامِ﴾ وكرر اللفظ نفسه؟","answer":"ليقرر المماثلة الدقيقة: انتهاكهم حرمة الشهر يقابل في الشهر الحرام بقدر الضرورة، فلا يحول احترامه دون ردهم إذا بدؤوا. والتكرار يجعل كفتي القصاص متطابقتين لفظًا ومعنى.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص167، تحت «الإيجاز بالحذف في قوله تعالى: «الشهر الحرام بالشهر الحرام»»","url":""}]},{"id":"s2-912","number":912,"surah":2,"verses":[194],"references":[{"surah":2,"verses":[194]}],"verseLabel":"البقرة: 194","question":"ما سرّ إفراد ﴿الشَّهْرُ الْحَرَامُ﴾ ثم جمع ﴿وَالْحُرُمَاتُ قِصَاصٌ﴾؟","answer":"ذكر الشهر الحرام أولًا لأنه سبب الواقعة المعينة، ثم عمم الحكم في جميع الحرمات: لكل حرمة قصاص إذا انتهكها المعتدي.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص169، تحت «نكتة عطف العام «والحرمات قصاص» على الخاص»","url":""}]},{"id":"s2-913","number":913,"surah":2,"verses":[194],"references":[{"surah":2,"verses":[194]}],"verseLabel":"البقرة: 194","question":"ما سرّ التعبير في قوله تعالى: ﴿وَالْحُرُمَاتُ قِصَاصٌ﴾، دون أن يقال: «تعظَّم الحرمات»؟","answer":"لأن المقام فيمن انتهك الحرمة متذرعًا بها، فبيّن أن صيانتها لا تعني ترك المعتدي، بل يقابل انتهاكه بمثله دون زيادة. لفظ القصاص يجمع الحماية والعدل في قاعدة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص170، تحت «بلاغة جمع «والحرمات»، والإخبار عنها بالمصدر «قصاص»»","url":""}]},{"id":"s2-914","number":914,"surah":2,"verses":[194],"references":[{"surah":2,"verses":[194]}],"verseLabel":"البقرة: 194","question":"ما سرّ التعبير في قوله تعالى: ﴿فَمَنِ اعْتَدَى عَلَيْكُمْ فَاعْتَدُوا عَلَيْهِ﴾، مع أن رد الاعتداء ليس اعتداءً مذمومًا؟","answer":"سمي الرد اعتداء من باب المشاكلة؛ لأنه في صورة فعل المعتدي ومقابل له، لكنه مقيد بالمثل، فليس عدوانًا مذمومًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص171، تحت «توجيه الأمر بالاعتداء في قوله تعالى: «فمن اعتدى عليكم فاعتدوا عليه بمثل ما اعتدى عليكم»»","url":""}]},{"id":"s2-915","number":915,"surah":2,"verses":[194],"references":[{"surah":2,"verses":[194]}],"verseLabel":"البقرة: 194","question":"ما مناسبة الأمر بالتقوى بعد الإذن برد الاعتداء؟","answer":"لأن الإذن بالرد مظنة مجاوزة الحد بدافع الغضب، فجاء الأمر بالتقوى حارسًا للمماثلة والعدل.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص174، تحت «أثر الأمر بالتقوى «واتقوا الله» بعد الأمر بمجازاة الاعتداء: «فاعتدوا عليه»»","url":""}]},{"id":"s2-916","number":916,"surah":2,"verses":[194],"references":[{"surah":2,"verses":[194]}],"verseLabel":"البقرة: 194","question":"ما سرّ التعبير في قوله تعالى: ﴿وَاعْلَمُوا أَنَّ اللَّهَ مَعَ الْمُتَّقِينَ﴾؟","answer":"المعية هنا معونة ونصرة وحفظ، وهي خاصة بالمتقين ما داموا على تقواهم؛ فيطمئنهم الوعد ويحثهم على ملازمة التقوى في أحوالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص175–176، تحت عنوان «المجاز بالإخبار بمعية الله تعالى: ﴿واعلموا أن الله مع المتقين﴾»","url":""}]},{"id":"s2-917","number":917,"surah":2,"verses":[194],"references":[{"surah":2,"verses":[194]}],"verseLabel":"البقرة: 194","question":"ما مناسبة ختم الآية بـ﴿الْمُتَّقِينَ﴾ دون «المنتصرين» أو «المقاتلين»؟","answer":"ختم بالمتقين لأن معية الله بالنصر والتأييد لمن يراقبه ويلتزم حدوده، ولا يتجاوز المثل عند الرد.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص174، تحت «أثر الأمر بالتقوى «واتقوا الله» بعد الأمر بمجازاة الاعتداء»","url":""}]},{"id":"s2-918","number":918,"surah":2,"verses":[195],"references":[{"surah":2,"verses":[195]}],"verseLabel":"البقرة: 195","question":"ما سرّ الجمع بين الأمر بالإنفاق والنهي عن إلقاء النفس في التهلكة؟","answer":"الإنفاق عدة الجهاد وسبب قوة الأمة؛ وتركه يفضي إلى ضعفها وهلاكها. لذلك اتصل الأمر به بالنهي عن التهلكة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص180، تحت «بلاغة الوصل في قوله: «ولا تلقوا بأيديكم إلى التهلكة»»","url":""}]},{"id":"s2-919","number":919,"surah":2,"verses":[195],"references":[{"surah":2,"verses":[195]}],"verseLabel":"البقرة: 195","question":"ما مناسبة الأمر بالإنفاق بعد آيات القتال؟","answer":"لأن القتال لا يقوم بلا إعداد وإنفاق، فجاء تمويله بعد بيان أحكامه وغاياته.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص177، تحت «لما سبق الأمر بالقتال، أعقبه بأهم ضامن لنجاحه ودعمه، وهو الإنفاق»","url":""}]},{"id":"s2-920","number":920,"surah":2,"verses":[195],"references":[{"surah":2,"verses":[195]}],"verseLabel":"البقرة: 195","question":"ما دلالة تقييد الإنفاق بقوله تعالى: ﴿فِي سَبِيلِ اللَّهِ﴾؟","answer":"قيد الإنفاق بسبيل الله ليكون في طريق دينه وما يقرب إليه، ويتقدم في هذا السياق الإنفاق في الجهاد وعدته.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص180، تحت «دلالة المجاز في قوله تعالى: «في سبيل الله»»","url":""}]},{"id":"s2-921","number":921,"surah":2,"verses":[195],"references":[{"surah":2,"verses":[195]}],"verseLabel":"البقرة: 195","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلَا تُلْقُوا بِأَيْدِيكُمْ إِلَى التَّهْلُكَةِ﴾، مع أن الإنسان يلقي نفسه لا يده فقط؟","answer":"ذكر الأيدي وأريدت الأنفس كلها من باب إطلاق الجزء وإرادة الكل، لأن اليد أبرز آلة للفعل؛ وقيل الباء للتعدية أو زائدة للتوكيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص181، تحت «بيان المجاز في قوله تعالى: «ولا تلقوا بأيديكم إلى التهلكة»»","url":""}]},{"id":"s2-922","number":922,"surah":2,"verses":[195],"references":[{"surah":2,"verses":[195]}],"verseLabel":"البقرة: 195","question":"ما المراد بالتهلكة في قوله تعالى: ﴿وَلَا تُلْقُوا بِأَيْدِيكُمْ إِلَى التَّهْلُكَةِ﴾؟","answer":"اللفظ عام في كل سبب يؤدي إلى الهلاك، ويدخل فيه ترك الإنفاق والجهاد حتى يسلط العدو، كما يدخل فيه الإقدام غير المنضبط على الضرر.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص182، تحت عنوان «وجوه التهلكة كثيرة؛ منها ما نجم عن إفراط، ومنها ما نتج عن تفريط»","url":""}]},{"id":"s2-923","number":923,"surah":2,"verses":[195],"references":[{"surah":2,"verses":[195]}],"verseLabel":"البقرة: 195","question":"ما مناسبة الأمر بالإحسان بعد النهي عن التهلكة؟","answer":"لما نهى عن أسباب التهلكة أمر بالإحسان، أي إتقان العمل والطاعة والإنفاق والقيام بها على وجهها، ليعم الإصلاح جميع الأحوال.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص183، تحت «وجه الأمر بالإحسان بعد النهي عن التهلكة»","url":""}]},{"id":"s2-924","number":924,"surah":2,"verses":[195],"references":[{"surah":2,"verses":[195]}],"verseLabel":"البقرة: 195","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿إِنَّ اللَّهَ يُحِبُّ الْمُحْسِنِينَ﴾؟","answer":"ختم بمحبة الله للمحسنين تعليلًا للأمر بالإحسان وترغيبًا في ملازمته؛ فمن أحبه الله داوم على الوصف الذي استوجب به هذه المحبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص185، تحت «دلالة إسناد المحبة إلى الله تعالى: «إن الله يحب المحسنين»»","url":""}]},{"id":"s2-925","number":925,"surah":2,"verses":[196],"references":[{"surah":2,"verses":[196]}],"verseLabel":"البقرة: 196","question":"ما سرّ التعبير في قوله تعالى: ﴿فإن أحصرتم﴾ بـ﴿إن﴾، ثم قال ﴿فإذا أمنتم﴾ بـ﴿إذا﴾؟","answer":"جاء الإحصار بـ﴿إن﴾ لأنه عارض غير محقق، وجاء الأمن بـ﴿إذا﴾ لأنه الأصل الغالب المتوقع بعد زوال العارض.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص197، تحت «بلاغة استعمال «إذا» دون «إن» في قوله تعالى: «فإذا أمنتم»»","url":""}]},{"id":"s2-926","number":926,"surah":2,"verses":[196],"references":[{"surah":2,"verses":[196]}],"verseLabel":"البقرة: 196","question":"ما سرّ التعبير في قوله تعالى: ﴿وَأَتِمُّوا الْحَجَّ وَالْعُمْرَةَ لِلَّهِ﴾، دون أن يقال: «حجوا واعتمروا»؟","answer":"ركز على إكمال العبادة بعد الدخول فيها وألا تقطع أو تفسد، لأن السياق سيفصل موانع الإتمام وجبرها. و﴿لله﴾ تصحح النية: إتمام المناسك تعبّد خالص لا عادة أو مفاخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص190، تحت «سر الأمر بالإتمام في قوله: «وأتموا الحج والعمرة لله»»","url":""}]},{"id":"s2-927","number":927,"surah":2,"verses":[196],"references":[{"surah":2,"verses":[196]}],"verseLabel":"البقرة: 196","question":"ما سرّ الجمع بين الحج والعمرة في أمر واحد؟","answer":"جمعهما في أمر واحد ليقرر وجوب إتمام كل واحد منهما بعد الشروع فيه، فلا يكون الإتمام خاصًا بالحج دون العمرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص190، تحت عنوان «سر الأمر بالإتمام في قوله: ﴿وأتموا الحج والعمرة لله﴾»","url":""}]},{"id":"s2-928","number":928,"surah":2,"verses":[196],"references":[{"surah":2,"verses":[196]}],"verseLabel":"البقرة: 196","question":"لماذا جاء الشرط بـ﴿إِنْ﴾ في قوله تعالى: ﴿فَإِنْ أُحْصِرْتُمْ﴾، دون «إذا»؟","answer":"لأن الإحصار أمر مكروه للمخاطبين، فأُلقي إليهم بصيغة ما لا يُجزم بوقوعه؛ وفي ذلك تنبيه إلى احتمال منعهم من العمرة ليستعدوا لما قد يقع.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص192، تحت «فائدة الشرط بـ(إن) دون غيرها»","url":""}]},{"id":"s2-929","number":929,"surah":2,"verses":[196],"references":[{"surah":2,"verses":[196]}],"verseLabel":"البقرة: 196","question":"ما سرّ التعبير في قوله تعالى: ﴿فَمَا اسْتَيْسَرَ مِنَ الْهَدْيِ﴾، ولم يحدد نوعًا واحدًا؟","answer":"راعى تفاوت القدرة، فأوجب ما تيسر من بهيمة الأنعام ضمن الحد الشرعي، لا ما يعجز عنه المحصر. والموصول يجعل اليسر جزءًا من صياغة التكليف نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص193، تحت «دلالة (من) ولام التعريف في قوله: «من الهدي»»","url":""}]},{"id":"s2-930","number":930,"surah":2,"verses":[196],"references":[{"surah":2,"verses":[196]}],"verseLabel":"البقرة: 196","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلَا تَحْلِقُوا رُءُوسَكُمْ حَتَّى يَبْلُغَ الْهَدْيُ مَحِلَّهُ﴾؟","answer":"منع الحلق حتى يبلغ الهدي موضع حلّه، فلا يقع التحلل قبله؛ وذكر الرؤوس وأريد شعرها من إطلاق الكل وإرادة الجزء وحذف المضاف.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص194، تحت «المجاز في قوله تعالى: «ولا تحلقوا رؤوسكم»»","url":""}]},{"id":"s2-931","number":931,"surah":2,"verses":[196],"references":[{"surah":2,"verses":[196]}],"verseLabel":"البقرة: 196","question":"ما سرّ التعبير في قوله تعالى: ﴿أَوْ بِهِ أَذًى مِنْ رَأْسِهِ﴾، دون أن يقال: «أو يؤذيه رأسه»؟","answer":"أضاف الأذى إلى الرأس بـ﴿من﴾ لبيان منشئه، وكنى بالأذى عما يستقبح التصريح به كالقمل ونحوه، مراعاة لأدب العبارة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص196، تحت «الكناية في قوله تعالى: «أو به أذى من رأسه»»","url":""}]},{"id":"s2-932","number":932,"surah":2,"verses":[196],"references":[{"surah":2,"verses":[196]}],"verseLabel":"البقرة: 196","question":"ما سرّ تنويع الفدية بين ﴿صِيَامٍ أَوْ صَدَقَةٍ أَوْ نُسُكٍ﴾؟","answer":"نوع الفدية بين صيام وصدقة ونسك، وعطفها بـ﴿أو﴾ لإفادة التخيير بينها، وقد بينت السنة مقادير كل نوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص196، تحت عنوان «الكناية في قوله تعالى: ﴿أو به أذى من رأسه﴾»","url":""}]},{"id":"s2-933","number":933,"surah":2,"verses":[196],"references":[{"surah":2,"verses":[196]}],"verseLabel":"البقرة: 196","question":"ما سرّ التعبير بقوله تعالى: ﴿فَإِذَا أَمِنْتُمْ﴾ بعد الإحصار، مع حذف متعلق الأمن؟","answer":"حذف متعلق الأمن ليعم الأمن من العدو والمرض وسائر أسباب الإحصار؛ فإذا زال المانع عاد الحاج إلى حكمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص197، تحت «دلالة الحذف في قوله تعالى: «فإذا أمنتم»»","url":""}]},{"id":"s2-934","number":934,"surah":2,"verses":[196],"references":[{"surah":2,"verses":[196]}],"verseLabel":"البقرة: 196","question":"ما سرّ تسمية الجمع بين العمرة والحج تمتعًا؟","answer":"لأنه ينتفع بإسقاط أحد السفرين، ويتمتع بما كان ممنوعًا عليه بالإحرام بين العمرة والحج.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص198، تحت «لطيفة في تسمية الجمع بين الحج والعمرة تمتعا»","url":""}]},{"id":"s2-935","number":935,"surah":2,"verses":[196],"references":[{"surah":2,"verses":[196]}],"verseLabel":"البقرة: 196","question":"ما سرّ التعبير في قوله تعالى: ﴿فَمَنْ لَمْ يَجِدْ﴾ دون أن يذكر ما لم يجده؟","answer":"دل الهدي السابق عليه، فحذف اختصارًا؛ ويشمل عدم وجود الهدي أو ثمنه والقدرة عليه. فانتقل من البدل المالي إلى الصوم من غير تكرار يثقل الآية الطويلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص200، تحت «دلالة حذف المفعول في قوله تعالى: «فمن لم يجد»»","url":""}]},{"id":"s2-936","number":936,"surah":2,"verses":[196],"references":[{"surah":2,"verses":[196]}],"verseLabel":"البقرة: 196","question":"ما وجه الالتفات إلى الخطاب في قوله تعالى: ﴿وَسَبْعَةٍ إِذَا رَجَعْتُمْ﴾ بعد ﴿فَمَنْ لَمْ يَجِدْ﴾؟","answer":"عاد الكلام من الغيبة إلى أصل خطاب المكلفين في ﴿وأتموا﴾ و﴿أحصرتم﴾ و﴿أمنتم﴾؛ إذ كانت الغيبة لذكر أحكام عارضة، ثم رجع النظم إلى الخطاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص200، تحت «بلاغة الالتفات في قوله تعالى: ﴿رجعتم﴾»","url":""}]},{"id":"s2-937","number":937,"surah":2,"verses":[196],"references":[{"surah":2,"verses":[196]}],"verseLabel":"البقرة: 196","question":"ما فائدة قوله: ﴿تِلْكَ عَشَرَةٌ كَامِلَةٌ﴾ بعد ذكر ثلاثة وسبعة؟","answer":"جمعت الجملة العدد بعد تفصيله لتدفع توهم التخيير بين الثلاثة والسبعة، وتؤكد أن المطلوب مجموعهما، ووصف ﴿كاملة﴾ يحث على استيفاء الأيام كلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص201، تحت «سر الإطناب بذكر فذلكة الحساب: «تلك عشرة كاملة»»","url":""}]},{"id":"s2-938","number":938,"surah":2,"verses":[196],"references":[{"surah":2,"verses":[196]}],"verseLabel":"البقرة: 196","question":"ما سرّ تخصيص حكم التمتع بمن لم يكن أهله حاضري المسجد الحرام؟","answer":"قيد حكم التمتع بغير حاضري المسجد الحرام، وعبّر بالأهل لأن العبرة بموطن السكن والاستقرار لا بوجود الشخص العابر في مكة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص204، تحت «علة التعبير بحضور الأهل لا سكن الحاج في قوله: «حاضري المسجد الحرام»»","url":""}]},{"id":"s2-939","number":939,"surah":2,"verses":[196],"references":[{"surah":2,"verses":[196]}],"verseLabel":"البقرة: 196","question":"ما مناسبة ختم تفصيلات الحج بقوله تعالى: ﴿وَاتَّقُوا اللَّهَ وَاعْلَمُوا أَنَّ اللَّهَ شَدِيدُ الْعِقَابِ﴾؟","answer":"ختم التفصيل بالأمر بالتقوى لتجمع امتثال الأحكام ظاهرًا وباطنًا وتحذر من التهاون بها، وأتبعه بالعلم بشدة العقاب ليقوى الزجر عن مخالفتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص206، تحت «نكتة تأكيد الخبر في قوله تعالى: «واعلموا أن الله شديد العقاب»»","url":""}]},{"id":"s2-940","number":940,"surah":2,"verses":[197],"references":[{"surah":2,"verses":[197]}],"verseLabel":"البقرة: 197","question":"ما سرّ التعبير في قوله تعالى: ﴿الحج أشهر معلومات﴾، دون أن يقال: حج البيت في أشهر معلومات؟","answer":"حذف المضاف والظرف ليجعل الصلة شديدة، كأن الحج نفسه هو هذه الأشهر؛ فيبرز أن الإحرام والمناسك مقيدة بزمن معلوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص211، تحت «نكات الإخبار بالأشهر عن الحج»","url":""}]},{"id":"s2-941","number":941,"surah":2,"verses":[197],"references":[{"surah":2,"verses":[197]}],"verseLabel":"البقرة: 197","question":"ما سرّ ترتيب الرفث والفسوق والجدال؟","answer":"جمع أصول ما يعكر النسك: الرفث المتصل بالشهوة، والفسوق الخارج عن الطاعة، والجدال المفضي إلى الخصومة؛ وكرر ﴿لا﴾ لاستقلال نفي كل واحد منها وتوكيده.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص216، تحت «براعة الترقي في ذكر المنهيات»","url":""}]},{"id":"s2-942","number":942,"surah":2,"verses":[197],"references":[{"surah":2,"verses":[197]}],"verseLabel":"البقرة: 197","question":"ما سرّ التعبير في قوله تعالى: ﴿الْحَجُّ أَشْهُرٌ مَعْلُومَاتٌ﴾، مع أن أعمال الحج الكبرى في أيام؟","answer":"أطلق الحج على زمنه مبالغة، أو التقدير: وقت الحج أشهر معلومات؛ والمراد بيان الزمن الذي يصح فيه الإحرام، وإن وقعت الأعمال الكبرى في أيام معلومة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص212، تحت «دلالة المجاز العقلي في إسناد الأشهر إلى الحج»","url":""}]},{"id":"s2-943","number":943,"surah":2,"verses":[197],"references":[{"surah":2,"verses":[197]}],"verseLabel":"البقرة: 197","question":"ما دلالة وصف أشهر الحج بأنها ﴿مَعْلُومَاتٌ﴾؟","answer":"لأنها مستقرة معروفة عند العرب من شريعة إبراهيم، فلا تحتاج إلى تعداد في هذا المقام؛ وفي الوصف حجة على من يعبث بتوقيتها. ما كان معلومًا يُبنى عليه الحكم مباشرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص212، تحت «نكات تقييد المسند بالصفة «معلومات»»","url":""}]},{"id":"s2-944","number":944,"surah":2,"verses":[197],"references":[{"surah":2,"verses":[197]}],"verseLabel":"البقرة: 197","question":"ما معنى فرض الإنسان الحج في قوله تعالى: ﴿فَمَنْ فَرَضَ فِيهِنَّ الْحَجَّ﴾؟","answer":"فرض الحج أي أوجبه على نفسه بالدخول في الإحرام والنية؛ فإذا أحرم لزمته أحكام النسك ومحظوراته.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص213، تحت «دلالة التقييد بالشرط في قوله: «فمن فرض فيهن الحج»»","url":""}]},{"id":"s2-945","number":945,"surah":2,"verses":[197],"references":[{"surah":2,"verses":[197]}],"verseLabel":"البقرة: 197","question":"ما سرّ التعبير في قوله تعالى: ﴿فَلَا رَفَثَ وَلَا فُسُوقَ وَلَا جِدَالَ فِي الْحَجِّ﴾؟","answer":"جاء النفي بـ﴿لا﴾ مكررًا لنفي كل واحد من الرفث والفسوق والجدال استقلالًا، وتشديد تنزيه الحج عنها.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص218، تحت «إيثار التعبير بنفي المصدر دون نفي الفعل»","url":""}]},{"id":"s2-946","number":946,"surah":2,"verses":[197],"references":[{"surah":2,"verses":[197]}],"verseLabel":"البقرة: 197","question":"ما سرّ التعبير في قوله تعالى: ﴿فِي الْحَجِّ﴾ بعد المنهيات، وهي ممنوعة في غيره أيضًا؟","answer":"لأن قبحها يشتد في العبادة والزمان والمكان الشريف، ولأن الحج موطن ازدحام ومشقة تتعرض فيه النفوس للجدال. القيد ليس لإباحتها خارجه، بل لتغليظ اجتنابها داخله.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص213، تحت «نكتة تقديم الجار والمجرور «فيهن» من قوله: «فمن فرض فيهن الحج»»","url":""}]},{"id":"s2-947","number":947,"surah":2,"verses":[197],"references":[{"surah":2,"verses":[197]}],"verseLabel":"البقرة: 197","question":"ما سرّ التعبير في قوله تعالى: ﴿وَمَا تَفْعَلُوا مِنْ خَيْرٍ يَعْلَمْهُ اللَّهُ﴾ بعد النهي؟","answer":"لم يترك الحاج في فراغ سلبي بعد الكف عن الرفث والفسوق والجدال، بل فتح له كل أبواب الخير. وعلم الله هنا وعد بالحفظ والجزاء، وحذف التفصيل ليعم صغير العمل وكبيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص222، تحت «بلاغة الكناية عن المجازاة بقوله: «يعلمه الله»»","url":""}]},{"id":"s2-948","number":948,"surah":2,"verses":[197],"references":[{"surah":2,"verses":[197]}],"verseLabel":"البقرة: 197","question":"ما سرّ التعبير في قوله تعالى: ﴿وَتَزَوَّدُوا فَإِنَّ خَيْرَ الزَّادِ التَّقْوَى﴾؟","answer":"أمرهم بالزاد الحسي الذي يحفظهم في السفر، ثم نبه إلى الزاد الباقي وهو التقوى؛ فكما لا يستغني المسافر عن طعامه لا يستغني السائر إلى الله عن التقوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص224، تحت «بلاغة الاستعارة في قوله: «فإن خير الزاد التقوى»»","url":""}]},{"id":"s2-949","number":949,"surah":2,"verses":[197],"references":[{"surah":2,"verses":[197]}],"verseLabel":"البقرة: 197","question":"ما مناسبة تخصيص النداء بقوله تعالى: ﴿وَاتَّقُونِ يَا أُولِي الْأَلْبَابِ﴾؟","answer":"لأن أصحاب العقول الخالصة يدركون أن المظاهر والمناسك لا تنفع بلا تقوى، وأن المسافر الحقيقي يحتاج إلى زاد الآخرة. وحذف ياء المتكلم في ﴿اتقون﴾ يوافق خفة الفاصلة مع بقاء قرب الخطاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص225، تحت «نكتة التخصيص بعد التعميم»","url":""}]},{"id":"s2-950","number":950,"surah":2,"verses":[198],"references":[{"surah":2,"verses":[198]}],"verseLabel":"البقرة: 198","question":"ما سرّ الكناية عن التجارة بقوله تعالى: ﴿تَبْتَغُوا فَضْلًا مِنْ رَبِّكُمْ﴾؟","answer":"كنى عن التجارة بابتغاء فضل الله ليبين أن مكاسبها رزق من عطائه، وأن المباح منها لا حرج فيه ما لم يشغل عن ذكر الله والنسك.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص230، تحت «نكتة اختيار لفظ «تبتغوا» وتخصيصه بالمفعول «فضلا»»","url":""}]},{"id":"s2-951","number":951,"surah":2,"verses":[198],"references":[{"surah":2,"verses":[198]}],"verseLabel":"البقرة: 198","question":"ما سرّ نفي الجناح عن ابتغاء فضل الله في الحج، والتعبير بذلك بدل الأمر بالتجارة؟","answer":"نفي الجناح يرفع حرجًا كان عندهم من التجارة في الحج، والتعبير بابتغاء فضل الله يبيح الكسب مع ربطه بالمنعم، من غير أن يجعل التجارة مقصد الحج.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص229، تحت «نكتة النفي بـ(ليس) في قوله: «ليس عليكم جناح»»","url":""}]},{"id":"s2-952","number":952,"surah":2,"verses":[198],"references":[{"surah":2,"verses":[198]}],"verseLabel":"البقرة: 198","question":"ما دلالة إضافة الفضل إلى الرب في قوله تعالى: ﴿فَضْلًا مِنْ رَبِّكُمْ﴾؟","answer":"إضافة الفضل إلى الرب تستحضر الرعاية والتربية والرزق، وتمنع أن ينسب الحاج كسبه إلى أسباب التجارة وحدها.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص230–231، تحت «نكتة اختيار لفظ ﴿تبتغوا﴾ وتخصيصه بالمفعول ﴿فضلًا﴾»","url":""}]},{"id":"s2-953","number":953,"surah":2,"verses":[198],"references":[{"surah":2,"verses":[198]}],"verseLabel":"البقرة: 198","question":"ما سرّ التعبير في قوله تعالى: ﴿فَإِذَا أَفَضْتُمْ مِنْ عَرَفَاتٍ﴾، دون أن يقال: «خرجتم»؟","answer":"الإفاضة اندفاع الجماعة الكثيرة كفيض الماء؛ فصورت حركة الحجيج من عرفات مجتمعين في سيل بشري.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص232، تحت «بلاغة الاستعارة في قوله: «أفضتم من عرفات»»","url":""}]},{"id":"s2-954","number":954,"surah":2,"verses":[198],"references":[{"surah":2,"verses":[198]}],"verseLabel":"البقرة: 198","question":"ما سرّ التعبير في قوله تعالى: ﴿مِنْ عَرَفَاتٍ﴾ بصيغة الجمع؟","answer":"﴿عرفات﴾ علم للمكان جاء بصيغة الجمع، ويجوز أن يلحظ تعدد بقاعه ومواقفه، مع بقاء المراد الموضع المعروف.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص233، تحت «سر إيثار لفظ «عرفات» جمعًا»","url":""}]},{"id":"s2-955","number":955,"surah":2,"verses":[198],"references":[{"surah":2,"verses":[198]}],"verseLabel":"البقرة: 198","question":"ما مناسبة الأمر بالذكر عند المشعر الحرام؟","answer":"أمر بالذكر عند المشعر الحرام تعظيمًا للذكر في ذلك الموضع والزمان الشريفين، وشكرًا لله على الهداية، ثم بين كيفية الذكر بقوله ﴿كما هداكم﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص234، تحت «نكتة تكرار الأمر بذكر الله تعالى»","url":""}]},{"id":"s2-956","number":956,"surah":2,"verses":[198],"references":[{"surah":2,"verses":[198]}],"verseLabel":"البقرة: 198","question":"ما سرّ تكرار الأمر بالذكر في قوله: ﴿وَاذْكُرُوهُ كَمَا هَدَاكُمْ﴾ بعد ﴿فَاذْكُرُوا اللَّهَ﴾؟","answer":"الأمر الأول أصل الذكر عند المشعر، والثاني يحدد صفته وسببه: اذكروه ذكرًا يليق بهدايته لكم بعد الضلال.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص236، تحت «دلالة الكاف في قوله: «كما هداكم» بين التشبيه والتعليل»","url":""}]},{"id":"s2-957","number":957,"surah":2,"verses":[198],"references":[{"surah":2,"verses":[198]}],"verseLabel":"البقرة: 198","question":"ما سرّ التعبير في قوله تعالى: ﴿وَإِنْ كُنْتُمْ مِنْ قَبْلِهِ لَمِنَ الضَّالِّينَ﴾؟","answer":"ذكّرهم بحالهم قبل القرآن أو قبل الهدى حتى يعرفوا مقدار النعمة التي تستوجب الذكر؛ فالهداية تظهر قيمتها بمقابلة الضلال السابق. وتوالي ﴿إن﴾ واللام و﴿من﴾ يقوي تقرير حال لا ينبغي نسيانها.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص238، تحت «سبب إيثار حذف متعلق «الضالين»»","url":""}]},{"id":"s2-958","number":958,"surah":2,"verses":[199],"references":[{"surah":2,"verses":[199]}],"verseLabel":"البقرة: 199","question":"ما سرّ الأمر بالإفاضة من حيث أفاض الناس؟","answer":"أمر قريشًا ومن كان يقف بالمزدلفة ترفعًا أن يقفوا بعرفات ويفيضوا مع الناس؛ فالدين يسوي بينهم ويبطل امتياز الجاهلية.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص240، تحت «دلالة حرف العطف (ثم) في قوله: «ثم أفيضوا من حيث أفاض الناس»»","url":""}]},{"id":"s2-959","number":959,"surah":2,"verses":[199],"references":[{"surah":2,"verses":[199]}],"verseLabel":"البقرة: 199","question":"ما سرّ التعبير في قوله تعالى: ﴿ثُمَّ أَفِيضُوا مِنْ حَيْثُ أَفَاضَ النَّاسُ﴾ بعد ذكر الإفاضة من عرفات؟","answer":"الأمر بالإفاضة من حيث أفاض الناس تصحيح لموقف من كان لا يقف بعرفات، و﴿ثم﴾ للانتقال في الرتبة أو لترتيب الذكر، لا يلزم منها أن الإفاضة الثانية بعد الأولى زمنًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص240، تحت «دلالة حرف العطف «ثم» في قوله: «ثم أفيضوا من حيث أفاض الناس»»","url":""}]},{"id":"s2-960","number":960,"surah":2,"verses":[199],"references":[{"surah":2,"verses":[199]}],"verseLabel":"البقرة: 199","question":"ما سرّ التعبير في قوله تعالى: ﴿مِنْ حَيْثُ أَفَاضَ النَّاسُ﴾، ولم يسمِّ عرفات؟","answer":"ليكون موضع إفاضتهم وطريقتها مثل سائر الحجيج، فيجتمعوا معهم ولا يختص أحد بطريقة يختارها لنفسه؛ فالمقصود الإفاضة من مكان إفاضة الناس ومصاحبتهم فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص240، تحت «دلالة حرف الجر (من) في قوله تعالى: ﴿من حيث أفاض الناس﴾»","url":""}]},{"id":"s2-961","number":961,"surah":2,"verses":[199],"references":[{"surah":2,"verses":[199]}],"verseLabel":"البقرة: 199","question":"ما مناسبة إتباع الإفاضة بالأمر بالاستغفار؟","answer":"أتبع الإفاضة بالاستغفار لجبر ما يقع في العبادة من تقصير، وطلب مغفرة ما سبق من مخالفة الموقف وعادة الجاهلية.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص240، تحت «بلاغة الاكتفاء في قوله: «واستغفروا الله»»","url":""}]},{"id":"s2-962","number":962,"surah":2,"verses":[199],"references":[{"surah":2,"verses":[199]}],"verseLabel":"البقرة: 199","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿إِنَّ اللَّهَ غَفُورٌ رَحِيمٌ﴾؟","answer":"وعد بالغفران لما يستغفرون منه، والرحمة بقبولهم وإصلاح مناسكهم بعد الخطأ. وجاءت الصيغتان الدالتان على الثبات لتفتحا باب الرجوع عقب الأمر المباشر بالاستغفار.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص241، تحت «دلالة التأكيد في قوله: «إن الله غفور رحيم»»","url":""}]},{"id":"s2-963","number":963,"surah":2,"verses":[200],"references":[{"surah":2,"verses":[200]}],"verseLabel":"البقرة: 200","question":"ما سرّ التعبير في قوله تعالى: ﴿فاذكروا الله كذكركم آباءكم أو أشد ذكرًا﴾؟","answer":"كان العرب يذكرون مفاخر آبائهم بعد الحج، فأمروا أن يستبدلوا بذلك ذكر الله، أو يزيدوا عليه في القوة؛ لأنه صاحب النعم والهداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص246، تحت «غرض التشبيه في قوله: «فاذكروا الله كذكركم آباءكم»»","url":""}]},{"id":"s2-964","number":964,"surah":2,"verses":[200,201],"references":[{"surah":2,"verses":[200,201]}],"verseLabel":"البقرة: 200–201","question":"ما سرّ المقابلة بين دعاء طالب الدنيا وحدها ودعاء طالب حسنتي الدنيا والآخرة؟","answer":"الأول حصر همّه في الدنيا فحرم نصيب الآخرة، والثاني جمع خير الدارين وطلب الوقاية من النار؛ فالمقابلة تعلم شمول الدعاء واتزان المقصد.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص248، تحت «دلالة أسلوب التقسيم في قوله: «فمن الناس من يقول»»","url":""}]},{"id":"s2-965","number":965,"surah":2,"verses":[200],"references":[{"surah":2,"verses":[200]}],"verseLabel":"البقرة: 200","question":"ما سرّ التعبير في قوله تعالى: ﴿فَإِذَا قَضَيْتُمْ مَنَاسِكَكُمْ فَاذْكُرُوا اللَّهَ﴾؟","answer":"انتهاء أعمال الحج لا يعني انتهاء الصلة بالله؛ بل ينتقل الحاج من حركة المناسك إلى دوام الذكر. والفاء تجعل الذكر أول ما يعقب الفراغ حتى لا تملأ المفاخرة واللغو المساحة التي تركتها العبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص246، تحت «دلالة الفاء في قوله: «فاذكروا الله»»","url":""}]},{"id":"s2-966","number":966,"surah":2,"verses":[200],"references":[{"surah":2,"verses":[200]}],"verseLabel":"البقرة: 200","question":"ما سرّ التعبير في قوله تعالى: ﴿أَوْ أَشَدَّ ذِكْرًا﴾ بـ﴿أو﴾، أفي الأمر شك؟","answer":"﴿أو﴾ للإباحة أو بمعنى بل الانتقالية؛ أي اذكروا الله كذكركم آباءكم، بل أشد ذكرًا، وليس في الأمر شك.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص247، تحت «دلالة (أو) في قوله تعالى: «فاذكروا الله كذكركم آباءكم أو أشد ذكرا»»","url":""}]},{"id":"s2-967","number":967,"surah":2,"verses":[200],"references":[{"surah":2,"verses":[200]}],"verseLabel":"البقرة: 200","question":"ما سرّ الانتقال من الخطاب إلى الغيبة في قوله تعالى: ﴿فَمِنَ النَّاسِ مَنْ يَقُولُ﴾؟","answer":"انتقل إلى الغيبة للتقسيم والحكم على أصناف الناس بعد خطاب الحجيج، وليعرض النموذجين للنظر والاعتبار.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص248، تحت «براعة الالتفات في قوله: «فمن الناس»»","url":""}]},{"id":"s2-968","number":968,"surah":2,"verses":[200],"references":[{"surah":2,"verses":[200]}],"verseLabel":"البقرة: 200","question":"ما دلالة حذف مفعول ﴿آتنا﴾ في قولهم: ﴿رَبَّنَا آتِنَا فِي الدُّنْيَا﴾؟","answer":"حذف المفعول لأن همهم مطلق عطاء الدنيا أيًا كان، من غير تعيين خير صالح ولا طلب للآخرة؛ ففضح الحذف ضيق مقصدهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص250، تحت «نكتة حذف المفعول الثاني من قوله: «ربنا آتنا في الدنيا»»","url":""}]},{"id":"s2-969","number":969,"surah":2,"verses":[200],"references":[{"surah":2,"verses":[200]}],"verseLabel":"البقرة: 200","question":"ما مناسبة ختم وصفهم بقوله تعالى: ﴿وَمَا لَهُ فِي الْآخِرَةِ مِنْ خَلَاقٍ﴾؟","answer":"ينفي التعبير عنهم أي نصيب من خير الآخرة ولو كان قليلًا؛ لأنهم آثروا الدنيا عليها. فجاء الختم تشنيعًا على من يقصر طلبه على الدنيا ويعرض عن الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص251، تحت عنوان «دلالة تنكير ﴿خلاق﴾ من قوله: ﴿وما له في الآخرة من خلاق﴾»","url":""}]},{"id":"s2-970","number":970,"surah":2,"verses":[201],"references":[{"surah":2,"verses":[201]}],"verseLabel":"البقرة: 201","question":"ما سرّ التعبير في قوله تعالى عن الفريق الثاني: ﴿وَمِنْهُمْ مَنْ يَقُولُ﴾، ولم يكرر ﴿ومن الناس﴾؟","answer":"الضمير يعيده إلى الناس المذكورين قبلها، ويجعل الفريقين داخل جماعة واحدة مع اختلاف الهمة والطلب؛ فبعد صاحب الدنيا وحدها يظهر صاحب الدعاء المتوازن. والإيجاز يقوي المقابلة ولا يقطعها بإعادة الاسم.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص248، تحت «دلالة أسلوب التقسيم في قوله: «فمن الناس من يقول»، الآية»","url":""}]},{"id":"s2-971","number":971,"surah":2,"verses":[201],"references":[{"surah":2,"verses":[201]}],"verseLabel":"البقرة: 201","question":"ما سرّ التعبير في قوله تعالى: ﴿فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً﴾، وكرر لفظ ﴿حسنة﴾؟","answer":"كررت ﴿حسنة﴾ لأن حسنة الدنيا غير حسنة الآخرة في حقيقتها ومجالها؛ فطلبوا لكل دار ما يلائمها من الخير.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص252، تحت «نكتة تكرير لفظ «حسنة» في قوله: «ربنا آتنا في الدنيا حسنة وفي الآخرة حسنة»»","url":""}]},{"id":"s2-972","number":972,"surah":2,"verses":[201],"references":[{"surah":2,"verses":[201]}],"verseLabel":"البقرة: 201","question":"ما دلالة تنكير ﴿حَسَنَةً﴾ في الدنيا والآخرة؟","answer":"نكر ﴿حسنة﴾ لتعم كل خير في الدنيا وكل خير في الآخرة، ولتفيد تعظيم المطلوب في الدارين.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص251، تحت «سر تنكير «حسنة» من قول الله تعالى: «ربنا آتنا في الدنيا حسنة وفي الآخرة حسنة»»","url":""}]},{"id":"s2-974","number":974,"surah":2,"verses":[201],"references":[{"surah":2,"verses":[201]}],"verseLabel":"البقرة: 201","question":"ما فائدة قوله تعالى: ﴿وَقِنَا عَذَابَ النَّارِ﴾ بعد طلب حسنة الآخرة؟","answer":"طلب حسنة الآخرة يشمل الخير، ثم صرح بالوقاية من النار لعظمها، وليجمع الدعاء بين تحصيل النفع ودفع الضر.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص253، تحت «بلاغة الاحتراس في قوله: «وقنا عذاب النار»»","url":""}]},{"id":"s2-975","number":975,"surah":2,"verses":[202],"references":[{"surah":2,"verses":[202]}],"verseLabel":"البقرة: 202","question":"ما دلالة الإشارة إليهم بقوله تعالى: ﴿أُولَئِكَ لَهُمْ نَصِيبٌ﴾؟","answer":"اسم الإشارة للبعد يرفع منزلتهم ويربط الجزاء بصفات الدعاء الجامع والعمل السابق؛ أولئك المتميزون لهم نصيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص256، تحت «نكتة تعريف المسند إليه باسم الإشارة»","url":""}]},{"id":"s2-976","number":976,"surah":2,"verses":[202],"references":[{"surah":2,"verses":[202]}],"verseLabel":"البقرة: 202","question":"ما دلالة تنكير ﴿نَصِيبٌ﴾ في قوله تعالى: ﴿أُولَئِكَ لَهُمْ نَصِيبٌ مِمَّا كَسَبُوا﴾؟","answer":"يفيد تعظيم النصيب الذي ينالونه، ويحتمل التنويع أيضًا؛ فلكل منهم نصيب يختلف عن نصيب الآخر. ولا مانع من اجتماع دلالتي التعظيم والتنويع.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص257، تحت «دلالة تنكير ﴿نصيب﴾ من قول الله تعالى: ﴿أولئك لهم نصيب مما كسبوا﴾»","url":""}]},{"id":"s2-977","number":977,"surah":2,"verses":[202],"references":[{"surah":2,"verses":[202]}],"verseLabel":"البقرة: 202","question":"ما سرّ التعبير في قوله تعالى: ﴿مِمَّا كَسَبُوا﴾ بعد أن حكى دعاءهم؟","answer":"قال ﴿مما كسبوا﴾ ليبين أن لهم نصيبًا بسبب ما قدموه من العبادة والذكر والدعاء والعمل الصالح، لا بمجرد ألفاظ الدعاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص259، تحت «دلالة «ما» في «مما كسبوا»»","url":""}]},{"id":"s2-978","number":978,"surah":2,"verses":[202],"references":[{"surah":2,"verses":[202]}],"verseLabel":"البقرة: 202","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿وَاللَّهُ سَرِيعُ الْحِسَابِ﴾؟","answer":"ختم بسرعة الحساب ليبين أن الله يحصي أعمال العباد ويجازيهم عليها سريعًا، فيرغب أهل الطاعة في ثوابهم ويحذرهم من الإخلال بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص260، تحت «دلالة قوله: «والله سريع الحساب» بين الحقيقة والمجاز»","url":""}]},{"id":"s2-979","number":979,"surah":2,"verses":[203],"references":[{"surah":2,"verses":[203]}],"verseLabel":"البقرة: 203","question":"ما سرّ وصف أيام منى بأنها ﴿أَيَّامٍ مَعْدُودَاتٍ﴾؟","answer":"وصفها بالمعدودات لقلة أيامها وسرعة انقضائها، حثًا للحاج على اغتنامها بالذكر قبل فواتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص265، تحت «سر تسمية الأيام بالمعدودات»","url":""}]},{"id":"s2-980","number":980,"surah":2,"verses":[203],"references":[{"surah":2,"verses":[203]}],"verseLabel":"البقرة: 203","question":"ما سرّ التعبير في قوله تعالى في أحد الفريقين ﴿فمن تعجل﴾، وفي الآخر ﴿ومن تأخر﴾ لا: تأنى؟","answer":"التعجل والتأخر متقابلان في وقت الانصراف المحدد، أما التأني فصفة في طريقة الفعل لا يلزم منها البقاء إلى اليوم التالي.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص269، تحت «دلالة قوله تعالى «ومن تأخر» معنى وصيغة»","url":""}]},{"id":"s2-981","number":981,"surah":2,"verses":[203],"references":[{"surah":2,"verses":[203]}],"verseLabel":"البقرة: 203","question":"ما المقصود بـ﴿أَيَّامٍ مَعْدُودَاتٍ﴾ في آية الحج؟","answer":"هي أيام التشريق الثلاثة التي يذكر الحجاج الله فيها عند رمي الجمار، ووصفها بالمعدودات يبين قلة عددها وتعينها.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص265، تحت «الفرق في وصف الأيام بالمعدودات والمعلومات»","url":""}]},{"id":"s2-982","number":982,"surah":2,"verses":[203],"references":[{"surah":2,"verses":[203]}],"verseLabel":"البقرة: 203","question":"ما سرّ التعبير في قوله تعالى: ﴿فَمَنْ تَعَجَّلَ فِي يَوْمَيْنِ﴾، دون أن يقال: «بعد يومين»؟","answer":"لأن المتعجل ينفر في أثناء اليوم الثاني من أيام التشريق وبعد أداء ذكره ورميه، فـ﴿في﴾ أدق في تصوير الزمن الذي يقع فيه الخروج. ولم يجعل اليومين مجرد مدة تنتهي ثم يبدأ الفعل خارجها.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص268، تحت «تغليب الأوقات في قوله تعالى: «في يومين»»","url":""}]},{"id":"s2-983","number":983,"surah":2,"verses":[203],"references":[{"surah":2,"verses":[203]}],"verseLabel":"البقرة: 203","question":"ما سرّ تكرار ﴿فَلَا إِثْمَ عَلَيْهِ﴾ للمتعجل والمتأخر؟","answer":"كرر نفي الإثم ليرفع الحرج عن المتعجل والمتأخر معًا، ويدفع ما كان من تأثيم بعض أهل الجاهلية لأحدهما، ويصرح بالتوسعة والتخيير بينهما، وإن كان التأخر أفضل عند جمهور الفقهاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص269، تحت «سر إيراد قوله تعالى «فلا إثم عليه» بعد ذكر المتأخر»","url":""}]},{"id":"s2-984","number":984,"surah":2,"verses":[203],"references":[{"surah":2,"verses":[203]}],"verseLabel":"البقرة: 203","question":"لماذا لم يُقيّد التأخر بمدة في قوله تعالى ﴿ومن تأخر﴾؟","answer":"لأن نهاية التأخر معروفة باليوم الثالث من أيام التشريق؛ فالمتأخر يبقى بمنى لرمي جمار ذلك اليوم، وبه تنتهي مناسك منى، فلم يحتج إلى تقييد آخر للمدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص269، تحت عنوان «دلالة قوله تعالى: ﴿ومن تأخر﴾ معنى وصيغة»","url":""}]},{"id":"s2-985","number":985,"surah":2,"verses":[203],"references":[{"surah":2,"verses":[203]}],"verseLabel":"البقرة: 203","question":"ما دلالة قوله تعالى: ﴿لِمَنِ اتَّقَى﴾ بعد إباحة الخيارين؟","answer":"أي إن انتفاء الإثم وكمال الانتفاع بالنسك لمن اتقى المحظورات وأخلص؛ فليست الإباحة منفصلة عن التقوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص270، تحت «فائدة حذف المبتدأ في قوله تعالى: «لمن اتقى»»","url":""}]},{"id":"s2-986","number":986,"surah":2,"verses":[203],"references":[{"surah":2,"verses":[203]}],"verseLabel":"البقرة: 203","question":"ما سرّ تكرار الأمر بالتقوى بعد قوله تعالى: ﴿لِمَنِ اتَّقَى﴾؟","answer":"كرر التقوى لأن الأولى قيد للخيارين، والثانية أمر عام يجمع أعمال الحج وما بعده، فانتقل من الحكم الجزئي إلى الأصل الجامع.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص271، تحت «دلالة فعل الأمر بالتقوى في قوله تعالى: «واتقوا الله»»","url":""}]},{"id":"s2-987","number":987,"surah":2,"verses":[203],"references":[{"surah":2,"verses":[203]}],"verseLabel":"البقرة: 203","question":"ما مناسبة ختم الآية بالحشر، ودلالة تقديم ﴿إليه﴾ في قوله: ﴿وَاعْلَمُوا أَنَّكُمْ إِلَيْهِ تُحْشَرُونَ﴾؟","answer":"ذكر الحشر ليصل أعمال الحج بالحساب، وقدم ﴿إليه﴾ للقصر: إلى الله وحده تجمعون، فيحمل العلم بذلك على التقوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص273، تحت «بلاغة تذييل آيات الحج بقوله تعالى: «واتقوا الله واعلموا أنكم إليه تحشرون»»","url":""}]},{"id":"s2-988","number":988,"surah":2,"verses":[204],"references":[{"surah":2,"verses":[204]},{"surah":63,"verses":[4]}],"verseLabel":"البقرة: 204، المنافقون: 4","question":"لماذا أُسند الإعجاب إلى أجسام المنافقين في سورة المنافقون، وإلى القول في البقرة: ﴿وَمِنَ النَّاسِ مَنْ يُعْجِبُكَ قَوْلُهُ﴾؟","answer":"سياق المنافقون يصف أشخاصًا عُرفوا بحسن أجسامهم وهيئاتهم؛ أما البقرة ففيها تحذير عام من تزيين المنافقين أقوالهم وفصاحة بيانهم الكاذب، مع مخالفة أفعالهم لأقوالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص798، تحت «سر إسناد الإعجاب إلى الأجسام دون الأقوال»","url":""}]},{"id":"s2-989","number":989,"surah":2,"verses":[204],"references":[{"surah":2,"verses":[204]}],"verseLabel":"البقرة: 204","question":"ما مناسبة الانتقال من الدعاء والذكر إلى قوله تعالى: ﴿وَمِنَ النَّاسِ مَنْ يُعْجِبُكَ قَوْلُهُ﴾؟","answer":"بعد أن ذكر صنفي الناس في دعائهم، ذكر صنفين آخرين: منافقًا حلو المنطق يخالف فعله قوله، ومخلصًا يبيع نفسه ابتغاء مرضاة الله؛ لتتكشف خبايا القلوب بمقابلة الظاهر بالعمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص281، تحت «بلاغة عطف الجمل على الجمل، وأثرها في تقسيم الناس»","url":""}]},{"id":"s2-990","number":990,"surah":2,"verses":[204],"references":[{"surah":2,"verses":[204]}],"verseLabel":"البقرة: 204","question":"ما سرّ التعبير في قوله تعالى: ﴿يُعْجِبُكَ قَوْلُهُ﴾، دون أن يقال: «يعجبك هو»؟","answer":"أسند الإعجاب إلى قوله لأن موطن الحسن الظاهر هو كلامه، أما حقيقته فتكشفها سريرته وأفعاله المخالفة لذلك القول.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص798، تحت «سر إسناد الإعجاب إلى الأجسام دون الأقوال»","url":""}]},{"id":"s2-991","number":991,"surah":2,"verses":[204],"references":[{"surah":2,"verses":[204]}],"verseLabel":"البقرة: 204","question":"ما فائدة قوله: ﴿فِي الْحَيَاةِ الدُّنْيَا﴾؟","answer":"كلامه يروج حيث تخفى السرائر ويُحكم بالمظاهر، أما الآخرة فتنكشف فيها الحقيقة ولا ينفع التزيين. والقيد قد يدل أيضًا على أن حديثه كله محصور في مصالح الدنيا ولو تلون بعبارات صالحة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص283، تحت «تعدد تعلق قوله: «في الحياة الدنيا»»","url":""}]},{"id":"s2-992","number":992,"surah":2,"verses":[204],"references":[{"surah":2,"verses":[204]}],"verseLabel":"البقرة: 204","question":"ما سرّ التعبير في قوله تعالى: ﴿وَيُشْهِدُ اللَّهَ عَلَى مَا فِي قَلْبِهِ﴾؟","answer":"قال ذلك لأنه يحلف بالله أن ما في قلبه موافق لما في لسانه، توكيدًا لدعواه عند ارتياب السامع، مع أن عمله يكشف خلاف ما يدعيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص284، تحت «دلالة القسم في قوله تعالى: «ويشهد الله على ما في قلبه»»","url":""}]},{"id":"s2-994","number":994,"surah":2,"verses":[204],"references":[{"surah":2,"verses":[204]}],"verseLabel":"البقرة: 204","question":"ما دلالة وصفه بأنه ﴿أَلَدُّ الْخِصَامِ﴾؟","answer":"الألد شديد الخصومة المعوج عنها، و﴿ألد الخصام﴾ أبلغ في تمكن الجدل والعداوة منه؛ فهو يحسن القول ثم يبالغ في مقاومة الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص285، تحت «معنى الصفة المشبهة في لفظ «ألد»»","url":""}]},{"id":"s2-995","number":995,"surah":2,"verses":[205],"references":[{"surah":2,"verses":[205]}],"verseLabel":"البقرة: 205","question":"ما سرّ التعبير في قوله تعالى: ﴿ويهلك الحرث والنسل﴾ فجمع أصلَي حياة الناس؟","answer":"الحرث أصل الأقوات والأموال، والنسل أصل بقاء الإنسان والحيوان؛ فجمعهما ليصور فسادًا يستأصل مقومات الحياة والحاضر والمستقبل.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص288، تحت «المقصود بإهلاك الحرث والنسل»","url":""}]},{"id":"s2-996","number":996,"surah":2,"verses":[205],"references":[{"surah":2,"verses":[205]}],"verseLabel":"البقرة: 205","question":"ما سرّ التعبير في قوله تعالى: ﴿وَإِذَا تَوَلَّى﴾؛ هل المعنى انصرف أم تولى سلطة؟","answer":"يحتمل أنه إذا انصرف وغاب كشف فعله، ويحتمل أنه إذا صار ذا ولاية استعملها في الفساد؛ وفي الحالين يخالف عمله قوله الظاهر.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص286، تحت «المعاني الاشتقاقية للفظ «تولى»»","url":""}]},{"id":"s2-997","number":997,"surah":2,"verses":[205],"references":[{"surah":2,"verses":[205]}],"verseLabel":"البقرة: 205","question":"ما سرّ التعبير في قوله تعالى: ﴿سَعَى فِي الْأَرْضِ﴾، دون أن يقال: «أفسد» مباشرة؟","answer":"عبر بالسعي ليصور الجد والسرعة والقصد إلى إحداث الفساد، وأضاف ﴿في الأرض﴾ لبيان اتساع مجال سعيه وضرره.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص287، تحت «سر التعبير بالسعي دون المشي أو السير»","url":""}]},{"id":"s2-998","number":998,"surah":2,"verses":[205],"references":[{"surah":2,"verses":[205]}],"verseLabel":"البقرة: 205","question":"ما سرّ التعبير في قوله تعالى: ﴿فِي الْأَرْضِ لِيُفْسِدَ فِيهَا﴾ وكرر ﴿في﴾ والضمير؟","answer":"الأول يحدد مجال حركته الواسع، والثاني يصرح بأن غاية الحركة إيقاع الفساد في المجال نفسه؛ فليست الأرض مجرد طريق بل محل الأثر. والتكرار يحيط المشهد بالفساد حركةً ونتيجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص287، تحت «بلاغة استعمال حرف الظرفية في قوله: «سعى في الأرض ليفسد فيها»»","url":""}]},{"id":"s2-999","number":999,"surah":2,"verses":[205],"references":[{"surah":2,"verses":[205]}],"verseLabel":"البقرة: 205","question":"ما سرّ التعبير في قوله تعالى: ﴿وَيُهْلِكَ الْحَرْثَ وَالنَّسْلَ﴾ بعد ﴿لِيُفْسِدَ فِيهَا﴾؟","answer":"ذكر الفساد أولًا على العموم، ثم خص إهلاك الحرث والنسل بالذكر لأنهما من أعظم ما يحتاج إليه الناس، فكان إفسادهما غاية الفساد.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص288، تحت «نوع العطف في قوله تعالى: «ويهلك الحرث والنسل»»","url":""}]},{"id":"s2-1000","number":1000,"surah":2,"verses":[205],"references":[{"surah":2,"verses":[205]}],"verseLabel":"البقرة: 205","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿وَاللَّهُ لَا يُحِبُّ الْفَسَادَ﴾؟","answer":"ختم بنفي محبة الله للفساد لنفي رضاه به، وتحذير فاعله من العقوبة، وبيان أن شرع الله قائم على مصالح العباد ودفع الضرر عنهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص289، تحت «بلاغة الفاصلة القرآنية: «والله لا يحب الفساد»»","url":""}]},{"id":"s2-1001","number":1001,"surah":2,"verses":[206],"references":[{"surah":2,"verses":[206]}],"verseLabel":"البقرة: 206","question":"ما سرّ التعبير في قوله تعالى: ﴿وَإِذَا قِيلَ لَهُ اتَّقِ اللَّهَ﴾ بالبناء للمجهول؟","answer":"لأن العبرة بنصيحة الحق لا باسم ناصح معين؛ أيًّا كان من يذكره بالله يرفض التذكير. كما يوحي بأن الكلمة شائعة ينبغي أن تقال له من كل من رأى فساده.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص290، تحت «دلالة البناء للمفعول في قوله تعالى: «وإذا قيل له اتق الله»»","url":""}]},{"id":"s2-1002","number":1002,"surah":2,"verses":[206],"references":[{"surah":2,"verses":[206]}],"verseLabel":"البقرة: 206","question":"ماذا يكشف رد المنافق حين يقال له: ﴿اتَّقِ اللَّهَ﴾؟","answer":"تكشف استجابته أن الكبر يحملُه على التمادي في الإثم بدل قبول الموعظة؛ فالعزة المذمومة هنا أنفة جاهلية تصده عن الرجوع إلى الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص291، تحت «بلاغة الاستعارة في قوله تعالى: ﴿أخذته العزة بالإثم﴾»","url":""}]},{"id":"s2-1003","number":1003,"surah":2,"verses":[206],"references":[{"surah":2,"verses":[206]}],"verseLabel":"البقرة: 206","question":"ما الصورة في قوله: ﴿أَخَذَتْهُ الْعِزَّةُ بِالْإِثْمِ﴾؟","answer":"صورت الآية عزة الجاهلية كأنها قوة تأخذه وتحمله على الإثم وتلزمه به، والباء تحتمل المصاحبة أو السببية؛ أي عزة ملتبسة بالإثم أو ناشئة بسببه.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص291، تحت «بلاغة الاستعارة في قوله تعالى «أخذته العزة بالإثم»»","url":""}]},{"id":"s2-1004","number":1004,"surah":2,"verses":[206],"references":[{"surah":2,"verses":[206]}],"verseLabel":"البقرة: 206","question":"ما سرّ التعبير في قوله تعالى: ﴿فَحَسْبُهُ جَهَنَّمُ﴾؟","answer":"أي تكفيه جهنم جزاءً على إعراضه عن النصح أنفةً وتكبرًا، وفي أسلوب الكفاية استعظام لما يلقاه من العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص292–293، تحت «معنى الفاء في قوله: ﴿فحسبه جهنم﴾»","url":""}]},{"id":"s2-1005","number":1005,"surah":2,"verses":[206],"references":[{"surah":2,"verses":[206]}],"verseLabel":"البقرة: 206","question":"ما سرّ وصف جهنم بقوله تعالى: ﴿وَلَبِئْسَ الْمِهَادُ﴾ مع أن المهاد موضع راحة؟","answer":"استعمل المهاد ـ وهو موضع التهيئة والراحة ـ على سبيل التهكم والمقابلة؛ فجهنم قرارهم، لكنها بئس القرار الذي لا راحة فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص293، تحت «بلاغة استعمال لفظ المهاد بدل جهنم»","url":""}]},{"id":"s2-1006","number":1006,"surah":2,"verses":[207],"references":[{"surah":2,"verses":[207]}],"verseLabel":"البقرة: 207","question":"ما سرّ تصوير بذل النفس لله بالبيع في قوله تعالى: ﴿يَشْرِي نَفْسَهُ ابْتِغَاءَ مَرْضَاتِ اللَّهِ﴾؟","answer":"صور بذل النفس بالبيع؛ فالمؤمن بائع لنفسه، والله هو المشتري، وثمنها مرضاته، وفي ذلك تعظيم للبذل وللجزاء المطلوب.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص295، تحت «جمال الاستعارة التبعية في لفظ «يشري»»","url":""}]},{"id":"s2-1007","number":1007,"surah":2,"verses":[207],"references":[{"surah":2,"verses":[207]}],"verseLabel":"البقرة: 207","question":"ما سرّ التعبير في قوله تعالى: ﴿مرضات الله﴾ بالمصدر الميمي، لا: رضا الله؟","answer":"عبر بالمصدر الميمي ﴿مرضات﴾ لأنه يزيد على أصل معنى الرضا، فيشعر بغاية الرضا المطلوب وتحققه جزاءً لمن بذل نفسه لله.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص295، تحت «سر التعبير بالمصدر الميمي «مرضاة» دون المصدر «رضا»»","url":""}]},{"id":"s2-1008","number":1008,"surah":2,"verses":[207],"references":[{"surah":2,"verses":[207]}],"verseLabel":"البقرة: 207","question":"ما سرّ مقابلة المفسد بقوله تعالى: ﴿وَمِنَ النَّاسِ مَنْ يَشْرِي نَفْسَهُ﴾؟","answer":"قابل المفسد بمن يبذل نفسه ابتغاء مرضاة الله؛ فالأول يهلك الناس ليستبقي نفسه، والثاني يعرض نفسه للأذى في سبيل إصلاحهم وطلب رضا الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص294، تحت «استكمال التقسيم أركانه بذكر: ﴿من يشري نفسه ابتغاء مرضات الله﴾»","url":""}]},{"id":"s2-1009","number":1009,"surah":2,"verses":[207],"references":[{"surah":2,"verses":[207]}],"verseLabel":"البقرة: 207","question":"ما سرّ التعبير في قوله تعالى: ﴿يَشْرِي نَفْسَهُ﴾؛ هل يبيعها أم يشتريها؟","answer":"﴿يشري﴾ تأتي بمعنى يبيع، أي يبذل نفسه طالبًا رضا الله، وهو في الحقيقة يشتري لها النجاة بهذا البيع. واجتماع المعنيين في صورة الصفقة يكشف أنه يخسر الظاهر ليربح الباقي.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص294، تحت «بلاغة استعمال لفظ ﴿يشري﴾ في سياق الآية»","url":""}]},{"id":"s2-1010","number":1010,"surah":2,"verses":[207],"references":[{"surah":2,"verses":[207]}],"verseLabel":"البقرة: 207","question":"ما سرّ التعبير في قوله تعالى: ﴿ابْتِغَاءَ مَرْضَاتِ اللَّهِ﴾، ولم يذكر ثمنًا دنيويًا؟","answer":"صرح بأن غاية بذل النفس وثمنها هو طلب مرضاة الله، ليجعل رضا الله وحده المقصد الذي يطلبه المؤمن بهذا البذل.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص295، تحت «جمال الاستعارة التبعية في لفظ: ﴿يشري﴾»","url":""}]},{"id":"s2-1011","number":1011,"surah":2,"verses":[207],"references":[{"surah":2,"verses":[207]}],"verseLabel":"البقرة: 207","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿وَاللَّهُ رَءُوفٌ بِالْعِبَادِ﴾ بصيغة العموم؟","answer":"عدل إلى لفظ ﴿العباد﴾ لتعم الرأفة جميع عباده، ومن رأفته بهم أن فتح لهم طريق البذل الذي ينالون به رضاه وثوابه.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص296–297، تحت «بلاغة الفاصلة القرآنية في قوله تعالى: ﴿والله رؤوف بالعباد﴾»","url":""}]},{"id":"s2-1012","number":1012,"surah":2,"verses":[208],"references":[{"surah":2,"verses":[208]}],"verseLabel":"البقرة: 208","question":"ما دلالة النهي عن اتباع ﴿خُطُوَاتِ الشَّيْطَانِ﴾ عقب الأمر بالدخول في السلم كافة؟","answer":"يحذر من مسالك الشيطان المتدرجة التي تبدأ بخطوة ثم تجر إلى أخرى، فتصد المؤمن عن الاستسلام الكامل لله وتوقعه في الانتقاء من الدين أو مخالفته.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص305، تحت «فائدة النهي والتحذير عما يصد عن الدخول في السلم المأمور به»","url":""}]},{"id":"s2-1013","number":1013,"surah":2,"verses":[208],"references":[{"surah":2,"verses":[208]}],"verseLabel":"البقرة: 208","question":"ما مناسبة نداء المؤمنين قبل قوله تعالى: ﴿ادْخُلُوا فِي السِّلْمِ كَافَّةً﴾؟","answer":"وُجّه النداء إلى المؤمنين لأمرهم بالثبات على الإسلام والدخول فيه جميعًا، واجتناب التفرق والجدل.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص302، تحت «خطاب المؤمنين بالالتزام بالإسلام والثبات عليه»","url":""}]},{"id":"s2-1014","number":1014,"surah":2,"verses":[208],"references":[{"surah":2,"verses":[208]}],"verseLabel":"البقرة: 208","question":"ما المراد بـ﴿السِّلْمِ﴾: الإسلام أم السلام؟","answer":"السِّلم يفسر بالإسلام والطاعة، ويفسر بالصلح والسلام؛ والمعنى الجامع الدخول الكامل في طاعة الله وترك مسالك الشيطان والفرقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص303، تحت «توجيه القراءات القرآنية في لفظ «السلم»»","url":""}]},{"id":"s2-1015","number":1015,"surah":2,"verses":[208],"references":[{"surah":2,"verses":[208]}],"verseLabel":"البقرة: 208","question":"ما سرّ التعبير في قوله تعالى: ﴿ادْخُلُوا فِي السِّلْمِ﴾، دون أن يقال: «التزموا السلم»؟","answer":"استُعير الدخول للاتباع والالتزام؛ فالمقصود الثبات على الإسلام حاضرًا ومستقبلًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص303، تحت «الاستعارة التصريحية في قوله تعالى: «ادخلوا في السلم كافة»»","url":""}]},{"id":"s2-1016","number":1016,"surah":2,"verses":[208],"references":[{"surah":2,"verses":[208]}],"verseLabel":"البقرة: 208","question":"إلى ماذا تتعلق ﴿كَافَّةً﴾: بالمؤمنين أم بالسِّلم؟","answer":"يجوز أن تكون ﴿كافة﴾ حالًا من المخاطبين: ادخلوا جميعًا، ويجوز أن تتعلق بالسلم: ادخلوا في شرائعه كلها؛ والمعنيان متلازمان في كمال الانقياد.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص305، تحت «إعراب كلمة «كافة» وتعيين صاحب الحال»","url":""}]},{"id":"s2-1017","number":1017,"surah":2,"verses":[208],"references":[{"surah":2,"verses":[208]}],"verseLabel":"البقرة: 208","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿إِنَّهُ لَكُمْ عَدُوٌّ مُبِينٌ﴾؟","answer":"علل النهي بعداوة الشيطان الظاهرة، وقدم ﴿لكم﴾ لإبراز اختصاص عداوته بالإنسان، فيكون المؤمن على حذر من وساوسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص306، تحت «بلاغة التذييل في قوله: «إنه لكم عدو مبين»»","url":""}]},{"id":"s2-1018","number":1018,"surah":2,"verses":[209],"references":[{"surah":2,"verses":[209]}],"verseLabel":"البقرة: 209","question":"ما سرّ التعبير في قوله تعالى: ﴿فَإِنْ زَلَلْتُمْ﴾، دون أن يقال: «فإن عصيتم»؟","answer":"الزلل في الأصل زلق القدم، فاستُعير للانحراف عن الحق واتباع طريق الشيطان، تشبيهًا لخطأ الرأي بزلل القدم في الطريق.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص307، تحت «استعمال الزلل مجازا على سبيل الاستعارة التمثيلية»","url":""}]},{"id":"s2-1019","number":1019,"surah":2,"verses":[209],"references":[{"surah":2,"verses":[209]}],"verseLabel":"البقرة: 209","question":"ما دلالة الشرط بـ﴿إِنْ﴾ في قوله تعالى: ﴿فَإِنْ زَلَلْتُمْ مِنْ بَعْدِ مَا جَاءَتْكُمُ الْبَيِّنَاتُ﴾؟","answer":"يفيد التعبير بأداة الشرط «إن» ندرة حصول الزلل من المؤمنين، وفيه ترغيب لهم وحث على الاستقامة على منهج الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص307، تحت «بلاغة الشرط في قوله تعالى: ﴿فإن زللتم﴾»","url":""}]},{"id":"s2-1020","number":1020,"surah":2,"verses":[209],"references":[{"surah":2,"verses":[209]}],"verseLabel":"البقرة: 209","question":"ما سرّ التعبير في قوله تعالى: ﴿فَاعْلَمُوا أَنَّ اللَّهَ عَزِيزٌ حَكِيمٌ﴾، ولم يصرح بالعقوبة؟","answer":"الأمر بالعلم تهديد أبلغ؛ العزيز لا يعجزه من زل، والحكيم يضع عقوبته في موضعها فلا تكون بطشًا بلا ميزان. وترك الجزاء مطويًا يفتح أمام النفس كل ما تقتضيه الصفتان.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص308، تحت «بلاغة التحذير والوعيد في قوله: «فاعلموا أن الله عزيز حكيم»»","url":""}]},{"id":"s2-1021","number":1021,"surah":2,"verses":[209],"references":[{"surah":2,"verses":[209]}],"verseLabel":"البقرة: 209","question":"ما سرّ ختم الآية بـ﴿عَزِيزٌ حَكِيمٌ﴾ دون ﴿غفور رحيم﴾؟","answer":"العزيز لا يعجزه عقاب من زل بعد البينات، والحكيم يضع عقوبته وحكمه موضعهما؛ فناسب الوعيد المقام، لا اسما المغفرة والرحمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص309، تحت عنوان «نكتة تقديم صفة ﴿عزيز﴾ على صفة ﴿حكيم﴾»","url":""}]},{"id":"s2-1022","number":1022,"surah":2,"verses":[210],"references":[{"surah":2,"verses":[210]}],"verseLabel":"البقرة: 210","question":"ما سرّ التعبير في قوله تعالى: ﴿هل ينظرون إلا أن يأتيهم الله في ظلل من الغمام﴾؟","answer":"تهديد بانتظار يوم القضاء وظهور آيات السلطان الإلهي على الوجه اللائق به، لا وصفًا يجيز تشبيه الله بخلقه؛ والغمام يزيد المشهد مهابة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص310، تحت «إسناد الإتيان إلى الله تعالى في هذه الآية على وجه إثبات الصفة»","url":""}]},{"id":"s2-1023","number":1023,"surah":2,"verses":[210],"references":[{"surah":2,"verses":[210]}],"verseLabel":"البقرة: 210","question":"ما سرّ التعبير في قوله تعالى: ﴿هَلْ يَنْظُرُونَ إِلَّا أَنْ يَأْتِيَهُمُ اللَّهُ﴾، والنظر غير الانتظار؟","answer":"﴿ينظرون﴾ هنا بمعنى ينتظرون، وفي الاستفهام إنكار وتهديد: ماذا بقي بعد البينات إلا مجيء الفصل الذي لا ينفع عنده الإيمان؟ صوّر إمهالهم كأنهم يتعمدون انتظار النهاية.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص309، تحت «بلاغة الاستفهام الإنكاري والالتفات البلاغي في: «هل ينظرون»»","url":""}]},{"id":"s2-1024","number":1024,"surah":2,"verses":[210],"references":[{"surah":2,"verses":[210]}],"verseLabel":"البقرة: 210","question":"ما دلالة قوله تعالى: ﴿أَنْ يَأْتِيَهُمُ اللَّهُ﴾، وكيف يفهم على الوجه اللائق بالله سبحانه؟","answer":"الآية من نصوص الصفات؛ نؤمن بأن الله يأتي يوم القيامة على الوجه اللائق بجلاله، من غير تكييف ولا تمثيل، كما نؤمن بسائر صفاته، ولا نقيس إتيانه على إتيان المخلوق.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص310، تحت «إسناد الإتيان إلى الله تعالى في هذه الآية على وجه إثبات الصفة»","url":""}]},{"id":"s2-1025","number":1025,"surah":2,"verses":[210],"references":[{"surah":2,"verses":[210]}],"verseLabel":"البقرة: 210","question":"ما سرّ التعبير في قوله تعالى: ﴿فِي ظُلَلٍ مِنَ الْغَمَامِ﴾؟","answer":"الغمام مما تُنتظر منه الرحمة، فإذا جاء منه العذاب كان أشد مفاجأة وهولًا؛ لأن الشر إذا جاء من حيث يُحتسب الخير كان أوقع.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص310، تحت «بلاغة التعبير في قوله تعالى: «في ظلل من الغمام»»","url":""}]},{"id":"s2-1026","number":1026,"surah":2,"verses":[210],"references":[{"surah":2,"verses":[210]}],"verseLabel":"البقرة: 210","question":"ما سرّ عطف ﴿وَالْمَلَائِكَةُ﴾ بعد ذكر الغمام؟","answer":"في قراءة الرفع عُطف ﴿والملائكة﴾ على اسم الجلالة، وأُسند إليهم الإتيان لأنهم يأتون بأمر الله أو عذابه، وهم الموكل إليهم تنفيذ قضائه.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص312–313، تحت «توجيه القراءات القرآنية»","url":""}]},{"id":"s2-1027","number":1027,"surah":2,"verses":[210],"references":[{"surah":2,"verses":[210]}],"verseLabel":"البقرة: 210","question":"ما سرّ التعبير في قوله تعالى: ﴿وَقُضِيَ الْأَمْرُ﴾ بالماضي مع أنه مستقبل؟","answer":"عبّر بالماضي لتحقق الوقوع حتى كأنه وقع وانتهى، وبنى الفعل للمجهول لأن العناية بحسم الأمر لا بذكر القاضي المعلوم. جملة قصيرة تغلق كل باب للتأجيل والمراجعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص313، تحت «سر العدول عن صيغة المضارع إلى الماضي»","url":""}]},{"id":"s2-1028","number":1028,"surah":2,"verses":[210],"references":[{"surah":2,"verses":[210]}],"verseLabel":"البقرة: 210","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿وَإِلَى اللَّهِ تُرْجَعُ الْأُمُورُ﴾، ودلالة تقديم ﴿إلى الله﴾؟","answer":"تقديم ﴿إلى الله﴾ يفيد القصر: إليه وحده مرجع الأمور وحكمها، وهو مناسب لمشهد القضاء الذي تنقطع فيه دعاوى الاستقلال.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص314، تحت «بلاغة الفاصلة القرآنية»","url":""}]},{"id":"s2-1029","number":1029,"surah":2,"verses":[211],"references":[{"surah":2,"verses":[211]}],"verseLabel":"البقرة: 211","question":"ما سرّ التعبير في قوله تعالى: ﴿من بعد ما جاءته﴾ بزيادة ﴿من﴾؟","answer":"تؤكد ابتداء التبديل مباشرة بعد تحقق مجيء النعمة ووضوحها، فتجعل الجريمة واقعة بعد تمام الحجة لا قبلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص325، تحت «بلاغة اختلاف المقامين في الآية»","url":""}]},{"id":"s2-1030","number":1030,"surah":2,"verses":[211],"references":[{"surah":2,"verses":[211]}],"verseLabel":"البقرة: 211","question":"ما سرّ التعبير في قوله تعالى: ﴿سَلْ بَنِي إِسْرَائِيلَ﴾، مع أن النبي ﷺ يعلم خبرهم بالوحي؟","answer":"الأمر بالسؤال للتقريع والتوبيخ وتذكير اليهود الحاضرين بما آتى بني إسرائيل من آيات، لا لطلب علم يجهله النبي ﷺ.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص317، تحت «مجيء التقرير في صورة الأمر بالسؤال أوقع في النفس وأدل على الإلزام»","url":""}]},{"id":"s2-1031","number":1031,"surah":2,"verses":[211],"references":[{"surah":2,"verses":[211]}],"verseLabel":"البقرة: 211","question":"ما سرّ التعبير في قوله تعالى: ﴿كَمْ آتَيْنَاهُمْ مِنْ آيَةٍ بَيِّنَةٍ﴾، ولم يذكر عدد الآيات؟","answer":"تحتمل ﴿كم﴾ الخبرية للتكثير، والاستفهامية للتقرير؛ والمقصود إبراز كثرة ما أوتوه من الآيات الواضحة لا تعيين عددها.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص318، تحت «الموقع البديع لـ«كم» واحتمالها الخبرية والاستفهام»","url":""}]},{"id":"s2-1032","number":1032,"surah":2,"verses":[211],"references":[{"surah":2,"verses":[211]}],"verseLabel":"البقرة: 211","question":"ما دلالة وصف الآية بأنها ﴿بَيِّنَةٍ﴾؟","answer":"الآية البينة هي الحجة الواضحة التي لا مجال للشك فيها؛ فوصفها بذلك يبين أن التبديل لم يكن لضعف الدليل بل للعناد.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص320، تحت «بلاغة وصف الآية بكونها بينة في قوله: «من آية بينة»»","url":""}]},{"id":"s2-1033","number":1033,"surah":2,"verses":[211],"references":[{"surah":2,"verses":[211]}],"verseLabel":"البقرة: 211","question":"ما سرّ تسمية الآيات ﴿نِعْمَةَ اللَّهِ﴾ في قوله: ﴿وَمَنْ يُبَدِّلْ نِعْمَةَ اللَّهِ﴾؟","answer":"سميت الآيات نعمة لأنها أدلة الهدى والنجاة، وهي من أجل نعم الله؛ فمن حرفها أو كفر بها فقد قابل النعمة بالكفر.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص322، تحت «سر وضع المظهر موضع المضمر»","url":""}]},{"id":"s2-1034","number":1034,"surah":2,"verses":[211],"references":[{"surah":2,"verses":[211]}],"verseLabel":"البقرة: 211","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿فَإِنَّ اللَّهَ شَدِيدُ الْعِقَابِ﴾؟","answer":"رتب شدة العقاب على التبديل بعد مجيء النعمة والآية البينة؛ فالعقوبة تشتد بقدر وضوح الحجة. وإظهار اسم الله يربي المهابة ويمنع أن يبدو الوعيد نتيجة آلية بلا حاكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص323، تحت «بلاغة التذييل، ودلالته على التعليل والعموم»","url":""}]},{"id":"s2-1035","number":1035,"surah":2,"verses":[212],"references":[{"surah":2,"verses":[212]}],"verseLabel":"البقرة: 212","question":"ما سرّ التعبير في قوله تعالى: ﴿زُيِّنَ لِلَّذِينَ كَفَرُوا الْحَيَاةُ الدُّنْيَا﴾ بالبناء للمجهول؟","answer":"لأن المقصود وصف وقوع التزيين عليهم وآثاره، وقد تكون أسبابه الشيطان والهوى وزخرف الدنيا بإذن الله الكوني؛ فحذف الفاعل ليشملها. وصيغة الماضي تصور تمكن الزينة في نفوسهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص328، تحت «نكتة بناء الفعل لما لم يسم فاعله»","url":""}]},{"id":"s2-1036","number":1036,"surah":2,"verses":[212],"references":[{"surah":2,"verses":[212]}],"verseLabel":"البقرة: 212","question":"ما دلالة التعبير بالاسم الموصول في قوله تعالى: ﴿زُيِّنَ لِلَّذِينَ كَفَرُوا الْحَيَاةُ الدُّنْيَا﴾؟","answer":"يشعر الموصول وصلته بأن كفرهم هو الذي حملهم على شدة التعلق بالدنيا والسخرية من أهل الإيمان، فالتعبير جارٍ مجرى التعليل.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص330، تحت «سر التعبير بالاسم الموصول (الذين)»","url":""}]},{"id":"s2-1037","number":1037,"surah":2,"verses":[212],"references":[{"surah":2,"verses":[212]}],"verseLabel":"البقرة: 212","question":"ما سرّ التعبير في قوله تعالى: ﴿وَيَسْخَرُونَ مِنَ الَّذِينَ آمَنُوا﴾ بالمضارع بعد ﴿زُيِّنَ﴾ بالماضي؟","answer":"الماضي يثبت رسوخ التزيين، والمضارع يصور سخريتهم المتجددة كلما رأوا المؤمنين وزهدهم في المقاييس الدنيوية. فالخلل الباطن المستقر ينتج سلوكًا يتكرر.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص331، تحت «نكتة التعبير عن التزيين بصيغة الماضي، وعن السخرية بالمضارع»","url":""}]},{"id":"s2-1038","number":1038,"surah":2,"verses":[212],"references":[{"surah":2,"verses":[212]}],"verseLabel":"البقرة: 212","question":"ما معنى كون الذين اتقوا ﴿فَوْقَهُمْ يَوْمَ الْقِيَامَةِ﴾؟","answer":"تنقلب موازين السخرية يوم القيامة؛ فيظهر علو منزلة المتقين وكرامتهم، ويكونون فوق الكافرين في المنزلة والمصير، بعد أن كان الكافرون يحتقرونهم في الدنيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص332–333، تحت «نكتة إيقاع الظاهر موقع الضمير: ﴿والذين اتقوا فوقهم يوم القيامة﴾»","url":""}]},{"id":"s2-1040","number":1040,"surah":2,"verses":[212],"references":[{"surah":2,"verses":[212]}],"verseLabel":"البقرة: 212","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿وَاللَّهُ يَرْزُقُ مَنْ يَشَاءُ بِغَيْرِ حِسَابٍ﴾؟","answer":"حتى لا تُتخذ سعة رزق الكافر دليل كرامة ولا قلة مال المؤمن دليل هوان؛ فالرزق يجري بمشيئة الله وحكمته، والجزاء الأخروي أوسع من مقاييسهم. و﴿بغير حساب﴾ تفيد السعة التي لا يحدها تقدير البشر.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص334، تحت «بلاغة تذييل الآية بقوله: «والله يرزق من يشاء بغير حساب»»","url":""}]},{"id":"s2-1041","number":1041,"surah":2,"verses":[213],"references":[{"surah":2,"verses":[213]}],"verseLabel":"البقرة: 213","question":"ما سرّ اختيار لفظ ﴿الصراط﴾ دون الطريق أو السبيل؟","answer":"الصراط يوحي بطريق واضح واسع موصل بلا تشعب، فناسب الحق الواحد الذي يهدي الله إليه وسط اختلاف الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص347، تحت «بلاغة استعارة الصراط لدين الله تعالى»","url":""}]},{"id":"s2-1042","number":1042,"surah":2,"verses":[213],"references":[{"surah":2,"verses":[213]},{"surah":4,"verses":[165]}],"verseLabel":"البقرة: 213؛ النساء: 165","question":"ما سرّ اختلاف التعبير بين قوله تعالى في البقرة: ﴿فَبَعَثَ اللَّهُ النَّبِيِّينَ مُبَشِّرِينَ وَمُنْذِرِينَ﴾، وقوله تعالى في النساء: ﴿رُسُلًا مُبَشِّرِينَ وَمُنْذِرِينَ﴾؟","answer":"سياق البقرة عام في قوله ﴿كان الناس أمة واحدة﴾، فناسبه لفظ النبيين الأعم من الرسل. أما النساء فسبق فيها ﴿ورسلًا قد قصصناهم عليك من قبل﴾، فناسب لفظ الرسل التخصيص والتوافق مع السياق.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص395–396، تحت عنوان «سر التعبير بالرسل دون النبيين، عكس ما في سورة البقرة»","url":""}]},{"id":"s2-1043","number":1043,"surah":2,"verses":[213],"references":[{"surah":2,"verses":[213]},{"surah":10,"verses":[19]},{"surah":11,"verses":[118]}],"verseLabel":"البقرة: 213، يونس: 19، هود: 118","question":"ما وجه الجمع بين كون الناس ﴿أُمَّةً وَاحِدَةً﴾ في البقرة ويونس، وقوله في هود: ﴿وَلَوْ شَاءَ رَبُّكَ لَجَعَلَ النَّاسَ أُمَّةً وَاحِدَةً﴾؟","answer":"المراد في البقرة ويونس أنهم كانوا مجتمعين في مرحلة سابقة ثم اختلفوا، أما هود فينفي دوام اجتماعهم على الإيمان في جميع الأزمنة؛ فلا تعارض بين وحدة عارضة قديمة وعدم جعلهم أمة واحدة دائمًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص43، تحت «بلاغة التشابه اللفظي»","url":""}]},{"id":"s2-1044","number":1044,"surah":2,"verses":[213],"references":[{"surah":2,"verses":[213]}],"verseLabel":"البقرة: 213","question":"ما سرّ التعبير في قوله تعالى: ﴿كَانَ النَّاسُ أُمَّةً وَاحِدَةً﴾، وعلى ماذا كانوا متحدين؟","answer":"كانوا جماعة واحدة متفقين على الإيمان والحق، ثم اختلفوا، فبعث الله النبيين وأنزل الكتب للفصل بينهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص339، تحت «دلالة «كان» بين المضي والثبوت»","url":""}]},{"id":"s2-1045","number":1045,"surah":2,"verses":[213],"references":[{"surah":2,"verses":[213]}],"verseLabel":"البقرة: 213","question":"ما سرّ التعبير في قوله تعالى: ﴿فَبَعَثَ اللَّهُ النَّبِيِّينَ﴾؛ أين ذُكر الاختلاف الذي سبّب بعثهم؟","answer":"كانوا جماعة واحدة متفقين على الإيمان والحق، ثم وقع بينهم الاختلاف، فبعث الله النبيين وأنزل الكتب للفصل فيما اختلفوا فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص341، تحت «تنوع دلالة الفاء وأثره في إثراء المعاني»","url":""}]},{"id":"s2-1046","number":1046,"surah":2,"verses":[213],"references":[{"surah":2,"verses":[213]}],"verseLabel":"البقرة: 213","question":"ما سرّ تقديم ﴿مُبَشِّرِينَ﴾ على ﴿مُنْذِرِينَ﴾؟","answer":"قدمت البشارة لأنها أبهج للنفس وأطيب للخاطر وأدعى إلى قبول الدعوة، وجمع معها الإنذار ليقوم الخطاب على الوعد والوعيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص342، تحت «نكتة تقديم البشارة على النذارة»","url":""}]},{"id":"s2-1047","number":1047,"surah":2,"verses":[213],"references":[{"surah":2,"verses":[213]}],"verseLabel":"البقرة: 213","question":"ما سرّ التعبير في قوله تعالى: ﴿وَأَنْزَلَ مَعَهُمُ الْكِتَابَ﴾، مع تعدد الكتب؟","answer":"أفرد ﴿الكتاب﴾ لإرادة جنس الكتب المنزلة؛ فهي وإن تعددت اتفقت على أصل واحد هو التوحيد، فكأنها كتاب واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص342، تحت «نكتة إفراد الكتاب في قوله: «وأنزل معهم الكتاب»»","url":""}]},{"id":"s2-1048","number":1048,"surah":2,"verses":[213],"references":[{"surah":2,"verses":[213]}],"verseLabel":"البقرة: 213","question":"ما دلالة تقييد إنزال الكتاب بقوله تعالى: ﴿بِالْحَقِّ﴾؟","answer":"قيد إنزال الكتاب بالحق لبيان أنه نزل ملتبسًا بالحق ومصاحبًا له، صالحًا للفصل فيما اختلف الناس فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص344، تحت «نكتة تقييد الفعل بالمفعول له»","url":""}]},{"id":"s2-1049","number":1049,"surah":2,"verses":[213],"references":[{"surah":2,"verses":[213]}],"verseLabel":"البقرة: 213","question":"ما سرّ التعبير في قوله تعالى: ﴿لِيَحْكُمَ بَيْنَ النَّاسِ﴾، والكتاب لا يتكلم ويحكم بنفسه؟","answer":"أسند الحكم إلى الكتاب مجازًا لأنه أصل الحكم ومتضمن له، وعلى قراءة البناء للمفعول يكون المعنى ليحكم الله أو الحاكم بالكتاب بين الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص343، تحت «بلاغة المجاز العقلي في إسناد الحكم للكتاب»","url":""}]},{"id":"s2-1050","number":1050,"surah":2,"verses":[213],"references":[{"surah":2,"verses":[213]}],"verseLabel":"البقرة: 213","question":"ما سرّ التعبير في قوله تعالى: ﴿وَمَا اخْتَلَفَ فِيهِ إِلَّا الَّذِينَ أُوتُوهُ﴾، مع أن الكتاب جاء ليزيل الاختلاف؟","answer":"لأن المشكلة لم تكن غموض الكتاب، بل بغي بعض أهله بعد العلم؛ فالدواء نفسه يصير موضع نزاع حين تفسد الإرادة. والقصر يفضح أن أحق الناس بالاجتماع عليه هم الذين صنعوا الانقسام فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص345، تحت «بلاغة أسلوب القلب»","url":""}]},{"id":"s2-1051","number":1051,"surah":2,"verses":[213],"references":[{"surah":2,"verses":[213]}],"verseLabel":"البقرة: 213","question":"ما سرّ التعبير في قوله تعالى: ﴿مِنْ بَعْدِ مَا جَاءَتْهُمُ الْبَيِّنَاتُ بَغْيًا بَيْنَهُمْ﴾؟","answer":"أكد أن اختلافهم وقع بعد وصول الحجج الواضحة، وأن دافعه البغي المتمثل في الحسد والظلم والحرص على الدنيا، لا نقص المعرفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص344، تحت «نكتة تقييد الفعل بالمفعول له»","url":""}]},{"id":"s2-1052","number":1052,"surah":2,"verses":[213],"references":[{"surah":2,"verses":[213]}],"verseLabel":"البقرة: 213","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿وَاللَّهُ يَهْدِي مَنْ يَشَاءُ إِلَى صِرَاطٍ مُسْتَقِيمٍ﴾؟","answer":"ختم ببيان أن الهداية بتوفيق الله وحده، وأن من يتحرى الحق يزيده الله هدى؛ والصراط المستقيم طريق واحد لا عوج فيه ولا تشعب.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص347، تحت «بلاغة التذييل في قوله: «والله يهدي من يشاء إلى صراط مستقيم»»","url":""}]},{"id":"s2-1053","number":1053,"surah":2,"verses":[214],"references":[{"surah":2,"verses":[214]}],"verseLabel":"البقرة: 214","question":"ما سرّ التعبير في قوله تعالى: ﴿وَزُلْزِلُوا﴾ بعد ﴿مَسَّتْهُمُ الْبَأْسَاءُ وَالضَّرَّاءُ﴾؟","answer":"تصور ﴿وزلزلوا﴾ شدة ما أصاب المؤمنين من الهول والفزع؛ فتكرير الزاي واللام يشعر بتكرر الإزعاج مرة بعد مرة، كما تكرر الزلزلة تحريك الشيء عن مكانه. فزيادة المبنى هنا تناسب شدة الابتلاء وتتابعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص354–355، تحت عنوان «العدول عن وزن إلى وزن آخر أكثر حروفًا»","url":""}]},{"id":"s2-1054","number":1054,"surah":2,"verses":[214],"references":[{"surah":2,"verses":[214]},{"surah":3,"verses":[142]},{"surah":9,"verses":[16]}],"verseLabel":"البقرة: 214، آل عمران: 142، التوبة: 16","question":"ما سرّ تفصيل الابتلاء في البقرة، واختصاره أو اختلاف عرضه في آل عمران والتوبة؟","answer":"خاطبت البقرة المؤمنين عامة وعرّفتهم سنة الابتلاء التي جرت على الأمم قبلهم، فناسبها التفصيل والتسلية بذكر البأساء والضراء والزلزال. أما آل عمران فخاطبت أهل أُحد في واقعة مخصوصة، فخصت الجهاد والصبر. والتوبة خاطبت المؤمنين بعد الفتح في مقام تمييز صدق الباطن من النفاق، فناسب سؤالهم هل يظنون أنهم سيُتركون بلا اختبار.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص22، تحت «التشابه اللفظي»","url":""}]},{"id":"s2-1055","number":1055,"surah":2,"verses":[214],"references":[{"surah":2,"verses":[214]},{"surah":48,"verses":[29]}],"verseLabel":"البقرة: 214، الفتح: 29","question":"ما سرّ التعبير في قوله تعالى في البقرة: ﴿وَالَّذِينَ آمَنُوا مَعَهُ﴾، بينما قال في الفتح: ﴿مُحَمَّدٌ رَسُولُ اللَّهِ وَالَّذِينَ مَعَهُ﴾ من غير أن يذكر الإيمان؟","answer":"يصف موضع البقرة عِظم الابتلاء الذي أصاب الرسول والمؤمنين المصاحبين له؛ فصرح بالإيمان لأن المقام يبين أن هذه المعية الإيمانية لها ثمن من الصبر والثبات. أما الفتح فالمقام في تعداد صفات أصحاب النبي ﷺ الظاهرة في جهادهم وعبادتهم وتراحمهم، وكانت معيتهم له قد عرَّفتهم، ثم جاءت الصفات لتكشف حقيقتها؛ فلم يحتج السياق إلى إعادة وصف الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج18، ص26، تحت «توجيه المتشابه اللفظي بين آية التوبة، وآيات في سور أخر»","url":""}]},{"id":"s2-1056","number":1056,"surah":2,"verses":[214],"references":[{"surah":2,"verses":[214]}],"verseLabel":"البقرة: 214","question":"ما سرّ افتتاح الآية بقوله تعالى: ﴿أَمْ حَسِبْتُمْ أَنْ تَدْخُلُوا الْجَنَّةَ﴾؟","answer":"الاستفهام للإنكار والتربية: لا تحسبوا دخول الجنة يقع بلا ابتلاء يمحص الإيمان، وقد مضت هذه السنة في الأمم السابقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص352، تحت «الثبات والصبر وعدم التبرم من الشدائد طريق لنيل الجنة»","url":""}]},{"id":"s2-1057","number":1057,"surah":2,"verses":[214],"references":[{"surah":2,"verses":[214]}],"verseLabel":"البقرة: 214","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلَمَّا يَأْتِكُمْ مَثَلُ الَّذِينَ خَلَوْا﴾، دون أن يقال: «ولم تُبتلوا»؟","answer":"﴿لما﴾ تنفي مع توقع الوقوع، و﴿مثل﴾ تستحضر حال السابقين ونمط ابتلائهم لا مجرد حادثة واحدة؛ فكأن سنّة الطريق ستأتيهم في صورة شبيهة. لم يشترط التطابق، بل المشاركة في أصل الامتحان.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص353، تحت «دلالة النفي بـ«ولما»»","url":""}]},{"id":"s2-1058","number":1058,"surah":2,"verses":[214],"references":[{"surah":2,"verses":[214]}],"verseLabel":"البقرة: 214","question":"ما الصورة البلاغية في قوله تعالى: ﴿مَسَّتْهُمُ الْبَأْسَاءُ وَالضَّرَّاءُ﴾؟","answer":"شُبّهت المحن بالنار في شدة إيلامها، وحُذف المشبه به ودل عليه المس، على سبيل الاستعارة المكنية. وتبرز الصورة شدة المحن وفضل المؤمنين الثابتين عليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص354، تحت «بلاغة الاستعارة المكنية في قوله: ﴿مستهم﴾»","url":""}]},{"id":"s2-1060","number":1060,"surah":2,"verses":[214],"references":[{"surah":2,"verses":[214]}],"verseLabel":"البقرة: 214","question":"ما دلالة بلوغ البلاء بالرسول والمؤمنين إلى قولهم: ﴿مَتَى نَصْرُ اللَّهِ﴾؟","answer":"ليس قولهم شكًا في وعد الله، بل استبطاء للنصر تحت شدة البلاء وتضرع بطلبه؛ حتى بلغ الامتحان غايته التي يظهر عندها تمام الافتقار.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص355، تحت «دلالة الاستفهام في «متى نصر الله»»","url":""}]},{"id":"s2-1061","number":1061,"surah":2,"verses":[214],"references":[{"surah":2,"verses":[214]}],"verseLabel":"البقرة: 214","question":"ما وظيفة ختم الابتلاء بقوله: ﴿أَلَا إِنَّ نَصْرَ اللَّهِ قَرِيبٌ﴾؟","answer":"يثبت المؤمنين بعد تصوير شدة البأساء والضراء والزلزال، ويقرر أن بلوغ المحنة غايتها لا يعني التخلي عنهم، بل يعقبه نصر الله القريب.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص356، تحت «سر تأكيد جملة التذييل»","url":""}]},{"id":"s2-1063","number":1063,"surah":2,"verses":[215],"references":[{"surah":2,"verses":[215]}],"verseLabel":"البقرة: 215","question":"ما سرّ توجيه جواب سؤالهم ﴿مَاذَا يُنْفِقُونَ﴾ إلى بيان جهات الإنفاق؟","answer":"ضمن الجواب بيان المنفَق ووجهته: سماه خيرًا وبدأ بأولى الناس به. فصلاح جهة الإنفاق أهم من السؤال عن المقدار وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص359، تحت «دلالة الأسلوب الحكيم في قوله: «يسألونك ماذا ينفقون»»","url":""}]},{"id":"s2-1064","number":1064,"surah":2,"verses":[215],"references":[{"surah":2,"verses":[215]}],"verseLabel":"البقرة: 215","question":"ما سرّ التعبير في قوله تعالى: ﴿مَا أَنْفَقْتُمْ مِنْ خَيْرٍ﴾، وسمّى المال خيرًا؟","answer":"التعبير عن المال بالخير يتضمن كونه حلالًا، ويشمل قليله وكثيره؛ فالعبرة بكون المنفَق خيرًا لا بكثرته. و«من» بيانية، وتنكير «خير» في سياق الشرط يفيد الشمول والعموم.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص360–361، تحت عنوان «نكتة التعبير بالفعل الماضي ﴿أنفقتم﴾»","url":""}]},{"id":"s2-1065","number":1065,"surah":2,"verses":[215],"references":[{"surah":2,"verses":[215]}],"verseLabel":"البقرة: 215","question":"ما سرّ تقديم الوالدين على بقية المستحقين؟","answer":"قدم الوالدان لأنهما سبب وجود المرء وربياه في غاية الضعف، فكان إنعامهما أعظم وحقهما أوجب بعد حق الله تعالى.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص361، تحت «سر ترتيب الأصناف المنفق عليهم»","url":""}]},{"id":"s2-1066","number":1066,"surah":2,"verses":[215],"references":[{"surah":2,"verses":[215]}],"verseLabel":"البقرة: 215","question":"ما سرّ ذكر ﴿الْأَقْرَبِينَ﴾ بعد الوالدين مع دخولهما في القرابة؟","answer":"هذا من عطف العام على الخاص؛ فالوالدان داخلان في الأقربين، لكنهما خُصّا أولًا لعظم حقهما ثم عُطف العام ليشمل سائر القرابة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص799، تحت «دلالة عطف العام على الخاص»","url":""}]},{"id":"s2-1067","number":1067,"surah":2,"verses":[215],"references":[{"surah":2,"verses":[215]}],"verseLabel":"البقرة: 215","question":"ما سرّ ختم قائمة المستحقين بـ﴿ابْنِ السَّبِيلِ﴾؟","answer":"ذكر ابن السبيل لأنه قد يقع في الحاجة والفقر لانقطاعه عن بلده ولو كان غنيًا فيه؛ وسمي ابن السبيل لملازمته الطريق كما يلازم الولد أمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص361–362، تحت «سر ترتيب الأصناف المنفق عليهم»","url":""}]},{"id":"s2-1068","number":1068,"surah":2,"verses":[215],"references":[{"surah":2,"verses":[215]}],"verseLabel":"البقرة: 215","question":"ما دلالة تكرار الخير في قوله تعالى: ﴿وَمَا تَفْعَلُوا مِنْ خَيْرٍ فَإِنَّ اللَّهَ بِهِ عَلِيمٌ﴾؟","answer":"عمم من الإنفاق إلى كل فعل خير واجب أو متطوع به، وأكد أن الله يعلمه ويجازي عليه؛ وقدم ﴿به﴾ للاهتمام بالحكم وتقويته وتوكيده.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص362–363، تحت «بلاغة التذييل في قوله: ﴿وما تفعلوا من خير فإن الله به عليم﴾»","url":""}]},{"id":"s2-1069","number":1069,"surah":2,"verses":[216],"references":[{"surah":2,"verses":[216]}],"verseLabel":"البقرة: 216","question":"ما القاعدة التي تقررها المقابلة بين كراهة ما فيه الخير ومحبة ما فيه الشر؟","answer":"تقرر قصور علم الإنسان عن إدراك جميع العواقب؛ فقد تنفر النفس من أمر يكون الخير في مآله، وتميل إلى آخر يكون الشر في عاقبته، والله يعلم المصالح على حقيقتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص372، تحت «بديع المقابلة في قوله تعالى: «وعسى أن تكرهوا شيئًا وهو خير لكم وعسى أن تحبوا شيئًا وهو شر لكم»»","url":""}]},{"id":"s2-1070","number":1070,"surah":2,"verses":[216],"references":[{"surah":2,"verses":[216]},{"surah":4,"verses":[19]}],"verseLabel":"البقرة: 216، النساء: 19","question":"ما سرّ ذكر وجهي الكراهة والمحبة في البقرة، والاكتفاء بوجه الكراهة في النساء؟","answer":"آية البقرة في سياق القتال الذي كرهه المخاطبون وأحبوا السلامة منه؛ فالمقام قائم على بيان طرفي الخير والشر: قد يكون الخير في المكروه، والشر في المحبوب، فناسب ذكر الطرفين. أما النساء ففي معالجة كراهية الزوجة وخشية التسرع في فراقها؛ فالمقصود حبس النفس عن قرار الفراق بسبب المكروه، ولو ذُكر احتمال الشر في المحبوب لفتح للنفس باب الميل إلى غيرها، فاقتصر السياق على الوجه الذي يعالج المشكلة مباشرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص754، تحت «بلاغة التشابه اللفظي في قوله تعالى: «فعسى أن تكرهوا شيئًا ويجعل الله فيه خيرًا كثيرًا»»","url":""}]},{"id":"s2-1071","number":1071,"surah":2,"verses":[216],"references":[{"surah":2,"verses":[216]},{"surah":4,"verses":[19]}],"verseLabel":"البقرة: 216، النساء: 19","question":"ما سرّ اختلاف التعبير بين قوله تعالى في البقرة: ﴿وَهُوَ خَيْرٌ لَكُمْ﴾، وقوله تعالى في النساء: ﴿وَيَجْعَلَ اللَّهُ فِيهِ خَيْرًا كَثِيرًا﴾؟","answer":"في البقرة أخبر عن حقيقة خفية ثابتة في الأمر نفسه: ما تكرهونه من القتال قد يكون خيرًا لكم وإن لم تدركوه الآن؛ فجاء ﴿وهو خير لكم﴾. أما النساء فربط الخير بجعل الله؛ لأن الصبر على الزوجة المكروهة امتثالًا لأمر حسن المعاشرة سبب يجعل الله عاقبته خيرًا كثيرًا، جزاءً على الصبر والامتثال. وزيادة ﴿كثيرًا﴾ تفتح أمام الزوج أبواب خير متعددة لا يراها ساعة الكراهية.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص754، تحت «بلاغة المتشابه اللفظي في قوله تعالى: «فعسى أن تكرهوا شيئا ويجعل الله فيه خيرا كثيرا»»","url":""}]},{"id":"s2-1072","number":1072,"surah":2,"verses":[216],"references":[{"surah":2,"verses":[216]}],"verseLabel":"البقرة: 216","question":"لماذا عُبّر بـ﴿كُتِبَ﴾ في قوله تعالى: ﴿كُتِبَ عَلَيْكُمُ الْقِتَالُ﴾، دون «فُرض»؟","answer":"لزيادة تأكيد الوجوب؛ فالكتابة في معنى التكليف أوثق وأقوى من مجرد الفرض، وذلك يناسب مشقة القتال وما فيه من مفارقة الراحة والأهل.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص366، تحت «السر في استعمال لفظ ﴿كتب﴾ بدل (فرض)»","url":""}]},{"id":"s2-1073","number":1073,"surah":2,"verses":[216],"references":[{"surah":2,"verses":[216]}],"verseLabel":"البقرة: 216","question":"ما سرّ التعبير في قوله تعالى: ﴿وَهُوَ كُرْهٌ لَكُمْ﴾ بالمصدر لا «مكروه»؟","answer":"عبر بالمصدر ﴿كره﴾ للمبالغة في شدة الكراهة وتمكين هذا الوصف من القتال، لما فيه من مشقة وبذل للنفس والمال.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص367، تحت «دلالة التعبير بالمصدر «كره» دون الوصف أو المفعول في قوله تعالى: «وهو كره لكم»»","url":""}]},{"id":"s2-1075","number":1075,"surah":2,"verses":[216],"references":[{"surah":2,"verses":[216]}],"verseLabel":"البقرة: 216","question":"ما سرّ مقابلة الكراهة بالخير والمحبة بالشر، دون «النفع والضر»؟","answer":"اختير لفظا ﴿خير﴾ و﴿شر﴾ لعمومهما وكثرة ما يحملانه من المعاني؛ فرب مكروه تشتمل عاقبته على الخير، ورب محبوب تشتمل عاقبته على الشر، وإن خفي ذلك على الإنسان.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص374، تحت «بلاغة إيجاز القصر في الآية الكريمة»","url":""}]},{"id":"s2-1076","number":1076,"surah":2,"verses":[216],"references":[{"surah":2,"verses":[216]}],"verseLabel":"البقرة: 216","question":"كيف عالجت الآية نفور المؤمنين من القتال المفروض؟","answer":"لم تنكر كراهة النفوس للمشقة، لكنها نبهت إلى أن المكروه قد يحمل خيرًا لا يظهر عاجلًا، وأن المحبوب قد يفضي إلى شر؛ ثم ردت العلم الكامل بالعواقب إلى الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص372، تحت «بديع المقابلة في قوله تعالى: «وعسى أن تكرهوا شيئا وهو خير لكم وعسى أن تحبوا شيئا وهو شر لكم»»","url":""}]},{"id":"s2-1077","number":1077,"surah":2,"verses":[216],"references":[{"surah":2,"verses":[216]}],"verseLabel":"البقرة: 216","question":"ما دلالة حذف مفعول العلم في قوله تعالى: ﴿وَاللَّهُ يَعْلَمُ وَأَنْتُمْ لَا تَعْلَمُونَ﴾؟","answer":"حذف مفعولا ﴿يعلم﴾ و﴿لا تعلمون﴾ للعموم؛ أي إن الله يعلم وجوه الخير والشر وعواقبهما، وأنتم لا تعلمونها، فجاء طباق الإثبات والنفي توكيدًا لهذا الفرق.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص374–375، تحت عنوان «بلاغة الإيجاز بحذف مفعولي ﴿يعلم﴾ و﴿تعلمون﴾»","url":""}]},{"id":"s2-1078","number":1078,"surah":2,"verses":[217],"references":[{"surah":2,"verses":[217]}],"verseLabel":"البقرة: 217","question":"ما سرّ ترتيب السؤال: ﴿يَسْأَلُونَكَ عَنِ الشَّهْرِ الْحَرَامِ قِتَالٍ فِيهِ﴾؟","answer":"قدم الشهر الحرام لأنه موضع اهتمام السائلين، ثم جاء ﴿قتال فيه﴾ بدل اشتمال أو بيانًا للمسؤول عنه؛ فبرزت حرمة الزمن قبل الفعل.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص383، تحت «فائدة بدل الاشتمال في لفظة «قتال»»","url":""}]},{"id":"s2-1079","number":1079,"surah":2,"verses":[217],"references":[{"surah":2,"verses":[217]}],"verseLabel":"البقرة: 217","question":"ما سرّ التعبير في قوله تعالى: ﴿ومن يرتدد﴾ بفك الإدغام، لا: يرتد؟","answer":"الفك هو الأصل ويعطي اللفظ امتدادًا يلائم تصوير الرجوع المتدرج والثبات عليه حتى الموت، مع جواز الإدغام في العربية.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص392، تحت «سر التعبير بصيغة المطاوعة «يرتدد»، وسر مجيئها على طريقة فك الإدغام»","url":""}]},{"id":"s2-1080","number":1080,"surah":2,"verses":[217],"references":[{"surah":2,"verses":[217]}],"verseLabel":"البقرة: 217","question":"ما سرّ مجيء الجواب: ﴿قُلْ قِتَالٌ فِيهِ كَبِيرٌ﴾ دون نفي حرمة القتال؟","answer":"أقر بأن القتال فيه كبير ولم ينف الحرمة؛ ثم وازن بينه وبين جرائم المشركين الأكبر: الصد والكفر والإخراج والفتنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص386، تحت «دلالة الاستعارة في تشبيه القتال بالشيء المحسوس في قوله تعالى: «قتال فيه كبير»»","url":""}]},{"id":"s2-1081","number":1081,"surah":2,"verses":[217],"references":[{"surah":2,"verses":[217]}],"verseLabel":"البقرة: 217","question":"ما سرّ تعداد قوله تعالى: ﴿وَصَدٌّ عَنْ سَبِيلِ اللَّهِ وَكُفْرٌ بِهِ وَالْمَسْجِدِ الْحَرَامِ﴾ بعد الإقرار بكبر القتال؟","answer":"ليبين أن خصومهم اقتطعوا حادثة القتال وأخفوا منظومة جرائمهم: الصد والكفر وانتهاك المسجد والإخراج. وتراكم المصادر يضع الأفعال على ميزان واحد ويكشف الأكبر.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص386، تحت «بديع ترتيب النظم الكريم في قوله تعالى: «وصد عن سبيل الله وكفر به والمسجد الحرام وإخراج أهله»»","url":""}]},{"id":"s2-1082","number":1082,"surah":2,"verses":[217],"references":[{"surah":2,"verses":[217]}],"verseLabel":"البقرة: 217","question":"ما سرّ التعبير في قوله تعالى: ﴿وَإِخْرَاجُ أَهْلِهِ مِنْهُ أَكْبَرُ عِنْدَ اللَّهِ﴾؟","answer":"لأن إخراج المؤمنين من مكة لأجل إسلامهم من أشق المحن، فكان أكبر جرمًا عند الله من القتال الواقع خطأً في الشهر الحرام؛ وصيغة التفضيل تبين تفاوت هذه الكبائر ولا تهون القتال.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص388، تحت «سر تسمية المؤمنين أهلا للمسجد الحرام في قوله تعالى: «وإخراج أهله منه»»","url":""}]},{"id":"s2-1083","number":1083,"surah":2,"verses":[217],"references":[{"surah":2,"verses":[217]}],"verseLabel":"البقرة: 217","question":"ما سرّ التعبير هنا بـ﴿وَالْفِتْنَةُ أَكْبَرُ مِنَ الْقَتْلِ﴾ بعد التعبير سابقًا بـ﴿أَشَدُّ مِنَ الْقَتْلِ﴾؟","answer":"﴿أشد﴾ في الموضع الأول تلحظ قوة الألم والضرر، و﴿أكبر﴾ هنا تلحظ عظم الجرم عند الله بعد تعداد الصد والكفر والإخراج؛ فلكل وصف جهة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص387، تحت «اختيار صيغة أفعل في قوله «أكبر عند الله»، وقوله «والفتنة أكبر من القتل»»","url":""}]},{"id":"s2-1084","number":1084,"surah":2,"verses":[217],"references":[{"surah":2,"verses":[217]}],"verseLabel":"البقرة: 217","question":"ما مناسبة الاعتراض بقوله تعالى: ﴿وَلَا يَزَالُونَ يُقَاتِلُونَكُمْ﴾؟","answer":"لينقل الكلام من حادثة ماضية إلى خطر مستمر: جدلهم عن الشهر ليس حرصًا على الحرمة، بل جزء من حرب لا تنقطع حتى يردوا المؤمنين. والمضارع مع ﴿لا يزالون﴾ يصور الإصرار المتجدد.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص389، تحت «دلالة الالتفات والاعتراض في قوله «ولا يزالون يقاتلونكم»»","url":""}]},{"id":"s2-1085","number":1085,"surah":2,"verses":[217],"references":[{"surah":2,"verses":[217]}],"verseLabel":"البقرة: 217","question":"ما سرّ التعبير في قوله تعالى: ﴿حَتَّى يَرُدُّوكُمْ عَنْ دِينِكُمْ إِنِ اسْتَطَاعُوا﴾؟","answer":"كشف الغاية القصوى لقتالهم: ليست أرضًا أو مالًا فقط، بل رد المؤمن عن دينه؛ ثم قيدها بـ﴿إن استطاعوا﴾ لتحقير قدرتهم وتثبيت المؤمنين مع التحذير من محاولتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص391، تحت «الغرض من تعليق الشرط بـ(إن) في قوله تعالى «إن استطاعوا»»","url":""}]},{"id":"s2-1086","number":1086,"surah":2,"verses":[217],"references":[{"surah":2,"verses":[217]}],"verseLabel":"البقرة: 217","question":"ما الشرط الذي ربطت به الآية حبوط عمل المرتد؟","answer":"ربطت الحبوط بأن يرتد المرء عن دينه ثم يموت وهو ثابت على الكفر؛ فالعبرة بالخاتمة التي لقي الله عليها، لا بمجرد طارئ يعقبه رجوع وتوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص393، تحت «السر في اقتران شرطي الارتداد والموت على الكفر في الآية»","url":""}]},{"id":"s2-1087","number":1087,"surah":2,"verses":[217],"references":[{"surah":2,"verses":[217]}],"verseLabel":"البقرة: 217","question":"ما دلالة تكرار اسم الإشارة في قوله تعالى: ﴿فَأُولَئِكَ حَبِطَتْ أَعْمَالُهُمْ... وَأُولَئِكَ أَصْحَابُ النَّارِ﴾؟","answer":"لأن لكل نتيجة فظاعتها: ضياع العمل في الدارين، ثم ملازمة النار والخلود؛ فأعيدت الإشارة ليستقل الوعيدان. والبعد في ﴿أولئك﴾ يناسب سقوط منزلتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص395، تحت «السر في تكرار اسم الإشارة في قوله تعالى «وأولئك أصحاب النار»»","url":""}]},{"id":"s2-1088","number":1088,"surah":2,"verses":[218],"references":[{"surah":2,"verses":[218]}],"verseLabel":"البقرة: 218","question":"ما سرّ الجمع بين الإيمان والهجرة والجهاد؟","answer":"الإيمان أصل باطن، والهجرة تضحية بالمكان والمألوف، والجهاد بذل للطاقة والنفس؛ فترقى من الاعتقاد إلى مفارقة ثم مواجهة. واجتماعها يثبت صدق الرجاء بالعمل لا بالدعوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص402، تحت «سر ترتيب الأوصاف الثلاثة: الإيمان ثم الهجرة ثم الجهاد»","url":""}]},{"id":"s2-1089","number":1089,"surah":2,"verses":[218],"references":[{"surah":2,"verses":[218]}],"verseLabel":"البقرة: 218","question":"ما سرّ التعبير في قوله تعالى: ﴿أُولَئِكَ يَرْجُونَ رَحْمَتَ اللَّهِ﴾، ولم يجزم لهم بها؟","answer":"الرجاء يجمع حسن الظن مع الخوف والعمل، فلا يغترون بأعمالهم ولا يجزمون لأنفسهم؛ بل يظلون متعلقين بفضل الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص402، تحت «إثبات الرجاء لهم دون الفوز بالرحمة»","url":""}]},{"id":"s2-1090","number":1090,"surah":2,"verses":[218],"references":[{"surah":2,"verses":[218]}],"verseLabel":"البقرة: 218","question":"ما سرّ التعبير بـ﴿رَحْمَتَ اللَّهِ﴾ بدل «ثواب الله»؟","answer":"عبر بـ﴿رحمت الله﴾ لأن العمل لا يوجب الأجر بنفسه، وإنما النجاة والثواب تفضل ورحمة من الله يرجوهما المؤمن بعد قيامه بأسبابهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص402–403، تحت «إثبات الرجاء لهم دون الفوز بالمرجو»","url":""}]},{"id":"s2-1091","number":1091,"surah":2,"verses":[218],"references":[{"surah":2,"verses":[218]}],"verseLabel":"البقرة: 218","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿وَاللَّهُ غَفُورٌ رَحِيمٌ﴾؟","answer":"ختم بـ﴿غفور رحيم﴾؛ فالغفور يستر ما فرط من عباده، والرحيم ينزل بهم الأجر والثواب الذي يرجونه، فجاء الاسمان موافقين لمقام الرجاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص404، تحت «دلالة التذييل بذكر المغفرة والرحمة في قوله تعالى: «والله غفور رحيم»»","url":""}]},{"id":"s2-1092","number":1092,"surah":2,"verses":[219],"references":[{"surah":2,"verses":[219]}],"verseLabel":"البقرة: 219","question":"كيف حسمت الآية الموازنة بين منافع الخمر والميسر وأضرارهما؟","answer":"أقرت بوجود منافع دنيوية فيهما، لكنها قررت أن إثمهما وما يترتب عليهما من فساد أكبر من تلك المنافع؛ فليست العبرة بمجرد وجود المنفعة، بل برجحان الضرر والإثم.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص413، تحت «وجه ذكر منافع الخمر والميسر مع أن سياق التحريم والتمهيد له يقتضي تناسي المنافع»","url":""}]},{"id":"s2-1093","number":1093,"surah":2,"verses":[219],"references":[{"surah":2,"verses":[219]}],"verseLabel":"البقرة: 219","question":"ما مناسبة عطف سؤال الإنفاق على سؤال الخمر والميسر؟","answer":"يجمع السؤالين شأن المال: الميسر أكل مال بالباطل، والإنفاق بذل للمال في الخير. فانتقل من طريق فاسد لاكتسابه إلى طريق صالح لإنفاقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص412، تحت «دلالة العطف وتكرار السؤال في قوله تعالى «ويسألونك ماذا ينفقون قل العفو»»","url":""}]},{"id":"s2-1094","number":1094,"surah":2,"verses":[219],"references":[{"surah":2,"verses":[219]}],"verseLabel":"البقرة: 219","question":"ما سرّ الجمع بين الخمر والميسر في السؤال عنهما؟","answer":"قرن بينهما لاشتراكهما في الضرر وإتلاف العقل والمال؛ فالخمر أشد إفسادًا للعقل، والميسر أشد إتلافًا للمال، وقد قرنهما القرآن كذلك في موضع التحريم.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص409، تحت «سر اقتران الخمر بالميسر، ونكتة تقديم ذكر الخمر على ذكر الميسر»","url":""}]},{"id":"s2-1095","number":1095,"surah":2,"verses":[219],"references":[{"surah":2,"verses":[219]}],"verseLabel":"البقرة: 219","question":"ما سرّ تقديم قوله تعالى: ﴿فِيهِمَا إِثْمٌ كَبِيرٌ﴾ على ذكر المنافع؟","answer":"قدم الإثم لأنه المقصود بالحكم والتحذير، ثم ذكر المنافع إنصافًا وتهيئة للموازنة التي انتهت إلى غلبة الإثم.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص409، تحت «دلالة تقديم الإثم على المنافع»","url":""}]},{"id":"s2-1096","number":1096,"surah":2,"verses":[219],"references":[{"surah":2,"verses":[219]}],"verseLabel":"البقرة: 219","question":"ما الأثر البلاغي لوصف الإثم بأنه ﴿كَبِيرٌ﴾ في قوله تعالى: ﴿فِيهِمَا إِثْمٌ كَبِيرٌ﴾؟","answer":"استُعير وصف الأجسام للإثم، فجُسّد معناه لتفظيعه وتهويل شأنه وتقبيحه إلى النفوس، تنفيرًا من الخمر والميسر.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص410–411، تحت «الاستعارة في وصف الإثم بكونه كبيرًا، وكثيرًا في قوله: ﴿فيهما إثم كبير﴾»","url":""}]},{"id":"s2-1097","number":1097,"surah":2,"verses":[219],"references":[{"surah":2,"verses":[219]}],"verseLabel":"البقرة: 219","question":"ما سرّ التعبير في قوله تعالى: ﴿وَإِثْمُهُمَا أَكْبَرُ مِنْ نَفْعِهِمَا﴾، دون أن يقال: «لا نفع فيهما»؟","answer":"لم ينف نفعهما لأن لهما منافع مادية ولذة يعرفها الناس، لكنه قرر أن إثمهما وضررهما أكبر منها، فكانت الموازنة تمهيدًا لتركهما ثم تحريمهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص411، تحت «السر في ترك وصف المنافع»","url":""}]},{"id":"s2-1098","number":1098,"surah":2,"verses":[219],"references":[{"surah":2,"verses":[219]}],"verseLabel":"البقرة: 219","question":"ما سرّ الجواب بقوله تعالى: ﴿قُلِ الْعَفْوَ﴾ عن سؤالهم: ﴿مَاذَا يُنْفِقُونَ﴾؟","answer":"العفو هو الفاضل السهل الذي يزيد عن الحاجة من غير إجحاف بالنفس والعيال؛ فحدد الجواب القدر المعتدل للإنفاق.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص413، تحت «دلالة التعبير عن الصدقة المستحبة بلفظة العفو»","url":""}]},{"id":"s2-1099","number":1099,"surah":2,"verses":[219],"references":[{"surah":2,"verses":[219]}],"verseLabel":"البقرة: 219","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿كَذَلِكَ يُبَيِّنُ اللَّهُ لَكُمُ الْآيَاتِ لَعَلَّكُمْ تَتَفَكَّرُونَ﴾؟","answer":"كما بين ميزان الخمر والإنفاق يبين سائر الأحكام لتعمل العقول في العواقب، لا لتتلقى أوامر بلا فهم؛ والتفكر يعبر من الدنيا إلى الآخرة كما تكمل الآية التالية. والإشارة تجمع طريقة البيان المتدرج المقنع.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص415، تحت «خروج «لعل» من معنى الترجي إلى التعليل في قوله تعالى: «لعلكم تتفكرون»»","url":""}]},{"id":"s2-1100","number":1100,"surah":2,"verses":[220],"references":[{"surah":2,"verses":[220]}],"verseLabel":"البقرة: 220","question":"ما سرّ التعبير في قوله تعالى في اليتامى ﴿إصلاح لهم خير﴾، دون أن يقال: إصلاحهم خير؟","answer":"اللام في ﴿لهم﴾ تجعل الإصلاح واقعًا لمصلحتهم ونفعهم، أما «إصلاحهم» فقد يوهم أن اليتامى أنفسهم محل الإصلاح لا أموالهم وشؤونهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص432، تحت «نكتة الإيجاز في قوله سبحانه: «قل إصلاح لهم خير»»","url":""}]},{"id":"s2-1101","number":1101,"surah":2,"verses":[220],"references":[{"surah":2,"verses":[220]}],"verseLabel":"البقرة: 220","question":"ما سرّ التعبير عن مخالطة اليتامى بصيغة المفاعلة؟","answer":"لأنها مشاركة متبادلة في الطعام والسكن والمال، لا فعل من طرف واحد؛ وصيغة المفاعلة تصور الحياة المشتركة التي تضبطها الأخوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص428، تحت «فائدة التعبير عن المخالطة بطريق المجاز»","url":""}]},{"id":"s2-1102","number":1102,"surah":2,"verses":[220],"references":[{"surah":2,"verses":[220]}],"verseLabel":"البقرة: 220","question":"ما دلالة حذف مفعول المشيئة في قوله تعالى: ﴿وَلَوْ شَاءَ اللَّهُ لَأَعْنَتَكُمْ﴾؟","answer":"حذف مفعول ﴿شاء﴾ لدلالة السياق ولتعم مشيئة الله النافذة، ثم دل جواب الشرط ﴿لأعنتكم﴾ على أنه لو شاء أن يكلفكم المشقة في مخالطة اليتامى لفعل.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص433، تحت «سر حذف مفعول المشيئة»","url":""}]},{"id":"s2-1103","number":1103,"surah":2,"verses":[220],"references":[{"surah":2,"verses":[220]}],"verseLabel":"البقرة: 220","question":"ما سرّ مجيء ﴿فِي الدُّنْيَا وَالْآخِرَةِ﴾ في أول الآية مع تعلقها بالتفكر قبلها؟","answer":"وصلها بما قبلها ليكون التفكر في مصالح الدارين معًا؛ فلا يحكم الإنسان على الخمر والإنفاق واليتامى بمعيار عاجل فقط. وموقعها بين الآيتين يجسر من قاعدة التفكير إلى تطبيق جديد.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص422، تحت «دلالة ارتباط المطلع بما قبله»","url":""}]},{"id":"s2-1104","number":1104,"surah":2,"verses":[220],"references":[{"surah":2,"verses":[220]}],"verseLabel":"البقرة: 220","question":"ما سرّ تكرار ﴿وَيَسْأَلُونَكَ عَنِ الْيَتَامَى﴾ بعد سؤالي الخمر والإنفاق؟","answer":"تتوالى الأسئلة لتكشف حاجتهم إلى بيان ينظم المال والمجتمع، وسؤال اليتامى نشأ من الخوف من مخالطة أموالهم بعد الوعيد. والمضارع يصور تجدد السؤال عند نزول الأحكام.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص424، تحت «بلاغة التصريح بلفظ السؤال»","url":""}]},{"id":"s2-1105","number":1105,"surah":2,"verses":[220],"references":[{"surah":2,"verses":[220]}],"verseLabel":"البقرة: 220","question":"ما سرّ إجمال الجواب بقوله تعالى: ﴿قُلْ إِصْلَاحٌ لَهُمْ خَيْرٌ﴾ دون تفصيل صور التصرف؟","answer":"أعطى معيارًا جامعًا هو الإصلاح؛ لأن صور التصرف تتغير باختلاف الأحوال، والعبرة بأن يكون العمل محققًا لمصلحة اليتيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص425، تحت «بلاغة التعبير عن الإصلاح بلفظ المصدر منكرا»","url":""}]},{"id":"s2-1106","number":1106,"surah":2,"verses":[220],"references":[{"surah":2,"verses":[220]}],"verseLabel":"البقرة: 220","question":"ما سرّ التعبير في قوله تعالى: ﴿وَإِنْ تُخَالِطُوهُمْ فَإِخْوَانُكُمْ﴾؟","answer":"المخالطة جائزة إذا قامت على الأخوة؛ فأنتم وإياهم أسرة إيمانية، لا أصحاب أموال منفصلة يعاملون بالحرج أو الاستغلال.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص429، تحت «جمالية التشبيه البليغ في التعبير عن الأخوة»","url":""}]},{"id":"s2-1107","number":1107,"surah":2,"verses":[220],"references":[{"surah":2,"verses":[220]}],"verseLabel":"البقرة: 220","question":"ما سرّ التعبير في قوله تعالى: ﴿فَإِخْوَانُكُمْ﴾، دون أن يقال: «فلا جناح عليكم»؟","answer":"قوله ﴿فإخوانكم﴾ أرفع من مجرد نفي الجناح؛ إذ يثبت رابطة توجب النصيحة والرعاية والمساواة، لا مجرد إباحة المخالطة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص428، تحت «فائدة التعبير عن المخالطة بطريق المجاز»","url":""}]},{"id":"s2-1108","number":1108,"surah":2,"verses":[220],"references":[{"surah":2,"verses":[220]}],"verseLabel":"البقرة: 220","question":"ما دلالة التضمين في قوله تعالى: ﴿والله يعلم المفسد من المصلح﴾؟","answer":"ضُمّن العلم معنى التمييز، فالمعنى أن الله يعرف من يقصد بمخالطة اليتامى الخيانة والإفساد مميزًا له ممن يقصد الإصلاح، ويجازي كلًا بعمله؛ ففيه وعد ووعيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص430، تحت عنوان «دلالة التضمين في لفظ العلم»","url":""}]},{"id":"s2-1521","number":1521,"surah":2,"verses":[220],"references":[{"surah":2,"verses":[220]}],"verseLabel":"البقرة: 220","question":"لماذا قُدّم المفسد على المصلح في قوله تعالى: ﴿والله يعلم المفسد من المصلح﴾؟","answer":"لزيادة التهديد وتأكيد الوعيد؛ فمقام أموال اليتامى يقتضي شدة الورع والتحذير من التعدي، وذُكر المفسد أولًا ليقع الإمساك عن الإفساد.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص431، تحت عنوان «نكتة تقديم المفسد على المصلح»","url":""}]},{"id":"s2-1109","number":1109,"surah":2,"verses":[220],"references":[{"surah":2,"verses":[220]}],"verseLabel":"البقرة: 220","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿وَلَوْ شَاءَ اللَّهُ لَأَعْنَتَكُمْ إِنَّ اللَّهَ عَزِيزٌ حَكِيمٌ﴾؟","answer":"ذكّرهم أن الله قادر على التشديد لكنه خفف بحكمته؛ فهو عزيز لا يعجزه الإعنات، حكيم يضع التيسير موضعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص434، تحت «دلالة الجمع بين اسمي الله تعالى: العزيز والحكيم»","url":""}]},{"id":"s2-1110","number":1110,"surah":2,"verses":[221],"references":[{"surah":2,"verses":[221]}],"verseLabel":"البقرة: 221","question":"ما سرّ التعبير في قوله تعالى: ﴿ولأمة مؤمنة خير من مشركة ولو أعجبتكم﴾؟","answer":"قلب ميزان الجمال والحرية والمكانة: أدنى مؤمنة اجتماعيًا خير من مشركة بالغة الإعجاب، لأن العقيدة تحفظ البيت والمصير.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص443، تحت «قرينة المقابلة بين المؤمنة والمشركة»","url":""}]},{"id":"s2-1111","number":1111,"surah":2,"verses":[221],"references":[{"surah":2,"verses":[221]}],"verseLabel":"البقرة: 221","question":"ما سرّ التعبير في قوله تعالى: ﴿حتى يؤمن﴾ بـ﴿حتى﴾ لا ﴿إلى أن﴾؟","answer":"﴿حتى﴾ تجعل الإيمان غاية ينتهي عند تحققها المنع، وتوحي بأن تبدل العقيدة انتقال حقيقي لا مرور زمن فقط.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص442، تحت «سر التعبير بحرف الغاية «حتى» دون (إلى)»","url":""}]},{"id":"s2-1112","number":1112,"surah":2,"verses":[221],"references":[{"surah":2,"verses":[221]}],"verseLabel":"البقرة: 221","question":"ما دلالة تقديم اسم الله في قوله تعالى: ﴿وَاللَّهُ يَدْعُو إِلَى الْجَنَّةِ وَالْمَغْفِرَةِ﴾؟","answer":"قُدّم اسم الله للترغيب في الإقبال عليه، وتقوية الحكم وتقريره، وتربية المهابة في النفوس بإبراز جلال الداعي؛ فتدعو مهابته إلى اجتناب نواهيه وتحري ما هو أسلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص449، تحت عنوان «سر تقديم الاسم الأحسن ﴿الله﴾ على الفعل»","url":""}]},{"id":"s2-1113","number":1113,"surah":2,"verses":[221],"references":[{"surah":2,"verses":[221]}],"verseLabel":"البقرة: 221","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلَأَمَةٌ مُؤْمِنَةٌ خَيْرٌ مِنْ مُشْرِكَةٍ﴾ مع أن المقارنة بين حرة وأمة؟","answer":"ليقلب ميزان الاختيار من المكانة الاجتماعية والجمال إلى الإيمان؛ فأدنى المؤمنات منزلة في عرف الناس خير من مشركة أعجبتهم. والمبالغة في الطرفين تجعل أولوية العقيدة أوضح.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص443، تحت «قرينة المقابلة بين المؤمنة والمشركة»","url":""}]},{"id":"s2-1114","number":1114,"surah":2,"verses":[221],"references":[{"surah":2,"verses":[221]}],"verseLabel":"البقرة: 221","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلَوْ أَعْجَبَتْكُمْ﴾؟","answer":"لأن الإعجاب هو المدخل الأقوى الذي قد يغطي على اختلاف العقيدة؛ فجاء الشرط مستوعبًا أقصى دواعي الرغبة ليقرر أن البريق العاجل لا يساوي سلامة البيت والدين.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص445، تحت «دلالة التعبير بـ﴿ولو﴾»","url":""}]},{"id":"s2-1115","number":1115,"surah":2,"verses":[221],"references":[{"surah":2,"verses":[221]}],"verseLabel":"البقرة: 221","question":"ما سرّ اختلاف البناء بين ﴿لَا تَنْكِحُوا الْمُشْرِكَاتِ﴾ و﴿لَا تُنْكِحُوا الْمُشْرِكِينَ﴾؟","answer":"الأول نهي الرجال عن الزواج، والثاني نهي الأولياء عن تزويج المؤمنات؛ فغيّر الفعل من الثلاثي إلى الرباعي لأن جهة التصرف تغيرت. وبذلك شمل الحكم طرفي الأسرة بعبارة دقيقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص454، تحت «دلالة فتح حرف المضارعة وضمه في فعل النكاح»","url":""}]},{"id":"s2-1116","number":1116,"surah":2,"verses":[221],"references":[{"surah":2,"verses":[221]}],"verseLabel":"البقرة: 221","question":"ما سرّ التعبير في قوله تعالى في الرجل: ﴿وَلَعَبْدٌ مُؤْمِنٌ خَيْرٌ مِنْ مُشْرِكٍ﴾؟","answer":"كرر الحكم في صورة الرجل تأكيدًا له، ودفعًا لتوهم اختصاصه بزواج الرجل من المشركة؛ فالعلة واحدة في الصورتين، وهي ما تجر إليه المخالطة من الدعوة إلى النار. فالمعيار الإيماني معتبر في اختيار الزوج كما هو معتبر في اختيار الزوجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص446، تحت عنوان «دلالة تكرار الحكم في قوله: ﴿ولا تنكحوا المشركين﴾»","url":""}]},{"id":"s2-1117","number":1117,"surah":2,"verses":[221],"references":[{"surah":2,"verses":[221]}],"verseLabel":"البقرة: 221","question":"ما سرّ التعبير في قوله تعالى عن المشركين: ﴿أُولَئِكَ يَدْعُونَ إِلَى النَّارِ﴾؟","answer":"أشار إليهم باسم البعيد إبعادًا لطريقهم، وجعل أثر الزواج بهم دعوة إلى النار لأن المخالطة والمودة تنقل الاعتقاد والسلوك إلى الأسرة والذرية؛ فالخطر أبعد من الشخصين.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص448، تحت «علة التعبير بالمجاز المرسل في لفظ الدعاء إلى النار وإلى الجنة والمغفرة»","url":""}]},{"id":"s2-1118","number":1118,"surah":2,"verses":[221],"references":[{"surah":2,"verses":[221]}],"verseLabel":"البقرة: 221","question":"ما سرّ مقابلة دعوة المشركين بقوله تعالى: ﴿وَاللَّهُ يَدْعُو إِلَى الْجَنَّةِ وَالْمَغْفِرَةِ﴾؟","answer":"وضع نهايتي الطريقين وجهًا لوجه: زواج يجر إلى النار، وأمر إلهي يقود إلى الجنة والمغفرة. وذكر المغفرة قبل دخول الجنة معنىً؛ إذ لا وصول إلى النعيم إلا بعد تطهير الذنب.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص450، تحت «فائدة المقابلة بين دعوة المشركين ودعوة الله تعالى»","url":""}]},{"id":"s2-1119","number":1119,"surah":2,"verses":[221],"references":[{"surah":2,"verses":[221]}],"verseLabel":"البقرة: 221","question":"ما دلالة تقييد الدعوة إلى الجنة والمغفرة بقوله تعالى: ﴿بإذنه﴾؟","answer":"يشمل الإذن الأمر والإعلام والإرادة والتوفيق والتيسير؛ فالله يبين للناس طريق الجنة والمغفرة ويأمرهم بسلوكه، واستجابتهم لدعوته إنما تكون بتيسيره وتوفيقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص451، تحت عنوان «نكتة تقييد الدعاء إلى الجنة بالإذن»","url":""}]},{"id":"s2-1522","number":1522,"surah":2,"verses":[221],"references":[{"surah":2,"verses":[221]}],"verseLabel":"البقرة: 221","question":"ما دلالة صيغة ﴿يتذكرون﴾ في ختام آية النهي عن نكاح المشركين؟","answer":"تناسب صيغة «يتذكرون» طول التدبر وعمق التأمل وإطالة النظر اللازم لفهم الآيات والاتعاظ بها. والتعبير بالمضارع يحث على تكرار التذكر وتجديده بتجدد الآيات.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص452–453، تحت عنوان «قصدية التعبير بلفظ التذكر دون غيره»","url":""}]},{"id":"s2-1120","number":1120,"surah":2,"verses":[222],"references":[{"surah":2,"verses":[222]}],"verseLabel":"البقرة: 222","question":"ما سرّ وصف المحيض بأنه ﴿أَذًى﴾ دون «مرض» أو «نجاسة»؟","answer":"الأذى أعم من المرض والنجاسة، ويصف الضرر والمشقة الملازمين للحال من غير أن يجعل المرأة نفسها موضع تنفير.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص465، تحت «نكتة الإخبار عن الحيض بالأذى»","url":""}]},{"id":"s2-1121","number":1121,"surah":2,"verses":[222],"references":[{"surah":2,"verses":[222]}],"verseLabel":"البقرة: 222","question":"ما سرّ التعبير في قوله تعالى: ﴿فَاعْتَزِلُوا النِّسَاءَ فِي الْمَحِيضِ﴾، دون أن يقال: «فاعتزلوا النساء» فقط؟","answer":"لفظ المحيض يحتمل الحيض نفسه ووقته وموضعه؛ فتجتمع دلالاته على تجنب موضع الحيض مدة الحيض، مع بقاء التمتع بالمرأة فيما عدا ذلك. فالقيد يحدد المراد بالاعتزال ولا يجعله هجرًا للمرأة في جميع أحوالها.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص464، تحت عنوان «قصدية اختيار لفظ المحيض»","url":""}]},{"id":"s2-1122","number":1122,"surah":2,"verses":[222],"references":[{"surah":2,"verses":[222]}],"verseLabel":"البقرة: 222","question":"ما سرّ توجيه جواب سؤال المحيض إلى بيان أنه ﴿أَذًى﴾؟","answer":"وجه الجواب إلى علة الحكم التي يحتاجون إليها: المحيض أذى، ولذلك شرع اعتزال موضعه؛ فلم يكن المقصود وصفًا طبيًا مجردًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص465، تحت «نكتة الإخبار عن الحيض بالأذى»","url":""}]},{"id":"s2-1124","number":1124,"surah":2,"verses":[222],"references":[{"surah":2,"verses":[222]}],"verseLabel":"البقرة: 222","question":"ما سرّ إتباع الاعتزال بقوله تعالى: ﴿وَلَا تَقْرَبُوهُنَّ﴾؟","answer":"الاعتزال قد يفهم على وجه مجمل، فجاء ﴿ولا تقربوهن﴾ لتأكيد منع الجماع ومقدماته في موضع الحيض.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص467، تحت «علة توكيد منع القربان»","url":""}]},{"id":"s2-1125","number":1125,"surah":2,"verses":[222],"references":[{"surah":2,"verses":[222]}],"verseLabel":"البقرة: 222","question":"ما سرّ اختلاف التعبير بين ﴿حَتَّى يَطْهُرْنَ﴾ و﴿فَإِذَا تَطَهَّرْنَ﴾؟","answer":"﴿يطهرن﴾ يدل على انقطاع دم الحيض، و﴿تطهرن﴾ يدل على فعل التطهر بالغسل؛ فجمع بين زوال الأذى وحصول الطهارة الشرعية.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص469، تحت «براعة الاحتباك في جملة الطهارة»","url":""}]},{"id":"s2-1126","number":1126,"surah":2,"verses":[222],"references":[{"surah":2,"verses":[222]}],"verseLabel":"البقرة: 222","question":"ما سرّ التعبير في قوله تعالى: ﴿فَأْتُوهُنَّ مِنْ حَيْثُ أَمَرَكُمُ اللَّهُ﴾؟","answer":"أباح المعاشرة بعد الطهر لكنه أبقاها في الحد الذي شرعه الله، فليست الإباحة مطلقة في كل موضع أو كيفية. والتعبير يربط أخص شؤون الحياة بأمر الله لا بمجرد الشهوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص474–475، تحت «دلالة الظرف «حيث»؛ وحاصل جماع معاني الحرف «من» والظرف «حيث»»","url":""}]},{"id":"s2-1127","number":1127,"surah":2,"verses":[222],"references":[{"surah":2,"verses":[222]}],"verseLabel":"البقرة: 222","question":"ما سرّ التعبير في قوله تعالى: ﴿إِنَّ اللَّهَ يُحِبُّ التَّوَّابِينَ﴾ في سياق أحكام الحيض؟","answer":"جاءت ﴿إن الله يحب التوابين﴾ عقب النهي لتفتح باب الرجوع لمن وقع في المحظور، ولتحث بصيغة المبالغة على تجديد التوبة كلما تجدد الذنب من غير يأس من رحمة الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص477، تحت «بلاغة حذف متعلقي التوبة والتطهر»","url":""}]},{"id":"s2-1128","number":1128,"surah":2,"verses":[222],"references":[{"surah":2,"verses":[222]}],"verseLabel":"البقرة: 222","question":"ما سرّ الجمع بين ﴿التَّوَّابِينَ﴾ و﴿الْمُتَطَهِّرِينَ﴾؟","answer":"التوبة طهارة الباطن من الذنب، والتطهر طهارة الظاهر من الأذى؛ فجمع الاسمان كمال النظافة الحسية والمعنوية.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص477، تحت «نكتة تقديم التوابين على المتطهرين»","url":""}]},{"id":"s2-1129","number":1129,"surah":2,"verses":[223],"references":[{"surah":2,"verses":[223]}],"verseLabel":"البقرة: 223","question":"ما سرّ التعبير في قوله تعالى: ﴿فأتوا حرثكم أنى شئتم﴾ لا: كيف شئتم؟","answer":"﴿أنى﴾ أوسع في الهيئات والأزمنة المباحة، لكن لفظ ﴿حرثكم﴾ يقيدها بموضع الحرث؛ فالتوسعة داخل الحد لا خارجه.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص490، تحت «بيان التشبيه التمثيلي في «فأتوا حرثكم أنى شئتم»»","url":""}]},{"id":"s2-1130","number":1130,"surah":2,"verses":[223],"references":[{"surah":2,"verses":[223]}],"verseLabel":"البقرة: 223","question":"ما سرّ تشبيه النساء بالحرث في قوله تعالى: ﴿نِسَاؤُكُمْ حَرْثٌ لَكُمْ﴾؟","answer":"الحرث موضع الإنبات والنسل، فشبه به موضع الولد من المرأة؛ وفي التشبيه توجيه إلى مقصد العلاقة وموضعها المشروع.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص487، تحت «وجه تشبيه النساء بالحرث»","url":""}]},{"id":"s2-1131","number":1131,"surah":2,"verses":[223],"references":[{"surah":2,"verses":[223]}],"verseLabel":"البقرة: 223","question":"ما دلالة إعادة لفظ ﴿حَرْثَكُمْ﴾ في قوله تعالى: ﴿فَأْتُوا حَرْثَكُمْ﴾؟","answer":"إعادة اللفظ تقيد الإباحة بالموضع الذي يتحقق فيه معنى الحرث والإنجاب؛ فلا تُفهم ﴿أنى شئتم﴾ إذنًا في غيره. والتكرار يثبت الصورة التي عليها مدار الحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص490، تحت «نكتة الإظهار في مقام الإضمار»","url":""}]},{"id":"s2-1132","number":1132,"surah":2,"verses":[223],"references":[{"surah":2,"verses":[223]}],"verseLabel":"البقرة: 223","question":"ما وجه قوله تعالى: ﴿أَنَّى شِئْتُمْ﴾ مع وجود حدود للمعاشرة؟","answer":"﴿أنى﴾ تحتمل كيف ومن أين، والمراد تنوع الهيئة والجهة ما دام الإتيان في موضع الحرث المشروع؛ فلا ترفع القيود المبينة في السياق.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص490، تحت «دلالة التعبير بـ«أنى»»","url":""}]},{"id":"s2-1133","number":1133,"surah":2,"verses":[223],"references":[{"surah":2,"verses":[223]}],"verseLabel":"البقرة: 223","question":"ما مناسبة الانتقال من المعاشرة إلى قوله تعالى: ﴿وَقَدِّمُوا لِأَنْفُسِكُمْ﴾؟","answer":"لينتقل من اللذة العاجلة إلى ما يقدمه الإنسان لنفسه عند الله؛ فالمفعول المحذوف يعم العمل الصالح، ويدخل فيه طلب الولد الصالح وذكر الله عند المعاشرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص494، تحت «دلالة عطف الجملة على ما قبلها»","url":""}]},{"id":"s2-1134","number":1134,"surah":2,"verses":[223],"references":[{"surah":2,"verses":[223]}],"verseLabel":"البقرة: 223","question":"ما مناسبة إتباع الإباحة بقوله تعالى: ﴿وَاتَّقُوا اللَّهَ وَاعْلَمُوا أَنَّكُمْ مُلَاقُوهُ﴾؟","answer":"لأن الخلوة قد توهم غياب الرقابة، فاستحضر التقوى واللقاء ليضبطا استعمال المباح وحدوده. و﴿اعلموا﴾ تنقل حقيقة الآخرة إلى يقين حاضر يراقب به الإنسان نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص495، تحت «سر ترتيب الجمل المتعاطفة»","url":""}]},{"id":"s2-1135","number":1135,"surah":2,"verses":[223],"references":[{"surah":2,"verses":[223]}],"verseLabel":"البقرة: 223","question":"ما مناسبة ختم الأحكام الأسرية بقوله تعالى: ﴿وَبَشِّرِ الْمُؤْمِنِينَ﴾؟","answer":"لأن من امتثل الحدود الخفية في علاقته الخاصة دل على صدق إيمانه، فاستحق البشارة. وحذف المبشر به يعم خير الدنيا والآخرة ويترك النفس متطلعة إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص498، تحت «حسن الابتداء والختام في الآية الكريمة»","url":""}]},{"id":"s2-1136","number":1136,"surah":2,"verses":[224],"references":[{"surah":2,"verses":[224]}],"verseLabel":"البقرة: 224","question":"ما الذي تنهى عنه جملة ﴿وَلَا تَجْعَلُوا اللَّهَ عُرْضَةً لِأَيْمَانِكُمْ﴾؟","answer":"تنهى عن اتخاذ الحلف بالله ذريعة تمنع صاحبها من البر والتقوى والإصلاح بين الناس؛ فلا يجعل يمينه حاجزًا عن الخير، بل يكفر عنها ويفعل ما هو أصلح.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص504، تحت «بلاغة الاستعارة في التعبير بلفظ «عرضة»»","url":""}]},{"id":"s2-1137","number":1137,"surah":2,"verses":[224],"references":[{"surah":2,"verses":[224]}],"verseLabel":"البقرة: 224","question":"لماذا سُمّي الحلف يمينًا، كما في قوله تعالى: ﴿لِأَيْمَانِكُمْ﴾؟","answer":"أصل اليمين اليد، وسُمّي الحلف يمينًا لما جرت به عادة المتعاهدين من المصافحة ووضع أيمانهم بعضها في بعض؛ ثم شاع اللفظ في كل حلف، ولو لم تصحبه مصافحة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص505، تحت «نكتة التعبير بالأيمان»","url":""}]},{"id":"s2-1138","number":1138,"surah":2,"verses":[224],"references":[{"surah":2,"verses":[224]}],"verseLabel":"البقرة: 224","question":"ما وجه قوله تعالى: ﴿أَنْ تَبَرُّوا وَتَتَّقُوا﴾ مع النهي عن جعل الله عرضة للأيمان؟","answer":"أي لا تجعلوا أيمانكم بالله مانعًا من أن تبروا وتتقوا وتصلحوا؛ فالمصدر المؤول متعلق بالنهي وبيان لما ينبغي ألا يحجبه الحلف.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص506، تحت «وجوه تعدد إعراب الصلة»","url":""}]},{"id":"s2-1139","number":1139,"surah":2,"verses":[224],"references":[{"surah":2,"verses":[224]}],"verseLabel":"البقرة: 224","question":"ما سرّ ترتيب البر والتقوى والإصلاح بين الناس؟","answer":"رتبت الأفعال من العام إلى الأخص: فالبر اسم جامع لأفعال الخير، والتقوى أخص منه، والإصلاح بين الناس صورة أخص ذات نفع متعدٍّ، فزاد ذكرها تنويهًا بشأنها.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص508، تحت «علة ترتيب الأفعال»","url":""}]},{"id":"s2-1140","number":1140,"surah":2,"verses":[224],"references":[{"surah":2,"verses":[224]}],"verseLabel":"البقرة: 224","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿وَاللَّهُ سَمِيعٌ عَلِيمٌ﴾؟","answer":"اليمين قول يسمعه الله، والنية التي وراءها سر يعلمه؛ فجمع الاسمان ظاهر الحلف وباطنه. والخاتمة تمنع الاحتيال بعبارات تبدو خيرًا وقصدها غير ذلك.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص508، تحت «سر التذييل في قوله: «والله سميع عليم»»","url":""}]},{"id":"s2-1141","number":1141,"surah":2,"verses":[225],"references":[{"surah":2,"verses":[225]}],"verseLabel":"البقرة: 225","question":"ما سرّ ختم حكم لغو الأيمان بـ﴿غَفُورٌ حَلِيمٌ﴾ دون ﴿غفور رحيم﴾؟","answer":"الغفور يناسب تجاوز لغو اليمين، والحليم يناسب عدم المعاجلة بالمؤاخذة على ما لم يعقده القلب؛ فالمقام عفو وإمهال لا مجرد رحمة عامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص521، تحت «بلاغة تشابه الأطراف في الآية الكريمة»","url":""}]},{"id":"s2-1142","number":1142,"surah":2,"verses":[225],"references":[{"surah":2,"verses":[225]},{"surah":5,"verses":[89]}],"verseLabel":"البقرة: 225، المائدة: 89","question":"ما سرّ اختلاف التعبير بين قوله تعالى في البقرة عن الأيمان: ﴿بِمَا كَسَبَتْ قُلُوبُكُمْ﴾، وقوله تعالى في المائدة: ﴿بِمَا عَقَّدْتُمُ الْأَيْمَانَ﴾؟","answer":"﴿كسبت قلوبكم﴾ في البقرة أعم من كل قصد وعزم باطني في اليمين، و﴿عقدتم الأيمان﴾ في المائدة أخص باليمين المؤكدة المعقودة التي تجب فيها الكفارة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص576، تحت «سر التعبير بكسب القلوب في البقرة وتعقيد الأيمان في المائدة»","url":""}]},{"id":"s2-1143","number":1143,"surah":2,"verses":[225],"references":[{"surah":2,"verses":[225]}],"verseLabel":"البقرة: 225","question":"ما سرّ التعبير في قوله تعالى: ﴿لَا يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ فِي أَيْمَانِكُمْ﴾؟","answer":"رفع المؤاخذة عما يجري بلا قصد عقد القلب، لأن التكليف يتعلق بالإرادة لا بمجرد صوت اللسان. وتعبير ﴿في أيمانكم﴾ يجعل اللغو واقعًا ضمن كلام القسم لا يمينًا مقصودة في ذاته.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص517، تحت «الاستعارة في قوله «باللغو في أيمانكم»»","url":""}]},{"id":"s2-1144","number":1144,"surah":2,"verses":[225],"references":[{"surah":2,"verses":[225]}],"verseLabel":"البقرة: 225","question":"ما سرّ مقابلة اللغو بقوله تعالى: ﴿بِمَا كَسَبَتْ قُلُوبُكُمْ﴾؟","answer":"اللغو ما يجري بلا قصد، فقابله بما تعمدته القلوب واكتسبته؛ فمحل المؤاخذة القصد لا مجرد حركة اللسان.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص519، تحت «كسب القلب كناية عن التعمد في حنث اليمين»","url":""}]},{"id":"s2-1145","number":1145,"surah":2,"verses":[225],"references":[{"surah":2,"verses":[225]}],"verseLabel":"البقرة: 225","question":"ما مناسبة ختم الآية بـ﴿غَفُورٌ حَلِيمٌ﴾ بدل ﴿سميع عليم﴾ المذكورة قبلها؟","answer":"بعد نفي المؤاخذة عن اللغو ناسبت المغفرة ما يقع من خلل، والحلم تأخير العقوبة وعدم العجلة على العبد؛ أما الآية السابقة فمقامها مراقبة القول والقصد.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص522، تحت «التذييل في قوله: «والله غفور حليم»»","url":""}]},{"id":"s2-1146","number":1146,"surah":2,"verses":[226],"references":[{"surah":2,"verses":[226]}],"verseLabel":"البقرة: 226","question":"ما دلالة تقديم ﴿لِلَّذِينَ يُؤْلُونَ مِنْ نِسَائِهِمْ﴾ قبل ذكر الحكم؟","answer":"قدم ﴿للذين يؤلون من نسائهم﴾ على الحكم تشويقًا إلى ما سيُذكر لهم، واهتمامًا بالتوسعة التي شرعها الله في مهلة الإيلاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص527، تحت «دلالة تقديم الجار والمجرور على المسند إليه»","url":""}]},{"id":"s2-1147","number":1147,"surah":2,"verses":[226],"references":[{"surah":2,"verses":[226]}],"verseLabel":"البقرة: 226","question":"ما سرّ التعبير في قوله تعالى: ﴿يُؤْلُونَ مِنْ نِسَائِهِمْ﴾، دون أن يقال: «يحلفون ألا يقربوهن»؟","answer":"اختار لفظ الإيلاء الجامع المعروف لهذا النوع من اليمين، ثم قيده بالنساء ليكشف أثره الأسري. والإيجاز يحول ممارسة جاهلية مفتوحة إلى حكم منضبط.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص530، تحت «يؤلون ويحلفون»","url":""}]},{"id":"s2-1148","number":1148,"surah":2,"verses":[226],"references":[{"surah":2,"verses":[226]}],"verseLabel":"البقرة: 226","question":"لماذا عبّر بـ﴿تَرَبُّصُ أَرْبَعَةِ أَشْهُرٍ﴾؟","answer":"التربص انتظار مقصود مع مراقبة العاقبة، وحد بأربعة أشهر حتى لا تبقى الزوجة معلقة بلا معاشرة ولا طلاق.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص528، تحت «إضافة المصدر إلى الظرف على الاتساع»","url":""}]},{"id":"s2-1149","number":1149,"surah":2,"verses":[226],"references":[{"surah":2,"verses":[226]}],"verseLabel":"البقرة: 226","question":"ما سرّ التعبير في قوله تعالى: ﴿فَإِنْ فَاءُوا﴾، وما الذي يوحي به لفظ الفيء؟","answer":"الفيء رجوع إلى ما ينبغي بعد عدول عنه، فكأن العشرة هي الأصل الذي يعود إليه الزوج. واللفظ يحمل معنى التصحيح والعودة لا مجرد إنهاء الامتناع.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص529، تحت «دلالة تعليق الفعل بحرف الشرط «إن» في قوله: «فإن فاءوا»»","url":""}]},{"id":"s2-1150","number":1150,"surah":2,"verses":[226],"references":[{"surah":2,"verses":[226]}],"verseLabel":"البقرة: 226","question":"ما مناسبة ختم الرجوع بقوله تعالى: ﴿فَإِنَّ اللَّهَ غَفُورٌ رَحِيمٌ﴾؟","answer":"لأن الفيء يفتح باب إصلاح ما أفسده الحلف؛ فالمغفرة تمحو الذنب والرحمة تعيد المودة وترفع الحرج. وجواب الشرط المحذوف يفهم من هذه البشارة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص529، تحت «نكتة التأكيد في قوله تعالى: «فإن الله غفور رحيم»»","url":""}]},{"id":"s2-1151","number":1151,"surah":2,"verses":[227],"references":[{"surah":2,"verses":[227]}],"verseLabel":"البقرة: 227","question":"ما سرّ التعبير في قوله تعالى: ﴿وَإِنْ عَزَمُوا الطَّلَاقَ﴾، دون أن يقال: «وإن طلقوا»؟","answer":"ذكر العزم لأن القضية بعد مهلة تفكير: المطلوب قرار جاد لا تهديد متكرر أو تعليق. وإضافة العزم إلى الطلاق تصور انتقاله من خاطر إلى اختيار محسوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص534، تحت «بلاغة التضمين في قوله «وإن عزموا الطلاق»»","url":""}]},{"id":"s2-1152","number":1152,"surah":2,"verses":[227],"references":[{"surah":2,"verses":[227]}],"verseLabel":"البقرة: 227","question":"أين جواب الشرط في ﴿وَإِنْ عَزَمُوا الطَّلَاقَ﴾؟","answer":"جواب الشرط محذوف لدلالة المقابلة والسياق، وتقديره: فإن عزموا الطلاق فليوقعوه؛ فالعزم قرار يسبق الإيقاع، ولا يقتضي اللفظ وحده حسم الخلاف الفقهي في وقوع الطلاق.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص534، تحت «دلالة حذف جواب الشرط في قوله: «وإن عزموا الطلاق»»","url":""}]},{"id":"s2-1153","number":1153,"surah":2,"verses":[227],"references":[{"surah":2,"verses":[227]}],"verseLabel":"البقرة: 227","question":"ما سرّ اختلاف الخاتمة بين الطلاق: ﴿سَمِيعٌ عَلِيمٌ﴾، والرجوع: ﴿غَفُورٌ رَحِيمٌ﴾؟","answer":"الفيء رجوع إلى المعاشرة والإصلاح فناسبه الغفران والرحمة، أما عزم الطلاق فعمل وقول خفيان أو معلنان فناسبهما السمع والعلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص536، تحت «قول الله تعالى: «فإن الله سميع عليم» بين بلاغة التذييل وبراعة تشابه الأطراف»","url":""}]},{"id":"s2-1154","number":1154,"surah":2,"verses":[228],"references":[{"surah":2,"verses":[228]}],"verseLabel":"البقرة: 228","question":"ما سرّ التعبير في قوله تعالى: ﴿بأنفسهن﴾ مع أن التربص لا يكون إلا منهن؟","answer":"يؤكد أنهن يحبسن رغبة النفس ويشاركن بوعي في حفظ النسب والحقوق، فلا يلقين المسؤولية على رقابة خارجية.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص546، تحت «تقديم الجار والمجرور «بأنفسهن» على المفعول «ثلاثة»»","url":""}]},{"id":"s2-1155","number":1155,"surah":2,"verses":[228],"references":[{"surah":2,"verses":[228]}],"verseLabel":"البقرة: 228","question":"ما سرّ التعبير في قوله تعالى: ﴿وللرجال عليهن درجة﴾ بعد تقرير الحقوق المتبادلة؟","answer":"ذكر الدرجة بعد المماثلة حتى لا تُفهم المماثلة مساواة مطلقة من كل وجه؛ فللرجل مزية ومسؤولية زائدة قررها الشرع، مع بقاء أصل تبادل الحقوق بالمعروف.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص559، تحت «دلالة الاحتراس في قوله: «وللرجال عليهن درجة»»","url":""}]},{"id":"s2-1156","number":1156,"surah":2,"verses":[228],"references":[{"surah":2,"verses":[228]}],"verseLabel":"البقرة: 228","question":"ما سرّ التعبير في قوله تعالى: ﴿وَالْمُطَلَّقَاتُ يَتَرَبَّصْنَ بِأَنْفُسِهِنَّ﴾ بدل «يُتربص بهن»؟","answer":"أسند التربص إليهن بصيغة الخبر للمبالغة في إلزامهن به، وأضاف ﴿بأنفسهن﴾ لتأكيد مباشرتهن حبس دواعي النفس والصبر حتى تمام العدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص545، تحت «دلالة البناء في قوله: «والمطلقات يتربصن بأنفسهن»»","url":""}]},{"id":"s2-1157","number":1157,"surah":2,"verses":[228],"references":[{"surah":2,"verses":[228]}],"verseLabel":"البقرة: 228","question":"ما سرّ التعبير بـ﴿ثَلَاثَةَ قُرُوءٍ﴾ دون «ثلاث قروء»؟","answer":"أُنث العدد ﴿ثلاثة﴾ لأن مفرد ﴿قروء﴾ وهو ﴿قرء﴾ مذكر، وجاء ﴿قروء﴾ جمع كثرة بدل جمع القلة ﴿أقراء﴾ لشيوعه في الاستعمال؛ واللفظ مشترك في اللغة بين الحيض والطهر.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص546، تحت «العدول عن جمع القلة إلى جمع الكثرة في قوله تعالى: «ثلاثة قروء»»","url":""}]},{"id":"s2-1158","number":1158,"surah":2,"verses":[228],"references":[{"surah":2,"verses":[228]}],"verseLabel":"البقرة: 228","question":"ما سرّ التعبير في قوله تعالى: ﴿إِنْ كُنَّ يُؤْمِنَّ بِاللَّهِ وَالْيَوْمِ الْآخِرِ﴾ بعد النهي عن كتمان الحمل؟","answer":"لأن ما في الرحم لا يطلع عليه غالبًا إلا المرأة، فاستدعى رقابة الإيمان حين تعجز رقابة الناس. وذكر اليوم الآخر يضع الكتمان السري أمام الحساب العلني.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص552، تحت «أسلوب التذييل في قوله: «يؤمن بالله واليوم الآخر»»","url":""}]},{"id":"s2-1159","number":1159,"surah":2,"verses":[228],"references":[{"surah":2,"verses":[228]}],"verseLabel":"البقرة: 228","question":"ما سرّ التعبير في قوله تعالى: ﴿وَبُعُولَتُهُنَّ أَحَقُّ بِرَدِّهِنَّ﴾ مع وقوع الطلاق؟","answer":"سمّاهم بعولة باعتبار بقاء رابطة الرجعة في العدة، وجاء بأفعل التفضيل لبيان أولوية الزوج بالرد ما دام الباب مفتوحًا، لا ملكًا مطلقًا بعد انقضاء الحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص553، تحت «الإيجاز في صياغة أسلوب التفضيل في قوله: «وبعولتهن أحق بردهن»»","url":""}]},{"id":"s2-1160","number":1160,"surah":2,"verses":[228],"references":[{"surah":2,"verses":[228]}],"verseLabel":"البقرة: 228","question":"ما دلالة تقييد الرجعة بقوله تعالى: ﴿إِنْ أَرَادُوا إِصْلَاحًا﴾؟","answer":"حتى لا تستعمل الرجعة للإضرار أو إطالة العدة؛ حق الرد مشروع عند قصد إصلاح الحياة الزوجية.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص555، تحت «دلالة التعليق بالشرط في قوله: «إن أرادوا إصلاحا»»","url":""}]},{"id":"s2-1161","number":1161,"surah":2,"verses":[228],"references":[{"surah":2,"verses":[228]}],"verseLabel":"البقرة: 228","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلَهُنَّ مِثْلُ الَّذِي عَلَيْهِنَّ﴾؟","answer":"صاغ قاعدة توازن مدهشة: كل واجب عليهن يقابله حق لهن بحسب المعروف، فبدأ بحقوقهن بعد أحكام قد تبدو كلها قيودًا عليهن. والتقديم في ﴿لهن﴾ يلفت إلى ما قد يغفل عنه المجتمع.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص557، تحت «براعة التشبيه في قوله: «ولهن مثل الذي عليهن»»","url":""}]},{"id":"s2-1162","number":1162,"surah":2,"verses":[228],"references":[{"surah":2,"verses":[228]}],"verseLabel":"البقرة: 228","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿وَاللَّهُ عَزِيزٌ حَكِيمٌ﴾؟","answer":"﴿عزيز﴾ يمنع من التلاعب بحدوده أو مغالبته، و﴿حكيم﴾ يضع الحقوق والدرجة كلًا في موضعه. فالفاصلة ترد نظام الأسرة إلى سلطان مقرون بالحكمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص560، تحت «بلاغة التذييل في قوله: «والله عزيز حكيم»»","url":""}]},{"id":"s2-1163","number":1163,"surah":2,"verses":[229],"references":[{"surah":2,"verses":[229]}],"verseLabel":"البقرة: 229","question":"ما سرّ تسمية أحكام الزواج والطلاق ﴿حُدُودَ اللَّهِ﴾؟","answer":"سميت حدودًا لأنها أحكام فاصلة تحد المباح من المحظور وتحجز عن الظلم؛ وإضافتها إلى الله تعظم حرمتها وتوجب الوقوف عندها.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص578، تحت «نكتة الاستعارة في قوله: «ومن يتعد حدود الله»»","url":""}]},{"id":"s2-1164","number":1164,"surah":2,"verses":[229],"references":[{"surah":2,"verses":[229]}],"verseLabel":"البقرة: 229","question":"ما سرّ التعبير في قوله تعالى: ﴿فلا تعتدوها﴾ بصيغة الافتعال؟","answer":"الافتعال يوحي بتعمد المجاوزة وبذل النفس فيها، فيحذر من التحايل المقصود على الحدود لا مجرد خطأ عابر.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص578، تحت «فائدة صيغة الافتعال في قوله «فلا تعتدوها»، ومعنى التمثيل فيها»","url":""}]},{"id":"s2-1165","number":1165,"surah":2,"verses":[229],"references":[{"surah":2,"verses":[229]}],"verseLabel":"البقرة: 229","question":"ما سرّ التعبير في قوله تعالى: ﴿الطلاق مرتان﴾ لا: طلقتان؟","answer":"﴿مرتان﴾ تعد فعل الطلاق الرجعي المتكرر الذي تتخلله فرصة مراجعة، لا مجرد لفظين أو طلقتين مجموعتين في لحظة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص582، تحت «مرتان وطلقتان»","url":""}]},{"id":"s2-1166","number":1166,"surah":2,"verses":[229],"references":[{"surah":2,"verses":[229]}],"verseLabel":"البقرة: 229","question":"ما سرّ التعبير في قوله تعالى: ﴿الطَّلَاقُ مَرَّتَانِ﴾ مع أن الطلاق قد يقع ثلاثًا؟","answer":"المقصود تحديد الطلاق الذي يملك الزوج بعده الرجعة دون تجديد مهر وولي؛ فجعله مرتين، وأبطل ما كان من تكرار الطلاق والرجعة بلا حد. فالعدد هنا متعلق بالطلاق الرجعي، لا بنفي وقوع طلقة ثالثة.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص565–566، تحت عنوان «سبب فصل قوله تعالى: ﴿الطلاق مرتان﴾ عما قبله»","url":""}]},{"id":"s2-1167","number":1167,"surah":2,"verses":[229],"references":[{"surah":2,"verses":[229]}],"verseLabel":"البقرة: 229","question":"ما سرّ التعبير في قوله تعالى: ﴿فَإِمْسَاكٌ بِمَعْرُوفٍ أَوْ تَسْرِيحٌ بِإِحْسَانٍ﴾؟","answer":"بعد كل رجعة لا ثالث بين حياة كريمة وفراق كريم؛ فحذف المبتدأ ليجعل الخيارين كأنهما الحكم الحاضر. ورفع التسريح من مجرد عدل إلى إحسان يمنع الانتقام عند الافتراق.","sources":[{"label":"موسوعة التفسير البلاغي، ج3، ص568، تحت «دلالة التعبير بالمصدر المرفوع في قوله: «فإمساك بمعروف أو تسريح بإحسان»»","url":""}]}]);
